/**
 * OkHttp RequestBody-Wrapper, der den Upload-Fortschritt per Callback meldet.
 * onProgress(sent, total): aufgerufen während writeTo()
 */
private class ProgressRequestBody(
    private val delegate: RequestBody,
    private val onProgress: (sent: Long, total: Long) -> Unit,
    private val onUploadComplete: () -> Unit = {}
) : RequestBody() {
    override fun contentType() = delegate.contentType()
    override fun contentLength() = delegate.contentLength()

    override fun writeTo(sink: BufferedSink) {
        val total = contentLength()
        val progressSink = object : ForwardingSink(sink) {
            var bytesSent = 0L
            override fun write(source: Buffer, byteCount: Long) {
                super.write(source, byteCount)
                bytesSent += byteCount
                onProgress(bytesSent, total)
            }
        }
        val bufferedSink = progressSink.buffer()
        delegate.writeTo(bufferedSink)
        bufferedSink.flush()
        onUploadComplete()
    }
}

/**
 * Datenklasse für eingehende Kontaktanfragen aus dem WebSocket.
 */
data class IncomingRequest(
    val fromFakeNumber: String,
    val fromName: String,
    val contactEntryId: String
)

/**
 * Datenklasse für eingehende Handshake-Erneuerungsanfragen aus dem WebSocket.
 */
data class IncomingHandshakeRenew(
    val fromUserId: String,
    val fromFakeNumber: String,
    val fromName: String,
    val requesterPublicKey: String
)

/** Link-Vorschau-Daten aus OG-Tags (erweitert um Embed-Support). */
data class LinkPreviewData(
    val url: String,
    val title: String,
    val description: String? = null,
    val imageUrl: String? = null,
    val siteName: String? = null,
    val embedType: String? = null,    // "youtube" | "tiktok" | "instagram" | null
    val embedUrl: String? = null,     // Embed-URL für WebView
    val thumbnailUrl: String? = null  // Direkte Thumbnail-URL (z.B. YouTube HQ-Thumbnail)
)

/** Informationen über ein verfügbares App-Update. */
data class UpdateInfo(
    val version: String,
    val apkUrl: String,
    val changelog: String
)

/** Ausstehender Share-Intent (Text, URI oder mehrere URIs). */
data class PendingShare(
    val text: String? = null,
    val uri: android.net.Uri? = null,
    val uris: List<android.net.Uri>? = null,
    val mimeType: String? = null,
    /** Begleit-Text (EXTRA_TEXT) einer Bild-/Datei-Freigabe → wird als Bildunterschrift übernommen. */
    val caption: String? = null,
    /** Gesetzt wenn der User via Direct Share einen Kontakt gewählt hat (userId des Kontakts). */
    val targetChatId: String? = null,
    /** True wenn targetChatId eine Gruppen-ID ist. */
    val targetIsGroup: Boolean = false
)

/** State eines eingehenden Anrufs (noch nicht angenommen). */
data class IncomingCallState(
    val callerId: String,
    val callerName: String,
    val callerImageUrl: String?,
    val sdpOffer: String,
    val callType: String = "VIDEO",   // "VIDEO" oder "VOICE"
    /** true = Gruppenanruf-Einladung (weitere Personen bereits im Anruf). */
    val isGroupCall: Boolean = false,
    /** Namen + Bild-URLs der bereits im Anruf befindlichen Teilnehmer (ohne den direkten Anrufer). */
    val groupParticipants: List<Pair<String, String?>> = emptyList(),
    /** ID des Gruppen-Chats, aus dem der Anruf gestartet wurde (null bei 1:1). */
    val groupId: String? = null,
    /** Name des Gruppen-Chats (für die Anzeige beim Angerufenen). */
    val groupName: String? = null
)

data class CallParticipant(
