    /** Wird aufgerufen wenn der Nutzer den Status-Tab öffnet – setzt Badge zurück. */
    fun markStatusTabSeen() {
        statusSeenPrefs.edit().putLong("last_seen_at", System.currentTimeMillis()).apply()
        _hasUnseenStatuses.value = false
    }

    /** Prüft ob neue Statuse vorhanden sind (createdAt > zuletzt gesehen). */
    fun checkForUnseenStatuses(statuses: List<StatusEntity>) {
        val lastSeenAt = statusSeenPrefs.getLong("last_seen_at", 0L)
        _hasUnseenStatuses.value = statuses.any { it.createdAt > lastSeenAt }
    }

