        hiddenNearbyPrefs.getStringSet("hidden_ids", emptySet()) ?: emptySet()
    private fun saveHiddenNearbyId(userId: String) {
        hiddenNearbyPrefs.edit()
            .putStringSet("hidden_ids", getHiddenNearbyIds().toMutableSet().also { it.add(userId) })
            .apply()
    }
    private fun removeHiddenNearbyId(userId: String) {
        hiddenNearbyPrefs.edit()
            .putStringSet("hidden_ids", getHiddenNearbyIds().toMutableSet().also { it.remove(userId) })
            .apply()
    }

