    val contactStatuses: Flow<List<StatusEntity>> =
        statusDao.getActiveStatuses(System.currentTimeMillis())

    /** Flow aktiver Status-Beiträge für den Status-Tab. */
    val activeStatuses: Flow<List<StatusEntity>> =
        statusDao.getAllStatuses()
            .map { all -> all.filter { it.expiresAt > System.currentTimeMillis() } }

    /** Eigene aktive Status-Beiträge (von GET /status/mine, in Room gecacht). */
    private val _myStatuses = MutableStateFlow<List<StatusEntity>>(emptyList())
    val myStatuses: StateFlow<List<StatusEntity>> = _myStatuses.asStateFlow()

    /** Status der gerade im Viewer angezeigt wird – wird VOR Navigation gesetzt, um Race Condition zu vermeiden. */
    private val _viewingStatus = MutableStateFlow<StatusEntity?>(null)
    val viewingStatus: StateFlow<StatusEntity?> = _viewingStatus.asStateFlow()

    /** Alle Status-Beiträge eines Kontakts, die gerade als Gruppe betrachtet werden. */
    private val _currentStatusGroup = MutableStateFlow<List<StatusEntity>>(emptyList())
    val currentStatusGroup: StateFlow<List<StatusEntity>> = _currentStatusGroup.asStateFlow()

    fun prepareStatusViewer(status: StatusEntity) {
        _currentStatusGroup.value = listOf(status)
        _viewingStatus.value = status
    }

    fun prepareStatusGroup(statuses: List<StatusEntity>) {
        val sorted = statuses.sortedBy { it.createdAt }  // älteste zuerst, neueste zuletzt
        _currentStatusGroup.value = sorted
        _viewingStatus.value = sorted.firstOrNull()
    }

    /** Springt zum nächsten Status in der Gruppe. Gibt false zurück wenn kein nächster existiert. */
    fun advanceToNextStatus(): Boolean {
        val group = _currentStatusGroup.value
        val currentId = _viewingStatus.value?.statusId ?: return false
        val idx = group.indexOfFirst { it.statusId == currentId }
        return if (idx >= 0 && idx < group.size - 1) {
            _viewingStatus.value = group[idx + 1]
            true
        } else false
    }

    /** Springt zum vorherigen Status in der Gruppe. Gibt false zurück wenn kein vorheriger existiert. */
    fun advanceToPreviousStatus(): Boolean {
        val group = _currentStatusGroup.value
        val currentId = _viewingStatus.value?.statusId ?: return false
        val idx = group.indexOfFirst { it.statusId == currentId }
        return if (idx > 0) {
            _viewingStatus.value = group[idx - 1]
            true
        } else false
    }

    fun clearViewingStatus() {
        _viewingStatus.value = null
        _currentStatusGroup.value = emptyList()
    }

