    // ─── WebRTC DataChannel P2P Chat ──────────────────────────────────────────

    /** Manager für Internet-P2P-Chat via WebRTC DataChannel (kein Audio/Video). */
    private val webRTCDataChannelManager =
        com.securechat.app.data.webrtc.WebRTCDataChannelManager(
            context = context,
            signalingCallback = object :
                com.securechat.app.data.webrtc.WebRTCDataChannelManager.SignalingCallback {
                override fun onLocalSdpReady(peerId: String, type: String, sdp: String) {
                    val msgType = if (type == "offer") "webrtc_dc_offer" else "webrtc_dc_answer"
                    webSocketManager.sendMessage(
                        msgType, peerId,
                        mapOf("sdp" to sdp, "type" to type)
                    )
                    Timber.tag("LETHE_P2P_DC").d("Local SDP ($type) sent to $peerId via WS")
                }

                override fun onIceCandidateReady(
                    peerId: String, sdpMid: String, sdpMLineIndex: Int, candidate: String
                ) {
                    webSocketManager.sendMessage(
                        "webrtc_dc_ice", peerId,
                        mapOf(
                            "sdp_mid"          to sdpMid,
                            "sdp_m_line_index" to sdpMLineIndex,
                            "candidate"        to candidate
                        )
                    )
                }
            }
        )

    /** Verbindungsstatus pro Peer (peerId → P2PState). */
    val p2pConnectionStates: StateFlow<Map<String, com.securechat.app.data.webrtc.WebRTCDataChannelManager.P2PState>> =
        webRTCDataChannelManager.connectionStates

