    // ─────────────────────────────────────────────────────────────────────────
    // VIDEO CALL FUNCTIONS
    // ─────────────────────────────────────────────────────────────────────────

    /** Prüft Bandbreite und aktualisiert lokalen VideoCapable-Status. */
    fun updateLocalVideoCapable(capable: Boolean) {
        if (_isLocalVideoCapable.value == capable) return
        _isLocalVideoCapable.value = capable
        // Broadcast to active contacts via WebSocket
        webSocketManager.sendMessage(
            "video_capable",
            "broadcast",
            mapOf("capable" to capable)
        )
        Timber.tag("LETHE_VIDEO").d("LocalVideoCapable → $capable")
    }

    /**
     * Initiiert einen ausgehenden Videoanruf zu [partnerId].
     * Erstellt einen WebRtcClient, generiert ein SDP Offer und sendet es via WebSocket.
     */
    fun startVideoCall(partnerId: String) = startCallInternal(partnerId, "VIDEO")

    /**
     * Initiiert einen ausgehenden Sprachanruf zu [partnerId].
     * Kamera wird nicht genutzt; Audio läuft über den Hörer (Earpiece).
     */
    fun startVoiceCall(partnerId: String) = startCallInternal(partnerId, "VOICE")

    /**
     * Startet einen Gruppen-Anruf zu mehreren Teilnehmern.
     * Der erste Teilnehmer wird primär angerufen; die restlichen werden nach dem Verbindungsaufbau eingeladen.
     *
     * [targets] enthält pro Teilnehmer (userId, Anzeigename, Bild-URL). [groupId]/[groupName]
     * geben dem Angerufenen den Kontext, aus welchem Gruppen-Chat der Anruf stammt, und werden
     * – zusammen mit der vollständigen Teilnehmerliste – in jedem Offer mitgesendet.
     */
    fun startGroupCallWithParticipants(
        targets: List<Triple<String, String, String?>>,
        callType: String,
        groupId: String? = null,
        groupName: String? = null
    ) {
        if (targets.isEmpty()) return
        activeGroupCallId = groupId
        activeGroupCallName = groupName
        groupCallTargets.clear()
        targets.forEach { (id, name, img) -> groupCallTargets[id] = name to img }
        pendingGroupInvites.clear()
        pendingGroupInvites.addAll(targets.drop(1).map { it.first })

        // Teilnehmerliste für den Primär-Angerufenen: alle anderen ausgewählten Teilnehmer,
        // damit auch er sieht, dass es ein Gruppenanruf ist und wer noch dabei sein wird.
        val primaryId = targets[0].first
        val participantInfoList = groupCallTargets
            .filterKeys { it != primaryId }
            .map { (_, info) ->
                mapOf("name" to info.first, "image_url" to (info.second ?: ""))
            }
        val groupPayload: Map<String, Any> = buildMap {
            put("is_group_call", true)
            put("group_participants", participantInfoList)
            activeGroupCallId?.let { put("group_id", it) }
            activeGroupCallName?.let { put("group_name", it) }
        }
        startCallInternal(primaryId, callType, groupPayload)
    }

    private fun startCallInternal(
        partnerId: String,
        callType: String,
        extraPayload: Map<String, Any> = emptyMap()
    ) {
        if (_callState.value != CallState.IDLE && _callState.value != CallState.ENDED) {
            Timber.tag("LETHE_VIDEO").w("Call already active – ignoring startCallInternal")
            return
        }
        audioFocusManager.requestFocus()
        audioFocusManager.setCommunicationActive(true)
        _callState.value = CallState.IDLE  // Reset in case we were in ENDED
        _activeCallType.value = callType
        // Tracking für "Keine Antwort"-Bubble: wir sind Anrufer, noch nicht verbunden
        isOutgoingCall = true
        callEverConnected = false
        callNoAnswerLogged = false
        primaryPeerLost = false
        // Retry-Zustand für diesen neuen Anruf zurücksetzen
        callRetryAttempted = false
        callRetryJob?.cancel()
        callRetryJob = null
        lastCallOfferPayload = null
        lastCallOfferPartner = null
        // Sofort als busy markieren (DB), bevor der WebSocket-Offer rausgeht
        viewModelScope.launch {
            try { apiService.setBusy(mapOf("is_busy" to true)) } catch (_: Exception) {}
        }
        // WS reconnect erzwingen falls nicht verbunden (z.B. nach App-Hintergrund)
        if (!webSocketManager.isConnected()) {
            Timber.tag("LETHE_VIDEO").w("WS nicht verbunden vor Anruf – erzwinge Reconnect")
            connectWebSocketAndListen()
        }
        // Foreground Service starten (Mikrofon/Kamera im Hintergrund, Android 14+)
        startCallForegroundService()
        // 60s-Timeout: wird bei Annahme oder Ablehnung gecancelt
        callTimeoutJob?.cancel()
        callTimeoutJob = viewModelScope.launch {
            delay(60_000)
            Timber.tag("LETHE_VIDEO").w("Ausgehender Anruf-Timeout nach 60s – lege auf")
            val pid = _activeCallPartnerId.value
            if (pid != null) webSocketManager.sendMessage("call_end", pid, emptyMap<String, Any>())
            cleanupCall()
        }
        viewModelScope.launch {
            val client = buildWebRtcClient(partnerId, callType, extraPayload = extraPayload)
            client.initialize()
            attachWebRtcFlows(client)
            webRtcClient = client
            _eglBaseContext.value = client.eglBase.eglBaseContext
            _activeCallPartnerId.value = partnerId
            client.createPeerConnection(isOffer = true)
        }
    }

    /**
     * Nimmt einen eingehenden Anruf an.
     * Erstellt einen WebRtcClient, setzt das SDP Offer und generiert ein Answer.
     */
    fun acceptCall() {
        callTimeoutJob?.cancel()
        callTimeoutJob = null
        val incoming = _incomingCall.value ?: return
        val callType = incoming.callType
        // Eingehender Anruf wird angenommen → keine "Keine Antwort"-Bubble für diesen Anruf
        isOutgoingCall = false
        callNoAnswerLogged = true
        primaryPeerLost = false
        audioFocusManager.requestFocus()
        audioFocusManager.setCommunicationActive(true)
        stopRingtone()
        notificationHelper.cancelCallNotification()
        _incomingCall.value = null
        _activeCallType.value = callType
        // WS-Reconnect erzwingen falls nicht verbunden (z.B. beim Annehmen aus dem Doze/
        // Sperrbildschirm, wenn der Anruf nur per FCM kam). Ohne aktiven WS würden
        // call_answer + ICE-Kandidaten nur gepuffert und der Anruf käme nie zustande.
        if (!webSocketManager.isConnected()) {
            Timber.tag("LETHE_VIDEO").w("WS nicht verbunden vor Anruf-Annahme – erzwinge Reconnect")
            connectWebSocketAndListen()
        }
        // Foreground Service starten (Mikrofon/Kamera im Hintergrund, Android 14+)
        startCallForegroundService()
        viewModelScope.launch {
            val client = buildWebRtcClient(incoming.callerId, callType)
            client.initialize()
            attachWebRtcFlows(client)
            webRtcClient = client
            _eglBaseContext.value = client.eglBase.eglBaseContext
            _activeCallPartnerId.value = incoming.callerId
            // Gepufferte ICE-Kandidaten die vor acceptCall() ankamen jetzt dem Client übergeben
            // (WebRtcClient puffert sie intern bis setRemoteSdp aufgerufen wurde)
            val buffered = pendingRemoteIceCandidates.toList()
            pendingRemoteIceCandidates.clear()
            buffered.forEach { (mid, idx, cand) -> client.addRemoteIceCandidate(mid, idx, cand) }
            if (buffered.isNotEmpty()) Timber.tag("LETHE_VIDEO").d("Flushed ${buffered.size} pre-buffered ICE candidates to client")
            client.createPeerConnection(isOffer = false)
            client.setRemoteSdp("offer", incoming.sdpOffer)
        }
    }

    /** Lehnt einen eingehenden Anruf ab (sendet call_end und verwirft den State). */
    fun declineCall() {
        callTimeoutJob?.cancel()
        callTimeoutJob = null
        val incoming = _incomingCall.value ?: return
        stopRingtone()
        notificationHelper.cancelCallNotification()
        webSocketManager.sendMessage("call_end", incoming.callerId, emptyMap<String, Any>())
        // "Keine Antwort"-Bubble für den Empfänger (mit Zurückrufen-Link)
        insertCallNoAnswerLog(incoming.callerId, incoming.callType, isOutgoing = false)
        _incomingCall.value = null
        IncomingCallStore.clear()
        Timber.tag("LETHE_VIDEO").d("Incoming call declined from ${incoming.callerId}")
    }

    /**
     * Nimmt einen Anruf an, der über FCM (Doze-Wakeup) oder den Sperrbildschirm kam.
     * Liest die Anrufdaten aus IncomingCallStore und verhält sich dann wie acceptCall().
     */
    fun acceptCallFromStore() {
        val pending = IncomingCallStore.pendingCall ?: run {
            // Anruf bereits im _incomingCall-State → normaler Pfad
            if (_incomingCall.value != null) acceptCall()
            return
        }
        // _incomingCall aus dem Store rekonstruieren (falls noch nicht gesetzt)
        if (_incomingCall.value == null) {
            _incomingCall.value = IncomingCallState(
                callerId          = pending.callerId,
                callerName        = pending.callerName,
                callerImageUrl    = pending.callerImageUrl,
                sdpOffer          = pending.sdpOffer,
                callType          = pending.callType,
                isGroupCall       = pending.isGroupCall,
                groupParticipants = pending.groupParticipants,
                groupId           = pending.groupId,
                groupName         = pending.groupName
            )
        }
        IncomingCallStore.clear()
        acceptCall()
    }

    /**
     * Lehnt einen Anruf ab, der über FCM / Sperrbildschirm-Benachrichtigung kam.
     * Falls kein _incomingCall-State vorhanden ist, wird call_end direkt an den Store-Caller gesendet.
     */
    fun declineCallFromStore() {
        val pending = IncomingCallStore.pendingCall
        if (_incomingCall.value != null) {
            declineCall()
        } else if (pending != null) {
            IncomingCallStore.clear()
            notificationHelper.cancelCallNotification()
            webSocketManager.sendMessage("call_end", pending.callerId, emptyMap<String, Any>())
            insertCallNoAnswerLog(pending.callerId, pending.callType, isOutgoing = false)
            Timber.tag("LETHE_VIDEO").d("Store-call declined (no active _incomingCall) for ${pending.callerId}")
        }
    }

    /** Beendet den laufenden Anruf und bereinigt alle Ressourcen. */
    fun endCall() {
        val partnerId = _activeCallPartnerId.value
        if (partnerId != null) {
            webSocketManager.sendMessage("call_end", partnerId, emptyMap<String, Any>())
        }
        additionalWebRtcClients.keys.toList().forEach { uid ->
            webSocketManager.sendMessage("call_end", uid, emptyMap<String, Any>())
        }
        inviteTimeoutJobs.values.forEach { it.cancel() }
        inviteTimeoutJobs.clear()
        stopAllRingback()
        cleanupCall()
    }

    /** Sendet eine Emoji-Reaktion an den aktuellen Anruf-Partner. */
    fun sendCallEmoji(emojiName: String) {
        val partnerId = _activeCallPartnerId.value ?: return
        webSocketManager.sendMessage("call_emoji", partnerId, mapOf("emoji" to emojiName))
    }

    /**
     * Hinterlässt nach einem fehlgeschlagenen Anruf (Partner nicht erreichbar) einen Hinweis
     * im 1:1-Chat. Die Nachricht wird über den normalen Versandweg gespeichert und dem Partner
     * zugestellt, sobald er wieder online ist, sodass beide Seiten den Anrufversuch sehen.
     */
    private fun recordMissedCallAttempt(partnerId: String, callType: String) {
        val myName = _currentUser.value?.name?.takeIf { it.isNotBlank() } ?: "Jemand"
        val callLabel = if (callType == "VOICE") "Sprachanruf" else "Videoanruf"
        val timeStr = java.text.SimpleDateFormat("dd.MM.yyyy - HH:mm", java.util.Locale.getDefault())
            .format(java.util.Date())
        val text = "📞 $myName hat versucht am $timeStr einen $callLabel zu starten"
        sendMessage(chatId = partnerId, content = text)
    }

    /**
     * Fügt lokal eine "Keine Antwort"-Anruf-Bubble in den 1:1-Chat ein.
     * Die Nachricht wird nur lokal gespeichert (nicht versendet) – jedes Gerät erzeugt sie selbst.
     * Der Absender (senderId) ist IMMER der Anrufer, damit die Bubble auf beiden Geräten auf der
     * Seite des Anruf-Auslösers erscheint. In der Bubble entscheidet isFromMe über die Aktion:
     *   Anrufer  → "Sprachnachricht aufnehmen"
     *   Empfänger → "Zurückrufen"
     *
     * @param partnerId der jeweils andere Gesprächsteilnehmer (= chatId)
     * @param callType  "VOICE" oder "VIDEO"
     * @param isOutgoing true = wir waren der Anrufer
     */
    private fun insertCallNoAnswerLog(partnerId: String, callType: String, isOutgoing: Boolean) {
        val myId = _currentUser.value?.userId ?: return
        val callerId = if (isOutgoing) myId else partnerId
        val json = org.json.JSONObject().apply {
            put("type", if (callType.equals("VIDEO", ignoreCase = true)) "video" else "voice")
            put("reason", "no_answer")
        }.toString()
        viewModelScope.launch(Dispatchers.IO) {
            messageDao.insertMessage(
                MessageEntity(
                    chatId         = partnerId,
                    senderId       = callerId,
                    receiverId     = if (isOutgoing) partnerId else myId,
                    content        = json,
                    mediaType      = "call",
                    timestamp      = System.currentTimeMillis(),
                    isRead         = true,
                    isSent         = true,
                    deliveryStatus = 3
                )
            )
        }
    }

    /** Lädt einen weiteren Kontakt in den laufenden Anruf ein. */
    fun inviteToCall(userId: String) {
        if (_callState.value != CallState.CONNECTED) return
        if (additionalWebRtcClients.containsKey(userId)) return
        viewModelScope.launch {
            val contact = contactDao.getContactById(userId)
            // Nach DB-Suspension: Anruf noch aktiv und User nicht schon eingeladen?
            if (_callState.value != CallState.CONNECTED) return@launch
            if (additionalWebRtcClients.containsKey(userId)) return@launch

            val username = contact?.username ?: contact?.fakeNumber ?: userId
            val imageUrl = contact?.profileImageUrl?.let {
                if (it.startsWith("http")) it else "https://letheapp.de$it"
            }
            val updated = _additionalParticipants.value.toMutableMap()
            updated[userId] = CallParticipant(userId, null, username, imageUrl)
            _additionalParticipants.value = updated

            // Shared Tracks vom Primärclient → verhindert doppeltes Kamera-/Mikrofon-Öffnen
            val primaryVideo = webRtcClient?.currentLocalVideoTrack
            val primaryAudio = webRtcClient?.currentLocalAudioTrack

            // Teilnehmerliste für den Einladungsempfänger (zeigt ihm wer bereits im Anruf ist)
            val participantInfoList = buildList<Map<String, String>> {
                _activeCallPartnerId.value?.let { pid ->
                    val c = contactDao.getContactById(pid)
                    add(mapOf(
                        "name" to (c?.username ?: c?.fakeNumber ?: pid),
                        "image_url" to (c?.profileImageUrl?.let {
                            if (it.startsWith("http")) it else "https://letheapp.de$it"
                        } ?: "")
                    ))
                }
                _additionalParticipants.value.values
                    .filter { it.userId != userId }
                    .forEach { p ->
                        add(mapOf(
                            "name" to p.username,
                            "image_url" to (p.imageUrl ?: "")
                        ))
                    }
            }
            // Bestehende Teilnehmer-IDs für den Server (damit er die anderen bei accept/decline benachrichtigen kann)
            val existingIds = buildList {
                _activeCallPartnerId.value?.let { add(it) }
                addAll(additionalWebRtcClients.keys.filter { it != userId })
            }
            val extraPayload: Map<String, Any> = buildMap {
                put("is_group_call", true)
                put("group_participants", participantInfoList)
                put("existing_participant_ids", existingIds)
                activeGroupCallId?.let { put("group_id", it) }
                activeGroupCallName?.let { put("group_name", it) }
            }

            val client = buildWebRtcClient(
                userId,
                _activeCallType.value,
                sharedLocalVideoTrack = primaryVideo,
                sharedLocalAudioTrack = primaryAudio,
                extraPayload = extraPayload
            )
            // Nach TURN-Credential-Suspension: Anruf noch aktiv?
            if (_callState.value != CallState.CONNECTED) {
                val revert = _additionalParticipants.value.toMutableMap()
                revert.remove(userId)
                _additionalParticipants.value = revert
                client.dispose()
                return@launch
            }
            client.initialize()

            // Bestehende Teilnehmer-Streams an neuen Client weitergeben (sieht alle vom Start an)
            // addForwardedTracks() puffert solange peerConnection noch null ist
            _activeCallPartnerId.value?.let { pid ->
                val video = webRtcClient?.currentRemoteVideoTrack
                val audio = webRtcClient?.currentRemoteAudioTrack
                client.addForwardedTracks(video, audio, pid)
            }
            additionalWebRtcClients.forEach { (existingUid, existingClient) ->
                val video = existingClient.currentRemoteVideoTrack
                val audio = existingClient.currentRemoteAudioTrack
                client.addForwardedTracks(video, audio, existingUid)
            }

            attachAdditionalWebRtcFlows(client, userId)
            additionalWebRtcClients[userId] = client
            client.createPeerConnection(isOffer = true)
        }
    }

    /** Bricht die Einladung eines noch wartenden Teilnehmers ab (klingelt noch). */
    fun cancelInvite(userId: String) {
        webSocketManager.sendMessage("call_end", userId, emptyMap<String, Any>())
        inviteTimeoutJobs.remove(userId)?.cancel()
        val client = additionalWebRtcClients.remove(userId)
        val updated = _additionalParticipants.value.toMutableMap()
        updated.remove(userId)
        _additionalParticipants.value = updated
        // Freizeichen für genau diesen Teilnehmer freigeben: der callState-Collector hat nach
        // additionalWebRtcClients.remove() keinen Zugang mehr (Guard schlägt fehl).
        releaseRingback(userId)
        client?.dispose()
    }

    private fun attachAdditionalWebRtcFlows(client: WebRtcClient, userId: String) {
        viewModelScope.launch {
            client.remoteVideoTrackFlow.collect { track ->
                if (additionalWebRtcClients[userId] !== client) return@collect
                val updated = _additionalParticipants.value.toMutableMap()
                val existing = updated[userId]
                if (existing != null) {
                    updated[userId] = existing.copy(videoTrack = track)
                } else {
                    // Eintrag wurde zwischenzeitlich entfernt (z.B. durch forwardedVideoTracksFlow-Bereinigung)
                    // → neu anlegen damit der Track trotzdem angezeigt wird.
                    val contact = contactDao.getContactById(userId)
                    val name = contact?.username ?: contact?.fakeNumber ?: userId
                    val imageUrl = contact?.profileImageUrl?.let {
                        if (it.startsWith("http")) it else "https://letheapp.de$it"
                    }
                    updated[userId] = CallParticipant(userId, track, name, imageUrl)
                }
                _additionalParticipants.value = updated

                // Host-Relay: Remote-Track von userId an alle anderen Teilnehmer weiterleiten
                if (track != null) {
                    val audioTrack = client.currentRemoteAudioTrack
                    forwardTrackToOthers(userId, track, audioTrack)
                }
            }
        }
        viewModelScope.launch {
            client.callState.collect { state ->
                if (additionalWebRtcClients[userId] !== client) return@collect
                when (state) {
                    WebRtcClient.CallState.CALLING -> {
                        requestRingback(userId)
                        // Sicherheitsnetz: verbindet sich der Eingeladene nicht binnen 60s
                        // (z.B. nimmt an, aber ICE/Relay scheitert → schwarzes Bild), wird die
                        // Einladung automatisch abgebrochen damit das Freizeichen nicht ewig läuft.
                        inviteTimeoutJobs.remove(userId)?.cancel()
                        inviteTimeoutJobs[userId] = viewModelScope.launch {
                            delay(60_000)
                            if (additionalWebRtcClients[userId] === client &&
                                client.callState.value != WebRtcClient.CallState.CONNECTED) {
                                Timber.tag("LETHE_VIDEO").w("Einladungs-Timeout für $userId – breche ab")
                                cancelInvite(userId)
                            }
                        }
                    }
                    WebRtcClient.CallState.CONNECTED -> {
                        inviteTimeoutJobs.remove(userId)?.cancel()
                        releaseRingback(userId)
                    }
                    WebRtcClient.CallState.ENDED, WebRtcClient.CallState.ICE_FAILED -> {
                        inviteTimeoutJobs.remove(userId)?.cancel()
                        releaseRingback(userId)
                        additionalWebRtcClients.remove(userId)
                        val updated = _additionalParticipants.value.toMutableMap()
                        updated.remove(userId)
                        _additionalParticipants.value = updated
                        client.dispose()
                        // Hatte der Primärpartner den Call bereits verlassen und war dies der
                        // letzte Sekundärteilnehmer → Anruf vollständig beenden (Host freigeben).
                        if (primaryPeerLost && additionalWebRtcClients.isEmpty()) {
                            cleanupCall()
                        }
                    }
                    else -> {}
                }
            }
        }
    }

    /**
     * Leitet Video- und Audio-Track eines Teilnehmers [fromUserId] an alle anderen Clients weiter.
     * Dadurch kann jeder Teilnehmer jeden anderen sehen/hören ohne direkte P2P-Verbindung.
     */
    private fun forwardTrackToOthers(
        fromUserId: String,
        videoTrack: org.webrtc.VideoTrack,
        audioTrack: org.webrtc.AudioTrack?
    ) {
        // An primären Partner (Person A, der erste Angerufene) – nur solange er verbunden ist.
        if (!primaryPeerLost) webRtcClient?.addForwardedTracks(videoTrack, audioTrack, fromUserId)
        // An alle weiteren zusätzlichen Teilnehmer
        additionalWebRtcClients.forEach { (uid, existingClient) ->
            if (uid != fromUserId) {
                existingClient.addForwardedTracks(videoTrack, audioTrack, fromUserId)
            }
        }
    }

    /** Mikrofon stummschalten / entstummen. */
    fun toggleCallMute() = webRtcClient?.toggleMute()

    /** Kamera wechseln (Vorder- ↔ Rückkamera). */
    fun switchCallCamera() = webRtcClient?.switchCamera()

    /** Zwischen Hörer (Earpiece) und Freisprecher umschalten (Sprachanrufe). */
    fun toggleSpeakerphone() = webRtcClient?.toggleSpeakerphone()

    fun setCallVideoQuality(isHighDefinition: Boolean) = webRtcClient?.setVideoQuality(isHighDefinition)

    /** Kein virtueller Hintergrund (Originalkamera). */
    fun setVirtualBackgroundNone() {
        webRtcClient?.setVirtualBackground(com.securechat.app.data.webrtc.VirtualBackgroundMode.NONE)
        _virtualBackgroundMode.value = com.securechat.app.data.webrtc.VirtualBackgroundMode.NONE
        _selectedBackgroundId.value = null
    }

    /** Hintergrund unscharf stellen. */
    fun setVirtualBackgroundBlur() {
        webRtcClient?.setVirtualBackground(com.securechat.app.data.webrtc.VirtualBackgroundMode.BLUR)
        _virtualBackgroundMode.value = com.securechat.app.data.webrtc.VirtualBackgroundMode.BLUR
        _selectedBackgroundId.value = null
    }

    /** Bereits dekodiertes Bitmap als Hintergrund setzen (z. B. generierte Preset-Hintergründe). */
    fun setVirtualBackgroundImage(bitmap: Bitmap, id: String) {
        webRtcClient?.setVirtualBackground(com.securechat.app.data.webrtc.VirtualBackgroundMode.IMAGE, bitmap)
        _virtualBackgroundMode.value = com.securechat.app.data.webrtc.VirtualBackgroundMode.IMAGE
        _selectedBackgroundId.value = id
    }

    /** Hintergrundbild aus der Galerie (URI) laden und anwenden. */
    fun setVirtualBackgroundImageFromUri(uri: Uri) {
        viewModelScope.launch(Dispatchers.IO) {
            val bitmap = try {
                context.contentResolver.openInputStream(uri)?.use { input ->
                    val opts = BitmapFactory.Options().apply { inSampleSize = 2 }
                    BitmapFactory.decodeStream(input, null, opts)
                }
            } catch (e: Exception) {
                Timber.tag("LETHE_BLUR").w(e, "Hintergrundbild konnte nicht geladen werden")
                null
            } ?: return@launch
            webRtcClient?.setVirtualBackground(com.securechat.app.data.webrtc.VirtualBackgroundMode.IMAGE, bitmap)
            _virtualBackgroundMode.value = com.securechat.app.data.webrtc.VirtualBackgroundMode.IMAGE
            _selectedBackgroundId.value = uri.toString()
        }
    }

    // ─── WebRTC DataChannel P2P Chat – öffentliche API ───────────────────────

    /**
     * Initiiert eine P2P-DataChannel-Verbindung zu [peerId].
     * Der TURN-Server wird automatisch vom Backend abgefragt.
     * Nach erfolgreichem Verbindungsaufbau (P2PState.CONNECTED) können Nachrichten
     * via [sendP2PMessage] gesendet werden.
     */
    fun initP2PChat(peerId: String) {
        if (!_userPrefs.value.p2pInternetEnabled) {
            // Wir haben P2P deaktiviert → Partner informieren, keine Verbindung aufbauen
            webSocketManager.sendMessage("webrtc_dc_disabled", peerId, emptyMap<String, String>())
            Timber.tag("LETHE_P2P_DC").d("P2P deaktiviert, webrtc_dc_disabled an $peerId gesendet")
            return
        }
        if (peerId in _userPrefs.value.p2pDisabledContacts) {
            // P2P für diesen Kontakt lokal deaktiviert → Partner informieren, nicht verbinden
            webSocketManager.sendMessage("webrtc_dc_disabled", peerId, emptyMap<String, String>())
            Timber.tag("LETHE_P2P_DC").d("P2P für Kontakt $peerId deaktiviert, webrtc_dc_disabled gesendet")
            return
        }
        if (_p2pPartnerDisabled.value[peerId] == true) {
            // Partner hat P2P aus (laut Serverdaten/Signal) → gar nicht erst verbinden,
            // verhindert hängende CONNECTING-Versuche/Ruckeln bei offline/inaktiven Partnern.
            Timber.tag("LETHE_P2P_DC").d("Partner $peerId hat P2P deaktiviert – kein Verbindungsaufbau")
            return
        }
        if (!webRTCDataChannelManager.initialize().let { true }) return // initialize is unit
        viewModelScope.launch {
            var turnUsername = ""
            var turnPassword = ""
            try {
                val resp = apiService.getTurnCredentials()
                if (resp.isSuccessful) {
                    resp.body()?.let { turnUsername = it.username; turnPassword = it.password }
                }
            } catch (_: Exception) { /* STUN only */ }
            webRTCDataChannelManager.connectToPeer(peerId, turnUsername, turnPassword)
            Timber.tag("LETHE_P2P_DC").d("P2P DataChannel initiert zu $peerId")
        }
    }

    /**
     * Sendet [message] via offenem DataChannel an [peerId].
     * Gibt true zurück wenn erfolgreich, false wenn der Kanal noch nicht offen ist.
     */
    fun sendP2PMessage(peerId: String, message: String): Boolean =
        webRTCDataChannelManager.sendMessage(peerId, message)

    /** Sendet rohe Binärdaten (z.B. Datei-Chunks) via DataChannel an [peerId]. */
    fun sendP2PBinaryData(peerId: String, data: ByteArray): Boolean =
        webRTCDataChannelManager.sendBinaryData(peerId, data)

    /** Schließt die P2P-DataChannel-Verbindung zu [peerId]. */
    fun closeP2PChat(peerId: String) = webRTCDataChannelManager.closeConnection(peerId)

    /** Liefert den aktuellen P2P-Verbindungsstatus zu [peerId]. */
    fun getP2PState(peerId: String) = webRTCDataChannelManager.getState(peerId)

    /** Bildschirmfreigabe starten (MediaProjection-Intent von Activity). */
    fun onStartScreenShare(data: Intent) {
        webRtcClient?.startScreenShare(data)
        _isScreenSharing.value = true
    }

    /** Bildschirmfreigabe beenden, Kamera wieder aktivieren. */
    fun onStopScreenShare() {
        webRtcClient?.stopScreenShare()
        _isScreenSharing.value = false
    }

    /**
     * Startet bzw. stoppt die serverseitige Aufzeichnung des laufenden Anrufs.
     * Beide Teilnehmer publishen via WHIP an MediaMTX; der Server komponiert beides zu einer MP4.
     */
    fun toggleCallRecording() {
        if (_isCallRecording.value) {
            stopServerRecording()
        } else {
            requestCallRecordingConsent()
        }
    }

    /**
     * Schritt 1 der Aufzeichnung: Den Partner um Einwilligung bitten.
     * Es wird NICHTS aufgezeichnet, bis der Partner über [respondCallRecordingConsent]
     * zustimmt (datenschutzkonform, §201 StGB / DSGVO).
     */
    private fun requestCallRecordingConsent() {
        val client = webRtcClient ?: return
        val partnerId = _activeCallPartnerId.value ?: return
        if (_recordingConsentPending.value) return
        val callType = if (client.callType == "VIDEO") "video" else "audio"
        _recordingConsentPending.value = true
        webSocketManager.sendMessage("call_recording_request", partnerId, mapOf("call_type" to callType))
        showCallToast("Warte auf Zustimmung des Partners…")
        // Timeout: falls der Partner nicht innerhalb 30s antwortet, Warten beenden.
        viewModelScope.launch {
            kotlinx.coroutines.delay(30_000)
            if (_recordingConsentPending.value && !_isCallRecording.value) {
                _recordingConsentPending.value = false
                showCallToast("Keine Antwort auf die Aufzeichnungs-Anfrage")
            }
        }
    }

    /**
     * Wird auf dem Gerät des Partners aufgerufen, wenn dieser im Einwilligungs-Dialog
     * antwortet. [allowDownload] = Initiator darf den eigenen Stream des Partners behalten.
     */
    fun respondCallRecordingConsent(accepted: Boolean, allowDownload: Boolean) {
        val requester = _incomingRecordingConsentFrom.value
        _incomingRecordingConsentFrom.value = null
        if (requester == null) return
        webSocketManager.sendMessage(
            "call_recording_response", requester,
            mapOf("accepted" to accepted, "allow_download" to allowDownload)
        )
    }

    private fun startServerRecording(allowPartnerDownload: Boolean) {
        val client = webRtcClient ?: return
        val partnerId = _activeCallPartnerId.value ?: return
        val callType = if (client.callType == "VIDEO") "video" else "audio"
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val req = com.securechat.app.data.network.RecordingStartRequest(partnerId, callType, allowPartnerDownload)
                val resp = apiService.startCallRecording(req)
                if (!resp.isSuccessful || resp.body() == null) {
                    showCallToast("Aufzeichnung konnte nicht gestartet werden")
                    return@launch
                }
                val info = resp.body()!!
                activeRecordingId = info.recordingId
                isRecordingStarter = true
                recordingStartMs = System.currentTimeMillis()

                // NUR den EIGENEN Stream an MediaMTX publishen (lokale Kamera/Mikro-Tracks).
                // Der Partner publisht seinen eigenen Stream selbst (siehe notifyPartnerRecording
                // mit WHIP-Feldern → call_recording-WS-Handler → startPartnerRequestedRecording).
                // So gibt es keine Weiterleitung fremder Remote-Tracks mehr (das verursachte
                // beim Start einen nativen WebRTC-Crash) und jeder Teilnehmer wird als eigene,
                // separat herunterladbare Datei aufgezeichnet.
                val selfUrl = "${info.whipBase}/${info.selfPath}/whip"
                val selfPub = com.securechat.app.data.webrtc.WhipPublisher()
                whipPublisher = selfPub
                val okSelf = selfPub.start(selfUrl, client.currentLocalVideoTrack, client.currentLocalAudioTrack)
                if (!okSelf) {
                    Timber.tag("LETHE_REC").w("WHIP-Publish (self) fehlgeschlagen")
                }

                // Partner anweisen, seinen eigenen Stream zu publishen.
                _isCallRecording.value = true
                notifyPartnerRecording(
                    recording = true,
                    recordingId = info.recordingId,
                    partnerPath = info.partnerPath,
                    whipBase = info.whipBase
                )
                showCallToast("Aufzeichnung gestartet")
            } catch (e: Exception) {
                Timber.tag("LETHE_REC").e(e, "startServerRecording fehlgeschlagen")
                showCallToast("Aufzeichnung konnte nicht gestartet werden")
            }
        }
    }

    private fun stopServerRecording() {
        val recId = activeRecordingId ?: return
        _isCallRecording.value = false
        activeRecordingId = null
        isRecordingStarter = false
        val durationSec = ((System.currentTimeMillis() - recordingStartMs) / 1000).toInt()

        whipPublisher?.stop()
        whipPublisher = null

        notifyPartnerRecording(recording = false)

        viewModelScope.launch(Dispatchers.IO) {
            try {
                val req = com.securechat.app.data.network.RecordingStopRequest(recId, durationSec)
                apiService.stopCallRecording(req)
                showCallToast("Aufzeichnung beendet – wird verarbeitet…")
            } catch (e: Exception) {
                Timber.tag("LETHE_REC").e(e, "stopCallRecording fehlgeschlagen")
            }
        }
    }

    /**
     * Wird aufgerufen wenn der PARTNER die Aufzeichnung gestartet hat (via WS call_recording).
     * Startet den WHIP-Publish des eigenen Streams zum MediaMTX-Pfad des Partners.
     */
    internal fun startPartnerRequestedRecording(recordingId: String, myPath: String, whipBase: String) {
        val client = webRtcClient ?: return
        viewModelScope.launch(Dispatchers.IO) {
            val whipUrl = "$whipBase/$myPath/whip"
            val pub = com.securechat.app.data.webrtc.WhipPublisher()
            whipPublisher = pub
            activeRecordingId = recordingId
            isRecordingStarter = false
            recordingStartMs = System.currentTimeMillis()
            val ok = pub.start(whipUrl, client.currentLocalVideoTrack, client.currentLocalAudioTrack)
            Timber.tag("LETHE_REC").i("Partner-Recording WHIP ${if (ok) "OK" else "FEHLER"}: $whipUrl")
        }
    }

    /**
     * Wird aufgerufen wenn der PARTNER die Aufzeichnung gestoppt hat.
     * Stoppt unseren WHIP-Publish.
     */
    internal fun stopPartnerRequestedRecording() {
        whipPublisher?.stop()
        whipPublisher = null
        activeRecordingId = null
        isRecordingStarter = false
    }

    /** Informiert den/die Gesprächspartner über den Aufzeichnungs-Status (REC-Hinweis). */
    private fun notifyPartnerRecording(
        recording: Boolean,
        recordingId: String? = null,
        partnerPath: String? = null,
        whipBase: String? = null
    ) {
        val payload = buildMap<String, Any> {
            put("recording", recording)
            if (recording && recordingId != null && partnerPath != null && whipBase != null) {
                put("recording_id", recordingId)
                put("partner_path", partnerPath)
                put("whip_base", whipBase)
            }
        }
        _activeCallPartnerId.value?.let { webSocketManager.sendMessage("call_recording", it, payload) }
        additionalWebRtcClients.keys.toList().forEach {
            webSocketManager.sendMessage("call_recording", it, payload)
        }
    }

    /** Lädt die Liste aller Aufzeichnungen des eingeloggten Users vom Server. */
    fun loadCallRecordings() {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val resp = apiService.listCallRecordings()
                if (resp.isSuccessful) {
                    _callRecordings.value = resp.body() ?: emptyList()
                }
            } catch (e: Exception) {
                Timber.tag("LETHE_REC").e(e, "loadCallRecordings fehlgeschlagen")
            }
        }
    }

    /**
     * Lädt einen der beiden Anruf-Streams herunter und speichert ihn in den öffentlichen
     * Downloads-Ordner. [which] = "self" (eigener Stream) oder "partner" (anderer Teilnehmer).
     */
    fun downloadCallRecording(recordingId: String, which: String = "self") {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val resp = apiService.downloadCallRecording(recordingId, which)
                if (!resp.isSuccessful || resp.body() == null) {
                    showCallToast("Download fehlgeschlagen")
                    return@launch
                }
                val fileName = "lethe_call_${recordingId.take(8)}_$which.mp4"
                val contentValues = android.content.ContentValues().apply {
                    put(android.provider.MediaStore.Downloads.DISPLAY_NAME, fileName)
                    put(android.provider.MediaStore.Downloads.MIME_TYPE, "video/mp4")
                    put(android.provider.MediaStore.Downloads.RELATIVE_PATH, "Download/Lethe")
                }
                val resolver = context.contentResolver
                val uri = if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.Q) {
                    resolver.insert(android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI, contentValues)
                } else null
                if (uri != null) {
                    resolver.openOutputStream(uri)?.use { out ->
                        resp.body()!!.byteStream().copyTo(out)
                    }
                    showCallToast("Gespeichert in Downloads/Lethe")
                } else {
                    // Fallback: in externem Cache speichern
                    val file = File(context.getExternalFilesDir(null), fileName)
                    file.outputStream().use { out -> resp.body()!!.byteStream().copyTo(out) }
                    showCallToast("Gespeichert: ${file.absolutePath}")
                }
            } catch (e: Exception) {
                Timber.tag("LETHE_REC").e(e, "downloadCallRecording fehlgeschlagen")
                showCallToast("Download fehlgeschlagen")
            }
        }
    }

    private fun showCallToast(message: String) {
        viewModelScope.launch(Dispatchers.Main) {
            android.widget.Toast.makeText(context, message, android.widget.Toast.LENGTH_SHORT).show()
        }
    }

    /** Wird von der Activity bei onPause aufgerufen – deaktiviert den Video-Track. */
    fun onCallPause() = webRtcClient?.onPause()

    /** Wird von der Activity bei onResume aufgerufen – reaktiviert den Video-Track. */
    fun onCallResume() = webRtcClient?.onResume()

    private fun startCallForegroundService() {
        val intent = Intent(context, CallForegroundService::class.java).apply {
            action = CallForegroundService.ACTION_START
        }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            context.startForegroundService(intent)
        } else {
            context.startService(intent)
        }
    }

    private fun stopCallForegroundService() {
        val intent = Intent(context, CallForegroundService::class.java).apply {
            action = CallForegroundService.ACTION_STOP
        }
        context.startService(intent)
    }

    private suspend fun buildWebRtcClient(
        partnerId: String,
        callType: String = "VIDEO",
        sharedLocalVideoTrack: org.webrtc.VideoTrack? = null,
        sharedLocalAudioTrack: org.webrtc.AudioTrack? = null,
        extraPayload: Map<String, Any> = emptyMap()
    ): com.securechat.app.data.webrtc.WebRtcClient {
        // TURN-Credentials serverseitig abrufen (Secret bleibt auf dem Server)
        var turnUsername = ""
        var turnPassword = ""
        try {
            val resp = apiService.getTurnCredentials()
            if (resp.isSuccessful) {
                resp.body()?.let { turnUsername = it.username; turnPassword = it.password }
            }
        } catch (_: Exception) { /* Fallback: nur STUN */ }
        val prefs = _userPrefs.value
        return com.securechat.app.data.webrtc.WebRtcClient(
            context  = context,
            partnerId = partnerId,
            callType = callType,
            turnUsername = turnUsername,
            turnPassword = turnPassword,
            sharedLocalVideoTrack = sharedLocalVideoTrack,
            sharedLocalAudioTrack = sharedLocalAudioTrack,
            segmentationProvider = segmentationProvider,
            audioQuality = prefs.audioQuality,
            audioOutputChannel = prefs.audioOutputChannel,
            bluetoothHeadsetEnabled = prefs.bluetoothHeadsetEnabled,
            androidAutoConnected = audioFocusManager.isAndroidAutoConnected,
            signalingCallback = object : com.securechat.app.data.webrtc.WebRtcClient.SignalingCallback {
                override fun onLocalSdpReady(type: String, sdp: String) {
                    val msgType = if (type == "offer") "call_offer" else "call_answer"
                    val payload = buildMap<String, Any> {
                        put("sdp", sdp)
                        put("type", type)
                        put("call_type", callType)
                        putAll(extraPayload)
                    }
                    // Offer-Payload für einen möglichen Retry bei "nicht erreichbar" merken.
                    // Gilt für 1:1-Anrufe UND den Primär-Anruf eines Gruppen-Calls (der sich wie
                    // ein 1:1-Offer verhält und den FCM-Wakeup-Retry ebenfalls braucht, sonst
                    // bricht der Gruppenanruf sofort mit "nicht erreichbar" ab, wenn der primäre
                    // Angerufene gerade im Hintergrund/Doze ist). NUR sekundäre Gruppen-Einladungen
                    // (inviteToCall, erkennbar an existing_participant_ids) haben eigene Logik.
                    val isSecondaryGroupInvite = extraPayload.containsKey("existing_participant_ids")
                    if (type == "offer" && !isSecondaryGroupInvite) {
                        lastCallOfferPayload = payload
                        lastCallOfferPartner = partnerId
                    }
                    webSocketManager.sendMessage(msgType, partnerId, payload)
                    Timber.tag("LETHE_VIDEO").d("Local SDP sent ($type) to $partnerId")
                }
                override fun onIceCandidateReady(sdpMid: String, sdpMLineIndex: Int, candidate: String) {
                    webSocketManager.sendMessage(
                        "ice_candidate", partnerId,
                        mapOf(
                            "sdp_mid"          to sdpMid,
                            "sdp_m_line_index" to sdpMLineIndex,
                            "candidate"        to candidate
                        )
                    )
                }
            }
        )
    }

    private fun attachWebRtcFlows(client: WebRtcClient) {
        viewModelScope.launch {
            client.localVideoTrackFlow.collect { _localVideoTrack.value = it }
        }
        viewModelScope.launch {
            client.remoteVideoTrackFlow.collect { track ->
                _remoteVideoTrack.value = track
                // Host-Seite: primären Partner-Track an alle bereits eingeladenen Zusatz-Teilnehmer weiterleiten.
                // Ohne dies sehen Teilnehmer die NACH dem Verbindungsaufbau eingeladen wurden den Primär-Partner
                // nicht, weil inviteToCall() nur den zum Einladungszeitpunkt vorhandenen Track übergibt.
                if (track != null && webRtcClient === client) {
                    val pid   = _activeCallPartnerId.value ?: return@collect
                    val audio = client.currentRemoteAudioTrack
                    additionalWebRtcClients.forEach { (_, additionalClient) ->
                        additionalClient.addForwardedTracks(track, audio, pid)
                    }
                }
            }
        }
        // Callee-Seite: weitergeleitete Tracks von anderen Gruppen-Teilnehmern (stream_fwd_<userId>) einsammeln
        viewModelScope.launch {
            client.forwardedVideoTracksFlow.collect { trackMap ->
                if (webRtcClient !== client) return@collect
                val current = _additionalParticipants.value.toMutableMap()
                // Direkten Gesprächspartner niemals als weitergeleiteten Teilnehmer eintragen –
                // er wird bereits als Haupt-Video angezeigt (remoteVideoTrack).
                val activePartner = _activeCallPartnerId.value
                val myOwnId = _currentUser.value?.userId
                // Tracks aktualisieren oder neue Teilnehmer-Einträge anlegen
                for ((participantId, videoTrack) in trackMap) {
                    if (participantId == activePartner) continue  // primärer Partner → Haupt-Ansicht, kein PiP
                    if (participantId == myOwnId) continue         // eigene ID → kein Duplikat
                    val existing = current[participantId]
                    if (existing != null) {
                        current[participantId] = existing.copy(videoTrack = videoTrack)
                    } else {
                        // Kontaktinfo aus lokaler DB laden
                        val contact = contactDao.getContactById(participantId)
                        val name = contact?.username ?: contact?.fakeNumber ?: participantId
                        val imageUrl = contact?.profileImageUrl?.let {
                            if (it.startsWith("http")) it else "https://letheapp.de$it"
                        }
                        current[participantId] = CallParticipant(participantId, videoTrack, name, imageUrl)
                    }
                }
                // Teilnehmer entfernen, deren Tracks vom Host nicht mehr weitergeleitet werden,
                // aber NUR wenn sie bereits einen Live-Track hatten (nicht bloß einen null-Platzhalter
                // von group_participant_invited). So wird kein klingelnder Teilnehmer versehentlich entfernt.
                current.keys
                    .filter { id ->
                        id !in trackMap
                        && !additionalWebRtcClients.containsKey(id)
                        && current[id]?.videoTrack != null   // nur entfernen wenn Track schon vorhanden war
                    }
                    .forEach { current.remove(it) }
                _additionalParticipants.value = current
            }
        }
        viewModelScope.launch {
            client.isMuted.collect { _callIsMuted.value = it }
        }
        viewModelScope.launch {
            client.isSpeakerphoneOn.collect { _isSpeakerphoneOn.value = it }
        }
        viewModelScope.launch {
            client.isUsingFrontCamera.collect { _isUsingFrontCamera.value = it }
        }
        viewModelScope.launch {
            client.callState.collect { state ->
                // Ignore events from a client that was already replaced/cleaned up
                if (webRtcClient !== client) return@collect
                // Primärpartner hat den Gruppen-Call bereits verlassen; Client ist nur noch
                // Track-Host → weitere State-Events (z.B. wiederholtes ICE_FAILED) ignorieren.
                if (primaryPeerLost) return@collect

                // ICE_FAILED: Verbindungsabbruch des Primärpartners.
                if (state == WebRtcClient.CallState.ICE_FAILED) {
                    // 1:1-Anruf → komplett beenden; Gruppen-Call → nur Primärpartner entfernen.
                    if (additionalWebRtcClients.isEmpty()) {
                        _callStatusMessage.value = "Verbindung abgebrochen"
                    }
                    handlePrimaryPeerLost()
                    return@collect
                }
                // ENDED während ein Gruppen-Call läuft → nur den Primärpartner entfernen,
                // die übrigen Teilnehmer bleiben verbunden (Host-Tracks bleiben erhalten).
                if (state == WebRtcClient.CallState.ENDED && additionalWebRtcClients.isNotEmpty()) {
                    handlePrimaryPeerLost()
                    return@collect
                }

                _callState.value = when (state) {
                    WebRtcClient.CallState.CALLING   -> CallState.CALLING
                    WebRtcClient.CallState.RINGING   -> CallState.RINGING
                    WebRtcClient.CallState.CONNECTED -> CallState.CONNECTED
                    WebRtcClient.CallState.ENDED     -> CallState.ENDED
                    WebRtcClient.CallState.IDLE      -> CallState.IDLE
                    else                             -> CallState.IDLE
                }
                // Freizeichen: NUR für den Anrufer (CALLING), NICHT für den Angerufenen (RINGING)
                when (state) {
                    WebRtcClient.CallState.CALLING   -> requestRingback(RINGBACK_PRIMARY)
                    WebRtcClient.CallState.RINGING,
                    WebRtcClient.CallState.CONNECTED,
                    WebRtcClient.CallState.ENDED,
                    WebRtcClient.CallState.IDLE      -> releaseRingback(RINGBACK_PRIMARY)
                    else                             -> releaseRingback(RINGBACK_PRIMARY)
                }
                // Sobald die Verbindung steht: Timeout definitiv stoppen (Fallback falls call_answer fehlte)
                if (state == WebRtcClient.CallState.CONNECTED) {
                    callEverConnected = true   // verhindert "Keine Antwort"-Bubble
                    callTimeoutJob?.cancel()
                    callTimeoutJob = null
                    // Ausstehende Gruppen-Einladungen jetzt senden
                    if (pendingGroupInvites.isNotEmpty()) {
                        val toInvite = pendingGroupInvites.toList()
                        pendingGroupInvites.clear()
                        toInvite.forEach { inviteId -> inviteToCall(inviteId) }
                    }
                }
                if (state == WebRtcClient.CallState.ENDED) cleanupCall()
            }
        }
    }

    /**
     * Behandelt den Verlust der Primärverbindung (ICE_FAILED/ENDED).
     *
     * - 1:1-Anruf (keine Sekundärteilnehmer): kompletter Cleanup wie bisher.
     * - Gruppen-Call: NUR der Primärpartner wird entfernt. Der Primärclient besitzt die
     *   geteilten lokalen Kamera-/Mikrofon-Tracks (isSecondary=false) und wird daher bewusst
     *   NICHT disposed – sonst verlören alle Sekundärclients ihr lokales Bild/Audio. Er bleibt
     *   als reiner Track-Host bestehen; [primaryPeerLost] unterdrückt seine weiteren Events.
     */
    private fun handlePrimaryPeerLost() {
        val primaryId = _activeCallPartnerId.value
        if (primaryId != null) {
            webSocketManager.sendMessage("call_end", primaryId, emptyMap<String, Any>())
        }
        if (additionalWebRtcClients.isEmpty()) {
            cleanupCall()
            return
        }
        // Gruppen-Call läuft weiter: Primärpartner als sichtbaren Teilnehmer entfernen,
        // Host-Client (geteilte Tracks) behalten.
        primaryPeerLost = true
        _activeCallPartnerId.value = null
        _remoteVideoTrack.value = null
        Timber.tag("LETHE_VIDEO").w(
            "Primärpartner verließ Gruppen-Call – ${additionalWebRtcClients.size} Teilnehmer bleiben verbunden"
        )
    }

    private fun startRingtone() {
        try {
            val uri = RingtoneManager.getDefaultUri(RingtoneManager.TYPE_RINGTONE)
            callRingtone = RingtoneManager.getRingtone(context, uri)?.also { ringtone ->
                if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.P) {
                    ringtone.isLooping = true
                }
                ringtone.play()
            }
        } catch (e: Exception) {
            Timber.tag("LETHE_VIDEO").w("Ringtone start failed: $e")
        }
    }

    private fun stopRingtone() {
        callRingtone?.stop()
        callRingtone = null
    }

    /** Startet leises Freizeichen (Ringback) für den Anrufer – läuft bis stopRingbackTone(). */
    private fun startRingbackTone() {
        if (ringbackJob?.isActive == true) return
        ringbackJob = viewModelScope.launch {
            try {
                ringbackToneGenerator = ToneGenerator(AudioManager.STREAM_VOICE_CALL, 80)
                while (true) {
                    ringbackToneGenerator?.startTone(ToneGenerator.TONE_SUP_RINGTONE, 2000)
                    delay(4000) // 2s Ton + 2s Pause = 4s Zyklus
                }
            } catch (e: Exception) {
                Timber.tag("LETHE_VIDEO").w("Ringback tone failed: $e")
            }
        }
    }

    private fun stopRingbackTone() {
        ringbackJob?.cancel()
        ringbackJob = null
        ringbackToneGenerator?.release()
        ringbackToneGenerator = null
    }

    /**
     * Freizeichen-Steuerung per Referenzzählung. Statt dass viele unabhängige Collector den
     * EINEN Generator unkoordiniert starten/stoppen (führte zu hängendem Dauerton bei
     * Gruppen-Einladungen), ist das Freizeichen genau dann aktiv wenn mindestens ein
     * Teilnehmer im [ringingParticipants]-Set klingelt.
     */
    private fun requestRingback(id: String) {
        ringingParticipants.add(id)
        if (ringbackJob?.isActive != true) startRingbackTone()
    }

    /** Entfernt [id]; stoppt den Ton sobald niemand mehr klingelt. */
    private fun releaseRingback(id: String) {
        ringingParticipants.remove(id)
        if (ringingParticipants.isEmpty()) stopRingbackTone()
    }

    /** Hartes Stoppen: alle klingelnden Teilnehmer entfernen und Ton sofort beenden. */
    private fun stopAllRingback() {
        ringingParticipants.clear()
        stopRingbackTone()
    }

    /** Kurzer Auflegesound wenn der Angerufene ablehnt. */
    private fun playHangupSound() {
        viewModelScope.launch {
            try {
                val tg = ToneGenerator(AudioManager.STREAM_VOICE_CALL, 60)
                tg.startTone(ToneGenerator.TONE_PROP_NACK, 1500)
                delay(2000)
                tg.release()
            } catch (e: Exception) {
                Timber.tag("LETHE_VIDEO").w("Hangup sound failed: $e")
            }
        }
    }

    /**
     * Sicherheitsnetz gegen einen "hängenden" Telefonmodus. Wird beim Zurückkehren der App in den
     * Vordergrund aufgerufen: Ist kein Anruf (mehr) aktiv und läuft keine Sprachnachricht-Aufnahme,
     * der System-Audiomodus aber steht noch auf MODE_IN_COMMUNICATION (z. B. weil ein Anruf durch
     * Falschbedienung oder Absturz nie sauber per Auflegen beendet wurde), wird der Modus hart auf
     * MODE_NORMAL zurückgesetzt und Speakerphone abgeschaltet. So laufen Sounds wieder über den
     * Lautsprecher statt nur über die Ohrmuschel.
     */
    fun ensureNoStuckCallAudioMode() {
        val callActive = webRtcClient != null ||
            additionalWebRtcClients.isNotEmpty() ||
            _callState.value == CallState.CALLING ||
            _callState.value == CallState.RINGING ||
            _callState.value == CallState.CONNECTED ||
            audioFocusManager.isCommunicationActive()
        if (callActive) return
        audioFocusManager.forceResetToNormalMode()
    }

    private fun cleanupCall() {
        // "Keine Antwort"-Bubble für den Anrufer: ausgehender Anruf, der nie verbunden wurde
        // (Timeout, vom Empfänger abgelehnt/aufgelegt oder selbst abgebrochen während es klingelte).
        if (isOutgoingCall && !callEverConnected && !callNoAnswerLogged) {
            val p = _activeCallPartnerId.value
            if (p != null) {
                callNoAnswerLogged = true
                insertCallNoAnswerLog(p, _activeCallType.value, isOutgoing = true)
            }
        }
        audioFocusManager.abandonFocus()
        audioFocusManager.setCommunicationActive(false)
        // Telefonmodus IMMER hart zurücksetzen – auch wenn dieser cleanupCall unten früh
        // zurückkehrt (webRtcClient bereits null) und WebRtcClient.dispose() den Modus nicht
        // mehr auf NORMAL setzt. Verhindert einen "hängenden" MODE_IN_COMMUNICATION, der Sounds
        // über die Ohrmuschel statt den Lautsprecher routet.
        audioFocusManager.forceResetToNormalMode()
        callTimeoutJob?.cancel()              // 60s-Timeout abbrechen
        callTimeoutJob = null
        inviteTimeoutJobs.values.forEach { it.cancel() }
        inviteTimeoutJobs.clear()
        stopAllRingback()                     // Freizeichen vollständig stoppen (falls noch aktiv)
        pendingRemoteIceCandidates.clear()    // Gepufferte Kandidaten verwerfen
        pendingGroupInvites.clear()           // Ausstehende Gruppen-Einladungen verwerfen
        activeGroupCallId = null              // Gruppen-Kontext zurücksetzen
        activeGroupCallName = null
        groupCallTargets.clear()
        // Busy-Status zurücksetzen (Backup, falls Server-seitig nicht passiert)
        viewModelScope.launch {
            try { apiService.setBusy(mapOf("is_busy" to false)) } catch (_: Exception) {}
        }
        // Foreground Service stoppen
        stopCallForegroundService()
        _isScreenSharing.value = false
        // Laufende Aufzeichnung beim Auflegen zuverlässig finalisieren. Ohne dies erfuhr
        // der Server nie vom Ende (Status blieb 'recording', Rohsegmente liefen ab) – der
        // häufigste Auflege-Fall. Nur der Starter sendet den Stop-Call; beim Partner
        // übernimmt der Server (call_end-Auto-Stop). Vor dem Nullen von activeRecordingId
        // sichern und in einem Scope absetzen, der cleanupCall nicht blockiert.
        val recToFinalize = activeRecordingId
        if (recToFinalize != null && isRecordingStarter) {
            val durationSec = ((System.currentTimeMillis() - recordingStartMs) / 1000).toInt()
            notifyPartnerRecording(recording = false)
            viewModelScope.launch(Dispatchers.IO) {
                try {
                    apiService.stopCallRecording(
                        com.securechat.app.data.network.RecordingStopRequest(recToFinalize, durationSec)
                    )
                } catch (e: Exception) {
                    Timber.tag("LETHE_REC").e(e, "stopCallRecording (cleanupCall) fehlgeschlagen")
                }
            }
        }
        _isCallRecording.value = false
        _partnerCallRecording.value = false
        _recordingConsentPending.value = false
        _incomingRecordingConsentFrom.value = null
        isRecordingStarter = false
        whipPublisher?.stop()
        whipPublisher = null
        activeRecordingId = null
        callRetryJob?.cancel()
        callRetryJob = null
        additionalWebRtcClients.values.toList().forEach { it.dispose() }
        additionalWebRtcClients.clear()
        _additionalParticipants.value = emptyMap()
        primaryPeerLost = false
        val client = webRtcClient ?: return   // Already cleaned up – avoid double-dispose
        webRtcClient = null                   // Null out FIRST so attachWebRtcFlows ignores future events
        // Clear UI state before dispose so Compose removes video sinks before tracks are released
        _eglBaseContext.value      = null
        _activeCallPartnerId.value = null
        _localVideoTrack.value     = null
        _remoteVideoTrack.value    = null
        _callIsMuted.value             = false
        _isSpeakerphoneOn.value        = false
        _isUsingFrontCamera.value      = true
        _virtualBackgroundMode.value   = com.securechat.app.data.webrtc.VirtualBackgroundMode.NONE
        _selectedBackgroundId.value    = null
        _activeCallType.value      = "VIDEO"  // Für den nächsten Anruf zurücksetzen
        _callState.value           = CallState.ENDED  // ENDED triggers VideoCallScreen navigation
        client.dispose()                              // Dispose AFTER state cleared
        // Reset to IDLE after enough time for VideoCallScreen to show any status message and navigate
        viewModelScope.launch {
            delay(3_000)
            _callState.value = CallState.IDLE
            _callStatusMessage.value = null
        }
        Timber.tag("LETHE_VIDEO").d("Call resources cleaned up")
    }

    /** Mutex + Set verhindert gleichzeitige loadMessages-Aufrufe für dieselbe chatId. */
    private val loadMessagesMutex = Mutex()
    private val loadMessagesInProgress = mutableSetOf<String>()

    /** Älteste vom Server geladene Nachrichten-ID pro Chat (für before_id Paginierung). */
    private val _oldestServerMessageId = java.util.concurrent.ConcurrentHashMap<String, String>()

    /** Ob noch ältere Nachrichten auf dem Server vorhanden sind (pro Chat). */
    private val _hasMoreMessages = java.util.concurrent.ConcurrentHashMap<String, Boolean>()

    /** Display-Limit pro Chat als StateFlow – startet bei 300, wächst um 5 beim Nachladen. */
    private val _chatDisplayLimits = HashMap<String, MutableStateFlow<Int>>()

    /** Gibt den Display-Limit-Flow für einen Chat zurück (lazy initialisiert mit 300). */
    private fun getDisplayLimitFlow(chatId: String): MutableStateFlow<Int> =
        _chatDisplayLimits.getOrPut(chatId) { MutableStateFlow(300) }

    /** Welche Chats laden gerade ältere Nachrichten nach (für Lade-Indikator in der UI). */
    private val _isLoadingOlderMessages = MutableStateFlow<Set<String>>(emptySet())
