    /** Lokaler Pfad-Cache für bereits heruntergeladene Status-Videos: statusId → lokalerPfad (max 100 Einträge) */
    private val statusVideoLocalCache = LruCache<String, String>(100)

    /** Gibt den lokalen Pfad eines gecachten Status-Videos zurück (null = nicht gecacht). */
    fun getStatusVideoLocalPath(statusId: String): String? = statusVideoLocalCache.get(statusId)

    /** Lädt ein Status-Video in den Cache-Ordner herunter (nur wenn noch nicht vorhanden). */
    fun cacheStatusVideo(statusId: String, url: String) {
        if (statusVideoLocalCache.get(statusId) != null) return
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val cacheDir = File(context.cacheDir, "status_videos").also { it.mkdirs() }
                val ext = url.substringAfterLast('.').let { if (it.length <= 4) ".$it" else ".mp4" }
                val localFile = File(cacheDir, "sv_$statusId$ext")
                if (localFile.exists()) {
                    statusVideoLocalCache.put(statusId, localFile.absolutePath)
                    return@launch
                }
                val client = OkHttpClient()
                val req = Request.Builder().url(url).build()
                val resp = client.newCall(req).execute()
                resp.body?.byteStream()?.use { input ->
                    FileOutputStream(localFile).use { out -> input.copyTo(out) }
                }
                if (localFile.exists() && localFile.length() > 0) {
                    statusVideoLocalCache.put(statusId, localFile.absolutePath)
                    Timber.tag("LETHE_BG").d("Status-Video gecacht: $statusId → ${localFile.absolutePath}")
                }
            } catch (e: Exception) {
                Timber.tag("LETHE_BG").e(e, "Status-Video-Cache fehlgeschlagen: $statusId")
            }
        }
    }

