    /**
     * Anzeige-Titel, wenn die Datei keinen ID3-Titel hat oder die Metadaten-Extraktion
     * fehlschlägt. Nutzt den Dateinamen aus der URL (falls sprechend), sonst "Musik".
     * Verhindert, dass der Player-Titel dauerhaft auf "Wird geladen…" hängen bleibt.
     */
    private fun musicFallbackTitle(url: String): String {
        val name = url.substringBefore('?').substringAfterLast('/').substringBeforeLast('.')
            .replace('_', ' ').replace('-', ' ').trim()
        // Reine Hash-/Zufallsnamen (keine Leerzeichen, hex/ziffern-lastig) nicht anzeigen
        val looksLikeRandom = name.isBlank() ||
            name.length > 48 ||
            (!name.contains(' ') && name.count { it.isDigit() } * 2 >= name.length)
        return if (looksLikeRandom) "Musik" else name
    }

