    /** Laedt die Basis-Bibliothek (fuer Favoriten-Status) und die Playlists des Nutzers. */
    fun loadUserMusicLibrary() {
        viewModelScope.launch(kotlinx.coroutines.Dispatchers.IO) {
            try {
                val resp = apiService.getUserMusic()
                if (resp.isSuccessful) {
                    val base = resp.body().orEmpty().filter { it.playlistId == null }
                    _userMusicByUrl.value = base.associateBy { it.musicUrl }
                }
            } catch (_: Exception) {}
            loadUserPlaylists()
        }
    }

    fun loadUserPlaylists() {
        viewModelScope.launch(kotlinx.coroutines.Dispatchers.IO) {
            try {
                val resp = apiService.getUserPlaylists()
                if (resp.isSuccessful) _userPlaylists.value = resp.body().orEmpty()
            } catch (_: Exception) {}
        }
    }

    /** Speichert ein gesendetes/empfangenes Musikstueck in der eigenen Bibliothek (dedupliziert serverseitig). */
    fun saveMusicToLibrary(url: String, title: String?, artist: String?, playTimeSec: Int?) {
        if (url.isBlank()) return
        if (_userMusicByUrl.value.containsKey(url)) return
        viewModelScope.launch(kotlinx.coroutines.Dispatchers.IO) {
            try {
                val resp = apiService.saveUserMusic(
                    UserMusicSaveRequest(musicUrl = url, musicTitle = title, artist = artist, playTime = playTimeSec)
                )
                if (resp.isSuccessful) resp.body()?.let { entry ->
                    _userMusicByUrl.update { it + (entry.musicUrl to entry) }
                }
            } catch (_: Exception) {}
        }
    }

    /** Stellt sicher, dass fuer die URL ein Basis-Eintrag existiert, und liefert dessen ID. */
    private suspend fun ensureLibraryEntryId(url: String, title: String?, artist: String?, playTimeSec: Int?): String? {
        _userMusicByUrl.value[url]?.let { return it.id }
        return try {
            val resp = apiService.saveUserMusic(
                UserMusicSaveRequest(musicUrl = url, musicTitle = title, artist = artist, playTime = playTimeSec)
            )
            if (resp.isSuccessful) resp.body()?.also { entry ->
                _userMusicByUrl.update { it + (entry.musicUrl to entry) }
            }?.id else null
        } catch (_: Exception) { null }
    }

    /** Schaltet den Favoriten-Status eines Musikstuecks um. */
    fun toggleMusicFavorite(url: String, title: String?, artist: String?, playTimeSec: Int?) {
        viewModelScope.launch(kotlinx.coroutines.Dispatchers.IO) {
            val id = ensureLibraryEntryId(url, title, artist, playTimeSec) ?: return@launch
            val newFav = !(_userMusicByUrl.value[url]?.favorit ?: false)
            try {
                val resp = apiService.setUserMusicFavorite(id, UserMusicFavoriteRequest(favorit = newFav))
                if (resp.isSuccessful) resp.body()?.let { entry ->
                    _userMusicByUrl.update { it + (entry.musicUrl to entry) }
                }
            } catch (_: Exception) {}
        }
    }

    /** Aktualisiert Titel/Artist/Laenge eines Bibliothek-Eintrags, sobald die Metadaten bekannt sind. */
    fun persistMusicMetadata(url: String, title: String?, artist: String?, playTimeSec: Int?) {
        if (url.isBlank()) return
        if (title.isNullOrBlank() && artist.isNullOrBlank() && playTimeSec == null) return
        viewModelScope.launch(kotlinx.coroutines.Dispatchers.IO) {
            try {
                val resp = apiService.saveUserMusic(
                    UserMusicSaveRequest(musicUrl = url, musicTitle = title, artist = artist, playTime = playTimeSec)
                )
                if (resp.isSuccessful) resp.body()?.let { entry ->
                    _userMusicByUrl.update { it + (entry.musicUrl to entry) }
                }
            } catch (_: Exception) {}
        }
    }

    /** Fuegt ein Musikstueck einer bestehenden oder neuen Playlist hinzu. */
    fun addMusicToPlaylist(url: String, title: String?, artist: String?, playTimeSec: Int?, playlistId: String?, playlistName: String) {
        viewModelScope.launch(kotlinx.coroutines.Dispatchers.IO) {
            val id = ensureLibraryEntryId(url, title, artist, playTimeSec) ?: return@launch
            try {
                val resp = apiService.addUserMusicToPlaylist(
                    id, UserMusicPlaylistRequest(playlistId = playlistId, playlistName = playlistName)
                )
                if (resp.isSuccessful) {
                    loadUserPlaylists()
                    if (playlistId != null) loadPlaylistTracks(playlistId)
                }
            } catch (_: Exception) {}
        }
    }

