    /** Laedt die Titel einer bestimmten Playlist. */
    fun loadPlaylistTracks(playlistId: String) {
        viewModelScope.launch(kotlinx.coroutines.Dispatchers.IO) {
            try {
                val resp = apiService.getUserMusic(favoritesOnly = false, playlistId = playlistId)
                if (resp.isSuccessful) {
                    _playlistTracks.update { it + (playlistId to resp.body().orEmpty()) }
                }
            } catch (_: Exception) {}
