    /** Loescht einen Bibliotheks- oder Playlist-Eintrag. */
    fun deleteMusicEntry(entry: UserMusicResponse) {
        viewModelScope.launch(kotlinx.coroutines.Dispatchers.IO) {
            try {
                val resp = apiService.deleteUserMusic(entry.id)
                if (resp.isSuccessful) {
                    if (entry.playlistId == null) {
                        _userMusicByUrl.update { it - entry.musicUrl }
                    } else {
                        _playlistTracks.update { map ->
                            val list = map[entry.playlistId]?.filterNot { it.id == entry.id } ?: return@update map
                            map + (entry.playlistId to list)
                        }
                        loadUserPlaylists()
                    }
                }
            } catch (_: Exception) {}
        }
    }

    /** Erstellt Cast-MediaMetadata für den aktuell spielenden Musik-Track. */
    fun buildCurrentMusicCastMetadata(): com.securechat.app.cast.CastMediaMetadata {
        return castDiscoveryManager.buildMusicMetadata(
            title = _musicTitle.value,
            artist = _musicArtist.value,
            coverUrl = _musicCoverUrl.value
        )
    }

    /** Wandelt eine Medien-URL in die /mc/-Cover-URL um (Chromecast-Endpoint). */
    fun buildCoverUrl(url: String): String {
        val abs = toAbsoluteUrl(url)
        return abs.replace(Regex("(https://letheapp\\.de)/uploads/(.+)$")) { m ->
            "${m.groupValues[1]}/mc/${m.groupValues[2]}"
        }
    }

    /** Erstellt Cast-MediaMetadata für eine Musik-URL; nutzt In-Memory-Cache für Titel/Artist.
     *  Akzeptiert sowohl Original-/uploads/-URLs als auch /m/-Cast-URLs. */
    fun buildMusicCastMetadataForUrl(url: String): com.securechat.app.cast.CastMediaMetadata {
        // Cache-Key ist immer die Original-/uploads/-URL; /m/-URLs hier zurückkonvertieren
        val uploadsUrl = url
            .replace(Regex("(https://letheapp\\.de)/m/(.+)$"), "$1/uploads/$2")
        val (cachedTitle, cachedArtist) =
            _musicTitleArtistCache[url] ?: _musicTitleArtistCache[uploadsUrl] ?: Pair(null, null)
        // Cover-URL: /mc/-Endpunkt benötigt immer /uploads/-Pfad als Basis
        val coverBase = if (uploadsUrl != url) uploadsUrl else url
        return castDiscoveryManager.buildMusicMetadata(
            title    = cachedTitle,
            artist   = cachedArtist,
            coverUrl = buildCoverUrl(coverBase)
        )
    }

    // ─────────────────────────────────────────────────────────────────────────────
    // Musik-Player: Ein einziger persistenter ExoPlayer für alle Chat-Musik-Nachrichten.
    // Dadurch läuft die Wiedergabe weiter, auch wenn der Player-Composable beim Scrollen
    // aus der Komposition entfernt wird.
    // ─────────────────────────────────────────────────────────────────────────────

    private var _musicExoPlayer: androidx.media3.exoplayer.ExoPlayer? = null
    private var _musicAudioFocusRequest: android.media.AudioFocusRequest? = null
    // Merkt sich, dass die Musik NUR wegen eines vorübergehenden Fokusverlusts pausiert wurde
    // (z. B. ein Video, eine Sprachnachricht oder ein Anruf begann). Nur dann wird sie beim
    // Zurückgewinnen des Fokus automatisch fortgesetzt. Ohne dieses Flag scheiterte das Fortsetzen,
    // weil pause() sofort _musicIsPlaying=false setzt und die bisherige GAIN-Prüfung nie zutraf.
    @Volatile
    private var _musicPausedByFocusLoss = false
    @Suppress("DEPRECATION")
    private val _musicAudioFocusLegacyListener = android.media.AudioManager.OnAudioFocusChangeListener { focusChange ->
        viewModelScope.launch(kotlinx.coroutines.Dispatchers.Main) {
            when (focusChange) {
                android.media.AudioManager.AUDIOFOCUS_LOSS -> {
                    // Endgültiger Verlust: pausieren, kein automatisches Fortsetzen.
                    _musicPausedByFocusLoss = false
                    _musicExoPlayer?.pause()
                }
                android.media.AudioManager.AUDIOFOCUS_LOSS_TRANSIENT,
                android.media.AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK -> {
                    // Vorübergehender Verlust (anderes Lethe-Playback/Anruf): pausieren und für
                    // späteres Fortsetzen merken.
                    if (_musicExoPlayer?.isPlaying == true) {
                        _musicPausedByFocusLoss = true
                        _musicExoPlayer?.pause()
                    }
                }
                android.media.AudioManager.AUDIOFOCUS_GAIN -> {
                    if (_musicPausedByFocusLoss) {
                        _musicPausedByFocusLoss = false
                        _musicExoPlayer?.play()
                    }
                }
            }
        }
    }
