    private val _musicCoverUrl = MutableStateFlow<String?>(null)
    val musicCoverUrl: StateFlow<String?> = _musicCoverUrl.asStateFlow()

    /** Listener für den persistenten Musik-ExoPlayer. */
    private val musicPlayerListener = object : androidx.media3.common.Player.Listener {
        override fun onPlaybackStateChanged(state: Int) {
            val player = _musicExoPlayer ?: return
            if (state == androidx.media3.common.Player.STATE_READY) {
                val dur = player.duration
                if (dur > 0L) _musicTotalMs.value = dur
                _musicIsPrepared.value = true
            }
            if (state == androidx.media3.common.Player.STATE_ENDED) {
                // Nur am Ende der gesamten Playlist (letztes Lied fertig)
                _musicIsPlaying.value = false
                _musicProgress.value = 0f
                _musicCurrentMs.value = 0L
                player.seekTo(0)
                abandonMusicAudioFocus()
            }
        }
        override fun onIsPlayingChanged(isPlaying: Boolean) {
            _musicIsPlaying.value = isPlaying
        }
        override fun onMediaItemTransition(mediaItem: androidx.media3.common.MediaItem?, reason: Int) {
            // Wird ausgelöst wenn ExoPlayer intern zum nächsten/vorherigen Titel wechselt
            val url = mediaItem?.mediaId?.takeIf { it.isNotBlank() } ?: return
            if (url == _currentMusicUrl.value) return
            _metadataJob?.cancel()
            _metadataJob = null
            _currentMusicUrl.value = url
            _musicIsPrepared.value = false
            _musicTotalMs.value = 0L
            _musicProgress.value = 0f
            _musicCurrentMs.value = 0L
            val cachedBitmap = _musicCoverCache.get(url)
            _musicCoverBitmap.value = cachedBitmap
            _musicTitle.value = if (cachedBitmap != null) "Musik" else "Wird geladen…"
            _musicArtist.value = ""
            _metadataJob = viewModelScope.launch(kotlinx.coroutines.Dispatchers.IO) {
                try {
                    val cached = musicMetadataDao.getByUrl(url)
                    if (cached != null) {
                        var bm = _musicCoverCache.get(url)
                        if (bm == null && cached.coverPath != null) {
                            bm = decodeSampledBitmapFromFile(cached.coverPath)
                            if (bm != null) _musicCoverCache.put(url, bm)
                        }
                        _musicTitle.value = if (!cached.title.isNullOrBlank()) cached.title else musicFallbackTitle(url)
                        if (!cached.artist.isNullOrBlank()) _musicArtist.value = cached.artist
                        if (bm != null) _musicCoverBitmap.value = bm
                        updateMediaSessionMetadata()
                        _musicNotificationManager?.invalidate()
                        return@launch
                    }
                    val retriever = android.media.MediaMetadataRetriever()
                    val lp = mediaCache.getCachedPath(url, "misc")
                        ?: if (_currentMusicChatId.isNotBlank()) mediaCache.getCachedPathForChat(url, _currentMusicChatId, "audio") else null
                    val t: String?
                    val a: String?
                    val durStr: String?
                    val art: ByteArray?
                    // release() in finally: bei Exception (z.B. Netzwerk-Audio nicht erreichbar)
                    // wurde der Retriever bisher nicht freigegeben → Datenquelle/Speicher leckte.
                    try {
                        if (lp != null) {
                            retriever.setDataSource(lp)
                        } else {
                            retriever.setDataSource(toAbsoluteUrl(url), HashMap<String, String>())
                        }
                        t = retriever.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_TITLE)
                        a = retriever.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_ARTIST)
                        durStr = retriever.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_DURATION)
                        art = retriever.embeddedPicture
                    } finally {
                        retriever.release()
                    }
                    _musicTitle.value = if (!t.isNullOrBlank()) t else musicFallbackTitle(url)
                    if (!a.isNullOrBlank()) _musicArtist.value = a
                    _musicTitleArtistCache[url] = Pair(
                        if (!t.isNullOrBlank()) t else null,
                        if (!a.isNullOrBlank()) a else null
                    )
                    var coverPath: String? = null
                    if (art != null) {
                        val bm = decodeSampledBitmap(art)
                        if (bm != null) {
                            _musicCoverBitmap.value = bm
                            _musicCoverCache.put(url, bm)
                            val coverDir = java.io.File(context.cacheDir, "music_covers").also { it.mkdirs() }
                            val file = java.io.File(coverDir, "${url.hashCode()}.jpg")
                            try { file.outputStream().use { it.write(art) }; coverPath = file.absolutePath } catch (_: Exception) {}
                        }
                    }
                    musicMetadataDao.upsert(com.securechat.app.data.local.MusicMetadataEntity(
                        url = url, title = t, artist = a, coverPath = coverPath,
                        durationMs = durStr?.toLongOrNull() ?: 0L, cachedAt = System.currentTimeMillis()
                    ))
                    persistMusicMetadata(url, t, a, ((durStr?.toLongOrNull() ?: 0L) / 1000L).toInt().takeIf { it > 0 })
                    updateMediaSessionMetadata()
                    _musicNotificationManager?.invalidate()
                } catch (_: Exception) {
                    // Extraktion fehlgeschlagen (z.B. Netzwerk-Audio nicht lesbar) – nicht auf
                    // "Wird geladen…" hängen bleiben, sondern Fallback-Titel anzeigen.
                    if (_currentMusicUrl.value == url && _musicTitle.value == "Wird geladen…") {
                        _musicTitle.value = musicFallbackTitle(url)
                        updateMediaSessionMetadata()
                        _musicNotificationManager?.invalidate()
                    }
                }
            }
        }
    }

    /** Erzeugt den ExoPlayer + MediaSession beim ersten Aufruf (lazy, Main-Thread). */
    private fun getOrCreateMusicPlayer(): androidx.media3.exoplayer.ExoPlayer {
        return _musicExoPlayer ?: run {
            val player = androidx.media3.exoplayer.ExoPlayer.Builder(context).build()
            player.addListener(musicPlayerListener)
            // MediaSession: verbindet ExoPlayer mit Androids Mediensteuerung
            // (Lockscreen, Benachrichtigungsbereich, Bluetooth-Headsets)
            val session = androidx.media3.session.MediaSession.Builder(context, player).build()
            _musicMediaSession = session
            _musicExoPlayer = player
            // Fortschritts-Polling (80 ms Intervall)
            _musicProgressJob = viewModelScope.launch {
                while (true) {
                    kotlinx.coroutines.delay(80)
                    if (_musicIsPlaying.value) {
                        val dur = player.duration.takeIf { it > 0L } ?: continue
                        _musicProgress.value = player.currentPosition.toFloat() / dur
                        _musicCurrentMs.value = player.currentPosition
                    }
                }
            }
            // PlayerNotificationManager: postet Medien-Benachrichtigung für Lockscreen & Notification-Shade
            val channelId = "lethe_music_playback"
            val notificationId = 1001
            if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.O) {
                val nm = context.getSystemService(android.app.NotificationManager::class.java)
                if (nm.getNotificationChannel(channelId) == null) {
                    val channel = android.app.NotificationChannel(
                        channelId, "Musik-Wiedergabe",
                        android.app.NotificationManager.IMPORTANCE_LOW
                    ).apply { description = "Lethe Musik-Player Steuerung" }
                    nm.createNotificationChannel(channel)
                }
            }
            val notifManager = androidx.media3.ui.PlayerNotificationManager.Builder(context, notificationId, channelId)
                .setMediaDescriptionAdapter(object : androidx.media3.ui.PlayerNotificationManager.MediaDescriptionAdapter {
                    override fun getCurrentContentTitle(p: androidx.media3.common.Player): CharSequence = _musicTitle.value
                    override fun createCurrentContentIntent(p: androidx.media3.common.Player): android.app.PendingIntent? = null
                    override fun getCurrentContentText(p: androidx.media3.common.Player): CharSequence = _musicArtist.value
                    override fun getCurrentLargeIcon(p: androidx.media3.common.Player, callback: androidx.media3.ui.PlayerNotificationManager.BitmapCallback): android.graphics.Bitmap? = _musicCoverBitmap.value
                })
                .setNotificationListener(object : androidx.media3.ui.PlayerNotificationManager.NotificationListener {
                    override fun onNotificationCancelled(notifId: Int, dismissedByUser: Boolean) { player.pause() }
                })
                .build()
            @Suppress("DEPRECATION")
            notifManager.setMediaSessionToken(session.sessionCompatToken)
            notifManager.setPlayer(player)
            _musicNotificationManager = notifManager
            player
        }
    }

    /**
     * Fordert Audio-Fokus für Musik-Wiedergabe an (pausiert andere Audio-Apps).
     * AUDIOFOCUS_GAIN_TRANSIENT (statt _GAIN): so pausiert die zuvor laufende Wiedergabe – egal
     * ob eine andere App (Podcast/Musik) oder ein anderes Lethe-Playback – nur vorübergehend und
     * läuft nach dem Ende der Musik automatisch wieder weiter.
     */
    private fun requestMusicAudioFocus() {
        val audioManager = context.getSystemService(android.content.Context.AUDIO_SERVICE) as android.media.AudioManager
        // Manueller/frischer Start: eine evtl. gemerkte Fokusverlust-Pause verwerfen.
        _musicPausedByFocusLoss = false
        if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.O) {
            // Vorherige Anfrage zuerst freigeben, damit eine neue erstellt werden kann
            _musicAudioFocusRequest?.let { audioManager.abandonAudioFocusRequest(it) }
            _musicAudioFocusRequest = null
            val req = android.media.AudioFocusRequest.Builder(android.media.AudioManager.AUDIOFOCUS_GAIN_TRANSIENT)
                .setAudioAttributes(
                    android.media.AudioAttributes.Builder()
                        .setUsage(android.media.AudioAttributes.USAGE_MEDIA)
                        .setContentType(android.media.AudioAttributes.CONTENT_TYPE_MUSIC)
                        .build()
                )
                .setOnAudioFocusChangeListener(_musicAudioFocusLegacyListener)
                .build()
            _musicAudioFocusRequest = req
            audioManager.requestAudioFocus(req)
        } else {
            @Suppress("DEPRECATION")
            audioManager.requestAudioFocus(
                _musicAudioFocusLegacyListener,
                android.media.AudioManager.STREAM_MUSIC,
                android.media.AudioManager.AUDIOFOCUS_GAIN_TRANSIENT
            )
        }
    }

    /** Gibt Audio-Fokus zurück (andere Apps können wieder Ton ausgeben). */
    private fun abandonMusicAudioFocus() {
        val audioManager = context.getSystemService(android.content.Context.AUDIO_SERVICE) as android.media.AudioManager
        _musicPausedByFocusLoss = false
        if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.O) {
            _musicAudioFocusRequest?.let { audioManager.abandonAudioFocusRequest(it) }
            _musicAudioFocusRequest = null
        } else {
            @Suppress("DEPRECATION")
            audioManager.abandonAudioFocus(_musicAudioFocusLegacyListener)
        }
    }

    /** Setzt die Playlist des aktiven Chats (für Prev/Next). */
    fun setMusicChatUrls(urls: List<String>, chatId: String = "") {
        _musicChatUrlList.clear()
        _musicChatUrlList.addAll(urls)
        if (chatId.isNotBlank()) _currentMusicChatId = chatId
    }

    /** Startet oder pausiert ein Lied. Bei URL-Wechsel startet das neue Lied neu. */
    fun toggleMusicPlayback(url: String, chatUrls: List<String>) {
        viewModelScope.launch(kotlinx.coroutines.Dispatchers.Main) {
            setMusicChatUrls(chatUrls)
            val player = getOrCreateMusicPlayer()
            if (_currentMusicUrl.value == url) {
                // Gleiches Lied: Play/Pause toggeln
                if (player.isPlaying) {
                    player.pause()
                    abandonMusicAudioFocus()
                } else {
                    requestMusicAudioFocus()
                    player.play()
                }
            } else {
                // Neues Lied: Metadaten laden und abspielen
                playMusicInternally(url, player)
            }
        }
    }

    private fun playMusicInternally(url: String, player: androidx.media3.exoplayer.ExoPlayer) {
        // Vorherigen Metadaten-Job abbrechen (verhindert gleichzeitige MediaMetadataRetriever-Instanzen → OOM)
        _metadataJob?.cancel()
        _metadataJob = null

        _currentMusicUrl.value = url
        _musicIsPrepared.value = false
        _musicTotalMs.value = 0L
        _musicProgress.value = 0f
        _musicCurrentMs.value = 0L

        // Meistgehört-Zähler erhöhen (teilt sich SharedPreferences mit dem Mini-Player)
        com.securechat.app.MusicPlayCountStore.increment(context, url)

        // In-Memory-Cache prüfen (schnell)
        val cachedBitmap = _musicCoverCache.get(url)
        _musicCoverBitmap.value = cachedBitmap
        _musicTitle.value = if (cachedBitmap != null) "Musik" else "Wird geladen…"
        _musicArtist.value = ""
        // Cover-URL für Chromecast: /mc/-Endpoint extrahiert APIC-Tag aus der Audio-Datei
        _musicCoverUrl.value = buildCoverUrl(url)

        // Gesamte Playlist laden damit ExoPlayer Next/Prev-Buttons in der Benachrichtigung korrekt anzeigt
        val allItems = _musicChatUrlList.map { itemUrl ->
            val cp = mediaCache.getCachedPath(itemUrl, "misc")
                ?: if (_currentMusicChatId.isNotBlank()) mediaCache.getCachedPathForChat(itemUrl, _currentMusicChatId, "audio") else null
            val uri = if (cp != null) android.net.Uri.fromFile(java.io.File(cp)) else android.net.Uri.parse(toAbsoluteUrl(itemUrl))
            androidx.media3.common.MediaItem.Builder()
                .setUri(uri)
                .setMediaId(itemUrl)
                // requestMetadata.mediaUri = anonymisierte HTTP-URL für Cast (kein /uploads/-Pfad sichtbar)
                .setRequestMetadata(
                    androidx.media3.common.MediaItem.RequestMetadata.Builder()
                        .setMediaUri(android.net.Uri.parse(toCastUrl(itemUrl)))
                        .build()
                )
                .build()
        }
        val startIndex = _musicChatUrlList.indexOf(url).coerceAtLeast(0)
        if (allItems.isNotEmpty()) {
            player.setMediaItems(allItems, startIndex, 0L)
        } else {
            val cp = mediaCache.getCachedPath(url, "misc")
                ?: if (_currentMusicChatId.isNotBlank()) mediaCache.getCachedPathForChat(url, _currentMusicChatId, "audio") else null
            val uri = if (cp != null) android.net.Uri.fromFile(java.io.File(cp)) else android.net.Uri.parse(toAbsoluteUrl(url))
            player.setMediaItem(
                androidx.media3.common.MediaItem.Builder()
                    .setUri(uri)
                    .setMediaId(url)
                    .setRequestMetadata(
                        androidx.media3.common.MediaItem.RequestMetadata.Builder()
                            .setMediaUri(android.net.Uri.parse(toCastUrl(url)))
                            .build()
                    )
                    .build()
            )
        }
        player.prepare()
        requestMusicAudioFocus()
        player.play()

        // Metadaten asynchron laden (DB-Cache zuerst, dann Netzwerk)
        _metadataJob = viewModelScope.launch(kotlinx.coroutines.Dispatchers.IO) {
            try {
                // 1. DB-Cache prüfen
                val cached = musicMetadataDao.getByUrl(url)
                if (cached != null) {
                    val title = cached.title
                    val artist = cached.artist
                    var bm = _musicCoverCache.get(url)
                    if (bm == null && cached.coverPath != null) {
                        bm = decodeSampledBitmapFromFile(cached.coverPath)
                        if (bm != null) _musicCoverCache.put(url, bm)
                    }
                    _musicTitle.value = if (!title.isNullOrBlank()) title else musicFallbackTitle(url)
                    if (!artist.isNullOrBlank()) _musicArtist.value = artist
                    _musicTitleArtistCache[url] = Pair(
                        if (!title.isNullOrBlank()) title else null,
                        if (!artist.isNullOrBlank()) artist else null
                    )
                    if (bm != null) _musicCoverBitmap.value = bm
                    updateMediaSessionMetadata()
                    _musicNotificationManager?.invalidate()
                    return@launch
                }

                // 2. Netzwerk-Laden (nur wenn kein DB-Cache)
                val retriever = android.media.MediaMetadataRetriever()
                val localPath = mediaCache.getCachedPath(url, "misc")
                    ?: if (_currentMusicChatId.isNotBlank()) mediaCache.getCachedPathForChat(url, _currentMusicChatId, "audio") else null
                val t: String?
                val a: String?
                val durStr: String?
                val art: ByteArray?
                // release() in finally: bei Exception wird der Retriever sonst nicht freigegeben → Leck.
                try {
                    if (localPath != null) {
                        retriever.setDataSource(localPath)
                    } else {
                        retriever.setDataSource(toAbsoluteUrl(url), HashMap<String, String>())
                    }
                    t   = retriever.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_TITLE)
                    a   = retriever.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_ARTIST)
                    durStr = retriever.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_DURATION)
                    art = retriever.embeddedPicture
                } finally {
                    retriever.release()
                }

                _musicTitle.value = if (!t.isNullOrBlank()) t else musicFallbackTitle(url)
                if (!a.isNullOrBlank()) _musicArtist.value = a
                _musicTitleArtistCache[url] = Pair(
                    if (!t.isNullOrBlank()) t else null,
                    if (!a.isNullOrBlank()) a else null
                )

                var coverPath: String? = null
                if (art != null) {
                    val bm = decodeSampledBitmap(art)
                    if (bm != null) {
                        _musicCoverBitmap.value = bm
                        _musicCoverCache.put(url, bm)
                        // Cover auf Disk speichern
                        val coverDir = java.io.File(context.cacheDir, "music_covers").also { it.mkdirs() }
                        val file = java.io.File(coverDir, "${url.hashCode()}.jpg")
                        try { file.outputStream().use { it.write(art) }; coverPath = file.absolutePath } catch (_: Exception) {}
                    }
                }

                // In DB-Cache schreiben
                musicMetadataDao.upsert(com.securechat.app.data.local.MusicMetadataEntity(
                    url = url,
                    title = t,
                    artist = a,
                    coverPath = coverPath,
                    durationMs = durStr?.toLongOrNull() ?: 0L,
                    cachedAt = System.currentTimeMillis()
                ))

                updateMediaSessionMetadata()
                _musicNotificationManager?.invalidate()
            } catch (_: Exception) {
                // Extraktion fehlgeschlagen (z.B. Netzwerk-Audio nicht lesbar) – nicht auf
                // "Wird geladen…" hängen bleiben, sondern Fallback-Titel anzeigen.
                if (_currentMusicUrl.value == url && _musicTitle.value == "Wird geladen…") {
                    _musicTitle.value = musicFallbackTitle(url)
                    updateMediaSessionMetadata()
                    _musicNotificationManager?.invalidate()
                }
            }
        }
    }

    /** Aktualisiert das MediaItem des ExoPlayers mit aktuellen Metadaten (für Mediensteuerung). */
    private suspend fun updateMediaSessionMetadata() {
        withContext(kotlinx.coroutines.Dispatchers.Main) {
            val meta = androidx.media3.common.MediaMetadata.Builder()
                .setTitle(_musicTitle.value)
                .setArtist(_musicArtist.value)
                .apply {
                    val bm = _musicCoverBitmap.value
                    if (bm != null) {
                        val stream = java.io.ByteArrayOutputStream()
                        bm.compress(android.graphics.Bitmap.CompressFormat.JPEG, 90, stream)
                        setArtworkData(stream.toByteArray(), androidx.media3.common.MediaMetadata.PICTURE_TYPE_FRONT_COVER)
                    }
                }
                .build()
            val updatedItem = _musicExoPlayer?.currentMediaItem?.buildUpon()?.setMediaMetadata(meta)?.build()
            if (updatedItem != null) {
                _musicExoPlayer?.replaceMediaItem(_musicExoPlayer?.currentMediaItemIndex ?: 0, updatedItem)
            }

            // Cast-Metadaten aktualisieren wenn Cast aktiv ist
            if (castDiscoveryManager.isCasting.value) {
                val castUrl = _currentMusicUrl.value
                if (castUrl != null && castDiscoveryManager.castCurrentUrl.value == castUrl) {
                    val castMeta = buildCurrentMusicCastMetadata()
                    castDiscoveryManager.loadUrlOnCast(castUrl, castMeta)
                }
            }
        }
    }

    /** Seekbar: Spring zu einer bestimmten Position in Millisekunden. */
    fun seekMusicTo(ms: Long) {
        viewModelScope.launch(kotlinx.coroutines.Dispatchers.Main) {
            val player = _musicExoPlayer ?: return@launch
            player.seekTo(ms)
            _musicCurrentMs.value = ms
            val dur = player.duration.takeIf { it > 0L } ?: return@launch
            _musicProgress.value = ms.toFloat() / dur
        }
    }

    /** Springt zum nächsten Lied im Chat (oder stoppt am Ende). */
    fun skipToNextMusic() {
        viewModelScope.launch(kotlinx.coroutines.Dispatchers.Main) {
            val player = _musicExoPlayer ?: return@launch
            if (player.hasNextMediaItem()) player.seekToNextMediaItem()
        }
    }

    /** Springt zum vorherigen Lied (oder startet das aktuelle neu wenn > 3 Sek gespielt). */
    fun skipToPrevMusic() {
        viewModelScope.launch(kotlinx.coroutines.Dispatchers.Main) {
            val player = _musicExoPlayer ?: return@launch
            // seekToPrevious: startet aktuelles neu wenn >3s gespielt, sonst vorheriges Lied
            player.seekToPrevious()
        }
    }

    /**
     * Lädt ID3-Tags + Cover aller Musik-URLs im Chat vorab und speichert sie in der DB.
     * Beim nächsten Öffnen wird alles aus dem DB-Cache geladen (kein Netzwerk nötig).
     */
    fun prefetchMusicMetadata(urls: List<String>) {
        if (urls.isEmpty()) return
        viewModelScope.launch(kotlinx.coroutines.Dispatchers.IO) {
            val coverDir = java.io.File(context.cacheDir, "music_covers").also { it.mkdirs() }
            // Batch-Query statt N+1 Einzelabfragen
            val urlsToFetch = urls.filter { _musicCoverCache.get(it) == null }
            if (urlsToFetch.isEmpty()) return@launch
            val cachedEntries = musicMetadataDao.getByUrls(urlsToFetch).associateBy { it.url }
            for (url in urlsToFetch) {
                // In-Memory-Cache bereits vorhanden → überspringen
                if (_musicCoverCache.get(url) != null) continue
                // DB-Cache prüfen
                val cached = cachedEntries[url]
                if (cached != null) {
                    if (cached.coverPath != null) {
                        val bm = decodeSampledBitmapFromFile(cached.coverPath)
                        if (bm != null) _musicCoverCache.put(url, bm)
                    }
                    _musicTitleArtistCache[url] = Pair(cached.title, cached.artist)
                    continue
                }
                // Netzwerk-Laden (bevorzugt lokale Datei für zuverlässige Cover-Extraktion)
                try {
                    val retriever = android.media.MediaMetadataRetriever()
                    val lp = mediaCache.getCachedPath(url, "misc")
                        ?: if (_currentMusicChatId.isNotBlank()) mediaCache.getCachedPathForChat(url, _currentMusicChatId, "audio") else null
                    val title: String?
                    val artist: String?
                    val durStr: String?
                    val art: ByteArray?
                    // release() in finally: prefetch läuft über viele URLs in einer Schleife –
                    // ohne finally leckte bei jedem fehlgeschlagenen setDataSource ein Retriever.
                    try {
                        if (lp != null) {
                            retriever.setDataSource(lp)
                        } else {
                            retriever.setDataSource(toAbsoluteUrl(url), HashMap<String, String>())
                        }
                        title   = retriever.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_TITLE)
                        artist  = retriever.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_ARTIST)
                        durStr  = retriever.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_DURATION)
                        art     = retriever.embeddedPicture
                    } finally {
                        retriever.release()
                    }
                    _musicTitleArtistCache[url] = Pair(title, artist)
                    var coverPath: String? = null
                    if (art != null) {
                        val bm = decodeSampledBitmap(art)
                        if (bm != null) {
                            _musicCoverCache.put(url, bm)
                            val file = java.io.File(coverDir, "${url.hashCode()}.jpg")
                            try { file.outputStream().use { it.write(art) }; coverPath = file.absolutePath } catch (_: Exception) {}
                        }
                    }
                    musicMetadataDao.upsert(com.securechat.app.data.local.MusicMetadataEntity(
                        url = url,
                        title = title,
                        artist = artist,
                        coverPath = coverPath,
                        durationMs = durStr?.toLongOrNull() ?: 0L,
                        cachedAt = System.currentTimeMillis()
                    ))
                } catch (_: Exception) {}
            }
        }
    }

