    /** State für eingehende Handshake-Erneuerungsanfragen. */
    private val _incomingHandshakeRenew = MutableStateFlow<IncomingHandshakeRenew?>(null)
    val incomingHandshakeRenew: StateFlow<IncomingHandshakeRenew?> = _incomingHandshakeRenew.asStateFlow()

    /** Link-Vorschau aus OG-Tags (wird beim URL-Tippen geladen). */
    private val _linkPreview = MutableStateFlow<LinkPreviewData?>(null)
    val linkPreview: StateFlow<LinkPreviewData?> = _linkPreview.asStateFlow()

    /** Ladeindikator für Link-Vorschau. */
    private val _linkPreviewLoading = MutableStateFlow(false)
    val linkPreviewLoading: StateFlow<Boolean> = _linkPreviewLoading.asStateFlow()

    /** Geteilter OkHttpClient für Link-Vorschau – einmalig erstellt, nie weggeworfen. */
    private val linkPreviewHttpClient by lazy {
        OkHttpClient.Builder()
            .followRedirects(true)
            .connectTimeout(8, java.util.concurrent.TimeUnit.SECONDS)
            .readTimeout(8, java.util.concurrent.TimeUnit.SECONDS)
            .build()
    }

    /** Debounced Job für URL-Analyse + Draft-Speicherung beim Tippen. */
    private var analyzeAndSaveDraftJob: Job? = null

    /** Wird aus dem UI-Layer bei jeder Text-Änderung aufgerufen.
     *  Debounce 500 ms → analyzeAndSaveDraft auf Hintergrund-Threads. */
    fun onChatTextChanged(chatId: String, text: String) {
        analyzeAndSaveDraftJob?.cancel()
        analyzeAndSaveDraftJob = viewModelScope.launch {
            delay(500)
            analyzeAndSaveDraft(chatId, text)
        }
    }

    private val chatInputUrlRegex = Regex("""(?:https?://[^\s]+|lethe://(?:post|sp|li)\?[^\s]*)""")

    private suspend fun analyzeAndSaveDraft(chatId: String, text: String) {
        if (text.length > 50_000) return
        // URL-Erkennung auf Default-Dispatcher (off main thread)
        val foundUrl = withContext(Dispatchers.Default) {
            chatInputUrlRegex.find(text)?.value
                ?.trimEnd('.', ',', '!', '?', ';', ':', ')', ']', '}', '"', '\'')
        }
        if (foundUrl != null) {
            fetchLinkPreview(foundUrl)
        } else {
            clearLinkPreview()
        }
        // Entwurf persistieren
        withContext(Dispatchers.IO) {
            saveChatDraft(chatId, text)
        }
    }

