    /** Verbindet den Billing-Provider und setzt den Server-Callback. Aus CoinsScreen aufrufen. */
    fun initBilling() {
        billingProvider.onPurchaseReady = { purchaseInfo ->
            handleCoinPurchase(purchaseInfo).also { added ->
