    // ── STRIPE PAYMENT ────────────────────────────────────────────────────────

    /**
     * Erstellt einen Stripe PaymentIntent für den Styx-Beutel (6,50 €) und liefert
     * (clientSecret, publishableKey) zurück. Bei Fehler wird (null, null) zurückgegeben.
     */
    fun createStripePaymentIntent(onResult: (clientSecret: String?, publishableKey: String?) -> Unit) {
        viewModelScope.launch {
            try {
                val response = apiService.createStripePaymentIntent()
                if (response.isSuccessful) {
                    val body = response.body()
                    onResult(body?.clientSecret, body?.publishableKey)
                } else {
                    onResult(null, null)
                }
            } catch (e: Exception) {
                Timber.tag("MainViewModel").e("createStripePaymentIntent fehlgeschlagen: ${e.message}")
                onResult(null, null)
            }
        }
    }

    /**
     * Bucht Styx nach erfolgreichem Stripe-Kauf auf dem Server gut.
     * [paymentIntentId] ist der PI-Teil aus dem clientSecret (vor "_secret_").
     */
    fun onStripePaymentCompleted(paymentIntentId: String) {
        viewModelScope.launch {
            try {
                val response = apiService.confirmStripePayment(mapOf("payment_intent_id" to paymentIntentId))
                if (response.isSuccessful) {
                    val body = response.body()
                    val added = body?.get("added")?.toString()?.toDoubleOrNull()?.toInt() ?: 0
                    val newBalance = body?.get("new_balance")?.toString()?.toDoubleOrNull()?.toInt()
                    if (added > 0) _billingMessage.value = "+$added Styx gutgeschrieben!"
                    if (newBalance != null) {
                        val updated = _currentUser.value?.copy(styx = newBalance)
                        if (updated != null) {
                            userDao.insertUser(updated)
                            _currentUser.value = updated
                        }
                    }
                }
            } catch (e: Exception) {
                Timber.tag("MainViewModel").e("onStripePaymentCompleted fehlgeschlagen: ${e.message}")
            }
        }
    }

    // ── CREATOR AUSZAHLUNG ────────────────────────────────────────────────────

    /** Beantragt eine Diamant-Auszahlung per SEPA. */
    fun requestCreatorPayout(
        iban: String,
        name: String,
        email: String,
        onResult: (success: Boolean, message: String) -> Unit
    ) {
        viewModelScope.launch {
            try {
                val response = apiService.requestCreatorPayout(
                    com.securechat.app.data.network.CreatorPayoutRequest(iban = iban, name = name, email = email)
                )
                if (response.isSuccessful) {
                    val body = response.body()
                    if (body?.success == true) {
                        _creatorDiamonds.value = (_creatorDiamonds.value - (body.diamondsDeducted)).coerceAtLeast(0)
                        onResult(true, body.message)
                    } else {
                        onResult(false, body?.message ?: "Fehler bei der Auszahlung.")
                    }
                } else {
                    onResult(false, "Auszahlung fehlgeschlagen (${response.code()}).")
                }
            } catch (e: Exception) {
                Timber.tag("MainViewModel").e("requestCreatorPayout fehlgeschlagen: ${e.message}")
                onResult(false, "Netzwerkfehler. Bitte erneut versuchen.")
            }
        }
    }

    /** Tauscht empfangene Creator-Styx in Diamanten um (1:1). */
    fun convertStyxToDiamonds(
        amount: Int,
        onResult: (success: Boolean, message: String) -> Unit
    ) {
        viewModelScope.launch {
            try {
                val response = apiService.convertStyxToDiamonds(
                    com.securechat.app.data.network.StyxToDiamondsRequest(amount = amount)
                )
                if (response.isSuccessful) {
                    val body = response.body()
                    if (body?.success == true) {
                        _creatorStyxReceived.value = body.newStyxReceived
                        _creatorDiamonds.value = body.newDiamonds
                        onResult(true, body.message)
                    } else {
                        onResult(false, body?.message ?: "Tausch fehlgeschlagen.")
                    }
                } else {
                    onResult(false, "Tausch fehlgeschlagen (${response.code()}).")
                }
            } catch (e: Exception) {
                Timber.tag("MainViewModel").e("convertStyxToDiamonds fehlgeschlagen: ${e.message}")
                onResult(false, "Netzwerkfehler. Bitte erneut versuchen.")
            }
        }
    }

    fun transferStyx(
        amount: Int,
        direction: String,
        onResult: (success: Boolean, message: String) -> Unit
    ) {
        viewModelScope.launch {
            try {
                val response = apiService.transferStyx(
                    com.securechat.app.data.network.StyxTransferRequest(amount = amount, direction = direction)
                )
                if (response.isSuccessful) {
                    val body = response.body()
                    if (body?.success == true) {
                        _currentUser.value = _currentUser.value?.copy(styx = body.newUserStyx)
                        _creatorStyxReceived.value = body.newCreatorStyx
                        onResult(true, body.message)
                    } else {
                        onResult(false, body?.message ?: "Übertragung fehlgeschlagen.")
                    }
                } else {
                    onResult(false, "Übertragung fehlgeschlagen (${response.code()}).")
                }
            } catch (e: Exception) {
                Timber.tag("MainViewModel").e("transferStyx fehlgeschlagen: ${e.message}")
                onResult(false, "Netzwerkfehler. Bitte erneut versuchen.")
            }
        }
    }

