    /**
     * Erstellt einen synthetischen Feed-Eintrag für eine rohe HLS-Playlist-URL und stellt ihn
     * an Position 0. SparksFeedScreen spielt ihn sofort ab und setzt danach mit dem normalen
     * Feed fort. Wird z.B. bei Deep-Links (lethe://sp?url=…) oder geteilten Links aufgerufen.
     */
    fun prependSparkUrlToFeed(url: String) {
        val absoluteUrl = if (url.startsWith("http")) url else "https://letheapp.de$url"
        val syntheticId = "url_spark_${absoluteUrl.hashCode()}"
        val syntheticSpark = com.securechat.app.data.network.CreatorContentResponse(
            id = syntheticId,
            creatorId = "",
            mediaType = "spark",
            mediaUrl = absoluteUrl
        )
        val withoutDuplicate = _vipFeed.value.filter { it.id != syntheticId }
        _vipFeed.value = listOf(syntheticSpark) + withoutDuplicate
        _feedScrollToTop.value = true
    }

    /** Entfernt alle synthetischen URL-Sparks aus dem Feed (beim Verlassen des SparksFeedScreen). */
    fun clearSyntheticSparks() {
        _vipFeed.value = _vipFeed.value.filter { !it.id.startsWith("url_spark_") }
    }

