    private fun loadPinnedItems() {
        _pinnedGroupIds.value = pinnedPrefs.getStringSet("pinned_groups", emptySet()) ?: emptySet()
        _pinnedContactIds.value = pinnedPrefs.getStringSet("pinned_contacts", emptySet()) ?: emptySet()
    }

    fun toggleGroupPin(groupId: String) {
        val current = _pinnedGroupIds.value.toMutableSet()
        if (current.contains(groupId)) {
            current.remove(groupId)
        } else if (current.size < 2) {
            current.add(groupId)
        }
        _pinnedGroupIds.value = current
        pinnedPrefs.edit().putStringSet("pinned_groups", current).apply()
    }

    fun toggleContactPin(userId: String) {
        val current = _pinnedContactIds.value.toMutableSet()
        if (current.contains(userId)) current.remove(userId) else current.add(userId)
        _pinnedContactIds.value = current
        pinnedPrefs.edit().putStringSet("pinned_contacts", current).apply()
    }

