    private var isListeningToWebSocket = false

    /**
     * Lädt Waveform-Daten für eine Audio-URL (lazy, gecacht).
     * Der erste Aufruf startet die Analyse im IO-Thread.
     */
    fun loadWaveformForUrl(url: String) {
        if (url.isBlank() || _waveformCache.get(url) != null) return
        viewModelScope.launch(Dispatchers.IO) {
            val localFile = mediaCache.get(url, "audio")
            val sourcePath = localFile?.absolutePath ?: url
            val data = AudioWaveformAnalyzer.analyze(sourcePath)
            _waveformCache.put(url, data)
            _waveformMap.value = buildMap { putAll(_waveformCache.snapshot()) }
        }
    }

    /** Gibt die gecachte (oder heruntergeladene) Mediendatei zurück. */
    suspend fun getMediaFile(url: String, subDir: String, extension: String? = null): java.io.File? =
        mediaCache.get(url, subDir, extension)

    // URLs der Medien-Dateien die zum aktuell geöffneten Chat gehören
    private val _chatMediaUrls = mutableSetOf<String>()

    /**
     * Lädt Medien-Dateien für einen Chat-Bereich vorab herunter (Disk-Cache).
     * Wird beim Öffnen des Chats und beim Scrollen aufgerufen.
     *
     * @param messages    Vollständige Nachrichten-Liste des Chats
     * @param chatId      Chat-ID (für chat-spezifisches Cache-Verzeichnis)
     * @param startIdx    Erster zu ladender Index (inklusiv, 0 = neueste Nachricht)
     * @param endIdx      Letzter zu ladender Index (inklusiv)
     */
    fun preloadChatMedia(
        messages: List<com.securechat.app.data.local.MessageEntity>,
        chatId: String,
        startIdx: Int,
        endIdx: Int
    ) {
        val from = startIdx.coerceAtLeast(0)
        val to = endIdx.coerceAtMost(messages.size - 1)
        if (from > to) return

        viewModelScope.launch(Dispatchers.IO) {
            for (i in from..to) {
                val msg = messages.getOrNull(i) ?: continue
                val url = msg.mediaUrl?.takeIf { it.isNotBlank() } ?: continue
                _chatMediaUrls.add(url)
                when (msg.mediaType) {
                    "image" -> mediaCache.getForChat(url, chatId, "images")
                    "audio" -> {
                        mediaCache.getForChat(url, chatId, "audio")
                        if (_waveformCache.get(url) == null) loadWaveformForUrl(url)
                    }
                    "audio_music" -> mediaCache.getForChat(url, chatId, "audio")
                    "video" -> {
                        if (_videoThumbnailCache.get(url) == null) loadVideoThumbnailFromUrl(url)
                    }
                    "3dprint" -> {
                        try {
                            val meta = com.google.gson.Gson().fromJson(
                                msg.content, ThreeDFileMeta::class.java
                            )
                            meta?.previewUrl?.takeIf { it.isNotBlank() }?.let { previewUrl ->
                                _chatMediaUrls.add(previewUrl)
                                mediaCache.getForChat(previewUrl, chatId, "3d")
                            }
                        } catch (_: Exception) {}
                    }
                }
            }
        }
    }

    /**
     * Speichert ein Thumbnail manuell (z.B. nach Transkodierung) unter einem Schlüssel (clientId oder URL).
     */
    fun cacheVideoThumbnail(key: String, bitmap: Bitmap) {
        val scaled = scaleBitmapToMaxWidth(bitmap, 320)
        _videoThumbnailCache.put(key, scaled)
        _videoThumbnailMap.value = buildMap {
            val snap = _videoThumbnailCache.snapshot()
            putAll(snap)
        }
    }

    private fun scaleBitmapToMaxWidth(src: Bitmap, maxWidth: Int): Bitmap {
        if (src.width <= maxWidth) return src
        val scale = maxWidth.toFloat() / src.width
        val h = (src.height * scale).toInt()
        return Bitmap.createScaledBitmap(src, maxWidth, h, true)
    }

    /**
     * Berechnet inSampleSize, damit ein Bild beim Dekodieren direkt auf maximal [maxDim]
     * verkleinert wird – ohne das volle (ggf. mehrere Dutzend MB große) Bitmap zuerst in
     * den Speicher zu laden. Verhindert OOM bei hochauflösenden eingebetteten Cover-Bildern.
     */
    private fun calcInSampleSize(width: Int, height: Int, maxDim: Int): Int {
        var sample = 1
        var w = width
        var h = height
        while (w / 2 >= maxDim && h / 2 >= maxDim) {
            w /= 2; h /= 2; sample *= 2
        }
        return sample
    }

    /** Dekodiert ein Bild aus Bytes verkleinert (max [maxDim] px Kantenlänge). */
    private fun decodeSampledBitmap(bytes: ByteArray, maxDim: Int = 512): Bitmap? {
        return try {
            val bounds = android.graphics.BitmapFactory.Options().apply { inJustDecodeBounds = true }
            android.graphics.BitmapFactory.decodeByteArray(bytes, 0, bytes.size, bounds)
            val opts = android.graphics.BitmapFactory.Options().apply {
                inSampleSize = calcInSampleSize(bounds.outWidth, bounds.outHeight, maxDim)
            }
            android.graphics.BitmapFactory.decodeByteArray(bytes, 0, bytes.size, opts)
        } catch (_: Throwable) { null }
    }

    /** Dekodiert ein Bild aus einer Datei verkleinert (max [maxDim] px Kantenlänge). */
    private fun decodeSampledBitmapFromFile(path: String, maxDim: Int = 512): Bitmap? {
        return try {
            val bounds = android.graphics.BitmapFactory.Options().apply { inJustDecodeBounds = true }
            android.graphics.BitmapFactory.decodeFile(path, bounds)
            val opts = android.graphics.BitmapFactory.Options().apply {
                inSampleSize = calcInSampleSize(bounds.outWidth, bounds.outHeight, maxDim)
            }
            android.graphics.BitmapFactory.decodeFile(path, opts)
        } catch (_: Throwable) { null }
    }

    /**
     * Lädt ein Video-Thumbnail: Versucht zuerst die serverseitig generierte _thumb.jpg
     * (schnell, klein), dann Fallback auf MediaMetadataRetriever.
     */
    fun loadVideoThumbnailFromUrl(url: String): Job? {
        if (url.isBlank() || _videoThumbnailCache.get(url) != null) return null
        // Duplikat-Guard: dieselbe URL nicht mehrfach parallel verarbeiten
        if (thumbnailInProgress.putIfAbsent(url, true) != null) return null
        return viewModelScope.launch(Dispatchers.IO) {
            // Warteschlange: maximal 2 Thumbnails gleichzeitig generieren
            thumbnailSemaphore.acquire()
            try {
                // 1. Versuch: Server-Thumbnail (_thumb.jpg neben dem Video)
                // z.B. .../media_5_abc.mp4 → .../media_5_abc_thumb.jpg
                val thumbUrl = url.substringBeforeLast(".") + "_thumb.jpg"
                val serverThumb = runCatching {
                    val req = okhttp3.Request.Builder()
                        .url(thumbUrl)
                        .header("User-Agent", "LetheApp/1.0")
                        .build()
                    val resp = okhttp3.OkHttpClient.Builder()
                        .connectTimeout(5, java.util.concurrent.TimeUnit.SECONDS)
                        .readTimeout(10, java.util.concurrent.TimeUnit.SECONDS)
                        .build()
                        .newCall(req).execute()
                    if (resp.isSuccessful) {
                        resp.body?.byteStream()?.let { android.graphics.BitmapFactory.decodeStream(it) }
                    } else null
                }.getOrNull()

                if (serverThumb != null) {
                    val scaled = scaleBitmapToMaxWidth(serverThumb, 320)
                    if (serverThumb !== scaled) serverThumb.recycle()
                    _videoThumbnailCache.put(url, scaled)
                    _videoThumbnailMap.value = buildMap { putAll(_videoThumbnailCache.snapshot()) }
                    _failedThumbnailUrls.value -= url
                    return@launch
                }

                // 2. Fallback: MediaMetadataRetriever (für alte Videos ohne Server-Thumbnail).
                // getScaledFrameAtTime (API 27+) dekodiert den Frame direkt verkleinert,
                // statt erst das volle 4K-Bild (~33 MB) in den Speicher zu laden.
                val frame = kotlinx.coroutines.withTimeoutOrNull(20_000L) {
                    runCatching {
                        val retriever = MediaMetadataRetriever()
                        retriever.setDataSource(url, mapOf("User-Agent" to "LetheApp/1.0"))
                        val f = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O_MR1) {
                            retriever.getScaledFrameAtTime(
                                0,
                                MediaMetadataRetriever.OPTION_CLOSEST_SYNC,
                                320,
                                320
                            )
                        } else {
                            retriever.getFrameAtTime(0, MediaMetadataRetriever.OPTION_CLOSEST_SYNC)
                        }
                        retriever.release()
                        f
                    }.getOrNull()
                }
                if (frame != null) {
                    val scaled = scaleBitmapToMaxWidth(frame, 320)
                    if (frame !== scaled) frame.recycle()
                    _videoThumbnailCache.put(url, scaled)
                    _videoThumbnailMap.value = buildMap { putAll(_videoThumbnailCache.snapshot()) }
                    _failedThumbnailUrls.value -= url
                } else {
                    _failedThumbnailUrls.value += url
                }
            } finally {
                thumbnailInProgress.remove(url)
                thumbnailSemaphore.release()
            }
        }
    }

    /**
     * Gibt den lokalen Pfad einer bereits gecachten Video-Datei zurück, oder null.
     * Wird vom Player genutzt, um Videos lokal abzuspielen statt sie erneut zu streamen.
     */
    fun getCachedVideoPath(url: String, chatId: String): String? {
        if (url.isBlank() || chatId.isBlank()) return null
        return mediaCache.getCachedPathForChat(url, chatId, "video")
    }

    // Merkt sich bereits aufgelöste öffentliche URIs (Movies/Pictures), damit
    // MediaStore nicht bei jeder Recomposition abgefragt werden muss.
    private val publicMediaUriMemo = java.util.concurrent.ConcurrentHashMap<String, android.net.Uri>()
    // URLs, die nachweislich (noch) NICHT in der Galerie liegen – verhindert
    // wiederholte MediaStore-Abfragen auf dem Main-Thread bei jeder Recomposition.
    private val publicMediaAbsent = java.util.concurrent.ConcurrentHashMap.newKeySet<String>()

    /**
     * Gibt die öffentliche Galerie-URI (Movies/Pictures) zurück, falls das Medium
     * bereits dorthin verschoben wurde – sonst null. Der Player/Coil lädt dann
     * lokal aus der Galerie statt aus dem Netz.
     */
    fun getPublicMediaUri(url: String, isVideo: Boolean): android.net.Uri? {
        if (url.isBlank()) return null
        publicMediaUriMemo[url]?.let { return it }
        if (url in publicMediaAbsent) return null
        val uri = try { mediaCache.findPublicUri(url, isVideo) } catch (_: Exception) { null }
        if (uri != null) publicMediaUriMemo[url] = uri else publicMediaAbsent.add(url)
        return uri
    }

    /**
     * Verschiebt ein Video aus dem Cache in den öffentlichen Movies-Ordner.
     * Wird nach dem Pausieren/Stoppen des Players aufgerufen. Danach wird das
     * Video bei weiteren Aufrufen lokal aus der Galerie abgespielt.
     */
    fun exportVideoToMovies(url: String, chatId: String) {
        if (url.isBlank()) return
        viewModelScope.launch(Dispatchers.IO) {
            try {
                if (getPublicMediaUri(url, true) != null) return@launch
                val cached = mediaCache.getForChat(url, chatId, "video") ?: return@launch
                val uri = mediaCache.moveToPublic(cached, url, true)
                if (uri != null) {
                    publicMediaUriMemo[url] = uri
                    publicMediaAbsent.remove(url)
                }
            } catch (_: Exception) {}
        }
    }

    /**
     * Verschiebt ein Bild aus dem Cache in den öffentlichen Pictures-Ordner.
     * Wird beim ersten Betrachten aufgerufen. Danach wird das Bild lokal aus der
     * Galerie geladen.
     */
    fun exportImageToPictures(url: String, chatId: String) {
        if (url.isBlank()) return
        viewModelScope.launch(Dispatchers.IO) {
            try {
                if (getPublicMediaUri(url, false) != null) return@launch
                val cached = mediaCache.getForChat(url, chatId, "images") ?: return@launch
                val uri = mediaCache.moveToPublic(cached, url, false)
                if (uri != null) {
                    publicMediaUriMemo[url] = uri
                    publicMediaAbsent.remove(url)
                }
            } catch (_: Exception) {}
        }
    }

    /**
     * Stellt sicher, dass die Video-Datei im Disk-Cache liegt (lädt sie ggf. im
     * Hintergrund herunter). Beim nächsten Abspielen wird sie dann lokal genutzt.
     */
    fun ensureVideoCached(url: String, chatId: String) {
        if (url.isBlank() || chatId.isBlank()) return
        viewModelScope.launch(Dispatchers.IO) {
            try {
                if (!mediaCache.isCachedForChat(url, chatId, "video")) {
                    mediaCache.getForChat(url, chatId, "video")
                }
            } catch (_: Exception) {}
        }
    }

    /** Setzt den Fehlerstatus zurück und versucht das Thumbnail erneut zu laden. */
    fun retryVideoThumbnail(url: String) {
        _failedThumbnailUrls.value -= url
        loadVideoThumbnailFromUrl(url)
    }

    /**
     * Speichert vorberechnete Waveform-Daten für eine lokale Audio-Datei im Cache,
     * sodass der Player die Daten sofort ohne neue Analyse anzeigen kann.
     */
    fun cacheWaveformForFile(file: java.io.File, data: WaveformData) {
        val key = file.absolutePath
        _waveformCache.put(key, data)
        _waveformMap.value = buildMap { putAll(_waveformCache.snapshot()) }
    }

    /**
     * Sendet einen Text direkt an einen Kontakt (z.B. beim Multi-Share ohne Chat-Öffnen).
     */
    fun sendTextToContact(contactId: String, text: String) {
        sendMessage(chatId = contactId, content = text)
    }

    /**
     * Registriert den Push-Token am Server (nach Login und Session-Restore).
     * Der konkrete Transport ist flavor-abhängig ([PushProvider]): playstore = FCM,
     * foss = no-op (WS-Foreground-Service).
     */
    private fun registerFcmToken() {
        pushProvider.registerToken()
    }

    /** Wird von MainActivity bei onResume/onPause aufgerufen, um den Foreground-Status zu setzen. */
    fun setAppForeground(inForeground: Boolean) {
        _isAppInForeground.value = inForeground
        // Online-Status nur setzen wenn bereits eingeloggt
        if (_currentUser.value != null) {
            // Online nur wenn App im Vordergrund UND Bildschirm aktiv
            val isScreenOn = (context.getSystemService(Context.POWER_SERVICE) as PowerManager).isInteractive
            val effectiveOnline = inForeground && isScreenOn
            // Präsenz an den WebSocket koppeln: künftige Keepalive-Reconnects im Hintergrund melden
            // active=0 → Server setzt is_online NICHT fälschlich auf "online" obwohl Display aus ist.
            webSocketManager.setPresenceActive(effectiveOnline)
            viewModelScope.launch { updateOnlineStatus(effectiveOnline) }
            if (inForeground) {
                if (!webSocketManager.isConnected()) {
                    // WS neu verbinden – syncMissedMessages wird automatisch beim Connect-Event ausgelöst
                    connectWebSocketAndListen()
                } else {
                    // WS-Verbindung prüfen: Ping senden und bei Fehler reconnecten
                    webSocketManager.sendPing()
                    // Ausstehende Nachrichten erneut senden (falls welche im Pending-Zustand hängen)
                    retryPendingMessages()
                    // FCM-Nachrichten könnten in Room fehlen → direkt nachladen
                    syncMissedMessages()
                }
                // Wenn ein Chat geöffnet ist: Nachrichten die während Bildschirmsperre
                // eintrafen (isRead=false) jetzt als gelesen markieren.
                val activeChatId = _activeChatId.value
                val myId = _currentUser.value?.userId
                if (activeChatId != null && myId != null) {
                    viewModelScope.launch(kotlinx.coroutines.Dispatchers.IO) {
                        messageDao.markAllRead(activeChatId, myId)
                        messageDao.markGroupMessagesRead(activeChatId, myId)
                    }
                }
            }
            // Chat-Focus an die Präsenz koppeln: Bei Display-aus / Hintergrund den Server-Focus
            // aufheben, damit FCM-Pushes (v.a. Gruppen, die bei aktivem Focus + noch offenem WS-Socket
            // unterdrückt werden) wieder gesendet werden und das Gerät im Doze aufgeweckt wird.
            // _activeChatId bleibt unverändert, damit Chat-UI und Read-Receipts erhalten bleiben.
            syncChatFocusToServer()
        }
    }

    /**
     * Meldet dem Server, welchen Chat der Nutzer aktuell WIRKLICH sieht (Vordergrund + Display an).
     * Bei Hintergrund/Display-aus wird der Focus aufgehoben, sonst würde der Server FCM-Pushes für
     * den offenen Chat unterdrücken, obwohl das Gerät schläft und die WS-Nachricht nicht verarbeitet.
     */
    private fun syncChatFocusToServer() {
        val activeChat = _activeChatId.value
        val screenOn = (context.getSystemService(Context.POWER_SERVICE) as PowerManager).isInteractive
        if (activeChat != null && _isAppInForeground.value && screenOn) {
            if (_activeChatIsGroup.value) {
                webSocketManager.sendRaw(mapOf("type" to "set_chat_focus", "group_id" to activeChat))
            } else {
                webSocketManager.sendRaw(mapOf("type" to "set_chat_focus", "chat_user_id" to activeChat))
            }
        } else {
            webSocketManager.sendRaw(mapOf("type" to "clear_chat_focus"))
        }
    }

    /** Lädt den Online-Status eines Kontakts neu (für periodisches Polling im ChatScreen). */
    fun refreshContactStatus(contactId: String) {
        viewModelScope.launch {
            try {
                val response = apiService.getUserStatus(contactId)
                if (response.isSuccessful) {
                    _contactStatus.value = response.body()
                }
            } catch (_: Exception) {}
        }
    }

    /** Aktualisiert den Online-Status auf dem Server (nur wenn eingeloggt).
     *  Redundante Aufrufe werden übersprungen – insbesondere wiederholte setOffline(),
     *  da der Server bei jedem setOffline() last_active = now() setzt. */
    private suspend fun updateOnlineStatus(isOnline: Boolean) {
        if (_lastReportedOnline == isOnline) return
        _lastReportedOnline = isOnline
        try {
            if (isOnline) apiService.setOnline()
            else apiService.setOffline()
        } catch (e: Exception) {
            Timber.tag("MainViewModel").d("Online-Status Update: ${e.message}")
            // Bei Fehler Reset, damit der nächste Versuch nicht übersprungen wird
            _lastReportedOnline = null
        }
    }

    /**
     * Trennt die WebSocket-Verbindung und stellt sie neu her (z.B. nach Netzwerkwechsel).
     * Wird vom NetworkCallback in MainActivity aufgerufen.
     */
    fun reconnectWebSocket() {
        val userId = _currentUser.value?.userId ?: return
        viewModelScope.launch {
            Timber.tag("LETHE_WS").d("Netzwerkwechsel erkannt – erzwinge Reconnect für userId=$userId")
            webSocketManager.disconnect()
            // Jitter (300–800 ms) verhindert Thundering-Herd wenn viele Geräte gleichzeitig reconnecten
            kotlinx.coroutines.delay(300L + (Math.random() * 500).toLong())
            webSocketManager.connect(userId)
        }
    }

    /**
     * Generiert einen neuen Einladungslink via Server-API und speichert ihn in [inviteLinkUrl].
     * Der Link hat das Format: https://letheapp.de/invite.php?token=…&n=…&u=…
     */
    fun generateInviteLink() {
        viewModelScope.launch(Dispatchers.IO) {
            _inviteLinkLoading.value = true
            _inviteLinkError.value = null
            try {
                val response = apiService.generateInvite()
                if (response.isSuccessful) {
                    val body = response.body()
                    if (body?.inviteUrl != null) {
                        _inviteLinkUrl.value = body.inviteUrl
                    } else {
                        _inviteLinkError.value = "Einladungslink konnte nicht erstellt werden."
                    }
                } else {
                    val err = response.errorBody()?.string()
                    val detail = try {
                        org.json.JSONObject(err ?: "").optString("detail", "Fehler beim Laden des Einladungslinks.")
                    } catch (_: Exception) {
                        "Fehler beim Laden des Einladungslinks."
                    }
                    _inviteLinkError.value = detail
                }
            } catch (e: Exception) {
                Timber.tag("MainViewModel").e("generateInviteLink fehlgeschlagen: ${e.message}")
                _inviteLinkError.value = "Keine Verbindung zum Server möglich."
            } finally {
                _inviteLinkLoading.value = false
            }
        }
    }

    /** Teilt den Einladungslink via Android-Share-Sheet. Lädt ihn ggf. zuerst. */
    fun shareInviteLink(activity: android.app.Activity) {
        val url = _inviteLinkUrl.value
        if (url != null) {
            val intent = android.content.Intent(android.content.Intent.ACTION_SEND).apply {
                type = "text/plain"
                putExtra(android.content.Intent.EXTRA_TEXT, "Tritt mir bei Lethe bei! 📲\n$url")
            }
            activity.startActivity(android.content.Intent.createChooser(intent, "Einladung teilen"))
        } else {
            // Zuerst Link generieren, dann teilen
            viewModelScope.launch(Dispatchers.IO) {
                try {
                    val response = apiService.generateInvite()
                    if (response.isSuccessful) {
                        val invUrl = response.body()?.inviteUrl ?: return@launch
                        _inviteLinkUrl.value = invUrl
                        withContext(Dispatchers.Main) {
                            val intent = android.content.Intent(android.content.Intent.ACTION_SEND).apply {
                                type = "text/plain"
                                putExtra(android.content.Intent.EXTRA_TEXT, "Tritt mir bei Lethe bei! 📲\n$invUrl")
                            }
                            activity.startActivity(android.content.Intent.createChooser(intent, "Einladung teilen"))
                        }
                    }
                } catch (e: Exception) {
                    Timber.tag("MainViewModel").e("shareInviteLink fehlgeschlagen: ${e.message}")
                }
            }
        }
    }

    /** Löst einen Einladungstoken ein (Deep Link: lethe://add?token=TOKEN&u=FAKE_NUMBER). */
    fun redeemInviteToken(token: String, creatorFakeNumber: String? = null) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val response = apiService.redeemInvite(token)
                if (response.isSuccessful) {
                    val body = response.body()
                    // Fake-Number des Einladenden aus Server-Antwort oder URL-Parameter
                    val fakeNumber = body?.creatorFakeNumber ?: creatorFakeNumber
                    if (fakeNumber != null) {
                        // Kontaktanfrage über fake_number senden
                        addContact(fakeNumber, body?.creatorName ?: "")
                    }
                    Timber.tag("MainViewModel").d("Einladung eingelöst: token=$token, creator=$fakeNumber")
                }
            } catch (e: Exception) {
                Timber.tag("MainViewModel").e("redeemInviteToken fehlgeschlagen: ${e.message}")
            }
        }
    }

    /** Sucht in der Lethe-Datenbank nach Nutzern anhand einer Telefonnummern-Liste. */
    fun lookupPhoneContacts(numbers: List<String>) {
        viewModelScope.launch(Dispatchers.IO) {
            _phoneLookupLoading.value = true
            try {
                val resp = apiService.lookupPhoneContacts(mapOf("phone_numbers" to numbers))
                if (resp.isSuccessful) {
                    _phoneLookupMatches.value = resp.body()?.matches ?: emptyList()
                }
            } catch (e: Exception) {
                Timber.tag("LETHE_CONTACTS").e(e, "Phone lookup failed")
            } finally {
                _phoneLookupLoading.value = false
            }
        }
    }

    /** Leert die Ergebnisse der Telefonbuch-Suche. */
    fun clearPhoneLookup() {
        _phoneLookupMatches.value = emptyList()
    }

    /**
     * Löst einen im SharedPreferences zwischengespeicherten Einladungstoken ein.
     * Wird nach erfolgreichem Login aufgerufen (einmalig pro neuem Nutzer).
     */
    private fun redeemPendingInvite() {
        val prefs = context.getSharedPreferences("lethe_invite", Context.MODE_PRIVATE)
        val token = prefs.getString("pending_invite_token", null) ?: return
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val resp = apiService.redeemInvite(token)
                if (resp.isSuccessful) {
                    prefs.edit().remove("pending_invite_token").apply()
                    Timber.tag("LETHE_INVITE").i("Pending invite redeemed: $token")
                }
            } catch (e: Exception) {
                Timber.tag("LETHE_INVITE").e(e, "Redeem failed: $token")
            }
        }
    }

