    private val _vipCategories = MutableStateFlow<List<com.securechat.app.data.network.VipCategoryResponse>>(emptyList())
    val vipCategories: StateFlow<List<com.securechat.app.data.network.VipCategoryResponse>> = _vipCategories.asStateFlow()

    /** Abonnierte VIP-Forum-Kategorien: Set aus Kategorie-IDs */
    private val _vipSubscribedCategories = MutableStateFlow<Set<String>>(emptySet())
    val vipSubscribedCategories: StateFlow<Set<String>> = _vipSubscribedCategories.asStateFlow()

    private val vipForumPrefs by lazy {
        context.getSharedPreferences("vip_forum_subscriptions", android.content.Context.MODE_PRIVATE)
    }

    init {
        _vipSubscribedCategories.value =
            vipForumPrefs.getStringSet("subscribed_ids", emptySet())?.toSet() ?: emptySet()

        // Kontakte-App-Integration ("Verbundene Apps") bei Kontaktänderung neu schreiben,
        // sofern aktiviert und WRITE_CONTACTS erteilt. Debounce gegen Schreib-Stürme.
        viewModelScope.launch {
            contactDao.getAllContacts()
                .collectLatest {
                    // collectLatest bricht bei neuer Emission ab → delay wirkt als Debounce.
                    delay(2500)
                    syncContactsAppIntegration()
                }
        }
    }

    fun subscribeToVipCategory(categoryId: String, categoryName: String) {
        val current = _vipSubscribedCategories.value.toMutableSet()
        current.add(categoryId)
        _vipSubscribedCategories.value = current
        vipForumPrefs.edit()
            .putStringSet("subscribed_ids", current)
            .putString("name_$categoryId", categoryName)
            .apply()
    }

    fun unsubscribeFromVipCategory(categoryId: String) {
        val current = _vipSubscribedCategories.value.toMutableSet()
        current.remove(categoryId)
        _vipSubscribedCategories.value = current
        vipForumPrefs.edit()
            .putStringSet("subscribed_ids", current)
            .remove("name_$categoryId")
            .apply()
    }

    fun isVipCategorySubscribed(categoryId: String): Boolean =
        categoryId in _vipSubscribedCategories.value

