    private val _voiceRecordError = MutableStateFlow<String?>(null)
    val voiceRecordError: StateFlow<String?> = _voiceRecordError.asStateFlow()

    fun setVoiceRecordError(message: String?) {
        _voiceRecordError.value = message
    }

    // ── Live-Aufnahme AGC ─────────────────────────────────────────────────────

    /**
     * AGC-normierter Live-Amplitudenwert (0.0 .. 1.0) für die Waveform-Visualisierung.
     * Wird von [updateLiveAmplitude] jedes Tick (ca. 80 ms) aktualisiert.
     */
    private val _liveRecordingAmplitude = MutableStateFlow(0f)
    val liveRecordingAmplitude: StateFlow<Float> = _liveRecordingAmplitude.asStateFlow()

    /** Interner AGC-Spitzenwert: steigt sofort, verfällt langsam (Decay 0,3 %/Tick). */
    private var agcPeakTracker = 0f

    /** Geglätteter Ausgabewert (EMA α = 0,35). Verhindert nervöses Zucken. */
    private var agcSmoothed = 0f

    /**
     * Setzt den AGC-State vollständig zurück.
     * Muss **vor jeder neuen Aufnahme** aufgerufen werden, damit der Algorithmus
     * nicht mit den Spitzenwerten der vorigen Aufnahme startet.
     */
    fun resetAgcState() {
        agcPeakTracker = 0f
        agcSmoothed    = 0f
        _liveRecordingAmplitude.value = 0f
    }

    /**
     * Verarbeitet einen rohen [rawAmplitude]-Wert (0..32 767) vom MediaRecorder,
     * wendet AGC + Smoothing an und aktualisiert [liveRecordingAmplitude].
     *
     * ## AGC-Algorithmus (vier Stufen)
     *
     * 1. **Normierung** — `raw / 32 767` → 0..1
     * 2. **Peak-Tracking** — Spitzenwert steigt sofort (`maxOf`), verfällt dann
     *    langsam mit `decayFactor = 0,997` (~0,3 % pro Tick bei 80 ms = ~3,75 %/s).
     *    Damit passt sich der AGC automatisch an leiser werdende Umgebungen an,
     *    ohne bei kurzen Sprachpausen sofort wieder zuzudrehen.
     * 3. **Gain** — `gain = targetPeak / currentPeak`, begrenzt auf [1,0 .. 8,0].
     *    `targetPeak = 0,70` hält die Waveform gut sichtbar ohne Clipping.
     *    Bei sehr stiller Umgebung (Peak < 0,02) wird volle Verstärkung angesetzt,
     *    sodass der Rauschboden als leichte Bewegung sichtbar bleibt.
     * 4. **EMA-Smoothing** — α = 0,35 (35 % neues Signal, 65 % Geschichte).
     *    Sorgt für flüssige, nicht springende Balken.
     *
     * Darf von **jedem Thread** aufgerufen werden — `StateFlow.value` ist threadsafe.
     */
    fun updateLiveAmplitude(rawAmplitude: Int) {
        val norm = rawAmplitude.toFloat().coerceIn(0f, 32767f) / 32767f

        // Schritt 1 – Peak-Tracking
        val decayFactor = 0.997f
        agcPeakTracker  = maxOf(norm, agcPeakTracker * decayFactor)

        // Schritt 2 – AGC-Gain
        val targetPeak = 0.70f
        val maxGain    = 8.0f
        val gain = if (agcPeakTracker > 0.02f) {
            (targetPeak / agcPeakTracker).coerceIn(1f, maxGain)
        } else {
            maxGain  // Komplette Stille → volle Verstärkung (zeigt Rauschboden)
        }
        val amplified = (norm * gain).coerceIn(0f, 1f)

        // Schritt 3 – EMA-Smoothing
        val alpha   = 0.35f
        agcSmoothed = agcSmoothed * (1f - alpha) + amplified * alpha

        _liveRecordingAmplitude.value = agcSmoothed
    }

    // ── Hybrid Voice Recording (Zweig A: MediaRecorder / Zweig B: Xiaomi AudioRecord) ──────

    /**
     * True für Xiaomi/POCO/Redmi-Geräte (HyperOS/MIUI): nutzt [AudioRecord]-Fallback
     * statt [MediaRecorder], weil MIUI die Amplitude-Abfrage blockiert und
     * VOICE_COMMUNICATION manchmal mit SecurityException scheitert.
     */
    val isXiaomiDevice: Boolean =
        Build.MANUFACTURER.equals("Xiaomi", ignoreCase = true) ||
        Build.MANUFACTURER.equals("POCO",   ignoreCase = true) ||
        Build.MANUFACTURER.equals("Redmi",  ignoreCase = true)

    /**
     * True für Samsung- und Google/Pixel-Geräte: Deren Audio-DSP (Samsung Knox/Sound
     * Intelligence bzw. Google Tensor mit aggressiver HW-Noise-Suppression + AGC) liefert bei
     * VOICE_COMMUNICATION extrem niedrige bis stumme Amplitudenwerte. Folge: Die Sprachnachricht
     * enthält keinen hörbaren Ton (Pixel 10 Pro „einfach still") bzw. wird am maxAmp-Check verworfen.
     * Fix: AudioSource.MIC verwenden, das native Amplitudenwerte ohne herstellerspezifisches DSP liefert.
     */
    val isVoiceCommProblematicDevice: Boolean =
        Build.MANUFACTURER.equals("samsung", ignoreCase = true) ||
        Build.MANUFACTURER.equals("Google", ignoreCase = true)

    // ── Shared Recording State ────────────────────────────────────────────────

    private val _isRecordingVoice = MutableStateFlow(false)
    val isRecordingVoice: StateFlow<Boolean> = _isRecordingVoice.asStateFlow()

    private val _isRecordingLocked = MutableStateFlow(false)
    val isRecordingLocked: StateFlow<Boolean> = _isRecordingLocked.asStateFlow()

    // ── Zweig A: Standard-MediaRecorder ──────────────────────────────────────

    private var mediaRecorder: MediaRecorder? = null
    private var mediaRecorderFile: File? = null
    private var amplitudeSamplerJob: Job? = null
    private var voiceAutoStopJob: Job? = null

    // ── Zweig B: Xiaomi-AudioRecord ───────────────────────────────────────────

    private var xiaomiAudioRecord: AudioRecord? = null
    private var xiaomiPcmFile: File? = null
    private var xiaomiReadJob: Job? = null

    // ── Gemeinsam ─────────────────────────────────────────────────────────────

    private val voiceRecordingAmplitudes = mutableListOf<Float>()
    private var voiceRecordingWakeLock: PowerManager.WakeLock? = null

    /** Kurze Vibration (50 ms) – geräteübergreifend, nutzt ViewModel-Context. */
    private fun vibrateShort() {
        try {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
                val vm = context.getSystemService(Context.VIBRATOR_MANAGER_SERVICE) as VibratorManager
                vm.defaultVibrator.vibrate(
                    VibrationEffect.createOneShot(50, VibrationEffect.DEFAULT_AMPLITUDE)
                )
            } else {
                @Suppress("DEPRECATION")
                val v = context.getSystemService(Context.VIBRATOR_SERVICE) as Vibrator
                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                    v.vibrate(VibrationEffect.createOneShot(50, VibrationEffect.DEFAULT_AMPLITUDE))
                } else {
                    @Suppress("DEPRECATION")
                    v.vibrate(50)
                }
            }
        } catch (_: Exception) {}
    }

    /** Setzt [isRecordingLocked] = true (ausgelöst durch Swipe-Up-Geste in ChatScreen). */
    fun lockVoiceRecording() {
        _isRecordingLocked.value = true
    }

    /**
     * Startet die Sprachaufnahme mit automatischer Geräteerkennung:
     *  - **Zweig A** (Standard): [MediaRecorder] → .mp4 / AAC
     *  - **Zweig B** (Xiaomi/POCO/Redmi): [AudioRecord] → PCM-Datei → später AAC/M4A via [MediaCodec]
     *
     * Gibt `true` zurück wenn die Aufnahme erfolgreich gestartet wurde.
     */
    fun startVoiceRecording(): Boolean {
        if (_isRecordingVoice.value) return false

        if (context.checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)
            != android.content.pm.PackageManager.PERMISSION_GRANTED
        ) {
            Timber.tag("LETHE_AUDIO").w("startVoiceRecording: RECORD_AUDIO-Berechtigung fehlt")
            _voiceRecordError.value =
                "Fehler: Mikrofon-Zugriff verweigert. Bitte Berechtigung erteilen."
            return false
        }

        resetAgcState()
        voiceRecordingAmplitudes.clear()

        // Sprachkommunikations-Modus: aktiviert SCO falls ein BT-Headset verbunden ist,
        // damit das Headset-Mikrofon genutzt wird. MUSS vor dem Start des Recorders passieren.
        audioFocusManager.enterVoiceCommunication()

        val started = if (isXiaomiDevice) {
            Timber.tag("LETHE_AUDIO").i("Xiaomi-Gerät erkannt → Zweig B: AudioRecord")
            startAudioRecordBranch()
        } else {
            Timber.tag("LETHE_AUDIO").i("Standard-Gerät → Zweig A: MediaRecorder")
            startMediaRecorderBranch()
        }

        if (!started) audioFocusManager.exitVoiceCommunication()

        if (started) {
            _isRecordingVoice.value  = true
            _isRecordingLocked.value = false

            // WakeLock: verhindert Mikrofon-Unterbrechung bei Display-Dimming (MIUI/HyperOS)
            val pm = context.getSystemService(Context.POWER_SERVICE) as PowerManager
            voiceRecordingWakeLock = pm.newWakeLock(
                PowerManager.PARTIAL_WAKE_LOCK,
                "lethe:voicerecording"
            ).also { it.acquire(10 * 60 * 1000L) }
            Timber.tag("LETHE_AUDIO").d("WakeLock (PARTIAL) erworben")

            // VoiceRecordingService: hält Mikrofon-Foreground-Type auf Android 14+ am Leben.
            // startService() statt startForegroundService(): Da der Nutzer aktiv den Button drückt,
            // ist die App garantiert im Vordergrund – der 5s-ForegroundService-Timer entfällt.
            // Der Service ruft startForeground() eigenständig in onCreate() auf.
            try {
                val svcIntent = Intent(
                    context,
                    com.securechat.app.VoiceRecordingService::class.java
                ).setAction(com.securechat.app.VoiceRecordingService.ACTION_START)
                context.startService(svcIntent)
            } catch (e: Exception) {
                Timber.tag("LETHE_AUDIO").w(e, "VoiceRecordingService konnte nicht gestartet werden (unkritisch)")
            }

            vibrateShort()
            // Dezentral-Modus: Sprachnachrichten auf 10 Sekunden begrenzen
            if (_userPrefs.value.decentralizedMode) {
                voiceAutoStopJob?.cancel()
                voiceAutoStopJob = viewModelScope.launch {
                    delay(10_000L)
                    val chatId = _activeChatId.value
                    if (_isRecordingVoice.value && chatId != null) {
                        stopAndSendVoiceMessage(chatId)
                    }
                }
            }
        }
        return started
    }

    // ── ZWEIG A: Standard MediaRecorder ──────────────────────────────────────

    private fun startMediaRecorderBranch(): Boolean {
        val f = File(context.cacheDir, "temp_voice_record.mp4")
        if (f.exists()) f.delete()

        @Suppress("DEPRECATION")
        val mr = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            MediaRecorder(context)
        } else {
            MediaRecorder()
        }

        try {
            mr.apply {
                // VOICE_COMMUNICATION: Aktiviert Hardware-Noise-Suppression + Echo-Cancellation
                // auf Nicht-Xiaomi-Geräten. Xiaomi-Geräte nutzen Zweig B (AudioRecord), da MIUI
                // die Telefonie-Audio-Pipeline für Drittanbieter einschränken kann.
                // Samsung/Google(Pixel): deren DSP macht VOICE_COMMUNICATION nahezu stumm →
                // MIC liefert nativen, hörbaren Ton ohne herstellerspezifisches Noise-Gating.
                setAudioSource(
                    if (isVoiceCommProblematicDevice) MediaRecorder.AudioSource.MIC
                    else MediaRecorder.AudioSource.VOICE_COMMUNICATION
                )
                setOutputFormat(MediaRecorder.OutputFormat.MPEG_4)
                setAudioEncoder(MediaRecorder.AudioEncoder.AAC)
                setAudioChannels(1)
                setAudioSamplingRate(44_100)
                setAudioEncodingBitRate(64_000)
                setOutputFile(f.absolutePath)
            }
            Timber.tag("LETHE_AUDIO").d("MediaRecorder konfiguriert – prepare()")
            mr.prepare()
            Timber.tag("LETHE_AUDIO").d("prepare() OK – start()")
            mr.start()
            Timber.tag("LETHE_AUDIO").i("MediaRecorder gestartet: ${f.absolutePath}")
        } catch (e: java.io.IOException) {
            Timber.tag("LETHE_AUDIO").e(e, "prepare() fehlgeschlagen (IOException)")
            mr.release()
            f.delete()
            _voiceRecordError.value =
                "Fehler: Aufnahme fehlgeschlagen (I/O). Bitte erneut versuchen."
            return false
        } catch (e: IllegalStateException) {
            Timber.tag("LETHE_AUDIO").e(e, "start() fehlgeschlagen (IllegalStateException)")
            mr.release()
            f.delete()
            _voiceRecordError.value =
                "Fehler: Aufnahme konnte nicht gestartet werden. Bitte erneut versuchen."
            return false
        } catch (e: SecurityException) {
            Timber.tag("LETHE_AUDIO").e(e, "SecurityException – MIUI-Restriktion?")
            mr.release()
            f.delete()
            _voiceRecordError.value =
                "Fehler: Mikrofon-Zugriff durch System verweigert."
            return false
        } catch (e: Exception) {
            Timber.tag("LETHE_AUDIO").e(e, "Unbekannter Fehler: ${e.javaClass.simpleName}")
            mr.release()
            f.delete()
            _voiceRecordError.value = "Fehler: ${e.message ?: "Unbekannter Aufnahmefehler"}"
            return false
        }

        mediaRecorder     = mr
        mediaRecorderFile = f

        // Amplitude alle 80 ms abfragen → AGC-StateFlow + Waveform-Cache nach Aufnahme
        amplitudeSamplerJob = viewModelScope.launch {
            delay(100)
            while (_isRecordingVoice.value) {
                val raw = mediaRecorder?.maxAmplitude ?: 0
                updateLiveAmplitude(raw)
                voiceRecordingAmplitudes.add((raw / 32767f).coerceIn(0f, 1f))
                delay(80)
            }
        }
        return true
    }

    // ── ZWEIG B: Xiaomi AudioRecord ───────────────────────────────────────────

    private fun startAudioRecordBranch(): Boolean {
        val sampleRate = 44_100
        val channelCfg = AudioFormat.CHANNEL_IN_MONO
        val encoding   = AudioFormat.ENCODING_PCM_16BIT
        val minBufSize = AudioRecord.getMinBufferSize(sampleRate, channelCfg, encoding)
        // Xiaomi/MIUI: Größerer Ringpuffer (4× min, mind. 16 KB) gibt dem Lese-Loop genug
        // Reserve, damit beim Schreiben/Amplituden-Berechnen keine Samples verworfen werden
        // (zu kleiner Puffer = Buffer-Overrun = Stottern/Aussetzer in der Aufnahme).
        val bufferSize = maxOf(minBufSize * 4, 16_384)

        // Xiaomi/MIUI: VOICE_COMMUNICATION wird manchmal durch MIUIs Berechtigungs-Policy
        // blockiert (SecurityException oder STATE_UNINITIALIZED). Fallback auf MIC.
        val audioSourcesToTry = intArrayOf(
            MediaRecorder.AudioSource.VOICE_COMMUNICATION,
            MediaRecorder.AudioSource.MIC
        )
        var ar: AudioRecord? = null
        for (source in audioSourcesToTry) {
            try {
                val candidate = AudioRecord(source, sampleRate, channelCfg, encoding, bufferSize)
                if (candidate.state == AudioRecord.STATE_INITIALIZED) {
                    Timber.tag("LETHE_AUDIO").i("AudioRecord initialisiert mit Quelle $source")
                    ar = candidate
                    break
                } else {
                    Timber.tag("LETHE_AUDIO").w("AudioSource $source: STATE_UNINITIALIZED – versuche nächste Quelle")
                    candidate.release()
                }
            } catch (e: SecurityException) {
                Timber.tag("LETHE_AUDIO").w("AudioSource $source: SecurityException (MIUI-Policy) – versuche nächste Quelle")
            } catch (e: Exception) {
                Timber.tag("LETHE_AUDIO").w("AudioSource $source: ${e.message} – versuche nächste Quelle")
            }
        }

        if (ar == null) {
            Timber.tag("LETHE_AUDIO").e("AudioRecord konnte mit keiner Quelle initialisiert werden")
            _voiceRecordError.value =
                "Fehler: Mikrofon-Initialisierung fehlgeschlagen (Xiaomi-Zweig)."
            return false
        }

        val safeAr = ar // non-null nach obigem Early-Return
        val pcmFile = File(context.cacheDir, "temp_voice_xiaomi.pcm")
        if (pcmFile.exists()) pcmFile.delete()

        try {
            safeAr.startRecording()
            Timber.tag("LETHE_AUDIO").i("AudioRecord gestartet: ${pcmFile.absolutePath}")
        } catch (e: Exception) {
            Timber.tag("LETHE_AUDIO").e(e, "AudioRecord.startRecording() fehlgeschlagen")
            safeAr.release()
            _voiceRecordError.value = "Fehler: Aufnahme konnte nicht gestartet werden."
            return false
        }

        xiaomiAudioRecord = safeAr
        xiaomiPcmFile     = pcmFile

        // Lese-Loop im IO-Dispatcher: PCM-Bytes → Datei + Amplitudenberechnung via RMS
        xiaomiReadJob = viewModelScope.launch(Dispatchers.IO) {
            val shortBuf = ShortArray(bufferSize / 2)
            FileOutputStream(pcmFile).use { fos ->
                while (isActive && _isRecordingVoice.value) {
                    val read = safeAr.read(shortBuf, 0, shortBuf.size)
                    if (read > 0) {
                        // PCM-Shorts → Bytes (Little-Endian, wie AudioRecord liefert).
                        // KEIN hartes Noise-Gate mehr: das frühere Nullsetzen einzelner Samples
                        // (abs < 400) erzeugte abrupte Sprünge in der Wellenform → hörbare
                        // Klicks/Kratzen ("Übersteuern") auf Xiaomi-Geräten. Rohe Samples bleiben
                        // erhalten; VOICE_COMMUNICATION übernimmt die Rauschunterdrückung in HW.
                        val byteChunk = ByteArray(read * 2)
                        for (i in 0 until read) {
                            val s = shortBuf[i]
                            byteChunk[i * 2]     = (s.toInt() and 0xFF).toByte()
                            byteChunk[i * 2 + 1] = ((s.toInt() shr 8) and 0xFF).toByte()
                        }
                        fos.write(byteChunk)

                        // Amplitude: RMS des aktuellen Chunks → skaliert auf 0..32767
                        var sumSq = 0.0
                        for (i in 0 until read) {
                            sumSq += shortBuf[i].toDouble() * shortBuf[i].toDouble()
                        }
                        val rms = kotlin.math.sqrt(sumSq / read).toFloat().coerceIn(0f, 32767f)
                        updateLiveAmplitude(rms.toInt())
                        voiceRecordingAmplitudes.add((rms / 32767f).coerceIn(0f, 1f))
                    }
                }
            }
            Timber.tag("LETHE_AUDIO").d("AudioRecord Lese-Loop beendet")
        }
        return true
    }

    /**
     * Stoppt die Aufnahme und sendet die Sprachnachricht an [chatId].
     *  - Zweig A: [MediaRecorder]-Datei wird normalisiert, dann direkt gesendet.
     *  - Zweig B: Rohe PCM-Datei wird via [convertPcmToM4a] enkodiert, dann gesendet.
     */
    fun stopAndSendVoiceMessage(chatId: String) {
        if (!_isRecordingVoice.value) return

        voiceAutoStopJob?.cancel()
        voiceAutoStopJob = null
        amplitudeSamplerJob?.cancel()
        amplitudeSamplerJob = null

        val fileToProcess: File? = if (isXiaomiDevice) {
            stopAudioRecordBranch()
        } else {
            stopMediaRecorderBranch()
        }

        _isRecordingVoice.value  = false
        _isRecordingLocked.value = false
        releaseWakeLockAndService()
        vibrateShort()

        if (fileToProcess == null) return

        val ampSnapshot = voiceRecordingAmplitudes.toList()
        voiceRecordingAmplitudes.clear()

        // Zu kurz oder zu leise → verwerfen, keine Nachricht senden
        val maxAmp = ampSnapshot.maxOrNull() ?: 0f
        if (ampSnapshot.size < 5 || maxAmp < 0.02f) {
            fileToProcess.delete()
            return
        }

        // Waveform sofort aus Live-Amplituden vorberechnen und cachen – kein nachträgliches
        // Analysieren nötig, da die Samples bereits während der Aufnahme gesammelt wurden.
        // Dadurch zeigt die Nachrichtenblase die Waveform sofort ohne weitere Verzögerung.
        val liveWaveform = AudioWaveformAnalyzer.computeWaveformFromRecordingAmplitudes(ampSnapshot)
        cacheWaveformForFile(fileToProcess, liveWaveform)

        viewModelScope.launch(Dispatchers.IO) {
            try {
                val readyFile: File = if (isXiaomiDevice) {
                    // Zweig B: PCM bereits noise-gate-gefiltert → M4A via MediaCodec + MediaMuxer
                    Timber.tag("LETHE_AUDIO").d("Konvertiere PCM → M4A (Xiaomi-Zweig)…")
                    val m4a = convertPcmToM4a(fileToProcess)
                    fileToProcess.delete()
                    m4a
                } else {
                    // Zweig A: Normalisierung nur wenn Peak deutlich unter Ziel liegt.
                    // VOICE_COMMUNICATION-Quelle liefert bereits AGC-normiertes Audio; wenn der
                    // geschätzte Gain < +3 dB (maxAmp ≥ 0,50) ist, entfällt der decode/encode-
                    // Durchlauf (~0,5–2 s) und der Upload startet sofort.
                    val estimatedGain = 0.708f / maxAmp.coerceAtLeast(0.01f)
                    if (estimatedGain <= 1.42f) {
                        Timber.tag("LETHE_AUDIO").d("Normalisierung übersprungen (estimatedGain=%.2f)".format(estimatedGain))
                        fileToProcess
                    } else {
                        AudioWaveformAnalyzer.normalizeAudio(fileToProcess)
                    }
                }

                // Waveform-Cache-Key auf finale Datei übertragen (falls Normalisierung neue Datei erstellt hat)
                if (readyFile != fileToProcess) {
                    cacheWaveformForFile(readyFile, liveWaveform)
                }

                withContext(Dispatchers.Main) {
                    if (_activeChatIsGroup.value) sendGroupMediaMessage(chatId, Uri.fromFile(readyFile), "audio")
                    else sendMediaMessage(chatId, Uri.fromFile(readyFile), "audio")
                }

                // Original löschen wenn normalizeAudio eine neue Datei erstellt hat
                if (!isXiaomiDevice && readyFile != fileToProcess) fileToProcess.delete()

            } catch (e: Exception) {
                Timber.tag("LETHE_AUDIO").e(e, "stopAndSendVoiceMessage: Fehler beim Enkodieren/Senden")
            }
        }
    }

    private fun stopMediaRecorderBranch(): File? {
        val file = mediaRecorderFile
        try {
            mediaRecorder?.apply { stop(); release() }
        } catch (_: Exception) {}
        mediaRecorder     = null
        mediaRecorderFile = null
        return file
    }

    private fun stopAudioRecordBranch(): File? {
        xiaomiReadJob?.cancel()
        xiaomiReadJob = null
        try {
            xiaomiAudioRecord?.apply { stop(); release() }
        } catch (_: Exception) {}
        xiaomiAudioRecord = null
        val file = xiaomiPcmFile
        xiaomiPcmFile = null
        return file
    }

    /**
     * Bricht die Aufnahme ab. Die temporäre Datei wird gelöscht, es wird nichts gesendet.
     */
    fun cancelVoiceRecording() {
        if (!_isRecordingVoice.value) return

        amplitudeSamplerJob?.cancel()
        amplitudeSamplerJob = null

        if (isXiaomiDevice) {
            xiaomiReadJob?.cancel()
            xiaomiReadJob = null
            try { xiaomiAudioRecord?.apply { stop(); release() } } catch (_: Exception) {}
            xiaomiAudioRecord = null
            xiaomiPcmFile?.delete()
            xiaomiPcmFile = null
        } else {
            try { mediaRecorder?.apply { stop(); release() } } catch (_: Exception) {}
            mediaRecorder = null
            mediaRecorderFile?.delete()
            mediaRecorderFile = null
        }

        _isRecordingVoice.value  = false
        _isRecordingLocked.value = false
        voiceRecordingAmplitudes.clear()
        releaseWakeLockAndService()
        Timber.tag("LETHE_AUDIO").d("Aufnahme abgebrochen (cancelVoiceRecording)")
    }

    private fun releaseWakeLockAndService() {
        // Sprachkommunikations-Modus verlassen (SCO deaktivieren, Standard-Routing zurück).
        audioFocusManager.exitVoiceCommunication()
        voiceRecordingWakeLock?.let { wl ->
            if (wl.isHeld) {
                wl.release()
                Timber.tag("LETHE_AUDIO").d("WakeLock freigegeben")
            }
        }
        voiceRecordingWakeLock = null
        try {
            context.stopService(
                Intent(context, com.securechat.app.VoiceRecordingService::class.java)
            )
        } catch (_: Exception) {}
    }

    /**
     * Konvertiert eine rohe PCM-16-bit-Mono-44100-Hz-Datei in eine M4A-Datei (AAC-LC, 64 kbps)
     * via [MediaCodec] (Encoder) + [MediaMuxer] (MP4-Container).
     *
     * Muss auf [Dispatchers.IO] aufgerufen werden.
     */
    private fun convertPcmToM4a(pcmFile: File): File {
        val outputFile = File(
            context.cacheDir,
            "voice_xiaomi_${System.currentTimeMillis()}.m4a"
        )

        // ── Codec konfigurieren ───────────────────────────────────────────────
        val codec = MediaCodec.createEncoderByType(MediaFormat.MIMETYPE_AUDIO_AAC)
        val inputFormat = MediaFormat.createAudioFormat(
            MediaFormat.MIMETYPE_AUDIO_AAC,
            /* sampleRate    = */ 44_100,
            /* channelCount  = */ 1
        ).also { fmt ->
            fmt.setInteger(MediaFormat.KEY_BIT_RATE, 64_000)
            fmt.setInteger(
                MediaFormat.KEY_AAC_PROFILE,
                MediaCodecInfo.CodecProfileLevel.AACObjectLC
            )
            fmt.setInteger(MediaFormat.KEY_MAX_INPUT_SIZE, 16_384)
        }
        codec.configure(inputFormat, null, null, MediaCodec.CONFIGURE_FLAG_ENCODE)
        codec.start()

        // ── Muxer vorbereiten ─────────────────────────────────────────────────
        val muxer = MediaMuxer(
            outputFile.absolutePath,
            MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4
        )

        var audioTrackIndex = -1
        var muxerStarted    = false
        var inputDone       = false
        var outputDone      = false
        val bufferInfo      = MediaCodec.BufferInfo()
        var presentationUs  = 0L

        val inputStream = FileInputStream(pcmFile)
        val readBuf     = ByteArray(4096)

        try {
            while (!outputDone) {

                // ─── Input: PCM-Bytes in Codec-Input-Buffer schieben ──────────
                if (!inputDone) {
                    val inputIdx = codec.dequeueInputBuffer(10_000L)
                    if (inputIdx >= 0) {
                        val bytesRead = inputStream.read(readBuf)
                        val inputBuf  = codec.getInputBuffer(inputIdx)!!
                        inputBuf.clear()
                        if (bytesRead == -1) {
                            // PCM-Datei erschöpft → EOS an Codec signalisieren
                            codec.queueInputBuffer(
                                inputIdx, 0, 0, presentationUs,
                                MediaCodec.BUFFER_FLAG_END_OF_STREAM
                            )
                            inputDone = true
                            Timber.tag("LETHE_AUDIO").d("convertPcmToM4a: EOS an Codec gesendet")
                        } else {
                            inputBuf.put(readBuf, 0, bytesRead)
                            // Samples = bytesRead / 2 (16-bit Mono), Zeitstempel in µs
                            val sampleDurationUs =
                                (bytesRead.toLong() / 2L * 1_000_000L) / 44_100L
                            codec.queueInputBuffer(
                                inputIdx, 0, bytesRead, presentationUs, 0
                            )
                            presentationUs += sampleDurationUs
                        }
                    }
                }

                // ─── Output: enkodierte AAC-Frames aus Codec holen ────────────
                var outputIdx = codec.dequeueOutputBuffer(bufferInfo, 10_000L)
                while (outputIdx != MediaCodec.INFO_TRY_AGAIN_LATER) {
                    when {
                        outputIdx == MediaCodec.INFO_OUTPUT_FORMAT_CHANGED -> {
                            // Codec-Format bekannt → Track hinzufügen, Muxer starten
                            audioTrackIndex = muxer.addTrack(codec.outputFormat)
                            muxer.start()
                            muxerStarted = true
                            Timber.tag("LETHE_AUDIO").d("convertPcmToM4a: Muxer gestartet")
                        }
                        outputIdx >= 0 -> {
                            val outBuf     = codec.getOutputBuffer(outputIdx)!!
                            val isConfig   = (bufferInfo.flags and
                                    MediaCodec.BUFFER_FLAG_CODEC_CONFIG) != 0
                            val isEos      = (bufferInfo.flags and
                                    MediaCodec.BUFFER_FLAG_END_OF_STREAM) != 0

                            if (muxerStarted && bufferInfo.size > 0 && !isConfig) {
                                outBuf.position(bufferInfo.offset)
                                outBuf.limit(bufferInfo.offset + bufferInfo.size)
                                muxer.writeSampleData(audioTrackIndex, outBuf, bufferInfo)
                            }
                            codec.releaseOutputBuffer(outputIdx, false)
                            if (isEos) {
                                outputDone = true
                                Timber.tag("LETHE_AUDIO")
                                    .d("convertPcmToM4a: EOS vom Codec empfangen → fertig")
                            }
                        }
                    }
                    outputIdx = if (!outputDone) {
                        codec.dequeueOutputBuffer(bufferInfo, 0L)
                    } else {
                        MediaCodec.INFO_TRY_AGAIN_LATER
                    }
                }
            }
        } finally {
            inputStream.close()
            try { codec.stop();  codec.release()  } catch (_: Exception) {}
            try { muxer.stop();  muxer.release()  } catch (_: Exception) {}
        }

        Timber.tag("LETHE_AUDIO").i(
            "convertPcmToM4a: ${pcmFile.length()} B PCM → ${outputFile.length()} B M4A"
        )
        return outputFile
    }

