    /** Speichert einen neuen oder bearbeiteten Creator-Beitrag. */
    fun saveCreatorContent(
        title: String,
        category: String?,
        description: String?,
        contentHtml: String?,
        styxCost: Int,
        previewImageUrl: String?,
        mediaUrl: String?,
        mediaType: String,
        isEdit: Boolean,
        contentId: String?,
        onResult: (Boolean, String?) -> Unit
    ) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val slug = title.lowercase()
                    .replace(Regex("[^a-z0-9äöüß\\s-]"), "")
                    .replace(Regex("\\s+"), "-")
                    .take(200)
                // Absolute URLs vor dem Senden wieder auf relative Pfade kürzen.
                // Beim Laden wird toAbsoluteUrl() angewendet (z.B. loadCreatorSparks).
                // Würde die absolute URL zurückgesendet, speichert der Server sie verbatim
                // und _enrich_content würde sie NOCHMALS prefixen → doppelte URL → schwarzes Video.
                val normalizedMediaUrl = mediaUrl?.let {
                    if (it.startsWith("https://letheapp.de")) it.removePrefix("https://letheapp.de") else it
                }
                val request = CreatorContentCreateRequest(
                    title = title,
                    category = category,
                    description = description,
                    contentHtml = contentHtml,
                    styxCost = styxCost,
                    previewImageUrl = previewImageUrl,
                    mediaUrl = normalizedMediaUrl,
                    mediaType = mediaType,
                    slug = slug
                )
                val response = if (isEdit && contentId != null) {
                    apiService.updateCreatorContent(contentId, request)
                } else {
                    apiService.createCreatorContent(request)
                }
                if (response.isSuccessful) {
                    loadCreatorContent()
                    loadCreatorSparks()

                    val saved = response.body()
                    if (saved != null && mediaType == "spark") {
                        val enriched = saved.copy(
                            mediaUrl = saved.mediaUrl?.let { toAbsoluteUrl(it) },
                            previewImageUrl = saved.previewImageUrl?.let { toAbsoluteUrl(it) },
                            creatorProfileImageUrl = saved.creatorProfileImageUrl
                                ?.let { toAbsoluteUrl(it) }
                        )
                        if (isEdit) {
                            // PUT: vorhandenes Item in-place ersetzen (Titel, Kategorie aktuell halten)
                            _vipFeed.value = _vipFeed.value.map { item ->
                                if (item.id == enriched.id) enriched else item
                            }
                        } else {
                            // POST-Fallback: Spark vorne anhängen wenn noch nicht vorhanden
                            if (_vipFeed.value.none { it.id == enriched.id }) {
                                _vipFeed.value = listOf(enriched) + _vipFeed.value
                            }
                        }
                    }

                    withContext(Dispatchers.Main) { onResult(true, null) }
                } else {
                    withContext(Dispatchers.Main) { onResult(false, "Fehler: ${response.code()}") }
                }
            } catch (e: Exception) {
                Timber.tag("MainViewModel").e("saveCreatorContent fehlgeschlagen: ${e.message}")
                withContext(Dispatchers.Main) { onResult(false, e.message) }
            }
        }
    }

