    /** Sendet einen neuen Kommentar zu einem Spark und hängt ihn lokal an die Liste an. */
    fun postSparkComment(
        sparkId: String,
        text: String,
        imageUri: android.net.Uri? = null,
        gifUrl: String? = null,
        onResult: (success: Boolean) -> Unit = {}
    ) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                var uploadedImageUrl: String? = gifUrl  // GIF-URL direkt verwenden
                if (imageUri != null && gifUrl == null) {
                    val cacheFile = java.io.File(context.cacheDir, "comment_img_${System.currentTimeMillis()}.jpg")
                    context.contentResolver.openInputStream(imageUri)?.use { input ->
                        java.io.FileOutputStream(cacheFile).use { out -> input.copyTo(out) }
                    }
                    val reqBody = cacheFile.asRequestBody("image/jpeg".toMediaTypeOrNull())
                    val part = MultipartBody.Part.createFormData("file", cacheFile.name, reqBody)
                    val typeBody = "image".toRequestBody("text/plain".toMediaTypeOrNull())
                    val uploadResp = apiService.uploadMedia(typeBody, part)
                    cacheFile.delete()
                    if (uploadResp.isSuccessful) {
                        uploadedImageUrl = uploadResp.body()?.get("url")?.let { toAbsoluteUrl(it) }
                    }
                }
                val response = apiService.postSparkComment(sparkId, SparkCommentCreateRequest(text, uploadedImageUrl))
                if (response.isSuccessful) {
                    response.body()?.let { newComment ->
                        // Laufendes loadSparkComments invalidieren; optimistisch anfügen
                        sparkCommentsLoadSeq++
                        _sparkComments.value = _sparkComments.value + newComment
                    }
                    withContext(Dispatchers.Main) { onResult(true) }
                    // Server-Stand nachladen (enthält jetzt den neuen Kommentar)
                    loadSparkComments(sparkId)
                } else {
                    withContext(Dispatchers.Main) { onResult(false) }
                }
            } catch (e: Exception) {
                Timber.tag("LETHE_SPARK").e("postSparkComment: ${e.message}")
                withContext(Dispatchers.Main) { onResult(false) }
            }
        }
    }

    /** Toggle-Like auf einen Spark-Kommentar; aktualisiert die Liste optimistisch. */
    fun likeSparkComment(commentId: String) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val response = apiService.likeSparkComment(commentId)
                if (response.isSuccessful) {
                    val body = response.body()
                    val nowLiked = body?.get("liked") as? Boolean ?: false
                    val newCount = (body?.get("likes_count") as? Double)?.toInt()
                        ?: (body?.get("likes_count") as? Int) ?: 0
                    _sparkComments.value = _sparkComments.value.map { c ->
                        if (c.id == commentId) c.copy(isLikedByMe = nowLiked, likesCount = newCount)
                        else c
                    }
                }
            } catch (e: Exception) {
                Timber.tag("LETHE_SPARK").e("likeSparkComment: ${e.message}")
            }
        }
    }

