    /** Erstellt eine Antwort auf einen Diskussions-Thread. */
    fun createDiscussionReply(discussionId: String, content: String, onDone: (Boolean) -> Unit) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val response = apiService.createDiscussionReply(
                    discussionId, com.securechat.app.data.network.VipDiscussionReplyCreate(content)
                )
                if (response.isSuccessful) {
                    response.body()?.let { newReply ->
                        _vipDiscussionReplies.value = _vipDiscussionReplies.value + newReply
