    fun loadVipThreadsWithCallback(categoryId: String, onResult: (List<VipThreadResponse>) -> Unit) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val response = apiService.getCategoryThreads(categoryId, false, null, null)
                if (response.isSuccessful) {
                    val threads = (response.body() ?: emptyList()).map { t ->
                        t.copy(
                            firstImageUrl = t.firstImageUrl
                                ?.takeIf { it.isNotBlank() }
                                ?.let { toAbsoluteUrl(it) }
                        )
                    }
                    // Benachrichtigung für abonnierte Kategorien bei neuen Threads
                    if (categoryId in _vipSubscribedCategories.value && threads.isNotEmpty()) {
                        val lastSeenIds = vipForumPrefs.getStringSet("seen_ids_$categoryId", emptySet()) ?: emptySet()
                        val newThreads = threads.filter { it.id !in lastSeenIds }
                        if (newThreads.isNotEmpty() && lastSeenIds.isNotEmpty()) {
                            val categoryName = vipForumPrefs.getString("name_$categoryId", "Forum") ?: "Forum"
                            newThreads.take(3).forEach { thread ->
                                notificationHelper.showVipForumNotification(categoryName, thread.title, categoryId)
                            }
                        }
                        // Gesehene IDs aktualisieren
                        vipForumPrefs.edit()
                            .putStringSet("seen_ids_$categoryId", threads.map { it.id }.toSet())
                            .apply()
                    }
                    withContext(Dispatchers.Main) { onResult(threads) }
                } else withContext(Dispatchers.Main) { onResult(emptyList()) }
            } catch (_: Exception) { withContext(Dispatchers.Main) { onResult(emptyList()) } }
        }
    }

