    fun createVipThreadWithContent(
        categoryId: String,
        title: String,
        body: String,
        urls: List<String> = emptyList(),
        mediaUris: List<android.net.Uri> = emptyList(),
        onDone: (Boolean) -> Unit = {}
    ) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                // 1. Thread anlegen
                val threadResp = apiService.createVipThread(
                    com.securechat.app.data.network.VipThreadCreate(categoryId, title)
                )
                if (!threadResp.isSuccessful || threadResp.body() == null) {
                    withContext(Dispatchers.Main) { onDone(false) }
                    return@launch
                }
                val newThread = threadResp.body()!!
                withContext(Dispatchers.Main) {
                    _vipThreads.value = listOf(newThread) + _vipThreads.value
                }

                // 2. Textbeitrag als erste Nachricht (nur body-Text)
                val trimmedBody = body.trim()
                if (trimmedBody.isNotBlank()) {
                    apiService.createThreadMessage(
                        newThread.id,
                        com.securechat.app.data.network.VipThreadMessageCreate(trimmedBody, null, "text")
                    )
                }

                // 3. Jede URL als eigene klickbare Nachricht
                for (url in urls) {
                    apiService.createThreadMessage(
                        newThread.id,
                        com.securechat.app.data.network.VipThreadMessageCreate(url, url, "url")
                    )
                }

                // 4. Mediendateien hochladen + als Nachricht posten
                for (mediaUri in mediaUris) {
                    try {
                        val mimeType = context.contentResolver.getType(mediaUri) ?: "image/jpeg"
                        val isVideo = mimeType.startsWith("video")
                        val ext = mimeType.substringAfterLast('/').let {
                            when (it) { "jpeg" -> "jpg"; "quicktime" -> "mov"; else -> it }
                        }
                        val bytes = context.contentResolver.openInputStream(mediaUri)?.readBytes() ?: continue
                        val filename = "thread_${System.currentTimeMillis()}.$ext"
                        val reqBody = bytes.toRequestBody(mimeType.toMediaTypeOrNull())
                        val part = okhttp3.MultipartBody.Part.createFormData("file", filename, reqBody)
                        val typeStr = if (isVideo) "video" else "image"
                        val typeBody = typeStr.toRequestBody("text/plain".toMediaTypeOrNull())
                        val uploadResp = apiService.uploadMedia(typeBody, part)
                        if (uploadResp.isSuccessful) {
                            val uploadedUrl = uploadResp.body()?.get("url")?.let { toAbsoluteUrl(it) } ?: continue
                            val label = if (isVideo) "Video" else "Bild"
                            apiService.createThreadMessage(
                                newThread.id,
                                com.securechat.app.data.network.VipThreadMessageCreate(label, uploadedUrl, typeStr)
                            )
                        }
                    } catch (e: Exception) {
                        Timber.tag("MainViewModel").e("Thread-Media-Upload: ${e.message}")
                    }
                }

                withContext(Dispatchers.Main) { onDone(true) }
            } catch (e: Exception) {
                Timber.tag("MainViewModel").e("createVipThreadWithContent: ${e.message}")
                withContext(Dispatchers.Main) { onDone(false) }
            }
        }
    }

