    fun createVipThreadMessageWithMedia(threadId: String, content: String, mediaUri: android.net.Uri?, mediaTypeName: String = "image", onDone: (Boolean) -> Unit = {}) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                if (mediaUri != null) {
                    val file = uriToFile(mediaUri, mediaTypeName) ?: run {
                        withContext(Dispatchers.Main) { onDone(false) }; return@launch
                    }
                    val requestFile = file.asRequestBody((if (mediaTypeName == "video") "video/*" else "image/*").toMediaTypeOrNull())
                    val part = okhttp3.MultipartBody.Part.createFormData("file", file.name, requestFile)
                    val mtBody = mediaTypeName.toRequestBody("text/plain".toMediaTypeOrNull())
                    val uploadResp = apiService.uploadMedia(mtBody, part)
                    val uploadedUrl = if (uploadResp.isSuccessful) uploadResp.body()?.get("url")?.let { toAbsoluteUrl(it) } else null
                    createVipThreadMessage(threadId, content, uploadedUrl, mediaTypeName, onDone)
                } else {
                    createVipThreadMessage(threadId, content, null, "text", onDone)
                }
            } catch (e: Exception) {
                Timber.tag("MainViewModel").e("createVipThreadMessageWithMedia: ${e.message}")
                withContext(Dispatchers.Main) { onDone(false) }
            }
        }
    }

