    /** Sendet RSVP-Status für einen finalisierten Termin. Optimistisches UI-Update. */
    fun rsvpAppointment(appointmentId: String, status: String, onResult: (Boolean, String) -> Unit) {
        // Optimistisches Update: myStatus sofort setzen
        val current = _appointments.value[appointmentId]
        if (current != null) {
            val myId = currentUser.value?.userId ?: ""
            val myName = currentUser.value?.name
            val myImg = currentUser.value?.profileImageUrl?.let { if (it.startsWith("http")) it else "https://letheapp.de$it" }
            val attendee = RsvpAttendee(userId = myId, name = myName, profileImageUrl = myImg)
            val updatedGoing = if (status == "going") {
                (current.going.filter { it.userId != myId } + attendee)
            } else {
                current.going.filter { it.userId != myId }
            }
            val updatedDeclined = if (status == "declined") {
                (current.declined.filter { it.userId != myId } + attendee)
            } else {
                current.declined.filter { it.userId != myId }
            }
            _appointments.value = _appointments.value + (appointmentId to current.copy(
                going = updatedGoing, declined = updatedDeclined, myStatus = status
            ))
        }

        viewModelScope.launch(Dispatchers.IO) {
            try {
                val response = apiService.rsvpAppointment(appointmentId, RsvpRequest(status))
                if (response.isSuccessful) {
                    response.body()?.let { apt ->
                        _appointments.value = _appointments.value + (apt.id to apt)
                    }
                    onResult(true, "")
                } else {
                    onResult(false, "Fehler beim Senden.")
                }
            } catch (e: Exception) {
                onResult(false, e.message ?: "Netzwerkfehler")
            }
        }
    }

