    /** WS-Event 'appointment_vote_update' oder 'appointment_status_update'. */
    fun handleAppointmentUpdate(payload: Map<*, *>) {
        @Suppress("UNCHECKED_CAST")
        val aptMap = payload["appointment"] as? Map<String, Any> ?: return
        val aptId = aptMap["id"] as? String ?: return
        try {
            val json = com.google.gson.Gson().toJson(aptMap)
            val apt = com.google.gson.Gson().fromJson(json, GroupAppointmentResponse::class.java)
            _appointments.value = _appointments.value + (aptId to apt)
        } catch (e: Exception) {
            Timber.tag("LETHE_WS").e("handleAppointmentUpdate parse error: ${e.message}")
        }
    }

    /** Verarbeitet ein eingehendes WS-Event 'appointment_rsvp_update'. */
    fun handleAppointmentRsvpUpdate(payload: Map<*, *>) {
        val appointmentId = payload["appointment_id"] as? String ?: return
        val userId = payload["user_id"] as? String ?: return
        val status = payload["status"] as? String ?: return
        val userName = payload["user_name"] as? String
        val profileImageUrl = payload["profile_image_url"] as? String

        val current = _appointments.value[appointmentId] ?: return
        val attendee = RsvpAttendee(userId = userId, name = userName, profileImageUrl = profileImageUrl)
        val updatedGoing = if (status == "going") {
            (current.going.filter { it.userId != userId } + attendee)
        } else {
            current.going.filter { it.userId != userId }
        }
        val updatedDeclined = if (status == "declined") {
            (current.declined.filter { it.userId != userId } + attendee)
        } else {
            current.declined.filter { it.userId != userId }
        }
        val myId = currentUser.value?.userId ?: ""
        val myStatus = if (userId == myId) status else current.myStatus
        _appointments.value = _appointments.value + (appointmentId to current.copy(
            going = updatedGoing, declined = updatedDeclined, myStatus = myStatus
        ))
        Timber.tag("LETHE_WS").d("RSVP-Update: appointment=$appointmentId user=$userId status=$status")
    }

    /**
     * Hängt weitere Sparks an den bestehenden Feed an.
     * Alle User sehen alle Sparks – der Feed gibt bis zu 200 Sparks zurück, personalisiert sortiert.
     */
    fun loadMoreSparks() {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val response = apiService.getVipFeed(type = "spark")
                if (response.isSuccessful) {
                    val newItems = response.body()?.map { c ->
                        c.copy(
                            mediaUrl = c.mediaUrl?.let { toAbsoluteUrl(it) },
                            previewImageUrl = c.previewImageUrl?.let { toAbsoluteUrl(it) },
                            creatorProfileImageUrl = c.creatorProfileImageUrl?.let { toAbsoluteUrl(it) }
                        )
                    } ?: return@launch
                    if (newItems.isEmpty()) return@launch
                    val existingIds = _vipFeed.value.map { it.id }.toSet()
                    val toAppend = newItems.filter { it.id !in existingIds }
                    // Cycling: nur wenn mehrere Sparks vorhanden (Shuffle für Abwechslung).
                    // Einzelne Sparks nicht wiederholen — verhindert endloses Duplizieren.
                    val toAdd = when {
                        toAppend.isNotEmpty() -> toAppend
                        newItems.size > 1 -> newItems.shuffled()
                        else -> emptyList()
                    }
                    if (toAdd.isNotEmpty()) _vipFeed.value = _vipFeed.value + toAdd
                }
            } catch (e: Exception) {
                Timber.tag("MainViewModel").e("loadMoreSparks fehlgeschlagen: ${e.message}")
            }
        }
    }

    /**
     * Lädt Sparks ähnlich zu [similarToId] und fügt sie ab Position [insertAfterPage]+1
     * in den Feed ein. Wird aufgerufen wenn ein User mit einem Spark interagiert hat
     * (≥50 % Video gesehen oder Bild-Spark zum nächsten Bild geswiped).
     */
    fun loadSimilarSparksAfterPage(insertAfterPage: Int, similarToId: String) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val response = apiService.getVipFeed(type = "spark", similarTo = similarToId)
                if (response.isSuccessful) {
                    val newItems = response.body()?.map { c ->
                        c.copy(
                            mediaUrl = c.mediaUrl?.let { toAbsoluteUrl(it) },
                            previewImageUrl = c.previewImageUrl?.let { toAbsoluteUrl(it) },
                            creatorProfileImageUrl = c.creatorProfileImageUrl?.let { toAbsoluteUrl(it) }
                        )
                    } ?: return@launch
                    if (newItems.isEmpty()) return@launch
                    val currentFeed = _vipFeed.value.toMutableList()
                    val existingIds = currentFeed.map { it.id }.toSet()
                    val toInsert = newItems.filter { it.id !in existingIds }
                    if (toInsert.isNotEmpty()) {
                        val insertAt = minOf(insertAfterPage + 1, currentFeed.size)
                        currentFeed.addAll(insertAt, toInsert)
                        _vipFeed.value = currentFeed
                    }
                }
            } catch (e: Exception) {
                Timber.tag("MainViewModel").e("loadSimilarSparks fehlgeschlagen: ${e.message}")
            }
        }
    }

    /**
     * Fügt einen Spark an Position 0 des Feeds ein (z.B. bei Tap auf gespeichertes/geliktes Video).
     * Duplikate werden zuerst entfernt, damit der Spark genau einmal ganz vorne steht.
     */
    fun prependSparkToFeed(spark: com.securechat.app.data.network.CreatorContentResponse) {
        val withoutDuplicate = _vipFeed.value.filter { it.id != spark.id }
        _vipFeed.value = listOf(spark) + withoutDuplicate
        _feedScrollToTop.value = true
    }

    /** Liked oder un-liked einen Content-Beitrag/Spark. Aktualisiert den Feed optimistisch. */
    fun likeContent(contentId: String) {
        // Optimistisches UI-Update
        _vipFeed.value = _vipFeed.value.map { item ->
            if (item.id == contentId) {
                val nowLiked = !item.isLikedByMe
                item.copy(
                    isLikedByMe = nowLiked,
                    likes = if (nowLiked) item.likes + 1 else maxOf(0, item.likes - 1)
                )
            } else item
        }
        viewModelScope.launch(Dispatchers.IO) {
            try {
                apiService.likeContent(contentId)
            } catch (e: Exception) {
                Timber.tag("MainViewModel").e("likeContent fehlgeschlagen: ${e.message}")
                // Rollback bei Fehler
                loadVipFeed()
            }
        }
    }

