    // ===================== LIVE CHAT =====================

    private val liveChatOkHttpClient by lazy {
        okhttp3.OkHttpClient.Builder()
            .readTimeout(0, java.util.concurrent.TimeUnit.MILLISECONDS)
            .build()
    }

    fun connectLiveChat(creatorId: String) {
        val token = tokenManager.getToken() ?: return
        val wsUrl = "wss://letheapp.de/ws/live/$creatorId/chat?token=$token"
        _liveChatMessages.value = emptyList()
        _liveViewerCount.value = 0
        _isLiveChatConnected.value = false

        val request = okhttp3.Request.Builder().url(wsUrl).build()
        liveChatWebSocket = liveChatOkHttpClient.newWebSocket(request, object : okhttp3.WebSocketListener() {
            override fun onOpen(ws: okhttp3.WebSocket, response: okhttp3.Response) {
                _isLiveChatConnected.value = true
            }
            override fun onMessage(ws: okhttp3.WebSocket, text: String) {
                try {
                    val json = org.json.JSONObject(text)
                    when (json.optString("type")) {
                        "chat_message" -> {
                            val msg = com.securechat.app.data.network.LiveChatMessage(
                                userId = json.optString("user_id"),
                                userName = json.optString("user_name", "Anonym"),
                                text = json.optString("text"),
                                isSystem = false,
                                profileImageUrl = json.optString("profile_image_url", "").takeIf { it.isNotBlank() }?.let { toAbsoluteUrl(it) },
                                timestamp = json.optString("timestamp")
                            )
                            _liveChatMessages.value = (_liveChatMessages.value + msg).takeLast(200)
                        }
                        "system_message" -> {
                            val msg = com.securechat.app.data.network.LiveChatMessage(
                                userId = "system",
                                userName = "System",
                                text = json.optString("text"),
                                isSystem = true
                            )
                            _liveChatMessages.value = (_liveChatMessages.value + msg).takeLast(200)
                        }
                        "viewer_count" -> {
                            _liveViewerCount.value = json.optInt("count", 0)
                        }
                        "kicked" -> {
                            disconnectLiveChat()
                        }
                    }
                } catch (e: Exception) {
                    Timber.tag("LETHE_WS").e("LiveChat parse error: ${e.message}")
                }
            }
            override fun onFailure(ws: okhttp3.WebSocket, t: Throwable, response: okhttp3.Response?) {
                _isLiveChatConnected.value = false
                Timber.tag("LETHE_WS").e("LiveChat WS failure: ${t.message}")
            }
            override fun onClosed(ws: okhttp3.WebSocket, code: Int, reason: String) {
                _isLiveChatConnected.value = false
            }
        })
    }

    fun disconnectLiveChat() {
        liveChatWebSocket?.close(1000, "leave")
        liveChatWebSocket = null
        _isLiveChatConnected.value = false
        _liveChatMessages.value = emptyList()
        _liveViewerCount.value = 0
    }

    fun sendLiveChatMessage(text: String) {
        val trimmed = text.trim()
        if (trimmed.isBlank() || liveChatWebSocket == null) return
        val payload = org.json.JSONObject().apply {
            put("type", "chat_message")
            put("text", trimmed)
        }
        liveChatWebSocket?.send(payload.toString())
    }

    fun sendLiveChatModAction(action: String, targetUserId: String, reason: String = "") {
        val payload = org.json.JSONObject().apply {
            put("type", "mod_action")
            put("action", action)
            put("target_user_id", targetUserId)
            put("reason", reason)
        }
        liveChatWebSocket?.send(payload.toString())
    }

