    fun startStream(onResult: (Boolean) -> Unit) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val response = apiService.startStream()
                if (response.isSuccessful) {
                    // Live-Eintrag an den Anfang des Spark-Feeds stellen
                    val profile = _creatorProfile.value
                    if (profile != null) {
                        val liveEntry = com.securechat.app.data.network.CreatorContentResponse(
                            id = "live_${profile.id}",
                            creatorId = profile.id,
                            title = "${profile.name ?: profile.username ?: "Creator"} ist jetzt LIVE",
                            mediaType = "live",
                            isLive = true,
                            creatorName = profile.name,
                            creatorUsername = profile.username,
                            creatorProfileImageUrl = profile.profileImageUrl
                        )
                        // Bestehenden Live-Eintrag desselben Creators ersetzen oder vorne einhängen
                        _vipFeed.value = listOf(liveEntry) +
                            _vipFeed.value.filter { !(it.mediaType == "live" && it.creatorId == profile.id) }
                    }
                    // Creator-Profil als live markieren
                    _creatorProfile.value = profile?.copy(isLive = true)
                }
                withContext(Dispatchers.Main) { onResult(response.isSuccessful) }
            } catch (e: Exception) {
                withContext(Dispatchers.Main) { onResult(false) }
            }
        }
    }

    fun endStream(onResult: (Boolean) -> Unit) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val response = apiService.endStream()
                if (response.isSuccessful) {
                    val profile = _creatorProfile.value
                    // Live-Eintrag aus dem Feed entfernen (isLive=true, nicht mediaType="live")
                    _vipFeed.value = _vipFeed.value.filter { !it.isLive }
                    // Creator-Profil als nicht-live markieren
                    _creatorProfile.value = profile?.copy(isLive = false)
                    // Feed neu laden damit Sparks & Content wieder erscheinen
                    loadVipFeed(type = "spark")
                    loadVipFeed(type = "content")
                }
                withContext(Dispatchers.Main) { onResult(response.isSuccessful) }
            } catch (e: Exception) {
                withContext(Dispatchers.Main) { onResult(false) }
            }
        }
    }

