    /** Lädt ein Bild für den Content-Editor hoch und gibt die URL zurück. */
    fun uploadContentImage(uri: Uri, onUrl: (String?) -> Unit) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val file = uriToFile(uri, "image") ?: run {
                    withContext(Dispatchers.Main) { onUrl(null) }
                    return@launch
                }
                if (file.length() > MAX_UPLOAD_BYTES) {
                    withContext(Dispatchers.Main) { _statusMessage.value = "Datei zu groß (max. 80 MB)"; onUrl(null) }
                    return@launch
                }
                val requestFile = file.asRequestBody("image/*".toMediaTypeOrNull())
                val body = MultipartBody.Part.createFormData("file", file.name, requestFile)
                val response = apiService.uploadContentImage(body)
                val url = response.body()?.get("url")?.let { toAbsoluteUrl(it) }
                withContext(Dispatchers.Main) { onUrl(url) }
            } catch (e: Exception) {
                Timber.tag("MainViewModel").e("uploadContentImage fehlgeschlagen: ${e.message}")
                withContext(Dispatchers.Main) { onUrl(null) }
            }
        }
    }

