    fun uploadArticleFile(
        articleId: Int,
        fileType: String,
        uri: Uri,
        onResult: (ArticleFileResponse?, String?) -> Unit
    ) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val mimeType = when (fileType) {
                    "image" -> "image/*"
                    "music" -> "audio/*"
                    "3d_model" -> "application/octet-stream"
                    else -> "*/*"
                }
                val file = uriToFile(uri, fileType) ?: run {
                    withContext(Dispatchers.Main) { onResult(null, "Datei konnte nicht gelesen werden") }
                    return@launch
                }
                if (file.length() > MAX_UPLOAD_BYTES) {
                    withContext(Dispatchers.Main) { onResult(null, "Datei zu groß (max. 80 MB)") }
                    return@launch
                }
                val requestFile = file.asRequestBody(mimeType.toMediaTypeOrNull())
                val filePart = MultipartBody.Part.createFormData("file", file.name, requestFile)
                val fileTypeBody = fileType.toRequestBody("text/plain".toMediaTypeOrNull())
                val response = apiService.uploadArticleFile(articleId, fileTypeBody, filePart)
                withContext(Dispatchers.Main) {
                    if (response.isSuccessful) {
                        onResult(response.body(), null)
                    } else {
                        onResult(null, "Fehler ${response.code()}: ${response.message()}")
                    }
                }
            } catch (e: Exception) {
                Timber.tag("MainViewModel").e("uploadArticleFile fehlgeschlagen: ${e.message}")
                withContext(Dispatchers.Main) { onResult(null, e.message) }
            }
        }
    }

    /**
     * Vollständiger Spark-Upload-Flow:
     *   1. Client-seitiges Transcoding + HLS-Segmentierung via [SparkTranscoder]  (0 % → 60 %)
     *   2. Multipart-Upload aller Dateien (thumbnail, m3u8, *.ts) an /creator/upload/spark-hls (60 % → 95 %)
     *   3. Fertig-Signal an Aufrufer                                                (95 % → 100 %)
     *
     * Der kombinierte Fortschritt wird in [sparkUploadProgress] gepublished.
     * Das Thumbnail ist ab Abschluss von Phase 1 in [sparkThumbnailUri] verfügbar.
     *
     * @param title        Titel des Sparks (kann leer sein – Backend setzt Fallback "Spark").
     * @param category     Kategorie (optional).
     * @param description  Beschreibung (optional).
     * @param onResult     Wird auf dem Main-Thread aufgerufen mit (spark, errorMessage?).
     *                     Bei Fehler ist spark null.
     */
    fun uploadSparkHls(
        uri: Uri,
        title: String = "",
        category: String? = null,
        description: String? = null,
        musicId: String? = null,
        soundOriginSparkId: String? = null,
        musicTitle: String? = null,
        musicArtist: String? = null,
        musicCoverUrl: String? = null,
        onResult: (spark: CreatorContentResponse?, error: String?) -> Unit
    ) {
        viewModelScope.launch {
            _sparkUploadProgress.value = 0f
            _sparkThumbnailUri.value = null

            try {
                // Upload-Größenlimit prüfen (80 MB) – vor dem Transcoding
                val inputSize = withContext(Dispatchers.IO) {
                    context.contentResolver.openAssetFileDescriptor(uri, "r")?.use { it.length } ?: 0L
                }
                if (inputSize > MAX_UPLOAD_BYTES) {
                    withContext(Dispatchers.Main) {
                        _sparkUploadProgress.value = -1f
                        onResult(null, "Datei zu groß (max. 80 MB)")
                    }
                    return@launch
                }

                // ── Phase 1+2+3: Transcode → Segment → m3u8 (0 % → 60 %) ─────────────
                val result = com.securechat.app.data.local.SparkTranscoder.transcode(
                    context = context,
                    inputUri = uri,
                    onProgress = { p ->
                        _sparkUploadProgress.value = p * 0.60f
                    }
                )

                when (result) {
                    is com.securechat.app.data.local.SparkTranscoder.TranscodeResult.Error -> {
                        Timber.tag("LETHE_SPARK").e("Transcode Fehler: ${result.message}")
                        _sparkUploadProgress.value = -1f
                        _sparkThumbnailUri.value = null
                        withContext(Dispatchers.Main) { onResult(null, result.message) }
                        return@launch
                    }
                    is com.securechat.app.data.local.SparkTranscoder.TranscodeResult.Success -> {
                        val output = result.output

                        // Thumbnail sofort für UI-Vorschau bereitstellen
                        _sparkThumbnailUri.value = Uri.fromFile(output.thumbnailFile)

                        // ── Phase 4: Multipart-Upload (60 % → 95 %) ──────────────────────
                        _sparkUploadProgress.value = 0.62f

                        // Dynamisch alle Dateien im Ausgabeverzeichnis einlesen.
                        // Dadurch werden thumbnail.jpg, index.m3u8 UND alle Segments
                        // (video.mp4 oder seg*.ts) zuverlässig ohne Hardcoding erfasst.
                        val allOutputFiles = output.outputDir
                            .listFiles()
                            ?.sortedBy { it.name }
                            ?: emptyList()

                        val parts = mutableListOf<MultipartBody.Part>()

                        allOutputFiles.forEachIndexed { idx, file ->
                            val mime = when (file.extension.lowercase()) {
                                "jpg", "jpeg" -> "image/jpeg"
                                "png"         -> "image/png"
                                "m3u8"        -> "application/x-mpegURL"
                                "ts"          -> "video/mp2t"
                                "mp4"         -> "video/mp4"
                                else          -> {
                                    Timber.tag("LETHE_SPARK")
                                        .w("Unbekannte Dateiendung übersprungen: ${file.name}")
                                    return@forEachIndexed
                                }
                            }
                            val body = file.asRequestBody(mime.toMediaTypeOrNull())
                            parts.add(
                                MultipartBody.Part.createFormData("files", file.name, body)
                            )
                            // Fortschritt anteilig über alle Dateien verteilen
                            val partProgress = 0.62f +
                                    (idx + 1).toFloat() / allOutputFiles.size.coerceAtLeast(1) * 0.30f
                            _sparkUploadProgress.value = partProgress.coerceAtMost(0.92f)
                        }

                        _sparkUploadProgress.value = 0.93f

                        // Titel und Kategorie als Multipart-Form-Felder (Backend erstellt DB-Eintrag)
                        val titleBody = (title.ifBlank { "Spark" })
                            .toRequestBody("text/plain".toMediaTypeOrNull())
                        val categoryBody = category
                            ?.toRequestBody("text/plain".toMediaTypeOrNull())
                        val descriptionBody = description
                            ?.toRequestBody("text/plain".toMediaTypeOrNull())

                        fun str(s: String?) = s?.toRequestBody("text/plain".toMediaTypeOrNull())
                        val response = withContext(Dispatchers.IO) {
                            apiService.uploadSparkHls(
                                parts, titleBody, categoryBody, descriptionBody,
                                str(musicTitle), str(musicArtist), str(musicCoverUrl),
                                str(soundOriginSparkId), str(musicId)
                            )
                        }

                        if (response.isSuccessful) {
                            val newSpark = response.body()

                            _sparkUploadProgress.value = 1.0f

                            // Neuen Spark sofort vorne in den VIP-Feed einhängen,
                            // damit er auf dem SparksFeedScreen sofort sichtbar ist –
                            // ohne dass ein kompletter Reload die Reihenfolge durcheinander bringt.
                            if (newSpark != null) {
                                val enriched = newSpark.copy(
                                    mediaUrl = newSpark.mediaUrl?.let { toAbsoluteUrl(it) },
                                    previewImageUrl = newSpark.previewImageUrl?.let { toAbsoluteUrl(it) },
                                    creatorProfileImageUrl = newSpark.creatorProfileImageUrl
                                        ?.let { toAbsoluteUrl(it) }
                                )
                                // Dedup: nur einhängen wenn noch nicht vorhanden
                                if (_vipFeed.value.none { it.id == enriched.id }) {
                                    _vipFeed.value = listOf(enriched) + _vipFeed.value
                                }
                            }

                            // Cache kurz sichtbar lassen, dann aufräumen
                            kotlinx.coroutines.delay(1_500)
                            withContext(Dispatchers.IO) { output.outputDir.deleteRecursively() }
                            _sparkUploadProgress.value = -1f
                            _sparkThumbnailUri.value = null

                            withContext(Dispatchers.Main) {
                                onResult(newSpark, null)
                            }
                        } else {
                            withContext(Dispatchers.IO) { output.outputDir.deleteRecursively() }
                            _sparkUploadProgress.value = -1f
                            _sparkThumbnailUri.value = null
                            withContext(Dispatchers.Main) {
                                onResult(null, "Upload fehlgeschlagen (${response.code()})")
                            }
                        }
                    }
                }
            } catch (e: Exception) {
                Timber.tag("LETHE_SPARK").e("uploadSparkHls fehlgeschlagen: ${e.message}")
                _sparkUploadProgress.value = -1f
                _sparkThumbnailUri.value = null
                withContext(Dispatchers.Main) { onResult(null, e.message) }
            }
        }
    }

