    /**
     * Lädt Bilder von [uris], speichert sie temporär und uploadet sie als Bild-Slideshow-Spark.
     */
    fun uploadSparkImages(
        uris: List<android.net.Uri>,
        title: String = "",
        description: String? = null,
        category: String? = null,
        musicTitle: String? = null,
        musicArtist: String? = null,
        musicCoverUrl: String? = null,
        soundOriginSparkId: String? = null,
        musicId: String? = null,
        audioUri: android.net.Uri? = null,
        onProgress: (Float) -> Unit = {},
        onResult: (CreatorContentResponse?, String?) -> Unit
    ) {
        viewModelScope.launch {
            try {
                onProgress(0.1f)
                val parts = mutableListOf<okhttp3.MultipartBody.Part>()
                uris.forEachIndexed { idx, uri ->
                    val bytes = withContext(Dispatchers.IO) {
                        context.contentResolver.openInputStream(uri)?.readBytes()
                    } ?: return@forEachIndexed
                    val ext = context.contentResolver.getType(uri)
                        ?.substringAfterLast('/')?.let { ".$it" } ?: ".jpg"
                    val filename = "img_${idx.toString().padStart(3, '0')}$ext"
                    val mime = context.contentResolver.getType(uri) ?: "image/jpeg"
                    val body = bytes.toRequestBody(mime.toMediaTypeOrNull())
                    parts.add(okhttp3.MultipartBody.Part.createFormData("files", filename, body))
                    onProgress(0.1f + (idx + 1).toFloat() / uris.size * 0.7f)
                }
                onProgress(0.85f)
                fun str(s: String?) = s?.toRequestBody("text/plain".toMediaTypeOrNull())
                // Audio-Datei als eigenes Part anhängen
                val audioPart: okhttp3.MultipartBody.Part? = audioUri?.let { aUri ->
                    val audioBytes = withContext(Dispatchers.IO) {
                        context.contentResolver.openInputStream(aUri)?.readBytes()
                    }
                    if (audioBytes != null) {
                        val rawExt = context.contentResolver.getType(aUri)?.substringAfterLast('/') ?: "mp3"
                        val ext = when (rawExt.lowercase()) {
                            "mpeg", "mp3" -> ".mp3"
                            "mp4", "m4a", "x-m4a" -> ".m4a"
                            "aac", "x-aac" -> ".aac"
                            "ogg", "x-ogg", "vorbis" -> ".ogg"
                            "flac", "x-flac" -> ".flac"
                            "wav", "x-wav" -> ".wav"
                            else -> ".mp3"
                        }
                        val mime = context.contentResolver.getType(aUri) ?: "audio/mpeg"
                        val body = audioBytes.toRequestBody(mime.toMediaTypeOrNull())
                        okhttp3.MultipartBody.Part.createFormData("audio_file", "audio$ext", body)
                    } else null
                }
                val response = withContext(Dispatchers.IO) {
                    apiService.uploadSparkImages(
                        parts,
                        (title.ifBlank { "Spark" }).toRequestBody("text/plain".toMediaTypeOrNull()),
                        str(description),
                        str(category),
                        str(musicTitle),
                        str(musicArtist),
                        str(musicCoverUrl),
                        str(soundOriginSparkId),
                        str(musicId),
                        audioPart
                    )
                }
                onProgress(1f)
                if (response.isSuccessful) {
                    val newSpark = response.body()
                    if (newSpark != null && _vipFeed.value.none { it.id == newSpark.id }) {
                        _vipFeed.value = listOf(newSpark) + _vipFeed.value
                    }
                    withContext(Dispatchers.Main) { onResult(newSpark, null) }
                } else {
                    withContext(Dispatchers.Main) {
                        onResult(null, "Upload fehlgeschlagen (${response.code()})")
                    }
                }
            } catch (e: Exception) {
                withContext(Dispatchers.Main) { onResult(null, e.message) }
            }
        }
    }

