    /** Lädt eine MP3-Datei mit Metadaten hoch und gibt den gespeicherten MusicResponse zurück. */
    fun uploadMusicFile(
        uri: android.net.Uri,
        artist: String? = null,
        songTitle: String? = null,
        year: String? = null,
        lyrics: String? = null,
        producer: String? = null,
        previewOffsetSec: Int = 0,
        onResult: (MusicResponse?, String?) -> Unit
    ) {
        viewModelScope.launch {
            try {
                val bytes = withContext(Dispatchers.IO) {
                    context.contentResolver.openInputStream(uri)?.readBytes()
                }
                if (bytes == null) {
                    withContext(Dispatchers.Main) { onResult(null, "Datei konnte nicht gelesen werden") }
                    return@launch
                }
                val mime = context.contentResolver.getType(uri) ?: "audio/mpeg"
                val ext = when (mime) {
                    "audio/mpeg", "audio/mp3", "audio/x-mp3" -> ".mp3"
                    "audio/mp4", "audio/x-m4a", "audio/m4a" -> ".m4a"
                    "audio/aac", "audio/x-aac" -> ".aac"
                    "audio/ogg", "application/ogg", "audio/vorbis" -> ".ogg"
                    "audio/flac", "audio/x-flac" -> ".flac"
                    "audio/wav", "audio/x-wav", "audio/wave" -> ".wav"
                    else -> ".mp3"
                }
                val filename = "music$ext"
                val body = bytes.toRequestBody(mime.toMediaTypeOrNull())
                val part = okhttp3.MultipartBody.Part.createFormData("file", filename, body)
                fun String.toPlain() = toRequestBody("text/plain".toMediaTypeOrNull())
                val response = withContext(Dispatchers.IO) {
                    apiService.uploadMusicFile(
                        file = part,
                        artist = artist?.takeIf { it.isNotBlank() }?.toPlain(),
                        songTitle = songTitle?.takeIf { it.isNotBlank() }?.toPlain(),
                        year = year?.takeIf { it.isNotBlank() }?.toPlain(),
                        lyrics = lyrics?.takeIf { it.isNotBlank() }?.toPlain(),
                        producer = producer?.takeIf { it.isNotBlank() }?.toPlain(),
                        previewOffsetSec = previewOffsetSec.toString().toPlain()
                    )
                }
                if (response.isSuccessful) {
                    withContext(Dispatchers.Main) { onResult(response.body(), null) }
                } else {
                    withContext(Dispatchers.Main) { onResult(null, "Musik-Upload fehlgeschlagen (${response.code()})") }
                }
            } catch (e: Exception) {
                withContext(Dispatchers.Main) { onResult(null, e.message) }
            }
        }
    }

