    /** Lädt eine Dokument-Datei (PDF, DOCX, TXT, Quellcode usw.) hoch und sendet sie als Chat-Nachricht. */
    fun sendDocumentMessage(chatId: String, uri: Uri, isGroup: Boolean = false) {
        viewModelScope.launch {
            _mediaUploadStatus.value = MediaUploadStatus.Uploading(0)
            _isLoading.value = true
            val me = _currentUser.value ?: return@launch
            val clientId = UUID.randomUUID().toString()
            var file: File? = null
            try {
                // Originalen Dateinamen aus ContentResolver lesen
                val fileName = context.contentResolver.query(uri, null, null, null, null)?.use { cursor ->
                    val idx = cursor.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME)
                    cursor.moveToFirst()
                    if (idx >= 0) cursor.getString(idx) else null
                } ?: uri.lastPathSegment ?: "Dokument"

                // Datei in den Cache kopieren (IO-Thread)
                file = withContext(Dispatchers.IO) {
                    val dest = File(context.cacheDir, "doc_${System.currentTimeMillis()}_$fileName")
                    context.contentResolver.openInputStream(uri)?.use { input ->
                        FileOutputStream(dest).use { input.copyTo(it) }
                    }
                    dest
                }
                val fileSize = file!!.length()

                // Upload-Größenlimit prüfen (80 MB)
                if (fileSize > MAX_UPLOAD_BYTES) {
                    withContext(Dispatchers.IO) { file?.delete() }
                    _statusMessage.value = "Datei zu groß (max. 80 MB)"
                    _mediaUploadStatus.value = MediaUploadStatus.Idle
                    return@launch
                }

                // Platzhalter-Bubble sofort mit Dateinamen anzeigen (URL noch leer)
                val placeholderBlob = org.json.JSONObject().apply {
                    put("filename", fileName)
                    put("file_size", fileSize)
                }.toString()
                messageDao.insertMessage(
                    MessageEntity(
                        chatId = chatId,
                        senderId = me.userId,
                        receiverId = chatId,
                        content = placeholderBlob,
                        mediaType = "document",
                        mediaUrl = null,
                        timestamp = System.currentTimeMillis(),
                        isSent = false,
                        clientMessageId = clientId,
                        deliveryStatus = 0
                    )
                )

                val requestFile = ProgressRequestBody(
                    delegate = file!!.asRequestBody("application/octet-stream".toMediaTypeOrNull()),
                    onProgress = { sent, total ->
                        if (total > 0) {
                            val pct = (sent * 100f / total).toInt().coerceIn(0, 99)
                            _mediaUploadStatus.value = MediaUploadStatus.Uploading(pct)
                        }
                    }
                )
                val body = MultipartBody.Part.createFormData("file", fileName, requestFile)
                val typeBody = "document".toRequestBody("text/plain".toMediaTypeOrNull())
                val response = apiService.uploadMedia(typeBody, body)
                withContext(Dispatchers.IO) { file?.delete() }

                if (response.isSuccessful) {
                    val mediaUrl = response.body()?.get("url")?.let { toAbsoluteUrl(it) }
                    if (mediaUrl != null) {
                        val finalBlob = org.json.JSONObject().apply {
                            put("file_url", mediaUrl)
                            put("filename", fileName)
                            put("file_size", fileSize)
                        }.toString()
                        // Platzhalter-Bubble URL + Content aktualisieren
                        messageDao.updateMessageUrlAndContent(clientId, mediaUrl, finalBlob)
                        if (chatId == "self_notes") {
                            messageDao.markSelfNoteDelivered(clientId)
                        } else if (isGroup) {
                            webSocketManager.sendMessage("group_message", chatId, mapOf(
                                "content_blob" to finalBlob,
                                "media_type" to "document",
                                "media_url" to mediaUrl,
                                "group_id" to chatId,
                                "client_message_id" to clientId,
                                "sender_timestamp" to System.currentTimeMillis()
                            ))
                        } else {
                            webSocketManager.sendMessage("message", chatId, mapOf(
                                "content_blob" to finalBlob,
                                "media_type" to "document",
                                "media_url" to mediaUrl,
                                "client_message_id" to clientId
                            ))
                        }
                    }
                } else {
                    messageDao.deleteMessageByClientId(clientId)
                    _statusMessage.value = "Upload fehlgeschlagen (${response.code()})"
                }
            } catch (e: Exception) {
                messageDao.deleteMessageByClientId(clientId)
                _statusMessage.value = "Upload fehlgeschlagen: ${e.message}"
                Timber.tag("Chat").e("sendDocumentMessage failed", e)
            } finally {
                _mediaUploadStatus.value = MediaUploadStatus.Idle
                _isLoading.value = false
            }
        }
    }

    /** Session-Expired-Event: wird emitted wenn Token-Refresh dauerhaft fehlschlägt. */
    val sessionExpiredEvent = tokenManager.sessionExpiredEvent

    /** BroadcastReceiver: setzt Online-Status auf offline wenn Bildschirm ausgeht. */
    private val screenStateReceiver = object : android.content.BroadcastReceiver() {
        override fun onReceive(ctx: android.content.Context, intent: android.content.Intent) {
            if (_currentUser.value == null) return
            when (intent.action) {
                android.content.Intent.ACTION_SCREEN_OFF -> {
                    viewModelScope.launch { updateOnlineStatus(false) }
                }
                android.content.Intent.ACTION_SCREEN_ON -> {
                    // Online nur wenn App auch im Vordergrund ist
                    if (_isAppInForeground.value) {
                        viewModelScope.launch { updateOnlineStatus(true) }
                    }
                }
            }
        }
    }

    // --- ACCOUNT-SWITCHER ---
    private val _savedAccounts = MutableStateFlow<List<ProfileManager.SavedAccount>>(emptyList())
    /** Alle auf diesem Gerät gespeicherten Accounts. */
    val savedAccounts: StateFlow<List<ProfileManager.SavedAccount>> = _savedAccounts.asStateFlow()

    init {
        // NotificationHandler-Service (lifecycle-unabhängig) darf keine WS-Benachrichtigungen
        // duplizieren solange dieses ViewModel selbst WS-Nachrichten verarbeitet.
        FcmMessageBus.isViewModelActive = true

        // Account-Switcher: gespeicherte Accounts sofort für den Login-Screen laden
        loadSavedAccounts()

        // Cast: lokale Wiedergabe stoppen sobald eine Cast-Session beginnt
        castDiscoveryManager.onCastSessionStarted = {
            viewModelScope.launch(kotlinx.coroutines.Dispatchers.Main) {
                _musicExoPlayer?.pause()
                _musicIsPlaying.value = false
            }
        }

        // Screen-State-Receiver für Display-Off/On registrieren
        val screenFilter = android.content.IntentFilter().apply {
            addAction(android.content.Intent.ACTION_SCREEN_OFF)
            addAction(android.content.Intent.ACTION_SCREEN_ON)
        }
        context.registerReceiver(screenStateReceiver, screenFilter)

        // P2P DataChannel: eingehende Textnachrichten in Room DB speichern
        viewModelScope.launch {
            webRTCDataChannelManager.incomingMessages.collect { p2pMsg ->
                if (p2pMsg.isBinary) return@collect  // Binär-Transfer: separater Handler (TODO)
                val myId = currentUser.value?.userId ?: return@collect
                // Envelope {cmid, content} parsen – die clientMessageId erlaubt Dedup gegen die
                // parallel über den Server gespiegelte WS-new_message (sonst Doppel-Anzeige beim Partner).
                val (cmid, text) = try {
                    val obj = org.json.JSONObject(p2pMsg.content)
                    obj.optString("cmid").ifBlank { null } to obj.optString("content")
                } catch (e: Exception) {
                    null to p2pMsg.content  // Legacy-Format (reiner Text ohne Envelope)
                }
                // Dedup: identische Nachricht bereits via WS/clientId in der DB?
                if (cmid != null && messageDao.getMessageByClientId(cmid) != null) {
                    Timber.tag("LETHE_P2P_DC").d("P2P-Nachricht $cmid bereits vorhanden – überspringe")
                    return@collect
                }
                messageDao.insertMessage(
                    MessageEntity(
                        chatId           = p2pMsg.fromPeerId,
                        senderId         = p2pMsg.fromPeerId,
                        receiverId       = myId,
                        content          = text,
                        mediaType        = "text",
                        timestamp        = p2pMsg.timestamp,
                        deliveryStatus   = 2,  // DELIVERED – direkte P2P-Zustellung, kein Server-Roundtrip
                        isP2pDelivered   = true,
                        clientMessageId  = cmid
                    )
                )
                Timber.tag("LETHE_P2P_DC").d("P2P-Nachricht von ${p2pMsg.fromPeerId} in Room gespeichert")
            }
        }

        // Session-Expired: Token ungültig nach Server-Wechsel o.ä. → automatisch ausloggen
        viewModelScope.launch {
            tokenManager.sessionExpiredEvent.collect {
                Timber.tag("MainViewModel").w("Session abgelaufen – automatischer Logout")
                logout()
            }
        }

        // Direct Share Shortcuts beim Start initialisieren
        viewModelScope.launch {
            try {
                val sorted = contactsSortedByRecent.first()
                val allGroups = groupDao.getAllGroups().first()
                val recentIds = messageDao.getRecentChatIds(50)
                shortcutHelper.refreshTopContactShortcuts(sorted, allGroups, recentIds)
            } catch (_: Exception) { /* Shortcuts sind optional */ }
        }

        // 1. Initialisierung und Beobachtung der Benutzereinstellungen
        viewModelScope.launch {
            try {
                prefsRepository.userPreferencesFlow.collectLatest { preferences ->
                    _userPrefs.value = preferences
                    Timber.tag("MainViewModel").d("Einstellungen aktualisiert: Theme=${preferences.themeMode}")
                    // Tor-Manager mit gespeicherten Einstellungen synchronisieren
                    val savedTorMode = try {
                        com.securechat.app.data.network.TorMode.valueOf(preferences.torMode)
                    } catch (e: Exception) {
                        com.securechat.app.data.network.TorMode.OFF
                    }
                    torProxyManager.configure(preferences.onionAddress, savedTorMode)
                    // Backup-URL: manuell eingetragene URL hat Vorrang, sonst automatisch abgerufene
                    val homeUrl = preferences.homeServerUrl.trim()
                        .ifBlank { preferences.autoBackupUrl.trim() }
                        .ifBlank { null }
                    fallbackInterceptor.setHomeServerUrl(homeUrl)
                    webSocketManager.setHomeServerUrl(homeUrl)
                    // Täglich /network-info abrufen und Backup-URL aktualisieren
                    refreshBackupUrlIfNeeded(preferences.lastBackupUrlFetchMs)
                    // Dezentral-Modus: P2P-Mesh starten/stoppen
                    if (preferences.decentralizedMode) {
                        if (!p2pMeshManager.isActive.value) p2pMeshManager.start()
                    } else {
                        if (p2pMeshManager.isActive.value) p2pMeshManager.stop()
                    }

                }
            } catch (e: Exception) {
                Timber.tag("MainViewModel").e("Fehler beim Laden der Einstellungen: ${e.message}", e)
            }
        }

        // Geräteweiter "Alle Accounts überwachen"-Schalter (Multi-Account-Einstellungen)
        viewModelScope.launch {
            prefsRepository.monitorAllAccountsFlow.collectLatest { enabled ->
                _monitorAllAccountsEnabled.value = enabled
            }
        }

        // Geräteweiter "Gemischte Kontaktliste"-Schalter (Multi-Account-Einstellungen)
        viewModelScope.launch {
            prefsRepository.mixedContactListFlow.collectLatest { enabled ->
                _mixedContactListEnabled.value = enabled
                if (enabled) loadOtherAccountContacts()
            }
        }

        // Giphy API-Key aus Cache laden und ggf. vom Server holen
        viewModelScope.launch {
            val cached = giphyPrefs.getString("api_key", null)
            if (!cached.isNullOrBlank()) _giphyApiKey.value = cached
            fetchGiphyApiKey()
        }

        // 2. Bestehende Sitzung laden und WebSocket-Verbindung herstellen
        viewModelScope.launch {
            try {
                var user = userDao.getCurrentUser()
                // Integritätscheck gegen Profil-Vermischung: Das aktive Token (von login()/
                // switchAccount() bereits VOR diesem Neustart korrekt profilspezifisch gesetzt)
                // muss zum lokalen user_me-Datensatz DIESES Profils passen. Weicht die userId ab,
                // enthält diese Profil-DB fälschlich Daten eines ANDEREN Accounts (z.B. Altlast aus
                // einer früheren, inzwischen gefixten Rennbedingung) → Profil komplett bereinigen
                // und wie eine leere DB behandeln, damit autoRestoreSession() sauber neu synchronisiert.
                if (user != null && tokenManager.hasToken() && user.userId != tokenManager.getUserId()) {
                    Timber.tag("MainViewModel").w(
                        "Profil-Integritätscheck fehlgeschlagen: lokaler User ${user.userId} " +
                        "≠ Token-User ${tokenManager.getUserId()} – bereinige Profil-DB und synchronisiere neu"
                    )
                    userDao.clearUser()
                    contactDao.clearAll()
                    messageDao.clearAll()
                    groupDao.clearAll()
                    groupSenderKeyDao.clearAll()
                    statusDao.clearAll()
                    pollDao.clearAll()
                    user = null
                }
                _currentUser.value = user
                if (user != null) {
                    Timber.tag("MainViewModel").d("Sitzung wiederhergestellt für User ID: ${user.userId}")
                    val activeProfileKey = ProfileManager.getActiveProfile(context)
                    tokenManager.saveToken(user.authToken, user.userId, activeProfileKey.ifEmpty { null })
                    if (activeProfileKey.isNotEmpty()) {
                        ProfileManager.saveAccountToRegistry(
                            context,
                            ProfileManager.SavedAccount(
                                profileKey = activeProfileKey,
                                fakeNumber = ProfileManager.getOriginalFakeNumber(context).ifEmpty { user.fakeNumber },
                                userId = user.userId,
                                displayName = user.name.ifBlank { user.fakeNumber },
                                profileImageUrl = user.profileImageUrl,
                                lastUsed = System.currentTimeMillis()
                            )
                        )
                        loadSavedAccounts()
                    }
                    registerFcmToken()
                    // ECDH-Schlüsselpaar sicherstellen – synchron, damit loadContacts() deriveSharedSecret() nutzen kann
                    try {
                        val ecdhPubKey = withContext(Dispatchers.IO) {
                            CryptoManager.ensureKeyPair(context, user.privateKey)
                        }
                        val exportedSoftKey = CryptoManager.exportSoftPrivateKey()
                        if (exportedSoftKey != null && exportedSoftKey != user.privateKey) {
                            val updated = user.copy(privateKey = exportedSoftKey)
                            userDao.insertUser(updated)
                            _currentUser.value = updated
                        }
                        if (user.publicKey.length <= 100 || ecdhPubKey != user.publicKey) {
                            viewModelScope.launch(Dispatchers.IO) {
                                try { apiService.updateEcdhKey(EcdhKeyUpdateRequest(ecdhPubKey)) }
                                catch (e: Exception) { Timber.tag("LETHE_E2EE").e("ECDH-Upload fehlgeschlagen: ${e.message}") }
                            }
                        }
                        Timber.tag("LETHE_E2EE").i("ECDH-Key bereit (Session-Restore)")
                    } catch (e: Exception) {
                        Timber.tag("LETHE_E2EE").e("ECDH-Key Setup (Session-Restore) fehlgeschlagen: ${e.message}")
                    }
                    connectWebSocketAndListen()
                    // Online-Status setzen: setAppForeground() wurde evtl. aufgerufen bevor User geladen war
                    val pmRestore = context.getSystemService(Context.POWER_SERVICE) as PowerManager
                    updateOnlineStatus(_isAppInForeground.value && pmRestore.isInteractive)
                    loadContacts()
                    loadLinkedDevices() // Self-Web-Secret für eigene Web-Gerät-Kopie
                    loadGroups()
                    loadPendingContactRequests()
                    schedulePendingContactsCheck()
                    loadAnimationState()
                    loadPinnedItems()
                    loadScheduledMessages()
                    startProfileImageRefreshLoop()
                    // .onion-Adresse automatisch vom Server aktualisieren (Nutzer muss nur Tor ein-/ausschalten)
                    fetchOnionAddressFromServer()
                    // Styx-Guthaben, Profilfelder und Verifikationsstatus vom Server aktualisieren
                    try {
                        val profileResponse = apiService.getMe()
                        if (profileResponse.isSuccessful) {
                            val profile = profileResponse.body()!!
                            val phoneVerified = profile.isPhoneVerified
                            val refreshed = (_currentUser.value ?: user).copy(
                                styx = profile.styx ?: user.styx,
                                name = profile.name ?: user.name,
                                isAdmin = profile.isAdmin ?: user.isAdmin,
                                isModerator = profile.isModerator ?: user.isModerator,
                                isCreator = profile.isCreator ?: user.isCreator,
                                ageVerified = profile.ageVerified ?: user.ageVerified,
                                is18Verified = profile.is18Verified ?: user.is18Verified,
                                profileImageUrl = profile.profileImageUrl?.let { toAbsoluteUrl(it) } ?: user.profileImageUrl,
                                isPhoneVerified = phoneVerified,
                                letheId = profile.letheId ?: user.letheId,
                                info = profile.info ?: user.info,
                                links = profile.links ?: user.links,
                                instagram = profile.instagram ?: user.instagram,
                                tiktok = profile.tiktok ?: user.tiktok,
                                youtube = profile.youtube ?: user.youtube
                            )
                            userDao.insertUser(refreshed)
                            _currentUser.value = refreshed
                            if (!phoneVerified) {
                                _requirePhoneVerification.value = true
                                Timber.tag("LETHE_E2EE").i("Session-Restore: Telefon nicht verifiziert → OTP-Screen")
                            }
                        }
                    } catch (_: Exception) { /* ignorieren wenn offline */ }
                } else if (tokenManager.hasToken()) {
                    // Kein User in DB, aber Token vorhanden → nach Profil-Wechsel neu starten
                    Timber.tag("MainViewModel").d("Token vorhanden, DB leer → Auto-Restore nach Profil-Wechsel")
                    autoRestoreSession()
                } else {
                    // Kein User, kein Token → prüfe ob Auto-Login aktiviert
                    val prefs = prefsRepository.userPreferencesFlow.first()
                    if (prefs.autoLoginEnabled && prefs.fakeNumber.isNotBlank() && prefs.password.isNotBlank()) {
                        Timber.tag("MainViewModel").d("Auto-Login gestartet für ${prefs.fakeNumber}")
                        login(prefs.fakeNumber, prefs.password, remember = true, autoLogin = true)
                    }
                }
            } catch (e: Exception) {
                Timber.tag("MainViewModel").e("Fehler beim Wiederherstellen der Sitzung: ${e.message}", e)
            }
        }

        // Live-Standort-Service: Standort-Updates via WebSocket an Partner senden
        viewModelScope.launch {
            com.securechat.app.LiveLocationService.locationUpdates.collect { update ->
                webSocketManager.sendMessage(
                    type = "location_update",
                    receiverId = update.receiverId,
                    payload = mapOf("lat" to update.lat, "lng" to update.lng)
                )
            }
        }
    }

    // --- AUTHENTIFIZIERUNG ---

    /**
     * Führt den Login-Prozess durch und speichert Credentials bei Erfolg.
     * AKTUALISIERT: Speichert jetzt auch das Token im TokenManager.
     */
    fun login(fakeNumber: String, password: String, remember: Boolean = false, autoLogin: Boolean = false) {
        viewModelScope.launch {
            _isLoading.value = true
            try {
                // Geräte-Fingerabdruck für neue-Gerät-Erkennung
                val fingerprint = withContext(Dispatchers.IO) {
                    try { DeviceIdentifier.getFingerprint(context) } catch (_: Exception) { "" }
                }

                // Versuche Login per Telefonnummer (E.164) wenn Nummer mit + beginnt
                val response = if (fakeNumber.startsWith("+")) {
                    val r = apiService.loginWithPhone(PhoneLoginRequest(phoneNumber = fakeNumber, password = password, deviceFingerprint = fingerprint))
                    // Fallback auf fake_number-Login falls Telefon-Login fehlschlägt
                    if (!r.isSuccessful) apiService.login(UserLoginRequest(fakeNumber = fakeNumber, password = password, deviceFingerprint = fingerprint))
                    else r
                } else {
                    apiService.login(UserLoginRequest(fakeNumber = fakeNumber, password = password, deviceFingerprint = fingerprint))
                }

                // HTTP 202 = neues Gerät erkannt → SMS wurde gesendet
                if (response.code() == 202) {
                    val body = response.body()
                    val sessionToken = body?.sessionToken
                    if (!sessionToken.isNullOrBlank()) {
                        _newDeviceState.value = NewDeviceState(
                            sessionToken = sessionToken,
                            fakeNumber = fakeNumber,
                            password = password
                        )
                        Timber.tag("LETHE_DEVICE").i("Neues Gerät erkannt – SMS-Verifikation erforderlich")
                    } else {
                        _statusMessage.value = "Neues Gerät erkannt, aber kein Session-Token erhalten."
                    }
                    _isLoading.value = false
                    return@launch
                }

                if (response.isSuccessful && response.body() != null) {
                    val loginData = response.body()!!

                    // Sicherheitsprüfung: Falls der Server doch new_device=true zurückgibt
                    if (loginData.newDevice && !loginData.sessionToken.isNullOrBlank()) {
                        _newDeviceState.value = NewDeviceState(
                            sessionToken = loginData.sessionToken,
                            fakeNumber = fakeNumber,
                            password = password
                        )
                        Timber.tag("LETHE_DEVICE").i("Neues Gerät erkannt (body flag) – SMS-Verifikation erforderlich")
                        _isLoading.value = false
                        return@launch
                    }

                    val accessToken = loginData.accessToken ?: run {
                        _statusMessage.value = "Login fehlgeschlagen. Bitte Daten prüfen."
                        _isLoading.value = false
                        return@launch
                    }
                    val userId = loginData.userId ?: run {
                        _statusMessage.value = "Login fehlgeschlagen. Bitte Daten prüfen."
                        _isLoading.value = false
                        return@launch
                    }

                    // WICHTIG: Token im TokenManager speichern für API-Requests.
                    // Zusätzlich profilspezifisch, damit der Account-Switcher später ohne
                    // erneute Passworteingabe zu diesem Account zurückwechseln kann.
                    val profileKeyForRegistry = ProfileManager.sanitize(fakeNumber)
                    tokenManager.saveToken(accessToken, userId, profileKeyForRegistry)
                    Timber.tag("MainViewModel").d("Token gespeichert für User: $userId")

                    // WICHTIG: Profil-Wechsel früh erkennen. Steht ein Wechsel bevor, darf NICHTS mehr
                    // in die aktuell geöffnete (alte) Room-DB geschrieben werden – sonst landet der neue
                    // Account-Datensatz in der user_me-Tabelle des ALTEN Profils. Da getCurrentUser()
                    // ein simples "SELECT * FROM user_me LIMIT 1" ohne Filter/Sortierung ist, würde ein
                    // solcher Fremd-Eintrag beim nächsten Öffnen des alten Profils fälschlich als aktiver
                    // User zurückgegeben ("Multiaccount landet immer im Hauptaccount"-Bug). autoRestoreSession()
                    // legt den lokalen User-Datensatz nach dem Neustart bereits sauber im richtigen (neuen)
                    // Profil an, daher hier gefahrlos übersprungen.
                    val willSwitchProfile = ProfileManager.getActiveProfile(context) != profileKeyForRegistry

                    // Pseudo-TokenResponse für die Weiterverarbeitung
                    val tokenData = TokenResponse(accessToken = accessToken, tokenType = loginData.tokenType ?: "bearer", userId = userId)

                    // Speichern im DataStore für zukünftige Logins/Biometrie. Der profil-lokale Teil
                    // wird bei einem Profil-Wechsel übersprungen (siehe willSwitchProfile-Kommentar oben) –
                    // sonst landen die neuen Zugangsdaten im DataStore-File des ALTEN Profils.
                    prefsRepository.updateCredentials(fakeNumber, password, remember, persistToProfile = !willSwitchProfile)
                    if (!willSwitchProfile) {
                        prefsRepository.setAutoLoginEnabled(autoLogin)

                        // Biometrie-Angebot bei erstem Erfolg
                        if (biometricHelper.canAuthenticate() && !userPrefs.value.biometricEnabled) {
                            prefsRepository.setBiometricEnabled(true)
                        }
                    }

                    // Vollständiges Profil vom Server abrufen (enthält publicKey und name)
                    val profileResponse = apiService.getMe()
                    val profile = if (profileResponse.isSuccessful) profileResponse.body() else null

                    val phoneVerified = profile?.isPhoneVerified ?: false
                    val newUser = UserEntity(
                        userId = tokenData.userId,
                        fakeNumber = fakeNumber,
                        name = profile?.name ?: "",
                        authToken = tokenData.accessToken,
                        publicKey = profile?.publicKey ?: "",
                        isAdmin = profile?.isAdmin ?: false,
                        isModerator = profile?.isModerator ?: false,
                        isCreator = profile?.isCreator ?: false,
                        styx = profile?.styx ?: 0,
                        ageVerified = profile?.ageVerified ?: false,
                        is18Verified = profile?.is18Verified ?: false,
                        profileImageUrl = profile?.profileImageUrl?.let { toAbsoluteUrl(it) },
                        statusPermitted = profile?.statusPermitted,
                        isPhoneVerified = phoneVerified,
                        letheId = profile?.letheId,
                        info = profile?.info,
                        links = profile?.links,
                        instagram = profile?.instagram,
                        tiktok = profile?.tiktok,
                        youtube = profile?.youtube,
                        isVerified = profile?.isVerified ?: false
                    )
                    if (!willSwitchProfile) {
                        userDao.insertUser(newUser)
                    }
                    _currentUser.value = newUser
                    ProfileManager.saveAccountToRegistry(
                        context,
                        ProfileManager.SavedAccount(
                            profileKey = profileKeyForRegistry,
                            fakeNumber = fakeNumber,
                            userId = userId,
                            displayName = newUser.name.ifBlank { fakeNumber },
                            profileImageUrl = newUser.profileImageUrl,
                            lastUsed = System.currentTimeMillis()
                        )
                    )
                    loadSavedAccounts()
                    registerFcmToken()
                    redeemPendingInvite()

                    // Auto-Restore: Falls kein lokaler Key vorhanden (Neuinstallation / Gerätewechsel),
                    // Key-Backup vom Server holen und mit Login-Passwort entschlüsseln.
                    // Dadurch bleiben alle alten Nachrichten lesbar ohne erneuten Key-Austausch.
                    withContext(Dispatchers.IO) {
                        try {
                            val backupResp = apiService.getKeyBackup()
                            val blob = backupResp.body()?.encryptedBlob
                            if (backupResp.isSuccessful && !blob.isNullOrBlank()) {
                                val restoredPub = CryptoManager.decryptAndLoadKeyBackup(password, blob)
                                if (restoredPub != null) {
                                    val softPriv = CryptoManager.exportSoftPrivateKey()
                                    val restored = newUser.copy(privateKey = softPriv, publicKey = restoredPub)
                                    if (!willSwitchProfile) {
                                        userDao.insertUser(restored)
                                    }
                                    _currentUser.value = restored
                                    Timber.tag("LETHE_KEYS").i("Key-Backup bei Login automatisch wiederhergestellt (pub=${restoredPub.take(20)}…)")
                                }
                            }
                        } catch (e: Exception) {
                            Timber.tag("LETHE_KEYS").w("Auto-Key-Restore fehlgeschlagen: ${e.message}")
                        }
                    }

                    // EPIC 1: ECDH-Schlüsselpaar sicherstellen – synchron, damit deriveSharedSecret()
                    // in loadContacts() den Key sofort vorfindet.
                    try {
                        val softPrivKey = _currentUser.value?.privateKey ?: newUser.privateKey
                        val softPubKey = _currentUser.value?.publicKey ?: newUser.publicKey
                        val ecdhPubKey = withContext(Dispatchers.IO) {
                            CryptoManager.ensureKeyPair(context, softPrivKey, softPubKey)
                        }
                        val exportedSoftKey = CryptoManager.exportSoftPrivateKey()
                        if (exportedSoftKey != null && exportedSoftKey != softPrivKey) {
                            val updated = newUser.copy(privateKey = exportedSoftKey)
                            if (!willSwitchProfile) {
                                userDao.insertUser(updated)
                            }
                            _currentUser.value = updated
                        }
                        // Key-Upload im Hintergrund (nicht-blockierend)
                        // Signing-Key sicherstellen und ggf. mit hochladen (Anti-MITM für Web-Linking)
                        val signingPubKey = withContext(Dispatchers.IO) {
                            try { CryptoManager.ensureSigningKeyPair() } catch (_: Exception) { null }
                        }
                        // Admin-erstellte Accounts haben noch den SHA256-Platzhalter-Key (64 Zeichen)
                        // oder das adminAdded-Flag → Keys jetzt vollständig hochladen wie bei Neuregistrierung
                        val isAdminAdded = profile?.adminAdded == true
                        if (isAdminAdded || newUser.publicKey.length <= 100 || ecdhPubKey != newUser.publicKey) {
                            viewModelScope.launch(Dispatchers.IO) {
                                try {
                                    apiService.updateEcdhKey(EcdhKeyUpdateRequest(
                                        ecdhPublicKey = ecdhPubKey,
                                        signingPublicKey = signingPubKey,
                                        // Admin-erstellte Accounts: Kontakte über den neuen ECDH-Key informieren
                                        // (ersetzt SHA-256-Dummy, den Kontakte beim Handshake gespeichert haben)
                                        notifyContacts = isAdminAdded
                                    ))
                                    if (isAdminAdded) {
                                        Timber.tag("LETHE_E2EE").i("Admin-Account: Keys beim ersten Login generiert, hochgeladen und Kontakte informiert")
                                    }
                                } catch (e: Exception) {
                                    Timber.tag("LETHE_E2EE").e("ECDH-Upload fehlgeschlagen: ${e.message}")
                                }
                            }
                        }
                        Timber.tag("LETHE_E2EE").i("ECDH-Key bereit (phoneVerified=$phoneVerified)")
                    } catch (e: Exception) {
                        Timber.tag("LETHE_E2EE").e("ECDH-Key Setup fehlgeschlagen: ${e.message}")
                    }

                    // Telefon-Verifikation ausstehend → OTP-Screen anzeigen (ECDH läuft bereits)
                    if (!phoneVerified) {
                        _requirePhoneVerification.value = true
                        Timber.tag("LETHE_E2EE").i("Telefon noch nicht verifiziert → OTP-Screen")
                        val previousProfile2 = ProfileManager.getActiveProfile(context)
                        val sanitizedNew2 = ProfileManager.sanitize(fakeNumber)
                        ProfileManager.setActiveProfile(context, fakeNumber)
                        if (previousProfile2 != sanitizedNew2) {
                            ProfileManager.markPendingRestart(context)
                            android.os.Process.killProcess(android.os.Process.myPid())
                            return@launch
                        }
                        connectWebSocketAndListen()
                        val pmLoginOtp = context.getSystemService(Context.POWER_SERVICE) as PowerManager
                        updateOnlineStatus(_isAppInForeground.value && pmLoginOtp.isInteractive)
                        loadContacts()
                        loadLinkedDevices()
                        loadEnrolledDevices()
                        loadGroups()
                        loadPendingContactRequests()
                        schedulePendingContactsCheck()
                        startProfileImageRefreshLoop()
                        loadFamilyStatus()
                        initUmkInBackground(password)
                        return@launch
                    }

                    // Profilspezifische Daten anlegen: DB + DataStore werden beim nächsten
                    // Start mit dem richtigen Namen geöffnet.
                    val previousProfile = ProfileManager.getActiveProfile(context)
                    val sanitizedNew = ProfileManager.sanitize(fakeNumber)
                    ProfileManager.setActiveProfile(context, fakeNumber)

                    if (previousProfile != sanitizedNew) {
                        // Profil gewechselt (oder erster Login) → Prozess neu starten
                        // Token ist bereits gespeichert. autoRestoreSession() wird beim
                        // nächsten Start die Sitzung aus dem Token wiederherstellen.
                        Timber.tag("MainViewModel").i("Profil-Wechsel: $previousProfile → $sanitizedNew, starte neu")
                        ProfileManager.markPendingRestart(context)
                        android.os.Process.killProcess(android.os.Process.myPid())
                        return@launch
                    }

                    _statusMessage.value = "Login erfolgreich"
                    connectWebSocketAndListen()
                    val pmLogin = context.getSystemService(Context.POWER_SERVICE) as PowerManager
                    updateOnlineStatus(_isAppInForeground.value && pmLogin.isInteractive)
                    loadContacts()
                    loadBlockedUsers()
                    loadLinkedDevices()
                    loadEnrolledDevices()
                    loadGroups()
                    loadPendingContactRequests()
                    schedulePendingContactsCheck()
                    startProfileImageRefreshLoop()
                    loadMyNearbyProfileForTracking()
                    // Lethe Family: Status nach Login laden (prüft ob Kind- oder Parent-Account)
                    loadFamilyStatus()

                    // Auto Key-Backup: Backup anlegen/aktualisieren damit neues Gerät sich wiederherstellen kann.
                    // Erstellt Backup wenn: (a) noch keins existiert, ODER (b) ein Soft Key aktiv ist
                    // (API 26-30 immer; API 31+ nach Backup-Restore oder nach erstem backupKeys()-Aufruf).
                    viewModelScope.launch(Dispatchers.IO) {
                        delay(3000) // Warte bis ECDH-Keys fertig generiert sind
                        try {
                            val backupResp = apiService.getKeyBackup()
                            val existingBlob = if (backupResp.isSuccessful) backupResp.body()?.encryptedBlob else null
                            val noBackup = existingBlob.isNullOrBlank()
                            val softKeyActive = CryptoManager.exportSoftPrivateKey() != null
                            if (noBackup || softKeyActive) {
                                backupKeys(password, automatic = true) { success, msg ->
                                    Timber.tag("LETHE_KEYS").d("Auto-Backup nach Login: $success – $msg")
                                }
                            }
                        } catch (_: Exception) { /* nicht-kritisch */ }
                    }

                    // UMK (User Master Key): nach Login mit Passwort laden/generieren.
                    initUmkInBackground(password)
                } else {
                    _statusMessage.value = "Login fehlgeschlagen. Bitte Daten prüfen."
                }
            } catch (e: Exception) {
                _statusMessage.value = "Serverfehler: ${e.message}"
                Timber.tag("MainViewModel").e("Login Error", e)
            } finally {
                _isLoading.value = false
            }
        }
    }

    /**
     * Startet den biometrischen Login-Vorgang.
     */
    fun performBiometricLogin(activity: FragmentActivity) {
        val saved = userPrefs.value
        if (saved.fakeNumber.isEmpty() || saved.password.isEmpty()) {
            _statusMessage.value = "Keine Daten für Schnell-Login gespeichert."
            return
        }

        biometricHelper.showPrompt(
            activity = activity,
            onSuccess = {
                login(saved.fakeNumber, saved.password, true)
            },
            onError = { error ->
                _statusMessage.value = "Biometrie fehlgeschlagen: $error"
            }
        )
    }

    /** Sendet einen Registrierungs-OTP per SMS. Gibt true zurück bei Erfolg. */
    fun sendRegistrationOtp(phoneNumber: String, onResult: (Boolean, String) -> Unit) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val response = apiService.sendRegistrationOtp(RegistrationOtpRequest(phoneNumber))
                withContext(Dispatchers.Main) {
                    if (response.isSuccessful) {
                        onResult(true, "SMS gesendet")
                    } else {
                        val err = response.errorBody()?.string() ?: "Fehler ${response.code()}"
                        onResult(false, err)
                    }
                }
            } catch (e: Exception) {
                withContext(Dispatchers.Main) { onResult(false, e.message ?: "Netzwerkfehler") }
            }
        }
    }

    fun register(
        phoneNumber: String,
        name: String,
        password: String,
        smsCode: String,
        isChildAccount: Boolean = false,
        birthDate: String? = null,
        inviteToken: String? = null
    ) {
        viewModelScope.launch {
            _isLoading.value = true
            try {
                // ECDH-Schlüsselpaar vor Registrierung generieren
                val ecdhPublicKey = withContext(Dispatchers.IO) {
                    try { CryptoManager.ensureKeyPair(context) } catch (_: Exception) { null }
                }
                val request = UserCreateRequest(
                    fakeNumber = phoneNumber,
                    name = name,
                    password = password,
                    phoneNumber = phoneNumber,
                    ecdhPublicKey = ecdhPublicKey,
                    smsCode = smsCode,
                    isChildAccount = if (isChildAccount) true else null,
                    birthDate = birthDate,
                    inviteToken = inviteToken
                )
                val response = apiService.register(request)
                if (response.isSuccessful) {
                    // Direkt einloggen – setzt Token, WebSocket, lädt Kontakte etc.
                    login(phoneNumber, password, remember = true, autoLogin = false)
                } else {
                    val errorBody = response.errorBody()?.string() ?: "Unbekannter Fehler"
                    _statusMessage.value = "Registrierung fehlgeschlagen: $errorBody"
                    _isLoading.value = false
                }
            } catch (e: Exception) {
                _statusMessage.value = "Fehler: ${e.message}"
                _isLoading.value = false
            }
        }
    }

