    /**
     * Bestätigt den OTP-Code. Bei Erfolg: ECDH-Schlüssel generieren + hochladen,
     * _requirePhoneVerification auf false setzen, onSuccess() aufrufen.
     */
    fun confirmPhoneOtp(phoneE164: String, code: String, onSuccess: () -> Unit) {
        viewModelScope.launch {
            _isLoading.value = true
            try {
                val response = apiService.confirmPhoneOtp(
                    PhoneOtpConfirmRequest(phoneNumber = phoneE164, code = code)
                )
                if (response.isSuccessful && response.body()?.success == true) {
                    // Telefon verifiziert → jetzt ECDH-Schlüssel generieren
                    val user = _currentUser.value
                    if (user != null) {
                        val updated = user.copy(isPhoneVerified = true)
                        userDao.insertUser(updated)
                        _currentUser.value = updated
                    }
                    // ECDH-Schlüsselpaar generieren + hochladen
                    viewModelScope.launch(Dispatchers.IO) {
                        try {
                            val softPrivKey = _currentUser.value?.privateKey
                            val softPubKey = _currentUser.value?.publicKey
                            val ecdhPubKey = CryptoManager.ensureKeyPair(context, softPrivKey, softPubKey)
                            val exportedSoftKey = CryptoManager.exportSoftPrivateKey()
                            if (exportedSoftKey != null && exportedSoftKey != softPrivKey) {
                                val refreshed = _currentUser.value?.copy(privateKey = exportedSoftKey)
                                if (refreshed != null) {
                                    userDao.insertUser(refreshed)
                                    _currentUser.value = refreshed
                                }
                            }
                            apiService.updateEcdhKey(EcdhKeyUpdateRequest(ecdhPubKey))
                            Timber.tag("LETHE_E2EE").i("ECDH nach OTP-Verifikation hochgeladen")
                        } catch (e: Exception) {
                            Timber.tag("LETHE_E2EE").e("ECDH nach OTP fehlgeschlagen: ${e.message}")
                        }
                    }
                    _requirePhoneVerification.value = false
                    _statusMessage.value = null
                    onSuccess()
                } else {
                    _statusMessage.value = "Falscher oder abgelaufener Code. Bitte erneut versuchen."
                }
            } catch (e: Exception) {
                _statusMessage.value = "Netzwerkfehler: ${e.message}"
            } finally {
                _isLoading.value = false
            }
        }
    }

    /**
     * Passwort ändern. Bei Erfolg gibt der Server ein neues Token zurück —
     * alle anderen aktiven Sessions werden sofort ungültig (token_version Mechanismus).
     */
    fun changePassword(currentPassword: String, newPassword: String) {
        viewModelScope.launch {
            _isLoading.value = true
            try {
                val response = apiService.changePassword(
                    ChangePasswordRequest(currentPassword, newPassword)
                )
                if (response.isSuccessful && response.body() != null) {
                    val tokenData = response.body()!!
                    // Neues Token speichern — altes ist ab sofort ungültig
                    tokenManager.saveToken(tokenData.accessToken, tokenData.userId)
                    // Lokale User-Entity aktualisieren
                    val updated = _currentUser.value?.copy(authToken = tokenData.accessToken)
                    if (updated != null) {
                        userDao.insertUser(updated)
                        _currentUser.value = updated
                    }
                    _statusMessage.value = "Passwort erfolgreich geändert."
                } else {
                    val error = response.errorBody()?.string() ?: "Unbekannter Fehler"
                    _statusMessage.value = "Fehler: $error"
                }
            } catch (e: Exception) {
                _statusMessage.value = "Netzwerkfehler: ${e.message}"
            } finally {
                _isLoading.value = false
            }
        }
    }

