    /** Liste der Betrachter eines Status-Beitrags. */
    private val _statusViewers = MutableStateFlow<List<com.securechat.app.data.network.StatusViewerResponse>>(emptyList())
    val statusViewers: StateFlow<List<com.securechat.app.data.network.StatusViewerResponse>> = _statusViewers.asStateFlow()

    /** IDs der Status-Beiträge, die der aktuelle Nutzer geliked hat (Session-Cache). */
    private val _likedStatusIds = MutableStateFlow<Set<String>>(emptySet())
    val likedStatusIds: StateFlow<Set<String>> = _likedStatusIds.asStateFlow()
    /** IDs, für die gerade ein Like-Toggle läuft (verhindert Race mit checkStatusLiked). */
    private val _pendingLikeIds = mutableSetOf<String>()

    /** Prüft beim Öffnen des Viewers ob der Status bereits geliked wurde (session-übergreifend). */
    fun checkStatusLiked(statusId: String) {
        viewModelScope.launch {
            try {
                val response = apiService.isStatusLiked(statusId)
                if (response.isSuccessful && statusId !in _pendingLikeIds) {
                    val liked = response.body()?.get("liked") ?: false
                    _likedStatusIds.update { if (liked) it + statusId else it - statusId }
                }
            } catch (_: Exception) {}
        }
    }

    /** Toggelt das Like eines fremden Status-Beitrags. */
    fun likeStatus(statusId: String) {
        // Optimistic UI: sofort toggeln, bei Fehler zurücksetzen
        val wasLiked = _likedStatusIds.value.contains(statusId)
        _likedStatusIds.update { if (wasLiked) it - statusId else it + statusId }
        _pendingLikeIds.add(statusId)
        viewModelScope.launch {
            try {
                val response = apiService.likeStatus(statusId)
                if (response.isSuccessful) {
                    val liked = response.body()?.get("liked") ?: false
                    _likedStatusIds.update { if (liked) it + statusId else it - statusId }
                } else {
                    // Revert bei Fehler
                    _likedStatusIds.update { if (wasLiked) it + statusId else it - statusId }
                }
            } catch (_: Exception) {
                // Revert bei Fehler
                _likedStatusIds.update { if (wasLiked) it + statusId else it - statusId }
            } finally {
                _pendingLikeIds.remove(statusId)
            }
        }
    }

