    /** Wandelt einen relativen Pfad (/uploads/...) in eine absolute URL um. */
    private fun toAbsoluteUrl(url: String?): String {
        if (url == null) return ""
        return if (url.startsWith("http")) url else "https://letheapp.de$url"
    }

    /** Wandelt eine Medien-URL für Cast-Geräte um (/uploads/ → /m/) damit die Server-Struktur verborgen bleibt. */
    fun toCastUrl(url: String): String {
        val abs = toAbsoluteUrl(url)
        return abs.replace(Regex("(https://letheapp\\.de)/uploads/(.+)$")) { m ->
            "${m.groupValues[1]}/m/${m.groupValues[2]}"
        }
    }

