    fun uploadGroupImage(groupId: String, uri: android.net.Uri) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val inputStream = context.contentResolver.openInputStream(uri) ?: return@launch
                val bytes = inputStream.readBytes()
                inputStream.close()
                val mimeType = context.contentResolver.getType(uri) ?: "image/jpeg"
                val ext = when (mimeType) {
                    "image/png" -> "png"
                    "image/webp" -> "webp"
                    else -> "jpg"
                }
                val requestBody = bytes.toRequestBody(mimeType.toMediaTypeOrNull())
                val part = okhttp3.MultipartBody.Part.createFormData("file", "groupimage.$ext", requestBody)
                val response = apiService.uploadGroupImage(groupId, part)
                if (response.isSuccessful) {
                    val url = response.body()?.get("url")?.let { url ->
                        val base = if (url.startsWith("http")) url else "https://letheapp.de$url"
                        "$base?v=${System.currentTimeMillis()}"
                    }
                    val existing = groupDao.getGroupById(groupId)
                    if (existing != null && url != null) {
                        groupDao.insertGroup(existing.copy(groupImageUrl = url))
                    }
                    _statusMessage.value = "Gruppenbild aktualisiert ✓"
                } else {
                    _statusMessage.value = "Fehler beim Hochladen des Gruppenbildes"
                }
            } catch (e: Exception) {
                _statusMessage.value = "Fehler: ${e.message}"
            }
        }
    }

