    // --- APP-UPDATE ---

    /** Prüft auf dem Server ob eine neuere App-Version verfügbar ist. */
    fun checkForUpdate() {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val response = apiService.getAppVersion()
                if (response.isSuccessful) {
                    val body = response.body() ?: return@launch
                    val currentVersion = com.securechat.app.BuildConfig.VERSION_NAME
                    if (isNewerVersion(body.version, currentVersion)) {
                        // Nutze Server-Changelog wenn vorhanden, sonst lokalen Changelog-Kurztext
                        val changelogText = if (!body.changelog.isNullOrBlank() &&
                            body.changelog != "Neue Version verfügbar")
                            body.changelog
                        else
                            com.securechat.app.AppChangelog.latestShort
                        val info = UpdateInfo(
                            version = body.version,
                            apkUrl = body.apkUrl,
                            changelog = changelogText
                        )
                        _pendingUpdateInfo.value = info
                        // Dialog nur zeigen wenn kein aktiver Snooze läuft
                        val snoozedUntil = context.getSharedPreferences(
                            "lethe_update", android.content.Context.MODE_PRIVATE
                        ).getLong("snoozed_until", 0L)
                        if (System.currentTimeMillis() >= snoozedUntil) {
                            _updateInfo.value = info
                        }
                    }
                }
            } catch (e: Exception) {
                Timber.tag("Update").e("Versions-Check fehlgeschlagen: ${e.message}")
            }
        }
    }

    /** Lädt die APK herunter und meldet den Fortschritt über downloadProgress. */
    fun downloadUpdate(apkUrl: String, targetVersion: String) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                _downloadProgress.value = 0
                val client = OkHttpClient.Builder()
                    .connectTimeout(30, TimeUnit.SECONDS)
                    .readTimeout(5, java.util.concurrent.TimeUnit.MINUTES)
                    .build()
                val request = Request.Builder().url(apkUrl).build()
                val response = client.newCall(request).execute()
                val body = response.body ?: run {
                    _downloadProgress.value = -1
                    return@launch
                }
                val contentLength = body.contentLength()
                val updatesDir = java.io.File(context.filesDir, "updates").also { it.mkdirs() }
                val file = java.io.File(updatesDir, "lethe-update.apk")
                val inputStream = body.byteStream()
                val outputStream = file.outputStream()
                val buffer = ByteArray(8192)
                var downloaded = 0L
                var read: Int
                while (inputStream.read(buffer).also { read = it } != -1) {
                    outputStream.write(buffer, 0, read)
                    downloaded += read
                    if (contentLength > 0) {
                        _downloadProgress.value = ((downloaded * 100) / contentLength).toInt()
                    }
                }
                outputStream.close()
                _downloadProgress.value = 100
                _installReady.value = file.absolutePath
                // Zielversion speichern – wird beim nächsten App-Start geprüft,
                // um die APK erst nach erfolgreichem Update zu löschen.
                context.getSharedPreferences("lethe_update", android.content.Context.MODE_PRIVATE)
                    .edit().putString("pending_apk_version", targetVersion).apply()
            } catch (e: Exception) {
                Timber.tag("Update").e("Download fehlgeschlagen: ${e.message}")
                _downloadProgress.value = -1
            }
        }
    }

    /** Schließt das Update-Dialog ("Später") – Snooze für 1 Stunde. */
    fun dismissUpdate() {
        context.getSharedPreferences("lethe_update", android.content.Context.MODE_PRIVATE)
            .edit().putLong("snoozed_until", System.currentTimeMillis() + 3_600_000L).apply()
        _updateInfo.value = null
        _downloadProgress.value = -1
    }

    /** Zeigt das Update-Dialog erneut (z. B. nach Klick auf das TopBar-Icon). */
    fun reshowUpdateDialog() {
        _pendingUpdateInfo.value?.let { info ->
            // Snooze aufheben damit Dialog sofort sichtbar wird
            context.getSharedPreferences("lethe_update", android.content.Context.MODE_PRIVATE)
                .edit().remove("snoozed_until").apply()
            _updateInfo.value = info
        }
    }

    /** Bestätigt dass die Installation gestartet wurde. */
    fun clearInstallReady() {
        _installReady.value = null
    }

    /** Vergleicht zwei Versionstrings (z.B. "3.50" > "3.30" → true). */
    private fun isNewerVersion(server: String, current: String): Boolean {
        val sParts = server.split(".").map { it.toIntOrNull() ?: 0 }
        val cParts = current.split(".").map { it.toIntOrNull() ?: 0 }
        val maxLen = maxOf(sParts.size, cParts.size)
        for (i in 0 until maxLen) {
            val s = sParts.getOrElse(i) { 0 }
            val c = cParts.getOrElse(i) { 0 }
            if (s > c) return true
            if (s < c) return false
        }
        return false
    }

    /**
     * Account vollständig löschen: Server-seitig alle Daten löschen,
     * dann lokal alle Room-Tabellen, Tokens und SharedPreferences leeren.
     * Nach dem Aufruf wird der User zum Login-Screen navigiert.
     */
    fun deleteAccount(onResult: (Boolean, String?) -> Unit) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val response = apiService.deleteAccount()
                if (response.isSuccessful || response.code() == 404) {
                    // Lokal alles löschen – Reihenfolge: zuerst Verbindung trennen
                    webSocketManager.disconnect()

                    // Room-Tabellen leeren
                    userDao.clearUser()
                    contactDao.clearAll()
                    messageDao.clearAll()
                    statusDao.clearAll()
                    pollDao.clearAll()
                    groupDao.clearAll()

                    // Token und Profil löschen
                    tokenManager.clearToken()

                    // SharedPreferences leeren
                    val prefNames = listOf(
                        "chat_backgrounds", "pending_lumis",
                        "hidden_nearby_profiles", "secure_chat_token"
                    )
                    prefNames.forEach { name ->
                        context.getSharedPreferences(name, android.content.Context.MODE_PRIVATE)
                            .edit().clear().apply()
                    }

                    // State zurücksetzen
                    withContext(Dispatchers.Main) {
                        _currentUser.value = null
                        onResult(true, null)
                    }
                } else {
                    withContext(Dispatchers.Main) {
                        onResult(false, "Fehler: ${response.code()}")
                    }
                }
            } catch (e: Exception) {
                Timber.tag("MainViewModel").e("deleteAccount fehlgeschlagen: ${e.message}")
                withContext(Dispatchers.Main) {
                    onResult(false, e.message)
                }
            }
        }
    }

    /** Logout: Session löschen und Verbindung trennen. */
    fun logout() {
        viewModelScope.launch {
            // Expliziter Logout: Account auch aus dem Account-Switcher entfernen,
            // damit beim nächsten Öffnen wieder das Passwort verlangt wird.
            val loggedOutProfileKey = ProfileManager.getActiveProfile(context)
            userDao.clearUser()
            tokenManager.clearToken()
            if (loggedOutProfileKey.isNotEmpty()) {
                tokenManager.clearProfileToken(loggedOutProfileKey)
                ProfileManager.removeSavedAccount(context, loggedOutProfileKey)
                loadSavedAccounts()
            }
            webSocketManager.disconnect()
            // NotificationHandler-Service stoppen, damit kein dataSync-Timeout-Crash entsteht
            try {
                context.stopService(android.content.Intent(context, NotificationHandler::class.java))
            } catch (e: Exception) {
                Timber.tag("MainViewModel").w("NotificationHandler stoppen fehlgeschlagen: ${e.message}")
            }
            _currentUser.value = null
            _statusMessage.value = "Abgemeldet"
            Timber.tag("MainViewModel").d("User ausgeloggt und Token gelöscht")
        }
    }

    // --- ACCOUNT-SWITCHER ---

    fun loadSavedAccounts() {
        _savedAccounts.value = ProfileManager.getSavedAccounts(context)
    }

    /** Wechselt ohne erneute Passworteingabe zu einem zuvor gespeicherten Account. */
    fun switchAccount(profileKey: String) {
        viewModelScope.launch {
            val account = ProfileManager.getSavedAccounts(context).find { it.profileKey == profileKey }
            if (account == null) {
                _statusMessage.value = "Account nicht gefunden."
                return@launch
            }
            if (!tokenManager.activateProfileToken(profileKey)) {
                _statusMessage.value = "Sitzung abgelaufen, bitte erneut mit Passwort anmelden."
                ProfileManager.removeSavedAccount(context, profileKey)
                loadSavedAccounts()
                return@launch
            }
            ProfileManager.setActiveProfile(context, account.fakeNumber)
            Timber.tag("MainViewModel").i("Account-Switcher: Wechsel zu ${account.profileKey}, starte neu")
            ProfileManager.markPendingRestart(context)
            android.os.Process.killProcess(android.os.Process.myPid())
        }
    }

    /** Entfernt einen gespeicherten Account aus dem Switcher (meldet ihn ggf. vorher ab). */
    fun removeSavedAccount(profileKey: String) {
        viewModelScope.launch {
            if (profileKey == ProfileManager.getActiveProfile(context)) {
                logout()
                return@launch
            }
            tokenManager.clearProfileToken(profileKey)
            ProfileManager.removeSavedAccount(context, profileKey)
            loadSavedAccounts()
        }
    }

    /**
     * Stellt die Sitzung nach einem Profil-Wechsel-Neustart wieder her.
     * Wird aufgerufen wenn TokenManager ein Token hat, aber die Room-DB noch leer ist.
     */
    private fun autoRestoreSession() {
        viewModelScope.launch {
            try {
                val userId = tokenManager.getUserId() ?: return@launch
                val fakeNumber = ProfileManager.getOriginalFakeNumber(context)
                    .ifEmpty { ProfileManager.getActiveProfile(context) }
                val profileResponse = apiService.getMe()
                if (profileResponse.isSuccessful && profileResponse.body() != null) {
                    val profile = profileResponse.body()!!
                    val phoneVerified = profile.isPhoneVerified
                    val newUser = UserEntity(
                        userId = userId,
                        fakeNumber = fakeNumber,
                        name = profile.name ?: "",
                        authToken = tokenManager.getToken() ?: "",
                        publicKey = profile.publicKey ?: "",
                        isAdmin = profile.isAdmin ?: false,
                        isModerator = profile.isModerator ?: false,
                        isCreator = profile.isCreator ?: false,
                        styx = profile.styx ?: 0,
                        ageVerified = profile.ageVerified ?: false,
                        is18Verified = profile.is18Verified ?: false,
                        profileImageUrl = profile.profileImageUrl?.let { toAbsoluteUrl(it) },
                        statusPermitted = profile.statusPermitted,
                        isPhoneVerified = phoneVerified,
                        info = profile.info,
                        links = profile.links,
                        instagram = profile.instagram,
                        tiktok = profile.tiktok,
                        youtube = profile.youtube,
                        isVerified = profile.isVerified ?: false
                    )
                    userDao.insertUser(newUser)
                    _currentUser.value = newUser
                    val autoRestoreProfileKey = ProfileManager.getActiveProfile(context)
                    if (autoRestoreProfileKey.isNotEmpty()) {
                        ProfileManager.saveAccountToRegistry(
                            context,
                            ProfileManager.SavedAccount(
                                profileKey = autoRestoreProfileKey,
                                fakeNumber = fakeNumber,
                                userId = userId,
                                displayName = newUser.name.ifBlank { fakeNumber },
                                profileImageUrl = newUser.profileImageUrl,
                                lastUsed = System.currentTimeMillis()
                            )
                        )
                        loadSavedAccounts()
                    }
                    redeemPendingInvite()
                    // ECDH-Schlüsselpaar sicherstellen – synchron, damit deriveSharedSecret() greift
                    try {
                        val softPrivKey = newUser.privateKey
                        val softPubKey = newUser.publicKey
                        val ecdhPubKey = withContext(Dispatchers.IO) {
                            CryptoManager.ensureKeyPair(context, softPrivKey, softPubKey)
                        }
                        val exportedSoftKey = CryptoManager.exportSoftPrivateKey()
                        if (exportedSoftKey != null && exportedSoftKey != softPrivKey) {
                            val updated = newUser.copy(privateKey = exportedSoftKey)
                            userDao.insertUser(updated)
                            _currentUser.value = updated
                        }
                        if (newUser.publicKey.length <= 100 || ecdhPubKey != newUser.publicKey) {
                            viewModelScope.launch(Dispatchers.IO) {
                                try { apiService.updateEcdhKey(EcdhKeyUpdateRequest(ecdhPubKey)) }
                                catch (e: Exception) { Timber.tag("LETHE_E2EE").e("ECDH-Upload fehlgeschlagen: ${e.message}") }
                            }
                        }
                        Timber.tag("LETHE_E2EE").i("ECDH-Key bereit (Auto-Restore, phoneVerified=$phoneVerified)")
                    } catch (e: Exception) {
                        Timber.tag("LETHE_E2EE").e("ECDH-Key Setup (Auto-Restore) fehlgeschlagen: ${e.message}")
                    }
                    connectWebSocketAndListen()
                    val pmAutoRestore = context.getSystemService(Context.POWER_SERVICE) as PowerManager
                    updateOnlineStatus(_isAppInForeground.value && pmAutoRestore.isInteractive)
                    loadContacts()
                    loadBlockedUsers()
                    loadLinkedDevices()
                    loadEnrolledDevices()
                    loadGroups()
                    loadPendingContactRequests()
                    schedulePendingContactsCheck()
                    startProfileImageRefreshLoop()
                    loadMyNearbyProfileForTracking()
                    // UMK: Bei Auto-Restore kein Passwort verfügbar → gespeicherten UMK aus Prefs laden
                    loadUmkFromPrefs()
                    if (!phoneVerified) {
                        _requirePhoneVerification.value = true
                        Timber.tag("LETHE_E2EE").i("Auto-Restore: Telefon noch nicht verifiziert → OTP-Screen")
                    }
                    Timber.tag("MainViewModel").i("Auto-Restore erfolgreich für Profil: $fakeNumber")
                } else {
                    // Token ungültig → Token löschen, auf Login-Screen bleiben
                    tokenManager.clearToken()
                    Timber.tag("MainViewModel").w("Auto-Restore fehlgeschlagen, Token gelöscht")
                }
            } catch (e: Exception) {
                Timber.tag("MainViewModel").e("Auto-Restore Exception", e)
            }
        }
    }

    // --- WEBSOCKET ---

    private fun connectWebSocketAndListen() {
        val userId = _currentUser.value?.userId ?: return
        webSocketManager.connect(userId)

        if (isListeningToWebSocket) return
        isListeningToWebSocket = true

        // Eingehende Echtzeit-Nachrichten verarbeiten
        viewModelScope.launch {
            webSocketManager.incomingMessages
                .catch { e -> Timber.tag("LETHE_WS").e(e, "Fehler im WebSocket-Message-Flow") }
                .collect { message ->
                    handleWebSocketMessage(message)
                }
        }

        // Bei Reconnect: verpasste Nachrichten nachladen + ausstehende Nachrichten erneut senden
        viewModelScope.launch {
            webSocketManager.connectionStatus.collect { connected ->
                if (connected) {
                    Timber.tag("LETHE_WS").d("Verbunden – lade verpasste Nachrichten nach")
                    syncMissedMessages()
                    restoreListenTogetherSession()
                    retryPendingMessages()
                    // Chat-Focus nach (Re-)Connect am Server wiederherstellen bzw. aufheben,
                    // damit die Server-seitige FCM-Unterdrückung zum tatsächlichen Sichtbarkeits-
                    // zustand passt (verhindert verpasste Gruppen-Pushes bei Display-aus).
                    syncChatFocusToServer()
                    // Anzahl offener Sketch-n-Check-Spiele aktualisieren
                    viewModelScope.launch(Dispatchers.IO) {
                        val count = try { apiService.getSknChGames().body()?.size ?: 0 } catch (_: Exception) { 0 }
                        _sknChOpenGamesCount.value = count
                    }
                    // UMK-Exchange bei (Re-)Connect für alle Kontakte ohne Conversation Key (v3)
                    viewModelScope.launch(Dispatchers.IO) { loadPartnerUmks() }
                }
            }
        }

        // FCM-Fallback: Nachricht per REST nachladen wenn WS sie nicht geliefert hat
        viewModelScope.launch {
            FcmMessageBus.newMessageSenderIds.collect { senderId ->
                Timber.tag("LETHE_FCM").d("FCM-Bus: lade Nachrichten von $senderId nach")
                loadMessages(senderId)
            }
        }

        // FCM-Bus: Gegenseite hat den Anruf beendet/abgebrochen (kam ggf. nur per FCM weil WS
        // im Doze getrennt war). Aktiven oder eingehenden Anruf dieses Anrufers sauber beenden.
        viewModelScope.launch {
            FcmMessageBus.callCancelledCallerIds.collect { callerId ->
                handleRemoteCallCancelled(callerId)
            }
        }
    }

    /**
     * Behandelt ein per FCM zugestelltes call_cancelled (Gegenseite hat aufgelegt).
     * Beendet nur dann, wenn der aktive Gesprächspartner oder der eingehende Anrufer
     * mit [callerId] übereinstimmt – sonst wird ein paralleler Anruf nicht angetastet.
     */
    private fun handleRemoteCallCancelled(callerId: String) {
        val activePartner = _activeCallPartnerId.value
        val incomingCaller = _incomingCall.value?.callerId
        if (activePartner != callerId && incomingCaller != callerId) {
            Timber.tag("LETHE_VIDEO").d("FCM call_cancelled von $callerId ignoriert – kein passender Anruf")
            return
        }
        Timber.tag("LETHE_VIDEO").d("FCM call_cancelled von $callerId – Anruf wird beendet")
        stopRingtone()
        stopAllRingback()
        _incomingCall.value = null
        IncomingCallStore.clear()
        notificationHelper.cancelCallNotification()
        context.sendBroadcast(
            android.content.Intent(IncomingCallActivity.ACTION_CALL_CANCELLED)
                .setPackage(context.packageName)
        )
        cleanupCall()
    }

    /**
     * Prüft nach Reconnect, ob eine aktive Listen-Together-Session in der DB existiert,
     * und stellt den lokalen State wieder her (Track + Position).
     */
    private fun restoreListenTogetherSession() {
        // Nur wiederherstellen wenn aktuell keine Session aktiv ist
        if (_listenTogetherActive.value) return
        val partnerId = _listenTogetherChatId.value ?: return
        viewModelScope.launch {
            try {
                val resp = apiService.getListenTogetherSession(partnerId)
                if (resp.isSuccessful) {
                    val body = resp.body() ?: return@launch
                    if (body.active && body.currentTrackUrl != null) {
                        _listenTogetherTrack.value     = ListenTogetherTrack(
                            url        = body.currentTrackUrl,
                            title      = body.currentTrackTitle ?: "",
                            artist     = "",
                            coverUrl   = null,
                            durationMs = 0L,
                        )
                        _listenTogetherIsPlaying.value = body.isPlaying
                        _listenTogetherPosition.value  = body.positionMs
                        _listenTogetherActive.value    = true
                        Timber.tag("LETHE_LISTEN").d("Session wiederhergestellt: ${body.currentTrackTitle} @ ${body.positionMs}ms")
                    }
                }
            } catch (e: Exception) {
                Timber.tag("LETHE_LISTEN").w("Session-Restore fehlgeschlagen: ${e.message}")
            }
        }
    }

    /** Lädt für alle bekannten Kontakte neue Nachrichten vom Server nach (nach Reconnect). */
    private fun syncMissedMessages() {
        viewModelScope.launch {
            try {
                // 1. Verpasste Delivery-Status-Updates (gesendet/zugestellt/gelesen) nachholen
                syncDeliveryStatuses()

                // 2. Neue Nachrichten für alle Kontakte laden – mit begrenzter Parallelität statt
                // Fire-and-Forget für ALLE Kontakte gleichzeitig. Direkt nach einem Reconnect (z.B.
                // nach nächtlichem Doze-/Prozess-Kill) kann die Funkverbindung noch instabil sein;
                // ein unbegrenzter Request-Burst bei vielen Kontakten ließ hintere Anfragen per
                // Timeout scheitern, sodass einzelne Chats trotz zugestellter FCM-Notification erst
                // nach einem kompletten App-Neustart korrekt nachgeladen wurden. loadMessagesSuspend()/
                // loadGroupMessagesSuspend() werden hier awaited statt nur gestartet.
                val syncSemaphore = Semaphore(4)
                val allContacts = contactDao.getAllContacts().first()
                coroutineScope {
                    allContacts.map { contact ->
                        launch { syncSemaphore.withPermit { loadMessagesSuspend(contact.userId) } }
                    }.joinAll()
                }
                // Auch Gruppen-Nachrichten synchronisieren
                val allGroups = groupDao.getAllGroups().first()
                coroutineScope {
                    allGroups.map { group ->
                        launch { syncSemaphore.withPermit { loadGroupMessagesSuspend(group.groupId) } }
                    }.joinAll()
                }
            } catch (e: Exception) {
                Timber.tag("LETHE_WS").e("syncMissedMessages fehlgeschlagen", e)
            }
        }
    }

    /**
     * Holt verpasste Delivery-Status-Updates vom Server nach.
     * Wird beim Reconnect aufgerufen, damit der Absender verpasste
     * Zustellungs- und Lesebestätigungen (Häkchen) nachträglich erhält.
     */
    private suspend fun syncDeliveryStatuses() {
        try {
            val response = apiService.getDeliveryStatusSync()
            if (response.isSuccessful) {
                val updates = response.body() ?: emptyList()
                var updatedCount = 0
                updates.forEach { update ->
                    val existing = messageDao.getMessageById(update.messageId)
                    if (existing != null && update.status > existing.deliveryStatus) {
                        messageDao.updateDeliveryStatusByMessageId(update.messageId, update.status)
                        updatedCount++
                    }
                }
                if (updatedCount > 0) {
                    Timber.tag("LETHE_STATUS").d("$updatedCount verpasste Status-Updates synchronisiert")
                }
            }
        } catch (e: Exception) {
            Timber.tag("LETHE_STATUS").w("Delivery-Status-Sync fehlgeschlagen: ${e.message}")
        }
    }

    /** Lädt verpasste Gruppen-Nachrichten vom Server und speichert neue in der lokalen DB. */
    // ──────────────────────────────────────────────────────────────────────────
    // GRUPPEN-E2EE: SENDER-KEY-VERWALTUNG
    // ──────────────────────────────────────────────────────────────────────────

    /**
     * Stellt sicher dass Gruppen-E2EE einsatzbereit ist.
     * Aufruf: beim Betreten eines Gruppen-Chats (vor dem ersten Senden/Anzeigen).
     *   1. Kein eigener Sender-Key vorhanden → generieren + an alle Mitglieder verteilen.
     *   2. Keys anderer Mitglieder fehlen → vom Server holen und entschlüsseln.
     */
    fun ensureGroupE2EE(groupId: String) {
        viewModelScope.launch(Dispatchers.IO) {
            val me = _currentUser.value ?: return@launch
            val myKey = groupSenderKeyDao.getKey(groupId, me.userId)
            if (myKey == null) {
                Timber.tag("LETHE_E2EE").d("Kein eigener Sender-Key für $groupId – generiere neuen…")
                generateAndDistributeGroupSenderKey(groupId)
            }
            // Unabhängig davon: fehlende Keys anderer Mitglieder vom Server holen
            fetchAndStoreGroupSenderKeys(groupId)
        }
    }

    /**
     * Generiert einen neuen AES-256 Sender-Key, verschlüsselt ihn für jedes Mitglied
     * mit dem jeweiligen 1:1-ECDH-Shared-Secret und lädt die verschlüsselten Bundles hoch.
     * Danach wird der eigene Klartext-Key lokal in Room gespeichert.
     */
    private suspend fun generateAndDistributeGroupSenderKey(groupId: String) {
        val me = _currentUser.value ?: return

        // 1. Public Keys aller anderen Mitglieder vom Server holen
        val membersResponse = try {
            apiService.getGroupMemberPublicKeys(groupId)
        } catch (e: Exception) {
            Timber.tag("LETHE_E2EE").e("getGroupMemberPublicKeys($groupId) Exception: ${e.message}")
            return
        }
        if (!membersResponse.isSuccessful) {
            Timber.tag("LETHE_E2EE").e("getGroupMemberPublicKeys($groupId) HTTP ${membersResponse.code()}")
            return
        }
        val members = membersResponse.body() ?: return

        // 2. Neuen Sender-Key erzeugen
        val rawKey = CryptoManager.generateGroupSenderKey()
        val keyBase64 = android.util.Base64.encodeToString(rawKey, android.util.Base64.NO_WRAP)
        // Version = Epoch-Sekunden statt hartkodiert 1: fetchAndStoreGroupSenderKeys() anderer
        // Mitglieder vergleicht "existing.version >= entry.version" um bereits bekannte Keys nicht
        // erneut zu laden. Bei hartkodierter 1 würde eine spätere Neugenerierung (z.B. nach lokalem
        // DB-Wipe durch die Profil-Selbstheilung) denselben Versionswert liefern → andere Mitglieder
        // überspringen den neuen Key fälschlich und entschlüsseln weiter mit dem alten, ungültigen
        // Key ("Schlüssel nicht verfügbar"). Ein monoton steigender Wert stellt sicher, dass jede
        // Neugenerierung als neuere Version erkannt und nachgeladen wird.
        val newVersion = (System.currentTimeMillis() / 1000L).toInt()

        // 3. Für jedes Mitglied ein verschlüsseltes Bundle erstellen
        val bundles = mutableListOf<SenderKeyBundle>()
        for (member in members) {
            if (member.publicKey.length <= 100) continue  // Zu kurz → Legacy SHA-256-Key, überspringen

            // Shared Secret ableiten falls noch nicht im Cache
            if (!CryptoManager.hasSharedSecret(member.userId)) {
                CryptoManager.deriveSharedSecret(member.userId, member.publicKey)
            }

            val encryptedBundle = CryptoManager.encryptSenderKeyBundle(member.userId, rawKey)
            if (encryptedBundle != null) {
                bundles.add(SenderKeyBundle(
                    recipientId = member.userId,
                    encryptedKeyBundle = encryptedBundle,
                    version = newVersion
                ))
            } else {
                Timber.tag("LETHE_E2EE").w("Kein Shared Secret für ${member.userId} – Bundle übersprungen")
            }
        }

        // 4. Bundles hochladen (auch wenn bundles leer ist – löscht alte Keys des Owners)
        try {
            val uploadResponse = apiService.distributeGroupSenderKeys(
                groupId, DistributeKeysRequest(bundles = bundles, version = newVersion)
            )
            if (uploadResponse.isSuccessful) {
                // 5. Eigenen Klartext-Key lokal speichern
                groupSenderKeyDao.insertKey(GroupSenderKeyEntity(
                    groupId = groupId,
                    ownerId = me.userId,
                    keyBase64 = keyBase64,
                    version = newVersion,
                    storedAt = System.currentTimeMillis()
                ))
                Timber.tag("LETHE_E2EE").d("Sender-Key generiert & verteilt: $groupId (${bundles.size} Bundles)")
            } else {
                Timber.tag("LETHE_E2EE").e("distributeGroupSenderKeys HTTP ${uploadResponse.code()}")
            }
        } catch (e: Exception) {
            Timber.tag("LETHE_E2EE").e("distributeGroupSenderKeys Exception: ${e.message}")
        }
    }

    /**
     * Holt verschlüsselte Sender-Key-Bundles anderer Mitglieder vom Server,
     * entschlüsselt sie mit dem jeweiligen 1:1-ECDH-Shared-Secret und speichert
     * die Klartext-Keys lokal in der Room-Datenbank.
     */
    private suspend fun fetchAndStoreGroupSenderKeys(groupId: String) {
        val me = _currentUser.value ?: return
        try {
            val response = apiService.getMyGroupKeyBundle(groupId)
            if (!response.isSuccessful) return
            val bundleResponse = response.body() ?: return

            for (entry in bundleResponse.bundles) {
                // Eigenen Key nicht überschreiben (der wurde in generateAndDistribute gesetzt)
                if (entry.ownerId == me.userId) continue

                // Bereits vorhanden und aktuell? Überspringen
                val existing = groupSenderKeyDao.getKey(groupId, entry.ownerId)
                if (existing != null && existing.version >= entry.version) continue

                // Shared Secret mit dem Key-Owner nötig – aus Kontakte-DB holen
                if (!CryptoManager.hasSharedSecret(entry.ownerId)) {
                    val contact = contactDao.getContactById(entry.ownerId)
                    if (contact != null && contact.publicKey.length > 100) {
                        CryptoManager.deriveSharedSecret(entry.ownerId, contact.publicKey)
                    }
                }

                val rawKey = CryptoManager.decryptSenderKeyBundle(entry.ownerId, entry.encryptedKeyBundle)
                if (rawKey != null) {
                    val keyBase64 = android.util.Base64.encodeToString(rawKey, android.util.Base64.NO_WRAP)
                    groupSenderKeyDao.insertKey(GroupSenderKeyEntity(
                        groupId = groupId,
                        ownerId = entry.ownerId,
                        keyBase64 = keyBase64,
                        version = entry.version,
                        storedAt = System.currentTimeMillis()
                    ))
                    Timber.tag("LETHE_E2EE").d("Sender-Key von ${entry.ownerId} gespeichert (Gruppe $groupId)")
                } else {
                    Timber.tag("LETHE_E2EE").w("Sender-Key von ${entry.ownerId} nicht entschlüsselbar – kein Shared Secret?")
                }
            }
        } catch (e: Exception) {
            Timber.tag("LETHE_E2EE").e("fetchAndStoreGroupSenderKeys($groupId) Exception: ${e.message}")
        }
    }

    /**
     * Opt-in Chat-Backup (chat_backup_plan.md Stufe 2): sichert einen frisch entschlüsselten
     * Klartext serverseitig via WS "backup_store" – nur wenn der Nutzer es lokal aktiviert hat.
     * Bewusster, einseitiger E2EE-Bruch (siehe Plan): server-side Gate + Rate-Limit schützen vor
     * Missbrauch, ein lokales Room-Dedup-Flag verhindert wiederholten Upload derselben Nachricht.
     */
    private fun maybeBackupPlaintext(messageId: String?, plaintext: String, groupId: String? = null) {
        if (!_userPrefs.value.chatBackupEnabled) return
        viewModelScope.launch(Dispatchers.IO) { backupPlaintextNow(messageId, plaintext, groupId) }
    }

    /**
     * Eigentliche Backup-Logik (suspend, sequentiell aufrufbar) – von [maybeBackupPlaintext] (fire-and-
     * forget an den Decrypt-Punkten) UND vom Stufe-3-Backfill (gedrosselt, sequentiell) genutzt.
     * Gibt true zurück, wenn tatsächlich ein "backup_store" verschickt wurde (für die Backfill-Drosselung).
     */
    private suspend fun backupPlaintextNow(messageId: String?, plaintext: String, groupId: String? = null): Boolean {
        if (messageId.isNullOrBlank()) return false
        if (plaintext.isBlank()) return false
        // Nur echten Klartext sichern – keine Fehlermeldungen und keinen noch verschlüsselten Blob
        if (plaintext.startsWith("v2:") || plaintext.startsWith("v3:")) return false
        if (plaintext.startsWith("\uD83D\uDD10") || plaintext.startsWith("🔐") || plaintext.startsWith("⚠️")) return false
        if (messageDao.isBackedUp(messageId) > 0) return false
        webSocketManager.sendMessage(
            "backup_store",
            groupId ?: messageId,
            buildMap<String, Any> {
                put("message_id", messageId)
                put("content", plaintext)
                if (groupId != null) put("group_id", groupId)
            }
        )
        messageDao.markBackedUp(messageId)
        return true
    }

    private var chatBackupBackfillJob: Job? = null

    /** -1 = inaktiv, sonst 0f..1f Fortschritt. Für UI-Fortschrittsanzeige beim Backfill (Stufe 3). */
    private val _chatBackupProgress = MutableStateFlow(-1f)
    val chatBackupProgress: StateFlow<Float> = _chatBackupProgress.asStateFlow()

    /**
     * Opt-in Chat-Backup Stufe 3 (Backfill): beim Einschalten werden alle bereits lokal im Klartext
     * vorliegenden Alt-Nachrichten (Room, `backedUp == false`) nachträglich per "backup_store" gesichert.
     * Kein erneutes Entschlüsseln nötig – Room hält den Klartext bereits. Gedrosselt (600ms zwischen
     * Sends), um sicher unter dem Server-Rate-Limit von 120/min zu bleiben (main.py
     * `_BACKUP_STORE_MAX_PER_MINUTE`). Idempotent: Server-Guard + Room-`backedUp`-Flag verhindern
     * Doppel-Uploads bei Abbruch/Neustart.
     */
    private fun startChatBackupBackfill() {
        chatBackupBackfillJob?.cancel()
        chatBackupBackfillJob = viewModelScope.launch(Dispatchers.IO) {
            try {
                val pending = messageDao.getUnbackedUpTextMessages()
                if (pending.isEmpty()) return@launch
                _chatBackupProgress.value = 0f
                val total = pending.size
                pending.forEachIndexed { index, msg ->
                    // Nutzer könnte während des laufenden Backfills wieder deaktiviert haben
                    if (!_userPrefs.value.chatBackupEnabled) return@launch
                    val isGroup = groupDao.getGroupById(msg.chatId) != null
                    val sent = backupPlaintextNow(msg.messageId, msg.content ?: "", if (isGroup) msg.chatId else null)
                    _chatBackupProgress.value = (index + 1).toFloat() / total
                    if (sent) delay(600)
                }
            } finally {
                _chatBackupProgress.value = -1f
            }
        }
    }

    /**
     * Entschlüsselt den content_blob einer Gruppen-Nachricht mit dem Sender-Key des Absenders.
     * Falls der Key lokal fehlt, wird er vom Server nachgeladen.
     * Gibt Klartext zurück, oder eine lesbare Fehlermeldung wenn Entschlüsselung fehlschlägt.
     */
    private suspend fun decryptGroupContent(groupId: String, senderId: String, content: String): String {
        if (!content.startsWith("v2:")) return content  // Klartext oder Nicht-E2EE

        suspend fun tryDecryptWith(keyEntity: GroupSenderKeyEntity?): String? {
            keyEntity ?: return null
            return try {
                val rawKey = android.util.Base64.decode(keyEntity.keyBase64, android.util.Base64.NO_WRAP)
                CryptoManager.decryptGroupMessage(rawKey, content)
            } catch (_: Exception) {
                null
            }
        }

        // Versuch 1: Key aus lokalem Cache
        val localKey = groupSenderKeyDao.getKey(groupId, senderId)
        tryDecryptWith(localKey)?.let { return it }

        // Versuch 2: Key vom Server nachladen, dann erneut versuchen
        fetchAndStoreGroupSenderKeys(groupId)
        val refreshedKey = groupSenderKeyDao.getKey(groupId, senderId)
        tryDecryptWith(refreshedKey)?.let { return it }

        Timber.tag("LETHE_E2EE").w("Gruppen-Entschlüsselung fehlgeschlagen für $senderId in $groupId")
        return "[🔐 Schlüssel nicht verfügbar]"
    }

    /**
     * Key-Rotation nach Mitglieds-Austritt oder Kick (Perfect Forward Secrecy).
     * Löscht alle lokalen Keys dieser Gruppe, generiert einen neuen Sender-Key
     * und verteilt ihn an die verbleibenden Mitglieder.
     * Wird durch das WS-Event "group_key_rotation" ausgelöst.
     */
    private fun rotateGroupSenderKey(groupId: String) {
        viewModelScope.launch(Dispatchers.IO) {
            // Alle lokalen Keys dieser Gruppe ungültig machen
            groupSenderKeyDao.deleteKeysForGroup(groupId)
            Timber.tag("LETHE_E2EE").d("Key-Rotation: alle Keys für $groupId gelöscht")
            // Neuen Key generieren und an verbliebene Mitglieder verteilen
            generateAndDistributeGroupSenderKey(groupId)
            // Aktuelle Keys der anderen Mitglieder holen
            fetchAndStoreGroupSenderKeys(groupId)
        }
    }

    // ──────────────────────────────────────────────────────────────────────────

    fun loadGroupMessages(groupId: String) {
        viewModelScope.launch { loadGroupMessagesSuspend(groupId) }
    }

    /** Kernlogik von [loadGroupMessages] als suspend-Funktion (siehe [loadMessagesSuspend]). */
    private suspend fun loadGroupMessagesSuspend(groupId: String) {
        // E2EE sicherstellen bevor Nachrichten geladen werden (nicht blockierend)
        viewModelScope.launch(Dispatchers.IO) { ensureGroupE2EE(groupId) }
        // Initial nur die neuesten 50 laden (statt der kompletten Historie) –
        // ältere werden beim Hochscrollen via loadOlderMessages nachgeladen.
        doLoadGroupMessagesFromServer(groupId, limit = 50, beforeId = null)
    }

    /**
     * Kernlogik: Lädt Gruppen-Nachrichten paginiert vom Server und schreibt sie in Room.
     * Spiegelt das 1:1-Pagination-Tracking (oldestServerMessageId/hasMoreMessages).
     */
    private suspend fun doLoadGroupMessagesFromServer(groupId: String, limit: Int, beforeId: String?) {
        try {
                val response = apiService.getGroupMessages(groupId, limit = limit, beforeId = beforeId)
                if (!response.isSuccessful) return
                val serverMessages = response.body() ?: return
                val myId = _currentUser.value?.userId ?: return

                // Pagination-Tracking: älteste ID + ob mehr vorhanden sind (Server liefert asc).
                if (serverMessages.isNotEmpty()) {
                    _oldestServerMessageId[groupId] = serverMessages.first().id
                    _hasMoreMessages[groupId] = serverMessages.size >= limit
                } else {
                    _hasMoreMessages[groupId] = false
                }

                serverMessages.forEach { item ->
                    val existingById = if (item.id.isNotBlank()) messageDao.getMessageById(item.id) else null
                    if (existingById != null) {
                        // deliveryStatus aus Server-Flags synchronisieren
                        val syncedStatus = if (item.senderId == myId) {
                            when { item.isRead -> 3; item.isDelivered -> 2; else -> 1 }
                        } else {
                            if (item.isRead) 3 else 2
                        }
                        if (syncedStatus > existingById.deliveryStatus) {
                            messageDao.updateDeliveryStatus(existingById.localId, syncedStatus)
                        }
                        // Bearbeitete Gruppen-Nachrichten beim Nachladen abgleichen: Gruppen-Nachrichten
                        // haben serverseitig kein is_edited-Flag, daher wird der Inhalt verglichen. War dieses
                        // Gerät beim Edit offline (message_edited-WS verpasst), wird der neue Text hier übernommen.
                        if ((item.mediaType ?: "text") == "text") {
                            val rawContent = item.contentBlob ?: ""
                            val serverContent = if (rawContent.startsWith("v2:")) {
                                withContext(Dispatchers.IO) { decryptGroupContent(groupId, item.senderId, rawContent) }
                            } else rawContent
                            if (serverContent.isNotBlank() && serverContent != existingById.content
                                && !serverContent.startsWith("[🔐") && !serverContent.startsWith("v2:")) {
                                messageDao.editMessageByServerId(item.id, serverContent)
                            }
                            maybeBackupPlaintext(item.id, serverContent, groupId)
                        }
                    } else {
                        val existing = messageDao.getMessageByClientId(item.clientMessageId ?: "")
                        if (existing != null) {
                            messageDao.ackMessage(item.clientMessageId ?: "", item.id)
                            val dedup2Status = when { item.isRead -> 3; item.isDelivered -> 2; else -> 1 }
                            if (dedup2Status > existing.deliveryStatus) {
                                messageDao.updateDeliveryStatus(existing.localId, dedup2Status)
                            }
                        } else {
                            // Entschlüsseln wenn content_blob im v2-Format und mediaType == "text"
                            val rawContent = item.contentBlob ?: ""
                            val decryptedContent = if (item.mediaType == "text" && rawContent.startsWith("v2:")) {
                                withContext(Dispatchers.IO) {
                                    decryptGroupContent(groupId, item.senderId, rawContent)
                                }
                            } else {
                                rawContent
                            }
                            // deliveryStatus aus Server-Flags berechnen
                            val groupDeliveryStatus = if (item.senderId == myId) {
                                when {
                                    item.isRead -> 3
                                    item.isDelivered -> 2
                                    else -> 1
                                }
                            } else {
                                if (item.isRead) 3 else 2
                            }

                            messageDao.insertMessage(
                                MessageEntity(
                                    messageId = item.id,
                                    chatId = groupId,
                                    senderId = item.senderId,
                                    receiverId = groupId,
                                    content = decryptedContent,
                                    mediaType = item.mediaType ?: "text",
                                    mediaUrl = item.mediaUrl,
                                    timestamp = item.timestamp?.let {
                                        try { java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss", java.util.Locale.US).parse(it)?.time }
                                        catch (e: Exception) { System.currentTimeMillis() }
                                    } ?: System.currentTimeMillis(),
                                    isSent = item.senderId == myId,
                                    isEncrypted = rawContent.startsWith("v2:") && item.mediaType == "text",
                                    replyToContent = item.replyToContent,
                                    replyToSenderId = item.replyToSenderId,
                                    replyToMediaType = item.replyToMediaType,
                                    deliveryStatus = groupDeliveryStatus
                                )
                            )
                            if (item.mediaType == "text") {
                                maybeBackupPlaintext(item.id, decryptedContent, groupId)
                            }
                        }
                    }
                }
        } catch (e: Exception) {
            Timber.tag("LETHE_WS").e("loadGroupMessages($groupId) fehlgeschlagen", e)
        }
    }

    private suspend fun handleWebSocketMessage(msg: WebSocketMessage) {
        Timber.tag("LETHE_WS").d("Handling message type: ${msg.type}")

        when (msg.type) {
            // Server sendet "new_message" wenn eine Nachricht weitergeleitet wird
            "new_message" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val senderId = msg.senderId ?: return
                val rawContentBlob = payload["content_blob"] as? String ?: ""
                val mediaType0 = payload["media_type"] as? String ?: "text"
                val isEncryptedFlag = payload["is_encrypted"] as? Boolean ?: rawContentBlob.startsWith("v2:")

                // Multi-Device Fan-Out: Web-Key + Selbst-Kopie aus Payload lesen
                val senderWebPub = payload["sender_web_pub"] as? String
                val selfContentBlobRaw = payload["self_content_blob"] as? String
                // isMyOwnMessage: Mirror einer eigenen Nachricht (z.B. vom Webchat an uns gespiegelt)
                val isMyOwnMessage = senderId.isNotBlank() && senderId == _currentUser.value?.userId

                // Entschlüsseln: is_encrypted=true (oder Legacy v2:-Präfix) → AES-256-GCM
                // is_encrypted=false → Klartext (Altlast), unverändert anzeigen
                val contentBlob = if (mediaType0 == "text" && isEncryptedFlag) {
                    withContext(Dispatchers.IO) {
                        if (isMyOwnMessage && rawContentBlob.startsWith("v3:")) {
                            // v3 (UMK): Eigene Nachricht – gleicher Conversation Key auf allen Geräten
                            try {
                                CryptoManager.decryptUniversal(senderId, rawContentBlob)
                            } catch (e: Exception) {
                                rawContentBlob
                            }
                        } else if (isMyOwnMessage && !senderWebPub.isNullOrBlank() && !selfContentBlobRaw.isNullOrBlank()) {
                            // Legacy v2: Eigene Nachricht vom Webchat via self_content_blob
                            CryptoManager.deriveWebSharedSecret(senderId, senderWebPub)
                            try {
                                CryptoManager.decryptBestEffort(senderId, selfContentBlobRaw)
                            } catch (e: Exception) {
                                Timber.tag("LETHE_E2EE").w("Self-Web-Msg Entschlüsselung fehlgeschlagen: ${e.message}")
                                selfContentBlobRaw
                            }
                        } else {
                            // Nachricht vom Kontakt (ggf. von dessen Webchat gesendet):
                            // Web-Secret ZUERST force-rederiven (synchron!) – race-condition-frei.
                            // Force-Rederive statt derive: bei Key-Rotation (neuer Browser-Tab) muss
                            // der veraltete Cache-Eintrag sofort ersetzt werden.
                            if (!senderWebPub.isNullOrBlank()) {
                                CryptoManager.forceRederiveWebSharedSecret(senderId, senderWebPub)
                                Timber.tag("LETHE_E2EE").i("Web-Secret für $senderId aus sender_web_pub force-rederived.")
                            }
                            // Race-Condition-Schutz: Android-Secret aus Room DB ableiten falls noch nicht gecacht
                            // Priorität 1: partner_public_key direkt aus dem Relay-Payload (immer aktuell)
                            val relayedPartnerKey = payload["partner_public_key"] as? String
                            if (!relayedPartnerKey.isNullOrBlank() && relayedPartnerKey.length > 100) {
                                CryptoManager.forceRederiveSharedSecret(senderId, relayedPartnerKey)
                                // Key auch in Room DB persistieren falls Kontakt bereits vorhanden
                                val existingContact = contactDao.getContactById(senderId)
                                if (existingContact != null && existingContact.publicKey != relayedPartnerKey) {
                                    contactDao.updateContact(existingContact.copy(publicKey = relayedPartnerKey))
                                }
                            } else if (!CryptoManager.hasSharedSecret(senderId)) {
                                // Priorität 2: Key aus Room DB (Fallback)
                                val contact = contactDao.getContactById(senderId)
                                if (contact != null && contact.publicKey.length > 100) {
                                    CryptoManager.deriveSharedSecret(senderId, contact.publicKey)
                                }
                            }
                            // Web-Key aus Relay-Payload ebenfalls aktualisieren
                            val relayedWebKey = payload["partner_web_public_key"] as? String
                            if (!relayedWebKey.isNullOrBlank() && relayedWebKey.length > 80) {
                                CryptoManager.forceRederiveWebSharedSecret(senderId, relayedWebKey)
                            }
                            try {
                                CryptoManager.decryptUniversal(senderId, rawContentBlob)
                            } catch (decEx: Exception) {
                                Timber.tag("LETHE_E2EE").w("WS-Entschlüsselung fehlgeschlagen: ${decEx.message}")
                                "\uD83D\uDD10 [Nachricht konnte nicht entschlüsselt werden]"
                            }
                        }
                    }
                } else {
                    rawContentBlob
                }

                Timber.tag("LETHE_WS").i("new_message: von=$senderId, typ=$mediaType0, msgId=${msg.messageId}")

                // FIX: message_id liegt auf top-level der WS-Nachricht (msg.messageId),
                // NICHT im payload – Server sendet: {"type":"new_message","message_id":"...","payload":{...}}
                val messageId = msg.messageId

                // DEDUP-1: Prüfen ob Nachricht bereits via messageId (Server-ID) vorhanden
                if (messageId != null) {
                    val existing = messageDao.getMessageById(messageId)
                    if (existing != null) {
                        Timber.tag("LETHE_WS").d("Nachricht bereits verarbeitet ($messageId) – überspringe")
                        // Empfang trotzdem bestätigen: Der Server holt beim (Re-)Connect alle
                        // Nachrichten mit is_delivered=False nach. Ohne dieses "delivered" bliebe
                        // das Flag ewig False → dieselbe (alte) Nachricht würde bei jedem Reconnect
                        // erneut gepusht und ggf. als neue Benachrichtigung angezeigt.
                        if (!isMyOwnMessage) {
                            webSocketManager.sendMessage(
                                "delivered", senderId, mapOf("message_id" to messageId)
                            )
                        }
                        return
                    }
                }

                // DEDUP-2: Prüfen ob Nachricht bereits via clientMessageId vorhanden
                // (verhindert Doppelpost wenn message_ack noch nicht verarbeitet wurde)
                val clientMsgId = payload["client_message_id"] as? String
                if (clientMsgId != null) {
                    val existingByClientId = messageDao.getMessageByClientId(clientMsgId)
                    if (existingByClientId != null) {
                        Timber.tag("LETHE_WS").d("Nachricht bereits via clientId verarbeitet ($clientMsgId) – überspringe")
                        // messageId synchronisieren falls noch nicht gesetzt
                        if (messageId != null && existingByClientId.messageId == null) {
                            messageDao.ackMessage(clientMsgId, messageId)
                        }
                        // Empfang bestätigen (siehe DEDUP-1) damit der Server nicht endlos nachholt
                        if (!isMyOwnMessage && messageId != null) {
                            webSocketManager.sendMessage(
                                "delivered", senderId, mapOf("message_id" to messageId)
                            )
                        }
                        return
                    }
                }

                val mediaType = payload["media_type"] as? String ?: "text"
                val replyToContent = payload["reply_to_content"] as? String
                val replyToSenderId = payload["reply_to_sender_id"] as? String
                val replyToMediaType = payload["reply_to_media_type"] as? String
                val replyToMessageId = payload["reply_to_message_id"] as? String

                // Systemnachrichten (Anruf-Events): chatId aus chat_partner_id ableiten
                val isSystemMsg = senderId == "lethe_system"
                // Eigene Web-Nachrichten (Mirror): receiver_id als chatId nutzen, da senderId == eigener User
                val effectiveChatId = if (isSystemMsg) {
                    payload["chat_partner_id"] as? String ?: return
                } else if (isMyOwnMessage) {
                    msg.receiverId ?: (payload["receiver_id"] as? String) ?: return
                } else {
                    senderId
                }

                // Benachrichtigung unterdrücken und Nachricht direkt als gelesen markieren,
                // wenn der Chat dieses Absenders aktuell geöffnet und sichtbar ist.
                val isScreenOn = (context.getSystemService(android.content.Context.POWER_SERVICE)
                    as android.os.PowerManager).isInteractive
                // Xiaomi (MIUI/HyperOS): isInteractive kann auch bei gesperrtem Gerät true sein,
                // weil MIUI die App bei FCM-Nachrichten kurz aufweckt. Keyguard-Check verhindert
                // fälschliches Unterdrücken der Notification und frühzeitiges Senden von Read-Receipts.
                val effectiveScreenOn = if (android.os.Build.MANUFACTURER.equals("Xiaomi", ignoreCase = true)) {
                    val kg = context.getSystemService(android.content.Context.KEYGUARD_SERVICE) as android.app.KeyguardManager
                    isScreenOn && !kg.isKeyguardLocked
                } else {
                    isScreenOn
                }
                // Benachrichtigung nur unterdrücken wenn Chat geöffnet UND Bildschirm aktiv ist.
                // Bei ausgeschaltetem Display muss immer eine Notification mit Text kommen.
                val shouldSuppress = (effectiveChatId == _activeChatId.value
                    && _isAppInForeground.value && effectiveScreenOn) || isMyOwnMessage

                // Sender-Zeitstempel aus Payload lesen (Long Epoch-Millis) damit Empfänger dieselbe Uhrzeit sieht
                val senderTimestamp = (payload["sender_timestamp"] as? Number)?.toLong()
                    ?: System.currentTimeMillis()
                val newMessage = MessageEntity(
                    messageId = messageId,
                    chatId = effectiveChatId,
                    senderId = senderId,
                    receiverId = _currentUser.value?.userId ?: "",
                    content = contentBlob,
                    mediaType = mediaType,
                    mediaUrl = (payload["media_url"] as? String)?.let { url ->
                        // JSON-Arrays (multi_image) dürfen nicht durch toAbsoluteUrl verändert werden
                        if (url.startsWith("[")) url else toAbsoluteUrl(url)
                    },
                    timestamp = senderTimestamp,
                    isRead = shouldSuppress || isSystemMsg, // Systemnachrichten immer als gelesen
                    replyToContent = replyToContent,
                    replyToSenderId = replyToSenderId,
                    replyToMediaType = replyToMediaType,
                    replyToMessageId = replyToMessageId
                )
                messageDao.insertMessage(newMessage)

                // Opt-in Chat-Backup: frisch entschlüsselten Klartext ggf. serverseitig sichern
                if (mediaType == "text" && messageId != null) {
                    maybeBackupPlaintext(messageId, contentBlob)
                }

                // Systemnachrichten: keine Benachrichtigung anzeigen, aber verpasste Anrufe
                // erhöhen den Badge-Zähler der Anrufliste (bzw. werden sofort bestätigt,
                // falls die Anrufliste gerade geöffnet ist).
                if (isSystemMsg) {
                    if (mediaType == "call_missed") {
                        if (_isCallListVisible.value) clearCallBadge() else _callBadgeCount.value++
                    }
                    return
                }

                // Poll-Nachricht: sofort in Room cachen damit UI sie anzeigen kann
                if (mediaType == "poll") {
                    val pollId = payload["poll_id"] as? String
                        ?: try { org.json.JSONObject(contentBlob).optString("poll_id") } catch (e: Exception) { null }
                    if (pollId != null) loadPoll(pollId)
                }

                // Benachrichtigung anzeigen – nur für wirklich neue Nachrichten (Dedup greift oben)
                val contact = contactDao.getContactById(senderId)
                val senderName = contact?.customAlias?.takeIf { it.isNotBlank() } ?: contact?.username ?: contact?.fakeNumber ?: senderId
                // Sicherstellen dass die URL absolut ist (Coil kann keine relativen URLs laden)
                val senderImage = contact?.profileImageUrl?.let { url ->
                    if (url.startsWith("http")) url else "https://letheapp.de$url"
                }
                val myImageUrl = _currentUser.value?.profileImageUrl?.let { url ->
                    if (url.startsWith("http")) url else "https://letheapp.de$url"
                }
                val preview = if (mediaType == "text") {
                    // Niemals rohen Ciphertext anzeigen: v2:/v3:-Blobs (oder ein noch verschlüsselter
                    // Fallback nach fehlgeschlagener Entschlüsselung) → generischer Text statt Blob.
                    // Gleicher Schwellenwert wie das "Aufklappen" im ChatScreen (400 Zeichen),
                    // damit die Notification die komplette Nachricht bis zu dieser Länge enthält.
                    if (contentBlob.startsWith("v2:") || contentBlob.startsWith("v3:") || contentBlob.startsWith("\uD83D\uDD10")) "Neue Nachricht" else contentBlob.take(400)
                } else when (mediaType) {
                    "image"    -> "📷 Bild"
                    "video"    -> "🎥 Video"
                    "audio"    -> "🎤 Sprachnachricht"
                    "document" -> "📎 Dokument"
                    "poll"     -> "📊 Umfrage"
                    else       -> "[$mediaType]"
                }
                // WICHTIG: identische Formel wie im FCM-Pfad (LetheFcmService) verwenden.
                // senderId.hashCode() kann negativ sein; ohne Maskierung entstünde eine andere
                // Notification-ID als bei FCM → zwei getrennte Android-Auto-Gespräche mit gleichem
                // Namen → Nachrichten würden doppelt vorgelesen.
                val notifId = (senderId.hashCode() and 0x7FFFFFFF) + NotificationHelper.NOTIFICATION_ID_MESSAGE_BASE

                Timber.tag("LETHE_NOTIF").d(
                    "Nachricht von $senderId: suppress=$shouldSuppress " +
                    "(activeChat=${_activeChatId.value}, foreground=${_isAppInForeground.value}, screenOn=$isScreenOn)"
                )

                if (!shouldSuppress) {
                    // Badge-Zähler erhöhen wenn ContactListScreen nicht sichtbar ist
                    if (!_isContactListVisible.value) {
                        _chatBadgeCount.value++
                    }

                    // Dedup-Guard: Benachrichtigung nur zeigen wenn weder FCM noch WS sie bereits gezeigt hat
                    val alreadyNotifiedByFcm = messageId != null &&
                        FcmMessageBus.wasNotificationShownByFcm(messageId)
                    val alreadyNotifiedByDb = messageId != null &&
                        messageDao.isDeliveredAsNotification(messageId) == 1
                    // FCM konnte den Text nicht entschlüsseln → WS soll die Notification updaten
                    val shouldUpdateFcmNotif = alreadyNotifiedByFcm && !alreadyNotifiedByDb
                        && preview != "Neue Nachricht"
                    val alreadyNotified = (alreadyNotifiedByFcm || alreadyNotifiedByDb) && !shouldUpdateFcmNotif

                    if (!alreadyNotified) {
                        if (!_onlyFcmMode.value) {
                            // Drop(1) entfernt die gerade eingefügte Nachricht (neueste) aus der Historie,
                            // damit sie nicht doppelt erscheint (einmal in recentMessages + einmal als messagePreview)
                            val recentRaw = messageDao.getRecentMessagesForChat(senderId, 6).drop(1)
                            val recentMessages = recentRaw.reversed().map { m ->
                                com.securechat.app.NotificationMessage(
                                    text = if (m.mediaType == "text") m.content ?: "" else "[${m.mediaType}]",
                                    timestamp = m.timestamp,
                                    isFromSender = m.senderId == senderId
                                )
                            }
                            val myId2 = _currentUser.value?.userId ?: ""
                            val unreadCount = messageDao.getUnreadCountFromSender(senderId, myId2).coerceAtLeast(1)

                            val wsMediaUrl = (payload["media_url"] as? String)
                                ?.let { if (it.startsWith("http")) it else "https://letheapp.de$it" }
                                ?.takeIf { it.isNotBlank() }
                            notificationHelper.showMessageNotification(
                                senderId = senderId,
                                senderName = senderName,
                                senderImageUrl = senderImage,
                                myImageUrl = myImageUrl,
                                messagePreview = preview,
                                notificationId = notifId,
                                recentMessages = recentMessages,
                                badgeCount = unreadCount,
                                mediaType = mediaType,
                                mediaHttpUrl = wsMediaUrl
                            )
                            // Erst NACH erfolgreicher Anzeige als notifiziert markieren: wird die
                            // Anzeige durch Doze/Prozess-Tod (z.B. während Bild-Download) unterbrochen,
                            // bleibt das Flag ungesetzt und FCM kann die Benachrichtigung als Fallback
                            // trotzdem zeigen, statt sie fälschlich dauerhaft zu unterdrücken.
                            if (messageId != null) {
                                messageDao.markDeliveredAsNotification(messageId)
                                FcmMessageBus.markNotificationShown(messageId)
                            }
                            if (shouldUpdateFcmNotif) {
                                Timber.tag("LETHE_NOTIF").d("FCM-Notification mit entschlüsseltem Text aktualisiert: $messageId")
                            } else {
                                Timber.tag("LETHE_NOTIF").d("Notification gezeigt für $messageId von $senderId")
                            }
                        } else {
                            Timber.tag("LETHE_NOTIF").d("WS-Notification unterdrückt (Only-FCM-Modus): $messageId")
                        }
                    } else {
                        Timber.tag("LETHE_NOTIF").d("Notification übersprungen (bereits gezeigt): $messageId")
                    }

                    // Direct Share / Google Assistant: Shortcuts nach neuer Nachricht aktualisieren
                    viewModelScope.launch {
                        val sorted = contactsSortedByRecent.first()
                        val allGroups = groupDao.getAllGroups().first()
                        val recentIds = messageDao.getRecentChatIds(50)
                        shortcutHelper.refreshTopContactShortcuts(sorted, allGroups, recentIds)
                    }
                }

                // ── READ-RECEIPTS: Chat ist gerade geöffnet ──────────────────────────────
                // Neue Nachricht kam an, während der User den Chat bereits ansieht →
                // alle ungelesenen Nachrichten dieses Absenders sofort als gelesen melden.
                if (shouldSuppress && !_userPrefs.value.readReceiptAfterReply) {
                    val myId = _currentUser.value?.userId ?: ""
                    // Alle Nachrichten mit deliveryStatus < 3 (inkl. der gerade eingegangenen)
                    val toRead = messageDao.getUnreadMessagesFrom(effectiveChatId, myId)
                    toRead.forEach { msg ->
                        messageDao.updateDeliveryStatus(msg.localId, 3)
                        if (!msg.messageId.isNullOrBlank()) {
                            webSocketManager.sendMessage(
                                "read_receipt", effectiveChatId,
                                mapOf("message_id" to msg.messageId)
                            )
                        }
                    }
                    // Sammel-Read-Receipt (Legacy-Kompatibilität)
                    webSocketManager.sendMessage(
                        "read_receipt", effectiveChatId,
                        mapOf("chat_partner" to effectiveChatId)
                    )
                    // isRead-Flag setzen → ContactlistScreen-Flow aktualisiert sich sofort
                    messageDao.markAllRead(effectiveChatId, myId)
                    Timber.tag("LETHE_WS").d(
                        "Chat geöffnet – ${toRead.size} Nachricht(en) von $effectiveChatId als gelesen gemeldet"
                    )
                }

                // Empfang bestätigen – erst NACH Benachrichtigung (Server setzt is_delivered = True)
                webSocketManager.sendMessage(
                    "delivered", senderId,
                    mapOf("message_id" to (messageId ?: ""))
                )
                Timber.tag("LETHE_WS").d("Nachricht gespeichert + delivered-Receipt gesendet: $messageId")
            }

            // Server bestätigt dass unsere Nachricht gespeichert wurde (SENT)
            "message_ack" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val clientId = payload["client_message_id"] as? String ?: return
                val serverId = payload["message_id"] as? String ?: return
                messageDao.ackMessage(clientId, serverId)
                Timber.tag("LETHE_WS").d("Message ACK: clientId=$clientId → serverId=$serverId")
            }

            // Gegenseite bestätigt dass unsere Nachricht angekommen ist
            "delivered" -> {
                // FIX: message_id liegt auf top-level (msg.messageId), nicht im payload
                // Server sendet: {"type":"delivered","message_id":"...","by":"..."}
                val messageId = msg.messageId
                if (messageId != null) {
                    messageDao.markDelivered(messageId)        // Legacy
                    messageDao.markDeliveredNew(messageId)     // Delivery Status
                    Timber.tag("LETHE_WS").d("Nachricht zugestellt: $messageId")
                }
            }

            // Gegenseite hat unsere Nachrichten gelesen
            "read_receipt" -> {
                val payload = msg.payload as? Map<*, *>
                val by = payload?.get("by") as? String
                val readMessageId = msg.messageId ?: payload?.get("message_id") as? String
                val groupId = payload?.get("group_id") as? String
                if (by != null) {
                    val myId = _currentUser.value?.userId ?: ""
                    if (groupId != null) {
                        // Gruppen-Read-Receipt: alle eigenen Nachrichten in der Gruppe auf READ setzen
                        messageDao.markAllReadNew(groupId, myId)
                        Timber.tag("LETHE_WS").d("Gruppen-Nachrichten gelesen von $by in Gruppe $groupId")
                    } else if (readMessageId != null) {
                        // Einzelne Nachricht als gelesen markieren (Fallback)
                        messageDao.markDelivered(readMessageId)
                        messageDao.updateDeliveryStatusByMessageId(readMessageId, 3)
                        Timber.tag("LETHE_WS").d("Nachricht $readMessageId gelesen von: $by")
                    } else {
                        // Alle Nachrichten vom Chat-Partner als gelesen (1:1)
                        messageDao.markAllRead(by, myId)         // Legacy
                        messageDao.markAllReadNew(by, myId)      // Delivery Status
                        Timber.tag("LETHE_WS").d("Nachrichten gelesen von: $by")
                    }
                }
            }

            // Multi-Device Sync: Delivered-Bestätigung von anderem eigenen Gerät
            "delivered_sync" -> {
                val messageId = msg.messageId ?: (msg.payload as? Map<*, *>)?.get("message_id") as? String
                if (messageId != null) {
                    messageDao.markDelivered(messageId)
                    messageDao.markDeliveredNew(messageId)
                    Timber.tag("LETHE_WS").d("delivered_sync: $messageId")
                }
            }

            // Multi-Device Sync: Read-Receipt von anderem eigenen Gerät
            "read_receipt_sync" -> {
                val payload = msg.payload as? Map<*, *>
                val chatId = payload?.get("chat_id") as? String
                if (chatId != null) {
                    val myId = _currentUser.value?.userId ?: ""
                    // Alle eingehenden Nachrichten vom Chat-Partner als gelesen markieren
                    messageDao.markAllRead(chatId, myId)
                    messageDao.markAllReadNew(chatId, myId)
                    Timber.tag("LETHE_WS").d("read_receipt_sync: Chat $chatId als gelesen markiert")
                }
            }

            // UMK-Exchange: Partner sendet seinen UMK (ECDH-verschlüsselt) → Conversation Key ableiten
            "umk_exchange" -> {
                val senderId = msg.senderId ?: return
                val payload = msg.payload as? Map<*, *> ?: return
                val encryptedUmk = payload["encrypted_umk"] as? String ?: return
                viewModelScope.launch(Dispatchers.IO) {
                    try {
                        // Partner-UMK entschlüsseln (via ECDH Shared Secret)
                        val decrypted = CryptoManager.decrypt(senderId, encryptedUmk)
                        if (decrypted.startsWith("v2:") || decrypted.startsWith("[")) return@launch
                        val partnerUmk = android.util.Base64.decode(decrypted, android.util.Base64.NO_WRAP)
                        if (partnerUmk.size == 32) {
                            CryptoManager.registerPartnerUmk(senderId, partnerUmk)
                            saveConversationKeysToPrefs()
                            savePartnerUmksToPrefs()
                            Timber.tag("LETHE_UMK").i("UMK-Exchange von $senderId: Conversation Key abgeleitet.")
                            // Antworten: eigenen UMK zurücksenden
                            val myUmk = CryptoManager.getUmkBytes() ?: return@launch
                            val myUmkB64 = android.util.Base64.encodeToString(myUmk, android.util.Base64.NO_WRAP)
                            val encrypted = CryptoManager.encrypt(senderId, myUmkB64)
                            if (encrypted != myUmkB64) {
                                webSocketManager.sendMessage("umk_exchange_response", senderId, mapOf("encrypted_umk" to encrypted))
                            }
                        }
                    } catch (e: Exception) {
                        Timber.tag("LETHE_UMK").w("umk_exchange Verarbeitung fehlgeschlagen: ${e.message}")
                    }
                }
            }

            // UMK-Exchange-Response: Partner antwortet mit seinem UMK
            "umk_exchange_response" -> {
                val senderId = msg.senderId ?: return
                val payload = msg.payload as? Map<*, *> ?: return
                val encryptedUmk = payload["encrypted_umk"] as? String ?: return
                viewModelScope.launch(Dispatchers.IO) {
                    try {
                        val decrypted = CryptoManager.decrypt(senderId, encryptedUmk)
                        if (decrypted.startsWith("v2:") || decrypted.startsWith("[")) return@launch
                        val partnerUmk = android.util.Base64.decode(decrypted, android.util.Base64.NO_WRAP)
                        if (partnerUmk.size == 32) {
                            CryptoManager.registerPartnerUmk(senderId, partnerUmk)
                            saveConversationKeysToPrefs()
                            savePartnerUmksToPrefs()
                            Timber.tag("LETHE_UMK").i("UMK-Exchange-Response von $senderId: Conversation Key abgeleitet.")
                        }
                    } catch (e: Exception) {
                        Timber.tag("LETHE_UMK").w("umk_exchange_response Verarbeitung fehlgeschlagen: ${e.message}")
                    }
                }
            }

            "contact_request" -> {
                // Eingehende Kontaktanfrage — Server schickt Felder direkt (nicht in payload)
                val payload = msg.payload as? Map<*, *> ?: return
                val fromNumber = payload["from_fake_number"] as? String ?: return
                val fromName = payload["from_name"] as? String ?: ""
                val entryId = payload["contact_entry_id"] as? String ?: return
                val fromUserId = payload["from_user_id"] as? String
                val fromPublicKey = payload["from_public_key"] as? String

                // EPIC 1: Public Key des Anfragenden vorab cachen (falls echter ECDH-Key)
                // Ermöglicht Shared-Secret-Ableitung schon vor dem Akzeptieren der Anfrage
                if (!fromUserId.isNullOrBlank() && !fromPublicKey.isNullOrBlank() && fromPublicKey.length > 100) {
                    withContext(Dispatchers.IO) {
                        CryptoManager.deriveSharedSecret(fromUserId, fromPublicKey)
                        Timber.tag("LETHE_E2EE").i("contact_request: Shared-Secret für $fromName vorab abgeleitet (key ok).")
                    }
                } else if (!fromPublicKey.isNullOrBlank()) {
                    Timber.tag("LETHE_E2EE").w("contact_request: Anfragender $fromName hat Legacy-Key (length=${fromPublicKey.length}) – kein Vorab-ECDH.")
                }

                _incomingContactRequest.value = IncomingRequest(fromNumber, fromName, entryId)
                // System-Benachrichtigung anzeigen (auch wenn App im Vordergrund ist)
                if (!_onlyFcmMode.value) notificationHelper.showContactRequestNotification(fromName, fromNumber, entryId)
                Timber.tag("LETHE_WS").d("Kontaktanfrage von: $fromName ($fromNumber)")
            }

            // Empfänger hat akzeptiert → Anfragender bekommt contact_accepted
            "contact_accepted" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val partnerId = payload["partner_id"] as? String ?: return
                val partnerNumber = payload["partner_fake_number"] as? String ?: return
                val partnerName = payload["partner_name"] as? String ?: ""
                val partnerKey = payload["partner_public_key"] as? String ?: return
                val partnerImage = (payload["partner_image"] as? String)?.let { toAbsoluteUrl(it) }
                val partnerWebKey = payload["partner_web_public_key"] as? String
                val isBot = payload["is_bot"] as? Boolean ?: false
                val isSystem = payload["is_system"] as? Boolean ?: false

                val newContact = ContactEntity(
                    userId = partnerId,
                    fakeNumber = partnerNumber,
                    username = partnerName,
                    publicKey = partnerKey,
                    profileImageUrl = partnerImage,
                    status = "accepted"
                )
                contactDao.insertContact(newContact)
                // Alle alten Krypto-Caches löschen (wichtig bei Neuregistrierung des Partners)
                CryptoManager.clearSecretForContact(partnerId)
                // EPIC 1: Android-Shared-Secret ableiten – Bots und System-Konten nutzen kein E2EE
                if (isBot || isSystem) {
                    Timber.tag("LETHE_E2EE").i("contact_accepted: $partnerName ist ${if (isBot) "Bot" else "System-Konto"} – kein ECDH.")
                } else if (partnerKey.length > 100) {
                    withContext(Dispatchers.IO) { CryptoManager.forceRederiveSharedSecret(partnerId, partnerKey) }
                } else {
                    // Admin/Moderator-erstellter Account: SHA-256-Dummy noch aktiv → kein ECDH möglich
                    // Normaler Zustand bis zum ersten Login des Partners (key_rotated folgt dann)
                    Timber.tag("LETHE_E2EE").w("contact_accepted: Partner $partnerName hat Legacy-Key (length=${partnerKey.length}) – kein Shared Secret ableitbar bis Handshake-Erneuerung.")
                }
                // EPIC 5: Web-Shared-Secret ableiten wenn Partner aktives Web-Gerät hat (nicht für Bots/System)
                if (!isBot && !isSystem && !partnerWebKey.isNullOrBlank() && partnerWebKey.length > 80) {
                    withContext(Dispatchers.IO) {
                        CryptoManager.forceRederiveWebSharedSecret(partnerId, partnerWebKey)
                        Timber.tag("LETHE_E2EE").i("contact_accepted: Web-Secret für $partnerName abgeleitet.")
                    }
                }
                // UMK-Exchange sofort initiieren (v3 Conversation Key)
                if (!isBot && !isSystem) {
                    viewModelScope.launch(Dispatchers.IO) { initiateUmkExchange(partnerId) }
                }
                _statusMessage.value = "Kontakt hinzugefügt: $partnerName"
                Timber.tag("LETHE_WS").d("Kontakt akzeptiert: $partnerName")

                // Neuen Kontakt automatisch zur Status-Sichtbarkeitsliste hinzufügen
                val me = _currentUser.value
                if (me != null) {
                    val currentPermitted = try {
                        val json = me.statusPermitted ?: "[]"
                        val arr = org.json.JSONArray(json)
                        (0 until arr.length()).map { arr.getString(it) }.toMutableList()
                    } catch (_: Exception) { mutableListOf() }
                    if (partnerId !in currentPermitted) {
                        currentPermitted.add(partnerId)
                        updateStatusPermitted(currentPermitted)
                    }
                }
            }

            // Anfragender hat bereits einen Kontakt angelegt → Empfänger bekommt contact_confirmed
            "contact_confirmed" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val partnerId = payload["partner_id"] as? String ?: return
                val partnerNumber = payload["partner_fake_number"] as? String ?: return
                val partnerName = payload["partner_name"] as? String ?: ""
                val partnerKey = payload["partner_public_key"] as? String ?: return
                val partnerImage = (payload["partner_image"] as? String)?.let { toAbsoluteUrl(it) }
                val partnerWebKey = payload["partner_web_public_key"] as? String
                val isBot = payload["is_bot"] as? Boolean ?: false
                val isSystem = payload["is_system"] as? Boolean ?: false

                val newContact = ContactEntity(
                    userId = partnerId,
                    fakeNumber = partnerNumber,
                    username = partnerName,
                    publicKey = partnerKey,
                    profileImageUrl = partnerImage,
                    status = "accepted"
                )
                contactDao.insertContact(newContact)
                // Alle alten Krypto-Caches löschen (wichtig bei Neuregistrierung des Partners)
                CryptoManager.clearSecretForContact(partnerId)
                // EPIC 1: Android-Shared-Secret ableiten – Bots und System-Konten nutzen kein E2EE
                if (isBot || isSystem) {
                    Timber.tag("LETHE_E2EE").i("contact_confirmed: $partnerName ist ${if (isBot) "Bot" else "System-Konto"} – kein ECDH.")
                } else if (partnerKey.length > 100) {
                    withContext(Dispatchers.IO) { CryptoManager.forceRederiveSharedSecret(partnerId, partnerKey) }
                } else {
                    // Admin/Moderator-erstellter Account: SHA-256-Dummy noch aktiv → kein ECDH möglich
                    // Normaler Zustand bis zum ersten Login des Partners (key_rotated folgt dann)
                    Timber.tag("LETHE_E2EE").w("contact_confirmed: Partner $partnerName hat Legacy-Key (length=${partnerKey.length}) – kein Shared Secret ableitbar bis Handshake-Erneuerung.")
                }
                // EPIC 5: Web-Shared-Secret ableiten wenn Partner aktives Web-Gerät hat (nicht für Bots/System)
                if (!isBot && !isSystem && !partnerWebKey.isNullOrBlank() && partnerWebKey.length > 80) {
                    withContext(Dispatchers.IO) {
                        CryptoManager.forceRederiveWebSharedSecret(partnerId, partnerWebKey)
                        Timber.tag("LETHE_E2EE").i("contact_confirmed: Web-Secret für $partnerName abgeleitet.")
                    }
                }
                // UMK-Exchange sofort initiieren (v3 Conversation Key)
                if (!isBot && !isSystem) {
                    viewModelScope.launch(Dispatchers.IO) { initiateUmkExchange(partnerId) }
                }
                _statusMessage.value = "Kontakt bestätigt: $partnerName"
                Timber.tag("LETHE_WS").d("Kontakt bestätigt: $partnerName")

                // Neuen Kontakt automatisch zur Status-Sichtbarkeitsliste hinzufügen
                val me = _currentUser.value
                if (me != null) {
                    val currentPermitted = try {
                        val json = me.statusPermitted ?: "[]"
                        val arr = org.json.JSONArray(json)
                        (0 until arr.length()).map { arr.getString(it) }.toMutableList()
                    } catch (_: Exception) { mutableListOf() }
                    if (partnerId !in currentPermitted) {
                        currentPermitted.add(partnerId)
                        updateStatusPermitted(currentPermitted)
                    }
                }
            }

            // Partner bittet um Erneuerung des E2EE-Handshakes
            "handshake_renew_request" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val fromUserId = payload["from_user_id"] as? String ?: return
                val fromNumber = payload["from_fake_number"] as? String ?: return
                val fromName = payload["from_name"] as? String ?: fromNumber
                val requesterKey = payload["requester_public_key"] as? String ?: ""
                _incomingHandshakeRenew.value = IncomingHandshakeRenew(fromUserId, fromNumber, fromName, requesterKey)
                Timber.tag("LETHE_E2EE").d("handshake_renew_request von: $fromName ($fromNumber)")
            }

            // Partner hat Handshake-Erneuerung angenommen → frische Keys ableiten
            "handshake_keys_updated" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val partnerId = payload["partner_id"] as? String ?: return
                val partnerKey = payload["partner_public_key"] as? String ?: return
                val partnerWebKey = payload["partner_web_public_key"] as? String
                if (partnerKey.length > 100) {
                    withContext(Dispatchers.IO) {
                        CryptoManager.forceRederiveSharedSecret(partnerId, partnerKey)
                        Timber.tag("LETHE_E2EE").i("handshake_keys_updated: Android-Secret für $partnerId erneuert")
                    }
                }
                if (!partnerWebKey.isNullOrBlank() && partnerWebKey.length > 80) {
                    withContext(Dispatchers.IO) {
                        CryptoManager.forceRederiveWebSharedSecret(partnerId, partnerWebKey)
                        Timber.tag("LETHE_E2EE").i("handshake_keys_updated: Web-Secret für $partnerId erneuert")
                    }
                }
                // UMK-Exchange nach Handshake-Erneuerung initiieren (v3 Conversation Key)
                viewModelScope.launch(Dispatchers.IO) { initiateUmkExchange(partnerId) }
                _contactScreenMessage.value = "Handshake erfolgreich erneuert"
            }

            // Partner hat Handshake-Erneuerung abgelehnt
            "handshake_renew_rejected" -> {
                _contactScreenMessage.value = "Handshake-Erneuerung wurde abgelehnt"
                Timber.tag("LETHE_E2EE").d("handshake_renew_rejected empfangen")
            }

            // Anonyme LetheID-Verbindung: Chat sofort öffnen (kein Name/Bild/Nummer sichtbar)
            "anonymous_chat_started" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val partnerId = payload["partner_id"] as? String ?: return
                val partnerLetheId = payload["partner_lethe_id"] as? String ?: partnerId
                val partnerKey = payload["partner_public_key"] as? String ?: return

                val newContact = ContactEntity(
                    userId = partnerId,
                    fakeNumber = partnerLetheId,
                    username = partnerLetheId,
                    publicKey = partnerKey,
                    profileImageUrl = null,
                    status = "accepted",
                    isAnonymous = true
                )
                contactDao.insertContact(newContact)
                if (partnerKey.length > 100) {
                    withContext(Dispatchers.IO) { CryptoManager.forceRederiveSharedSecret(partnerId, partnerKey) }
                }
                _statusMessage.value = "Anonymer Chat gestartet: $partnerLetheId"
                Timber.tag("LETHE_WS").d("Anonymer Chat gestartet: $partnerLetheId")
            }

            // Creator hat einen Spark gelöscht → sofort aus dem lokalen Feed entfernen
            "spark_deleted" -> {
                val sparkId = (msg.payload as? Map<*, *>)?.get("spark_id") as? String ?: return
                _vipFeed.value = _vipFeed.value.filter { it.id != sparkId }
                Timber.tag("LETHE_WS").d("spark_deleted: $sparkId aus Feed entfernt")
            }

            // Server bestätigt, dass eine geplante Nachricht versendet wurde
            "scheduled_message_sent" -> {
                val p = msg.payload as? Map<*, *> ?: return
                val scheduledId = p["scheduled_id"] as? String ?: return
                _scheduledMessages.value = _scheduledMessages.value.filter { it.id != scheduledId }
                Timber.tag("LETHE_WS").d("Geplante Nachricht versendet: $scheduledId")
            }

            // Server sendet aktualisierte Poll-Ergebnisse nach einer Abstimmung
            "poll_update" -> {
                val pollId = (msg.payload as? Map<*, *>)?.get("poll_id") as? String ?: return
                val resultsRaw = (msg.payload as? Map<*, *>)?.get("results")
                val resultsJson = org.json.JSONArray(resultsRaw?.let {
                    com.google.gson.Gson().toJson(it)
                } ?: "[]").toString()
                pollDao.updateResults(pollId, resultsJson)
                // Wenn die angezeigte Poll betroffen ist, neu laden
                if (_currentPoll.value?.pollId == pollId) {
                    _currentPoll.value = pollDao.getPollById(pollId)
                }
                Timber.tag("LETHE_WS").d("Poll-Ergebnisse aktualisiert: $pollId")
            }

            "request_listen_together" -> {
                val p = msg.payload as? Map<*, *> ?: return
                val trackUrl    = p["track_url"]    as? String ?: return
                val trackTitle  = p["track_title"]  as? String ?: ""
                val trackArtist = p["track_artist"] as? String ?: ""
                val trackCover  = p["track_cover"]  as? String
                val trackDuration = (p["track_duration"] as? Number)?.toLong() ?: 0L
                val inviteChatId  = p["chat_id"] as? String ?: (msg.senderId ?: return)
                val ltSenderId = msg.senderId ?: return
                _listenTogetherInvite.value = ListenTogetherInvite(
                    fromUserId = ltSenderId,
                    chatId     = inviteChatId,
                    track      = ListenTogetherTrack(trackUrl, trackTitle, trackArtist, trackCover, trackDuration)
                )
                val ltContact = contactDao.getContactById(ltSenderId)
                val ltName = ltContact?.username ?: ltContact?.fakeNumber ?: ltSenderId
                if (!_onlyFcmMode.value) notificationHelper.showListenTogetherNotification(ltName, trackTitle)
                // Systemnachricht lokal in den Chat einfügen (für den Empfänger sichtbar)
                messageDao.insertMessage(
                    MessageEntity(
                        chatId     = ltSenderId,
                        senderId   = "lethe_system",
                        receiverId = _currentUser.value?.userId ?: "",
                        content    = "🎵 $ltName möchte Listen Together starten: $trackTitle",
                        mediaType  = "text",
                        timestamp  = System.currentTimeMillis(),
                        isRead     = true,
                        isSent     = true,
                        deliveryStatus = 3,
                        replyToSenderId = ltSenderId
                    )
                )
                Timber.tag("LETHE_LISTEN").d("Listen Together Einladung von $ltSenderId")
            }

            "music_sync_state" -> {
                if (!_listenTogetherActive.value) return
                val p = msg.payload as? Map<*, *> ?: return
                val isPlaying  = p["is_playing"]  as? Boolean ?: return
                val positionMs = (p["position_ms"] as? Number)?.toLong() ?: 0L
                val serverTs   = (p["server_ts"]   as? Number)?.toLong() ?: System.currentTimeMillis()
                val latencyMs  = (System.currentTimeMillis() - serverTs).coerceAtLeast(0L) / 2
                val adjustedPos = positionMs + latencyMs
                _listenTogetherIsPlaying.value = isPlaying
                _listenTogetherPosition.value  = adjustedPos
                Timber.tag("LETHE_LISTEN").d("Sync: playing=$isPlaying pos=${adjustedPos}ms")
            }

            "playlist_action" -> {
                if (!_listenTogetherActive.value) return
                val p = msg.payload as? Map<*, *> ?: return
                when (p["action"] as? String) {
                    "leave" -> {
                        _listenTogetherActive.value  = false
                        _listenTogetherChatId.value  = null
                        _listenTogetherTrack.value   = null
                        _isListenTogetherHost.value  = false
                        Timber.tag("LETHE_LISTEN").d("Partner hat Listen Together verlassen")
                    }
                    "next", "prev" -> {
                        // Host hat Track gewechselt – Gast übernimmt den neuen Track
                        val trackUrl = p["track_url"] as? String
                        if (trackUrl != null) {
                            val trackTitle    = p["track_title"]    as? String ?: ""
                            val trackArtist   = p["track_artist"]   as? String ?: ""
                            val trackCover    = p["track_cover"]    as? String
                            val trackDuration = (p["track_duration"] as? Number)?.toLong() ?: 0L
                            _listenTogetherTrack.value     = ListenTogetherTrack(trackUrl, trackTitle, trackArtist, trackCover, trackDuration)
                            _listenTogetherIsPlaying.value = false
                            _listenTogetherPosition.value  = 0L
                        }
                    }
                }
            }

            "accept_listen_together" -> {
                // Gast hat Einladung angenommen → Host aktiviert den Player
                if (!_listenTogetherWaiting.value) return
                _listenTogetherWaiting.value = false
                _listenTogetherActive.value  = true
                Timber.tag("LETHE_LISTEN").d("Listen Together akzeptiert von ${msg.senderId}")
            }

            "reject_listen_together" -> {
                // Gast hat Einladung abgelehnt → Host sieht Ablehnungs-Hinweis
                _listenTogetherWaiting.value = false
                _listenTogetherActive.value  = false
                _listenTogetherChatId.value  = null
                _listenTogetherTrack.value   = null
                _isListenTogetherHost.value  = false
                _listenTogetherRejected.value = true
                Timber.tag("LETHE_LISTEN").d("Listen Together abgelehnt von ${msg.senderId}")
            }

            "action_request" -> {
                // Partner fordert Wiedergabe-Aktion an
                if (!_listenTogetherActive.value) return
                val p = msg.payload as? Map<*, *> ?: return
                val action = p["action"] as? String ?: return
                val contact = contactDao.getContactById(msg.senderId ?: "")
                val senderName = contact?.customAlias?.takeIf { it.isNotBlank() } ?: contact?.username ?: contact?.fakeNumber ?: (msg.senderId ?: "Partner")
                _listenTogetherActionRequest.value = ListenTogetherActionRequest(senderName, action)
                Timber.tag("LETHE_LISTEN").d("Aktionsanfrage empfangen: $action von $senderName")
            }

            "action_confirm" -> {
                // Partner hat unsere Aktion bestätigt → ausführen
                if (!_listenTogetherActive.value) return
                val p = msg.payload as? Map<*, *> ?: return
                val action = p["action"] as? String ?: return
                _listenTogetherPendingAction.value = null
                when (action) {
                    "play"  -> {
                        _listenTogetherIsPlaying.value = true
                        syncListenTogetherState(true, _listenTogetherPosition.value)
                    }
                    "pause" -> {
                        _listenTogetherIsPlaying.value = false
                        syncListenTogetherState(false, _listenTogetherPosition.value)
                    }
                    "next"  -> sendPlaylistAction("next")
                    "prev"  -> sendPlaylistAction("prev")
                }
                Timber.tag("LETHE_LISTEN").d("Aktion bestätigt: $action")
            }

            "action_reject" -> {
                // Partner hat unsere Aktion abgelehnt
                _listenTogetherPendingAction.value = null
                _listenTogetherRejected.value = true
                Timber.tag("LETHE_LISTEN").d("Aktion abgelehnt von ${msg.senderId}")
            }

            "sync_shuffle_order" -> {
                // Partner hat die Playlist neu gemischt → lokale Reihenfolge anpassen
                val payload = msg.payload as? Map<*, *> ?: return
                @Suppress("UNCHECKED_CAST")
                val order = payload["order"] as? List<String> ?: return
                val current = _listenTogetherPlaylist.value
                val idToTrack = current.associateBy { it.url }
                // Nutze url als ID-Fallback wenn unique_id nicht vorhanden
                @Suppress("UNCHECKED_CAST")
                val idToTrackByUniqueId = current.associateBy {
                    (payload["tracks"] as? List<Map<*, *>>)
                        ?.find { t -> t["url"] == it.url }
                        ?.get("unique_id") as? String ?: it.url
                }
                val reordered = order.mapNotNull { uid ->
                    idToTrackByUniqueId[uid] ?: idToTrack[uid]
                }
                val seen = reordered.toSet()
                val remaining = current.filter { it !in seen }
                _listenTogetherPlaylist.value = reordered + remaining
                _listenTogetherShuffleActive.value = true
                Timber.tag("LETHE_LISTEN").d("Shuffle-Order vom Partner empfangen")
            }

            "dating_match" -> {
                _statusMessage.value = "Dating Match!"
                Timber.tag("LETHE_WS").d("Dating Match erhalten!")
            }

            "group_message" -> {
                // payload enthält content_blob, media_type, group_id, is_e2ee
                val payload = msg.payload as? Map<*, *> ?: return
                val groupId = payload["group_id"] as? String ?: return
                val senderId = msg.senderId ?: return
                val mediaType = payload["media_type"] as? String ?: "text"
                val rawContent = payload["content_blob"] as? String ?: ""
                val isE2ee = payload["is_e2ee"] as? Boolean == true

                // ── DEDUP-1: Server-Message-ID prüfen ─────────────────────────
                // Der Server legt `message_id` auf das Top-Level des WS-Events
                // (identisch zum `new_message`-Event). Falls diese ID bereits in
                // Room vorhanden ist, wurde die Nachricht schon verarbeitet → skip.
                val messageId = msg.messageId
                if (messageId != null) {
                    val existingById = messageDao.getMessageById(messageId)
                    if (existingById != null) {
                        Timber.tag("LETHE_WS").d(
                            "group_message bereits verarbeitet (serverId=$messageId) – überspringe"
                        )
                        return
                    }
                }

                // ── DEDUP-2: client_message_id prüfen ─────────────────────────
                // Wenn der Sender die Nachricht optimistisch in Room angelegt hat
                // (clientMessageId gesetzt), und der Server sie als group_message
                // zurückspiegelt, darf sie nicht erneut insertet werden.
                // Stattdessen nur den serverId (messageId) via ackMessage nachtragen.
                val clientMsgId = payload["client_message_id"] as? String
                if (clientMsgId != null) {
                    val existingByClientId = messageDao.getMessageByClientId(clientMsgId)
                    if (existingByClientId != null) {
                        Timber.tag("LETHE_WS").d(
                            "group_message via clientId bereits vorhanden ($clientMsgId) – nur ACK"
                        )
                        if (messageId != null && existingByClientId.messageId == null) {
                            messageDao.ackMessage(clientMsgId, messageId)
                        }
                        return
                    }
                }

                // ── E2EE entschlüsseln ────────────────────────────────────────
                val decryptedContent = if (isE2ee && mediaType == "text" && rawContent.startsWith("v2:")) {
                    decryptGroupContent(groupId, senderId, rawContent)
                } else {
                    rawContent
                }

                // ── Insert ────────────────────────────────────────────────────
                val grpScreenOnRaw = (context.getSystemService(android.content.Context.POWER_SERVICE)
                    as android.os.PowerManager).isInteractive
                // Xiaomi (MIUI/HyperOS): isInteractive kann bei gesperrtem Gerät true sein wenn FCM die App aufweckt.
                val grpScreenOn = if (android.os.Build.MANUFACTURER.equals("Xiaomi", ignoreCase = true)) {
                    val kg = context.getSystemService(android.content.Context.KEYGUARD_SERVICE) as android.app.KeyguardManager
                    grpScreenOnRaw && !kg.isKeyguardLocked
                } else {
                    grpScreenOnRaw
                }
                val isActiveGroup = groupId == _activeChatId.value && _isAppInForeground.value && grpScreenOn
                messageDao.insertMessage(MessageEntity(
                    messageId = messageId,   // Server-ID persistieren für zukünftige Dedup
                    chatId = groupId,
                    senderId = senderId,
                    receiverId = groupId,
                    content = decryptedContent,
                    mediaType = mediaType,
                    mediaUrl = (payload["media_url"] as? String)?.let { url ->
                        if (url.startsWith("[")) url else toAbsoluteUrl(url)
                    },
                    timestamp = (payload["sender_timestamp"] as? Number)?.toLong() ?: System.currentTimeMillis(),
                    isRead = isActiveGroup,
                    isEncrypted = isE2ee && mediaType == "text",
                    replyToContent = payload["reply_to_content"] as? String,
                    replyToSenderId = payload["reply_to_sender_id"] as? String,
                    replyToMessageId = payload["reply_to_message_id"] as? String
                ))

                // Termin-Nachricht: direkt laden damit die Karte sofort angezeigt wird
                if (mediaType == "appointment" || mediaType == "appointment_proposal") {
                    val appointmentId = try {
                        org.json.JSONObject(rawContent).getString("appointment_id")
                    } catch (_: Exception) { null }
                    if (appointmentId != null) loadAppointment(appointmentId)
                }
                // Badge-Zähler erhöhen wenn ContactListScreen nicht sichtbar ist
                if (!isActiveGroup && !_isContactListVisible.value) {
                    _chatBadgeCount.value++
                }

                // Benachrichtigung anzeigen wenn Gruppe nicht aktiv ist und kein FCM-Modus
                if (!isActiveGroup && !_onlyFcmMode.value) {
                    val alreadyNotifiedByFcm = messageId != null && FcmMessageBus.wasNotificationShownByFcm(messageId)
                    val alreadyNotifiedByDb = messageId != null && messageDao.isDeliveredAsNotification(messageId) == 1
                    val group = groupDao.getGroupById(groupId)
                    val groupName = group?.name ?: "Gruppe"
                    val senderContact = contactDao.getContactById(senderId)
                    val senderDisplayName = senderContact?.customAlias?.takeIf { it.isNotBlank() }
                        ?: senderContact?.username ?: senderContact?.fakeNumber ?: senderId
                    val grpPreview = when (mediaType) {
                        "image"    -> "$senderDisplayName: 📷 Bild"
                        "video"    -> "$senderDisplayName: 🎥 Video"
                        "audio"    -> "$senderDisplayName: 🎤 Sprachnachricht"
                        "poll"     -> "$senderDisplayName: 📊 Umfrage"
                        else -> {
                            val c = decryptedContent
                            if (c.startsWith("[🔐")) "$senderDisplayName: Neue Nachricht"
                            else "$senderDisplayName: ${c.take(400)}"
                        }
                    }
                    // FCM konnte den Text nicht entschlüsseln → WS soll die Notification updaten
                    val grpShouldUpdate = alreadyNotifiedByFcm && !alreadyNotifiedByDb
                        && !grpPreview.endsWith("Neue Nachricht")
                    val alreadyNotified = (alreadyNotifiedByFcm || alreadyNotifiedByDb) && !grpShouldUpdate
                    if (!alreadyNotified) {
                        val notifId = (groupId.hashCode() and 0x7FFFFFFF) + 5000
                        val senderProfileImg = senderContact?.profileImageUrl?.let { toAbsoluteUrl(it) }
                        notificationHelper.showMessageNotification(
                            senderId = groupId,
                            senderName = groupName,
                            senderImageUrl = group?.groupImageUrl?.let { toAbsoluteUrl(it) },
                            messagePreview = grpPreview,
                            notificationId = notifId,
                            isGroup = true,
                            senderDisplayName = senderDisplayName,
                            senderProfileUrl = senderProfileImg
                        )
                        // Erst NACH erfolgreicher Anzeige markieren (siehe 1:1-Pfad oben):
                        // verhindert dauerhaft unterdrückte FCM-Fallback-Notification bei Abbruch.
                        if (messageId != null) messageDao.markDeliveredAsNotification(messageId)
                    }
                }

                // ── READ-RECEIPT: Gruppen-Chat ist gerade geöffnet ──────────────
                if (isActiveGroup && !_userPrefs.value.readReceiptAfterReply && messageId != null) {
                    webSocketManager.sendMessage(
                        "read_receipt", groupId, mapOf("message_id" to messageId)
                    )
                    val inserted = messageDao.getMessageById(messageId)
                    if (inserted != null) {
                        messageDao.updateDeliveryStatus(inserted.localId, 3)
                    }
                    messageDao.markGroupMessagesRead(groupId, _currentUser.value?.userId ?: "")
                }

                Timber.tag("LETHE_WS").d(
                    "Gruppen-Nachricht gespeichert: $groupId (e2ee=$isE2ee, serverId=$messageId)"
                )
            }

            "group_updated" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val groupId = payload["group_id"] as? String ?: return
                val newName = payload["name"] as? String ?: return
                val newDescription = payload["description"] as? String
                val newImageUrl = (payload["group_image_url"] as? String)?.let { url ->
                    if (url.startsWith("http")) url else "https://letheapp.de$url"
                }
                viewModelScope.launch(Dispatchers.IO) {
                    val existing = groupDao.getGroupById(groupId)
                    if (existing != null) {
                        groupDao.insertGroup(existing.copy(
                            name = newName,
                            description = newDescription,
                            groupImageUrl = newImageUrl ?: existing.groupImageUrl
                        ))
                    }
                }
            }

            "group_key_rotation" -> {
                // Ein Mitglied hat die Gruppe verlassen oder wurde entfernt.
                // Perfect Forward Secrecy: alle lokalen Keys löschen und neue generieren.
                val payload = msg.payload as? Map<*, *>
                val groupId = (payload?.get("group_id") ?: (msg as? Map<*, *>)?.get("group_id")) as? String
                    ?: return
                val removedUserId = payload?.get("removed_user_id") as? String
                Timber.tag("LETHE_E2EE").d("Key-Rotation für Gruppe $groupId (entfernt: $removedUserId)")
                rotateGroupSenderKey(groupId)
            }

            "appointment_rsvp_update" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                handleAppointmentRsvpUpdate(payload)
            }

            "appointment_vote_update", "appointment_status_update" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                handleAppointmentUpdate(payload)
            }

            // Gruppen-Einladung: E2EE-Handshake durchführen, dann /ready melden
            "group_invite_pending" -> {
                val raw = msg.payload as? Map<*, *> ?: return
                val groupId = raw["group_id"] as? String ?: return
                val groupName = raw["name"] as? String ?: ""
                val createdBy = raw["created_by"] as? String ?: ""
                @Suppress("UNCHECKED_CAST")
                val members = raw["members"] as? List<Map<*, *>> ?: emptyList()
                Timber.tag("LETHE_E2EE").d("group_invite_pending empfangen: $groupName ($groupId)")
                viewModelScope.launch(Dispatchers.IO) {
                    val me = _currentUser.value ?: return@launch
                    // Shared Secrets für alle Mitglieder ableiten (auch Nicht-Kontakte)
                    for (memberMap in members) {
                        val memberId = memberMap["user_id"] as? String ?: continue
                        val publicKey = memberMap["public_key"] as? String ?: continue
                        if (memberId == me.userId) continue
                        if (publicKey.length > 100 && !com.securechat.app.data.crypto.CryptoManager.hasSharedSecret(memberId)) {
                            com.securechat.app.data.crypto.CryptoManager.deriveSharedSecret(memberId, publicKey)
                            Timber.tag("LETHE_E2EE").d("Shared Secret abgeleitet für $memberId")
                        }
                    }
                    // Sender-Key generieren und verteilen
                    generateAndDistributeGroupSenderKey(groupId)
                    // Server informieren dass dieser Client bereit ist
                    try {
                        val readyResponse = apiService.markGroupReady(groupId)
                        if (readyResponse.isSuccessful) {
                            Timber.tag("LETHE_E2EE").d("markGroupReady OK für $groupId")
                        } else {
                            Timber.tag("LETHE_E2EE").w("markGroupReady HTTP ${readyResponse.code()} für $groupId")
                        }
                    } catch (e: Exception) {
                        Timber.tag("LETHE_E2EE").e("markGroupReady Exception: ${e.message}")
                    }
                }
            }

            "group_created" -> {
                // Gruppe ist jetzt aktiv (alle Handshakes abgeschlossen)
                val raw = msg.payload as? Map<*, *>
                val groupId = (raw?.get("group_id") ?: (msg as? Map<*, *>)?.get("group_id")) as? String
                val groupName = (raw?.get("name") ?: raw?.get("group_name")) as? String
                val createdBy = (raw?.get("created_by")) as? String
                if (groupId != null && groupName != null) {
                    groupDao.insertGroup(GroupEntity(
                        groupId = groupId,
                        name = groupName,
                        createdBy = createdBy ?: "",
                        memberCount = 0,
                        createdAt = System.currentTimeMillis()
                    ))
                    Timber.tag("LETHE_WS").d("Gruppe aktiviert & eingefügt: $groupName ($groupId)")
                } else {
                    loadGroups()
                    Timber.tag("LETHE_WS").d("Neue Gruppe erhalten, Gruppen neu laden")
                }
            }

            // Tipp-Indikator: Gegenseite schreibt gerade
            "typing" -> {
                val senderId = msg.senderId ?: return
                val groupId = (msg.payload as? Map<*, *>)?.get("group_id") as? String
                Timber.tag("LETHE_WS").d("Typing-Event von $senderId (group=$groupId, activeChat=${_activeChatId.value})")

                if (groupId != null) {
                    // Gruppen-Tipp: nur in DIESER Gruppe anzeigen, nicht im 1:1-Chat des Senders
                    val current = _typingGroupMembers.value.toMutableMap()
                    current[groupId] = (current[groupId] ?: emptySet()) + senderId
                    _typingGroupMembers.value = current
                    val resetKey = "$groupId|$senderId"
                    typingGroupResetJobs[resetKey]?.cancel()
                    typingGroupResetJobs[resetKey] = viewModelScope.launch {
                        kotlinx.coroutines.delay(5000L)
                        val map = _typingGroupMembers.value.toMutableMap()
                        val remaining = (map[groupId] ?: emptySet()) - senderId
                        if (remaining.isEmpty()) map.remove(groupId) else map[groupId] = remaining
                        _typingGroupMembers.value = map
                    }
                } else {
                    // 1:1-Tipp: Kontaktlisten-Indikator (unabhängig vom aktiven Chat)
                    _typingContactIds.value = _typingContactIds.value + senderId
                    typingContactResetJobs[senderId]?.cancel()
                    typingContactResetJobs[senderId] = viewModelScope.launch {
                        kotlinx.coroutines.delay(5000L)
                        _typingContactIds.value = _typingContactIds.value - senderId
                    }

                    // Chat-TopBar-Indikator: nur wenn dieser 1:1-Chat gerade aktiv ist
                    if (senderId == _activeChatId.value) {
                        _partnerIsTyping.value = true
                        typingResetJob?.cancel()
                        typingResetJob = viewModelScope.launch {
                            kotlinx.coroutines.delay(5000L)
                            _partnerIsTyping.value = false
                        }
                    }
                }
            }

            // Nachricht wurde vom Absender bearbeitet
            "message_edited" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val messageId = payload["message_id"] as? String ?: return
                val newContent = payload["content"] as? String ?: return
                messageDao.editMessageByServerId(messageId, newContent)
                Timber.tag("LETHE_WS").d("Nachricht bearbeitet: $messageId")
            }

            // ─── WebRTC Call Signaling ─────────────────────────────────────────

            // Eingehender Anruf: SDP Offer empfangen → IncomingCallState setzen
            "call_offer" -> {
                val payload  = msg.payload as? Map<*, *> ?: return
                val sdp      = payload["sdp"] as? String ?: return
                val senderId = msg.senderId ?: return
                val callType = payload["call_type"] as? String ?: "VIDEO"

                // Renegotiation: bereits in aktivem Anruf mit diesem Sender → mid-call Offer
                // Auch RINGING abfangen: B hat gerade acceptCall() aufgerufen (ICE noch nicht verbunden)
                // und A schickt bereits eine Renegotiation (weitergeleitete Tracks). Ohne diesen Check
                // würde B das neue Offer fälschlich als Neuanruf interpretieren und erneut klingeln.
                if ((_callState.value == CallState.CONNECTED || _callState.value == CallState.RINGING)
                    && senderId == _activeCallPartnerId.value) {
                    webRtcClient?.setRemoteSdp("offer", sdp)
                    Timber.tag("LETHE_VIDEO").d("Mid-call renegotiation offer von $senderId → primärer Client (state=${_callState.value})")
                    return
                }
                val renegotiationClient = additionalWebRtcClients[senderId]
                if (renegotiationClient != null) {
                    renegotiationClient.setRemoteSdp("offer", sdp)
                    Timber.tag("LETHE_VIDEO").d("Mid-call renegotiation offer von $senderId → zusätzlicher Client")
                    return
                }

                val contact  = contactDao.getContactById(senderId)
                val callerName = contact?.username ?: contact?.fakeNumber ?: senderId
                val callerImage = contact?.profileImageUrl?.let { url ->
                    if (url.startsWith("http")) url else "https://letheapp.de$url"
                }
                // Gruppenanruf-Info (gesetzt von inviteToCall des Einladenden)
                val isGroupCall = payload["is_group_call"] as? Boolean ?: false
                val groupParticipants = (payload["group_participants"] as? List<*>)
                    ?.mapNotNull { item ->
                        val m = item as? Map<*, *> ?: return@mapNotNull null
                        val name = m["name"] as? String ?: return@mapNotNull null
                        val img = (m["image_url"] as? String)?.takeIf { it.isNotEmpty() }
                        name to img
                    } ?: emptyList()
                val groupId   = (payload["group_id"] as? String)?.takeIf { it.isNotEmpty() }
                val groupName = (payload["group_name"] as? String)?.takeIf { it.isNotEmpty() }
                _incomingCall.value = IncomingCallState(
                    callerId          = senderId,
                    callerName        = callerName,
                    callerImageUrl    = callerImage,
                    sdpOffer          = sdp,
                    callType          = callType,
                    isGroupCall       = isGroupCall,
                    groupParticipants = groupParticipants,
                    groupId           = groupId,
                    groupName         = groupName
                )
                // Anrufdaten im globalen Store sichern (für IncomingCallActivity / FCM-Pfad)
                IncomingCallStore.pendingCall = IncomingCallStore.PendingCall(
                    callerId          = senderId,
                    callerName        = callerName,
                    callerImageUrl    = callerImage,
                    sdpOffer          = sdp,
                    callType          = callType,
                    isGroupCall       = isGroupCall,
                    groupParticipants = groupParticipants,
                    groupId           = groupId,
                    groupName         = groupName
                )
                if (!_onlyFcmMode.value) notificationHelper.showIncomingCallNotification(callerName, callType)
                // Bildschirm gesperrt ODER App im Hintergrund → IncomingCallActivity starten.
                // So ist immer eine persistente Anruf-UI sichtbar, unabhängig davon ob
                // USE_FULL_SCREEN_INTENT gewährt wurde oder der Heads-Up-Banner weggeklickt wird.
                val kg = context.getSystemService(Context.KEYGUARD_SERVICE) as? KeyguardManager
                if (kg?.isKeyguardLocked == true || !_isAppInForeground.value) {
                    IncomingCallActivity.startFromBackground(context)
                }
                startRingtone()
                // 60s-Timeout: eingehender Anruf der nicht angenommen wird → automatisch ablehnen
                callTimeoutJob?.cancel()
                callTimeoutJob = viewModelScope.launch {
                    delay(60_000)
                    Timber.tag("LETHE_VIDEO").w("Eingehender Anruf-Timeout nach 60s")
                    val sid = _incomingCall.value?.callerId
                    if (sid != null) {
                        webSocketManager.sendMessage("call_end", sid, emptyMap<String, Any>())
                        stopRingtone()
                        _incomingCall.value = null
                        IncomingCallStore.clear()
                        notificationHelper.cancelCallNotification()
                        context.sendBroadcast(
                            android.content.Intent(IncomingCallActivity.ACTION_CALL_CANCELLED)
                                .setPackage(context.packageName)
                        )
                    }
                    callTimeoutJob = null
                }
                Timber.tag("LETHE_VIDEO").d("Incoming call_offer from $senderId")
            }

            // SDP Answer vom Gesprächspartner → im PeerConnection setzen
            "call_answer" -> {
                val payload  = msg.payload as? Map<*, *> ?: return
                val sdp      = payload["sdp"] as? String ?: return
                val senderId = msg.senderId
                // Prüfen ob die Antwort zu einem zusätzlichen Teilnehmer gehört
                val additionalClient = if (senderId != null) additionalWebRtcClients[senderId] else null
                if (additionalClient != null) {
                    additionalClient.setRemoteSdp("answer", sdp)
                    Timber.tag("LETHE_VIDEO").d("call_answer for additional participant $senderId")
                } else {
                    // Angerufener hat angenommen → 60s-Timeout auf Anruferseite stoppen
                    callTimeoutJob?.cancel()
                    callTimeoutJob = null
                    webRtcClient?.setRemoteSdp("answer", sdp)
                    Timber.tag("LETHE_VIDEO").d("call_answer received")
                }
            }

            // ICE Candidate vom Gesprächspartner → in PeerConnection einfügen
            // Falls webRtcClient noch nicht existiert (Angerufener hat noch nicht angenommen), puffern
            "ice_candidate" -> {
                val payload        = msg.payload as? Map<*, *> ?: return
                val sdpMid         = payload["sdp_mid"] as? String ?: return
                val sdpMLineIndex  = (payload["sdp_m_line_index"] as? Number)?.toInt() ?: return
                val candidate      = payload["candidate"] as? String ?: return
                val senderId       = msg.senderId
                // Zuerst prüfen ob ICE-Kandidat zu zusätzlichem Teilnehmer gehört
                val additionalClient = if (senderId != null) additionalWebRtcClients[senderId] else null
                if (additionalClient != null) {
                    additionalClient.addRemoteIceCandidate(sdpMid, sdpMLineIndex, candidate)
                    Timber.tag("LETHE_VIDEO").d("ICE candidate for additional participant $senderId")
                } else {
                    val client = webRtcClient
                    if (client != null) {
                        client.addRemoteIceCandidate(sdpMid, sdpMLineIndex, candidate)
                        Timber.tag("LETHE_VIDEO").d("ICE candidate received and added")
                    } else {
                        pendingRemoteIceCandidates.add(Triple(sdpMid, sdpMLineIndex, candidate))
                        Timber.tag("LETHE_VIDEO").d("ICE candidate buffered (webRtcClient not ready yet), total=${pendingRemoteIceCandidates.size}")
                    }
                }
            }

            // ─── WebRTC DataChannel P2P Chat Signaling ────────────────────────────

            // Eingehender P2P-DataChannel-Offer → PeerConnection aufbauen und Answer senden
            "webrtc_dc_offer" -> {
                val payload  = msg.payload as? Map<*, *> ?: return
                val sdp      = payload["sdp"] as? String ?: return
                val senderId = msg.senderId ?: return
                if (!_userPrefs.value.p2pInternetEnabled) {
                    // Wir haben P2P deaktiviert → Offer ablehnen und Partner informieren
                    webSocketManager.sendMessage("webrtc_dc_declined", senderId, emptyMap<String, String>())
                    Timber.tag("LETHE_P2P_DC").d("P2P deaktiviert, webrtc_dc_declined an $senderId gesendet")
                    return
                }
                if (senderId in _userPrefs.value.p2pDisabledContacts) {
                    // P2P für diesen Kontakt lokal deaktiviert → Offer ablehnen
                    webSocketManager.sendMessage("webrtc_dc_declined", senderId, emptyMap<String, String>())
                    Timber.tag("LETHE_P2P_DC").d("P2P für Kontakt $senderId deaktiviert, webrtc_dc_declined gesendet")
                    return
                }
                // Partner hatte evtl. früher disabled gemeldet → jetzt connected er sich → Flag löschen
                _p2pPartnerDisabled.value = _p2pPartnerDisabled.value - senderId
                viewModelScope.launch {
                    var turnUsername = ""
                    var turnPassword = ""
                    try {
                        val resp = apiService.getTurnCredentials()
                        if (resp.isSuccessful) {
                            resp.body()?.let { turnUsername = it.username; turnPassword = it.password }
                        }
                    } catch (_: Exception) { /* Fallback: STUN only */ }
                    webRTCDataChannelManager.handleRemoteOffer(senderId, sdp, turnUsername, turnPassword)
                    Timber.tag("LETHE_P2P_DC").d("webrtc_dc_offer from $senderId handled")
                }
            }

            // Partner hat P2P deaktiviert (sendet uns dies aktiv beim Chat-Öffnen)
            "webrtc_dc_disabled" -> {
                val senderId = msg.senderId ?: return
                _p2pPartnerDisabled.value = _p2pPartnerDisabled.value + (senderId to true)
                Timber.tag("LETHE_P2P_DC").d("Partner $senderId hat P2P deaktiviert")
            }

            // Partner hat unseren Offer abgelehnt (sein P2P ist deaktiviert)
            "webrtc_dc_declined" -> {
                val senderId = msg.senderId ?: return
                _p2pPartnerDisabled.value = _p2pPartnerDisabled.value + (senderId to true)
                Timber.tag("LETHE_P2P_DC").d("Partner $senderId hat P2P-Offer abgelehnt (P2P deaktiviert)")
            }

            // Eingehender P2P-DataChannel-Answer → RemoteDescription setzen
            "webrtc_dc_answer" -> {
                val payload  = msg.payload as? Map<*, *> ?: return
                val sdp      = payload["sdp"] as? String ?: return
                val senderId = msg.senderId ?: return
                webRTCDataChannelManager.handleRemoteAnswer(senderId, sdp)
                Timber.tag("LETHE_P2P_DC").d("webrtc_dc_answer from $senderId handled")
            }

            // Eingehender P2P ICE-Kandidat → PeerConnection einfügen
            "webrtc_dc_ice" -> {
                val payload       = msg.payload as? Map<*, *> ?: return
                val sdpMid        = payload["sdp_mid"] as? String ?: return
                val sdpMLineIndex = (payload["sdp_m_line_index"] as? Number)?.toInt() ?: return
                val candidate     = payload["candidate"] as? String ?: return
                val senderId      = msg.senderId ?: return
                webRTCDataChannelManager.addRemoteIceCandidate(senderId, sdpMid, sdpMLineIndex, candidate)
                Timber.tag("LETHE_P2P_DC").d("webrtc_dc_ice from $senderId added")
            }

            // Anruf beendet (von Gegenseite) → Ressourcen freigeben
            "call_end" -> {
                val senderId       = msg.senderId
                val callPartnerId  = _activeCallPartnerId.value
                val incomingCallerId = _incomingCall.value?.callerId
                val incomingCallType = _incomingCall.value?.callType ?: "VOICE"

                // Prüfen ob ein zusätzlicher Teilnehmer den Anruf verlässt
                if (senderId != null && additionalWebRtcClients.containsKey(senderId)) {
                    val ac = additionalWebRtcClients.remove(senderId)
                    val updated = _additionalParticipants.value.toMutableMap()
                    updated.remove(senderId)
                    _additionalParticipants.value = updated
                    inviteTimeoutJobs.remove(senderId)?.cancel()
                    releaseRingback(senderId)   // Freizeichen für diesen Teilnehmer freigeben (abbricht/ablehnt)
                    ac?.dispose()
                    Timber.tag("LETHE_VIDEO").d("Zusätzlicher Teilnehmer $senderId hat call_end gesendet – entfernt")
                    return
                }

                // Sicherheitscheck: call_end nur vom aktiven Gesprächspartner oder eingehenden Anrufer akzeptieren.
                // Stale Re-Deliveries bei WS-Reconnect oder Nachrichten fremder User beenden NICHT den aktiven Anruf.
                if (senderId != null && callPartnerId == null && incomingCallerId == null) {
                    Timber.tag("LETHE_VIDEO").d("call_end von $senderId ignoriert – kein aktiver Anruf")
                    return
                }
                if (senderId != null && callPartnerId != null
                    && senderId != callPartnerId && senderId != incomingCallerId) {
                    Timber.tag("LETHE_VIDEO").w("call_end von $senderId ignoriert – aktiver Partner: $callPartnerId")
                    return
                }

                // Merken ob wir gerade als Anrufer im Freizeichen-Zustand waren (= Gegenseite lehnt ab)
                val wasWaiting = _callState.value == CallState.CALLING
                    || _callState.value == CallState.RINGING
                stopRingtone()        // Falls Anrufer auflegt bevor wir annehmen (callee-Seite)
                stopAllRingback()     // Freizeichen vollständig stoppen (caller-Seite)
                // Empfänger-Seite: Anrufer hat aufgelegt während es klingelte (nie angenommen)
                // → "Keine Antwort"-Bubble mit Zurückrufen-Link. Die Anrufer-Bubble erzeugt cleanupCall().
                if (incomingCallerId != null) {
                    insertCallNoAnswerLog(incomingCallerId, incomingCallType, isOutgoing = false)
                    callNoAnswerLogged = true   // nachfolgendes cleanupCall soll keine Anrufer-Bubble erzeugen
                }
                _incomingCall.value = null
                IncomingCallStore.clear()
                notificationHelper.cancelCallNotification()
                context.sendBroadcast(
                    android.content.Intent(IncomingCallActivity.ACTION_CALL_CANCELLED)
                        .setPackage(context.packageName)
                )
                cleanupCall()
                if (wasWaiting) playHangupSound()  // Auflegesound wenn Anruf abgelehnt wurde
                _statusMessage.value = "Anruf beendet"
                Timber.tag("LETHE_VIDEO").d("call_end von $senderId – Anruf beendet (wasWaiting=$wasWaiting)")
            }

            // Bandbreiteninfo vom Gesprächspartner
            "video_capable" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val userId  = payload["user_id"] as? String ?: msg.senderId ?: return
                val capable = payload["capable"] as? Boolean ?: false
                val updated = _partnerVideoCapable.value.toMutableMap()
                updated[userId] = capable
                _partnerVideoCapable.value = updated
                Timber.tag("LETHE_VIDEO").d("Partner $userId videoCapable → $capable")
            }

            // Empfänger ist besetzt (bereits in einem Anruf) oder Glare-Auflösung (wir sind Verlierer)
            "call_busy" -> {
                val payload      = msg.payload as? Map<*, *>
                val reason       = payload?.get("reason") as? String
                val busySenderId = msg.senderId
                // Bei Gruppenanrufen: Wenn nur ein zusätzlicher Teilnehmer besetzt ist,
                // nur diesen aus dem Anruf entfernen – nicht den ganzen Call beenden.
                if (busySenderId != null && additionalWebRtcClients.containsKey(busySenderId)) {
                    val busyClient = additionalWebRtcClients.remove(busySenderId)
                    val updated = _additionalParticipants.value.toMutableMap()
                    updated.remove(busySenderId)
                    _additionalParticipants.value = updated
                    inviteTimeoutJobs.remove(busySenderId)?.cancel()
                    releaseRingback(busySenderId)   // Freizeichen für besetzten Teilnehmer freigeben
                    busyClient?.dispose()
                    Timber.tag("LETHE_VIDEO").w("call_busy für Gruppen-Teilnehmer $busySenderId (reason=$reason) – nur dieser entfernt")
                    return
                }
                val message = if (reason == "glare") "Gleichzeitiger Anruf – bitte erneut versuchen"
                              else "Teilnehmer spricht gerade"
                stopAllRingback()
                _callStatusMessage.value = message
                cleanupCall()
                Timber.tag("LETHE_VIDEO").d("call_busy empfangen – reason=$reason")
            }

            // Empfänger ist nicht mit dem WebSocket verbunden (App im Hintergrund/offline)
            "call_not_reachable" -> {
                val nrPayload   = msg.payload as? Map<*, *>
                val isGroupInvite = nrPayload?.get("is_group_invite") as? Boolean ?: false
                val targetId      = nrPayload?.get("target_id") as? String

                if (isGroupInvite && _activeCallPartnerId.value != null && targetId != null) {
                    // Nur den fehlgeschlagenen Eingeladenen entfernen – primärer Anruf bleibt bestehen
                    val failedClient = additionalWebRtcClients.remove(targetId)
                    val upd = _additionalParticipants.value.toMutableMap()
                    upd.remove(targetId)
                    _additionalParticipants.value = upd
                    inviteTimeoutJobs.remove(targetId)?.cancel()
                    failedClient?.dispose()
                    releaseRingback(targetId)
                    _statusMessage.value = "Teilnehmer nicht erreichbar"
                    Timber.tag("LETHE_VIDEO").d("call_not_reachable für Gruppen-Einladung an $targetId – primärer Anruf bleibt")
                    return
                }
                // Einmaliger Retry: Der Server hat den Empfänger gerade per FCM geweckt; dessen
                // WS-Route ist nach längerer Hintergrund-Phase oft erst Sekundenbruchteile später
                // wieder da. Statt sofort aufzulegen senden wir das Offer EINMAL erneut.
                val retryPayload = lastCallOfferPayload
                val retryPartner = lastCallOfferPartner
                if (!callRetryAttempted && retryPayload != null && retryPartner != null &&
                    webRtcClient != null && _activeCallPartnerId.value == retryPartner) {
                    callRetryAttempted = true
                    _callStatusMessage.value = "Verbinde …"
                    Timber.tag("LETHE_VIDEO").d("call_not_reachable – starte einmaligen Retry an $retryPartner")
                    callRetryJob?.cancel()
                    callRetryJob = viewModelScope.launch {
                        // WS sicherstellen + dem Empfänger Zeit geben, nach FCM-Wakeup zu reconnecten
                        if (!webSocketManager.isConnected()) connectWebSocketAndListen()
                        delay(2_500)
                        // Abbruch falls inzwischen verbunden/aufgelegt
                        if (webRtcClient == null || _activeCallPartnerId.value != retryPartner) return@launch
                        webSocketManager.sendMessage("call_offer", retryPartner, retryPayload)
                        Timber.tag("LETHE_VIDEO").d("Retry call_offer an $retryPartner gesendet")
                    }
                    return
                }
                stopAllRingback()
                _callStatusMessage.value = "Teilnehmer nicht erreichbar"
                // Auch wenn der Anruf nicht zugestellt werden konnte: einen Hinweis im Chat
                // mit der Person hinterlassen, damit der Empfänger den Anrufversuch sieht.
                val failedCallPartner = _activeCallPartnerId.value ?: lastCallOfferPartner
                if (failedCallPartner != null) {
                    recordMissedCallAttempt(failedCallPartner, _activeCallType.value)
                    lastCallOfferPartner = null   // verhindert doppelten Hinweis bei Folge-Events
                }
                callNoAnswerLogged = true   // Offline-Fall hat eigenen Text-Hinweis → keine zusätzliche Bubble
                cleanupCall()
                Timber.tag("LETHE_VIDEO").d("call_not_reachable – Empfänger offline (kein Retry mehr)")
            }

            // Bestehender Teilnehmer wird benachrichtigt dass ein neuer Teilnehmer eingeladen wurde
            "group_participant_invited" -> {
                val payload   = msg.payload as? Map<*, *> ?: return
                val invUserId = payload["user_id"] as? String ?: return
                val invName   = payload["name"] as? String ?: invUserId
                val invImage  = (payload["image_url"] as? String)?.takeIf { it.isNotEmpty() }
                // Eigene ID und direkten Gesprächspartner nicht als zusätzlichen Teilnehmer hinzufügen
                val skipId = invUserId == _activeCallPartnerId.value || invUserId == _currentUser.value?.userId
                if (!skipId && !_additionalParticipants.value.containsKey(invUserId)) {
                    val upd = _additionalParticipants.value.toMutableMap()
                    upd[invUserId] = CallParticipant(invUserId, null, invName, invImage)
                    _additionalParticipants.value = upd
                }
                requestRingback(invUserId)   // B hört Freizeichen während C klingelt
                Timber.tag("LETHE_VIDEO").d("group_participant_invited: $invUserId ($invName) wird eingeladen")
            }

            // Bestehender Teilnehmer wird benachrichtigt dass der Eingeladene angenommen hat
            "group_participant_joined" -> {
                val payload   = msg.payload as? Map<*, *> ?: return
                val joinUserId = payload["user_id"] as? String ?: return
                releaseRingback(joinUserId)   // Freizeichen für diesen Teilnehmer freigeben – hat angenommen
                Timber.tag("LETHE_VIDEO").d("group_participant_joined: $joinUserId ist beigetreten")
            }

            // Emoji-Reaktion während eines laufenden Anrufs vom Partner empfangen
            "call_emoji" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val emojiName = payload["emoji"] as? String ?: return
                _incomingCallEmoji.value = emojiName
                // Nach 5 Sekunden automatisch zurücksetzen
                viewModelScope.launch {
                    kotlinx.coroutines.delay(5_000)
                    if (_incomingCallEmoji.value == emojiName) _incomingCallEmoji.value = null
                }
                Timber.tag("LETHE_VIDEO").d("call_emoji empfangen: $emojiName")
            }

            // Partner hat die Aufzeichnung gestartet/gestoppt → blinkenden REC-Hinweis + eigenen WHIP
            "call_recording" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val recording = payload["recording"] as? Boolean ?: false
                _partnerCallRecording.value = recording
                if (recording) {
                    val recId = payload["recording_id"] as? String
                    val partnerPath = payload["partner_path"] as? String
                    val whipBase = payload["whip_base"] as? String
                    if (recId != null && partnerPath != null && whipBase != null) {
                        startPartnerRequestedRecording(recId, partnerPath, whipBase)
                    }
                } else {
                    stopPartnerRequestedRecording()
                }
                Timber.tag("LETHE_VIDEO").d("call_recording empfangen: $recording von ${msg.senderId}")
            }

            // Partner bittet um Einwilligung zur Aufzeichnung → Zustimmungs-Dialog anzeigen
            "call_recording_request" -> {
                val from = msg.senderId ?: return
                // Nur akzeptieren, wenn es der aktive Gesprächspartner ist
                if (from == _activeCallPartnerId.value) {
                    _incomingRecordingConsentFrom.value = from
                }
                Timber.tag("LETHE_VIDEO").d("call_recording_request von $from")
            }

            // Partner hat auf unsere Einwilligungs-Anfrage geantwortet
            "call_recording_response" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val accepted = payload["accepted"] as? Boolean ?: false
                val allowDownload = payload["allow_download"] as? Boolean ?: false
                _recordingConsentPending.value = false
                if (accepted) {
                    startServerRecording(allowDownload)
                } else {
                    showCallToast("Partner hat die Aufzeichnung abgelehnt")
                }
                Timber.tag("LETHE_VIDEO").d("call_recording_response: accepted=$accepted allow=$allowDownload")
            }

            // ─── Emoji-Reaktion ────────────────────────────────────────────────

            // Emoji-Reaktion auf eine Nachricht vom Chat-Partner empfangen
            "reaction" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val messageId = payload["message_id"] as? String ?: return
                val emoji = payload["emoji"] as? String
                // Für Gruppen-Nachrichten kommt die vollständige JSON-Map mit
                val reactionsJson = payload["reactions_json"] as? String
                val senderId = msg.senderId ?: return
                val reactionValue = reactionsJson ?: emoji
                val updated = messageDao.setReactionByServerId(messageId, reactionValue)
                if (updated == 0) {
                    // Nachricht nicht in Room-Cache → Server-Sync als Fallback
                    loadMessages(senderId)
                }
                // Benachrichtigung an den Nachrichten-Ersteller (auch ohne FCM), wenn jemand
                // auf eine EIGENE 1:1-Nachricht neu reagiert hat (nicht beim Entfernen/eigenem Mirror).
                val myUid = _currentUser.value?.userId
                if (reactionsJson == null && !emoji.isNullOrBlank() && senderId != myUid && !_onlyFcmMode.value) {
                    val reacted = messageDao.getMessageById(messageId)
                    if (reacted != null && reacted.senderId == myUid) {
                        val reactorContact = contactDao.getContactById(senderId)
                        val reactorName = (if (reactorContact?.isAnonymous == true) {
                            reactorContact.fakeNumber
                        } else {
                            reactorContact?.username?.takeIf { it.isNotBlank() }
                                ?: reactorContact?.fakeNumber
                        }) ?: "Jemand"
                        val target = when (reacted.mediaType) {
                            "image" -> "dein Bild"
                            "video" -> "dein Video"
                            "audio" -> "deine Sprachnachricht"
                            "poll"  -> "deine Umfrage"
                            else    -> "deine Nachricht"
                        }
                        notificationHelper.showReactionNotification(reactorName, emoji, senderId, target)
                    }
                }
                Timber.tag("LETHE_WS").d("Reaktion empfangen: $emoji auf $messageId (updated=$updated)")
            }

            // Eine Nachricht wurde vom Sender für alle gelöscht (1:1 oder Gruppe) oder auf einem
            // anderen eigenen Gerät gelöscht → lokal entfernen, damit sie überall verschwindet.
            "message_deleted" -> {
                val payload = msg.payload as? Map<*, *>
                val messageId = payload?.get("message_id") as? String ?: msg.messageId ?: return
                messageDao.deleteMessageByServerId(messageId)
                Timber.tag("LETHE_WS").d("Nachricht gelöscht (Sync): $messageId")
            }

            // Eine Nachricht wurde vom Sender bearbeitet (1:1 oder Gruppe) oder auf einem anderen
            // eigenen Gerät bearbeitet → lokalen Inhalt aktualisieren und als bearbeitet markieren.
            "message_edited" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val messageId = payload["message_id"] as? String ?: return
                val newContent = payload["content"] as? String ?: return
                messageDao.editMessageByServerId(messageId, newContent)
                Timber.tag("LETHE_WS").d("Nachricht bearbeitet (Sync): $messageId")
            }

            // Lumis-Animations-Event: vom Chat-Partner gesendet
            "lumis" -> {
                val payload       = msg.payload as? Map<*, *> ?: return
                val senderId      = msg.senderId ?: return
                val lumisTypeName = payload["lumis_type"] as? String ?: return

                val lumisType = try {
                    com.securechat.app.ui.screens.LumisType.valueOf(lumisTypeName)
                } catch (e: IllegalArgumentException) {
                    Timber.tag("LETHE_WS").w("Unbekannter LumisType empfangen: $lumisTypeName")
                    return
                }

                // Systemnachricht im Chat des Absenders einfügen
                val senderContact = contactDao.getContactById(senderId)
                val senderLabel = if (senderContact?.isAnonymous == true) {
                    senderContact.fakeNumber
                } else {
                    senderContact?.username?.takeIf { it.isNotBlank() }
                        ?: senderContact?.fakeNumber
                        ?: senderId
                }
                val displayName = lumisTypeDisplayName(lumisType)
                messageDao.insertMessage(
                    MessageEntity(
                        chatId         = senderId,
                        senderId       = "system",
                        receiverId     = _currentUser.value?.userId ?: "",
                        content        = "$senderLabel hat ein \"$displayName\" Lumis gesendet",
                        mediaType      = "system",
                        timestamp      = System.currentTimeMillis(),
                        isRead         = true,
                        deliveryStatus = 3
                    )
                )

                val isScreenOn = (context.getSystemService(android.content.Context.POWER_SERVICE)
                    as android.os.PowerManager).isInteractive

                if (senderId == _activeChatId.value && _isAppInForeground.value && isScreenOn) {
                    // Beide Chatpartner sind gerade im selben Chat → sofort abspielen
                    _activeLumis.value = lumisType
                    Timber.tag("LETHE_WS").d("Lumis sofort abgespielt: $lumisTypeName von $senderId")
                } else {
                    // Chat ist gerade nicht geöffnet → persistent speichern, beim nächsten Öffnen abspielen
                    savePendingLumis(senderId, lumisType)
                    Timber.tag("LETHE_WS").d("Lumis als ausstehend gespeichert: $lumisTypeName für $senderId")
                }
            }

            "group_lumis" -> {
                // Lumis-Animation in einer Gruppe empfangen
                val payload = msg.payload as? Map<*, *> ?: return
                val lumisTypeName = payload["lumis_type"] as? String ?: return
                val groupId = payload["group_id"] as? String ?: return
                val groupSenderId = msg.senderId
                val lumisType = try {
                    com.securechat.app.ui.screens.LumisType.valueOf(lumisTypeName)
                } catch (e: IllegalArgumentException) {
                    Timber.tag("LETHE_WS").w("Unbekannter GroupLumisType: $lumisTypeName")
                    return
                }

                // Systemnachricht in der Gruppe einfügen (nur für Empfänger, nicht für Absender – der hat sie schon lokal)
                if (groupSenderId != null && groupSenderId != _currentUser.value?.userId) {
                    val senderContact = contactDao.getContactById(groupSenderId)
                    val senderLabel = senderContact?.username?.takeIf { it.isNotBlank() }
                        ?: senderContact?.fakeNumber
                        ?: groupSenderId
                    val displayName = lumisTypeDisplayName(lumisType)
                    messageDao.insertMessage(
                        MessageEntity(
                            chatId         = groupId,
                            senderId       = "system",
                            receiverId     = groupId,
                            content        = "$senderLabel hat ein \"$displayName\" Lumis gesendet",
                            mediaType      = "system",
                            timestamp      = System.currentTimeMillis(),
                            isRead         = true,
                            deliveryStatus = 3
                        )
                    )
                }

                if (groupId == _activeChatId.value && _isAppInForeground.value) {
                    _activeLumis.value = lumisType
                    Timber.tag("LETHE_WS").d("Group-Lumis sofort abgespielt: $lumisTypeName in $groupId")
                } else {
                    savePendingLumis(groupId, lumisType)
                    Timber.tag("LETHE_WS").d("Group-Lumis ausstehend gespeichert: $lumisTypeName für $groupId")
                }
            }

            "animation_state_update" -> {
                // Admin hat Animations-Zustand geändert → sofort anzeigen/entfernen
                val payload = msg.payload as? Map<*, *> ?: return
                val animation = payload["animation"] as? String ?: return
                _contactListAnimation.value = animation
                Timber.tag("LETHE_WS").d("Animation-State-Update empfangen: $animation")
            }

            "global_lumis" -> {
                // Admin-Broadcast: Lumis für alle Nutzer → in Kontaktliste abspielen
                val payload = msg.payload as? Map<*, *> ?: return
                val lumisTypeName = payload["lumis_type"] as? String ?: return
                try {
                    val lumisType = com.securechat.app.ui.screens.LumisType.valueOf(lumisTypeName)
                    // Persistent speichern damit es nach Neustart noch abgespielt wird
                    lumisPrefs.edit().putString("global_lumis", lumisTypeName).apply()
                    _globalLumis.value = lumisType
                    Timber.tag("LETHE_WS").d("Admin-Global-Lumis empfangen: $lumisTypeName")
                } catch (_: IllegalArgumentException) {
                    Timber.tag("LETHE_WS").w("Unbekannter GlobalLumisType: $lumisTypeName")
                }
            }

            "location_update" -> {
                val payload   = msg.payload as? Map<*, *> ?: return
                val senderId  = msg.senderId ?: return
                val lat = (payload["lat"] as? Number)?.toDouble() ?: return
                val lng = (payload["lng"] as? Number)?.toDouble() ?: return
                _liveLocationPins.value = _liveLocationPins.value + (senderId to LiveLocationPin(senderId, lat, lng))
            }

            // Jemand hat uns in Nearby geliked
            "nearby_like" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val like = NearbyLikeIncoming(
                    id = payload["like_id"] as? String ?: return,
                    likerId = payload["liker_id"] as? String ?: return,
                    username = payload["username"] as? String ?: "Unbekannt",
                    nearbyImageUrl = payload["nearby_image_url"] as? String,
                    age = (payload["age"] as? Number)?.toInt() ?: 0,
                    gender = payload["gender"] as? String ?: "",
                    createdAt = ""
                )
                if (_incomingLikes.value.none { it.id == like.id }) {
                    _incomingLikes.value = listOf(like) + _incomingLikes.value
                    _nearbyBadgeCount.value = _nearbyBadgeCount.value + 1
                }
                Timber.tag("LETHE_WS").d("Nearby-Like empfangen von: ${like.username}")
            }

            // Jemand hat unseren Status geliked
            "status_liked" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val likerUsername = payload["liker_username"] as? String ?: "Jemand"
                if (!_onlyFcmMode.value) notificationHelper.showStatusLikedNotification(likerUsername)
                Timber.tag("LETHE_WS").d("Status geliked von: $likerUsername")
            }

            // Ein Kontakt hat einen neuen Status veröffentlicht (auch ohne FCM)
            "new_status" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val senderName = payload["sender_name"] as? String ?: "Jemand"
                if (!_onlyFcmMode.value) notificationHelper.showNewStatusNotification(senderName)
                Timber.tag("LETHE_WS").d("Neuer Status von: $senderName")
            }

            // Neues Support-Ticket (nur an Admins/Moderatoren gesendet). Wird hier behandelt,
            // damit die Benachrichtigung auch bei geöffneter App (aktives ViewModel) erscheint –
            // der NotificationHandler-Service überspringt WS-Nachrichten dann bewusst.
            "new_support_ticket" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val ticketId = payload["ticket_id"] as? String ?: return
                val category = payload["category"] as? String ?: ""
                val title = payload["title"] as? String ?: "Neues Ticket"
                if (!_onlyFcmMode.value) notificationHelper.showNewSupportTicketNotification(category, title, ticketId)
                Timber.tag("LETHE_WS").d("Neues Support-Ticket: [$category] $title")
            }

            // Ein gegenseitiges Match wurde erstellt
            "nearby_match" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val match = NearbyMatch(
                    id = payload["match_id"] as? String ?: return,
                    partnerId = payload["partner_id"] as? String ?: return,
                    partnerUsername = payload["partner_username"] as? String ?: "Unbekannt",
                    partnerImageUrl = payload["partner_image_url"] as? String,
                    lastMessage = null,
                    lastMessageAt = null,
                    createdAt = ""
                )
                if (_nearbyMatches.value.none { it.id == match.id }) {
                    _nearbyMatches.value = listOf(match) + _nearbyMatches.value
                }
                Timber.tag("LETHE_WS").d("Nearby-Match empfangen: ${match.partnerUsername}")
            }

            // Neue Nachricht im Nearby-Chat
            "nearby_message" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val newMsg = NearbyMessage(
                    id = payload["id"] as? String ?: return,
                    matchId = payload["match_id"] as? String ?: return,
                    senderId = payload["sender_id"] as? String ?: return,
                    content = payload["content"] as? String,
                    mediaUrl = (payload["media_url"] as? String)?.let { toAbsoluteUrl(it) },
                    previewUrl = (payload["preview_url"] as? String)?.let { toAbsoluteUrl(it) },
                    mediaType = payload["media_type"] as? String ?: "text",
                    viewMode = payload["view_mode"] as? String ?: "permanent",
                    viewCount = (payload["view_count"] as? Number)?.toInt() ?: 0,
                    createdAt = payload["created_at"] as? String ?: ""
                )
                if (newMsg.matchId == _activeMatchId.value) {
                    if (_nearbyMessages.value.none { it.id == newMsg.id }) {
                        _nearbyMessages.value = _nearbyMessages.value + newMsg
                    }
                }
                // lastMessage in der Match-Liste lokal aktualisieren
                val msgPreviewForList = newMsg.content?.takeIf { it.isNotBlank() }
                    ?: "[${newMsg.mediaType}]"
                _nearbyMatches.value = _nearbyMatches.value.map { m ->
                    if (m.id == newMsg.matchId)
                        m.copy(lastMessage = msgPreviewForList, lastMessageAt = newMsg.createdAt)
                    else m
                }
                // Unread-Indikator setzen (wenn Match nicht gerade geöffnet)
                if (newMsg.matchId != _activeNearbyMatchId.value) {
                    val current = _unreadNearbyMatchIds.value.toMutableSet()
                    current.add(newMsg.matchId)
                    _unreadNearbyMatchIds.value = current
                    _hasUnreadNearbyMessages.value = true
                    _nearbyBadgeCount.value = _nearbyBadgeCount.value + 1
                }

                // Benachrichtigung für neue Nearby-Nachricht (nur wenn Match nicht gerade offen)
                val myUid = _currentUser.value?.userId ?: ""
                if (newMsg.senderId != myUid) {
                    val isScreenOn = (context.getSystemService(android.content.Context.POWER_SERVICE)
                        as android.os.PowerManager).isInteractive
                    val effectiveScreenOnNearby = if (android.os.Build.MANUFACTURER.equals("Xiaomi", ignoreCase = true)) {
                        val kg = context.getSystemService(android.content.Context.KEYGUARD_SERVICE) as android.app.KeyguardManager
                        isScreenOn && !kg.isKeyguardLocked
                    } else {
                        isScreenOn
                    }
                    val isMatchOpen = newMsg.matchId == _activeMatchId.value
                        && _isAppInForeground.value && effectiveScreenOnNearby
                    if (!isMatchOpen) {
                        val matchObj = _nearbyMatches.value.find { it.id == newMsg.matchId }
                        val partnerName = matchObj?.partnerUsername ?: "Lethe Dating"
                        val partnerImg = matchObj?.partnerImageUrl?.let {
                            if (it.startsWith("http")) it else "https://letheapp.de$it"
                        }
                        val msgPreview = newMsg.content?.takeIf { it.isNotBlank() }
                            ?: "[${newMsg.mediaType}]"
                        val notifId = NotificationHelper.NOTIFICATION_ID_MESSAGE_BASE + newMsg.matchId.hashCode()
                        if (!_onlyFcmMode.value) viewModelScope.launch {
                            notificationHelper.showMessageNotification(
                                senderId = newMsg.senderId,
                                senderName = partnerName,
                                senderImageUrl = partnerImg,
                                messagePreview = msgPreview,
                                notificationId = notifId,
                                channelId = NotificationHelper.CHANNEL_ID_DATING
                            )
                        }
                    }
                }
                Timber.tag("LETHE_WS").d("Nearby-Nachricht empfangen im Match: ${newMsg.matchId}")
            }

            // Partner möchte sich als Lethe-Kontakt hinzufügen
            "nearby_lethe_invite" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val matchId = payload["match_id"] as? String ?: return
                val fromUsername = payload["from_username"] as? String ?: "Unbekannt"
                val fromUserId = payload["from_user_id"] as? String ?: return
                // Match-Objekt für den Dialog aufbauen
                val match = _nearbyMatches.value.find { it.id == matchId }
                    ?: NearbyMatch(
                        id = matchId,
                        partnerId = fromUserId,
                        partnerUsername = fromUsername,
                        partnerImageUrl = null,
                        lastMessage = null,
                        lastMessageAt = null,
                        createdAt = ""
                    )
                _pendingLetheInvite.value = match
                Timber.tag("LETHE_WS").d("Nearby-Lethe-Einladung empfangen von: $fromUsername")
            }

            "nearby_reaction" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val emoji = payload["emoji"] as? String ?: return
                if (!_onlyFcmMode.value) notificationHelper.showNearbyQuestionReactionNotification(emoji)
            }

            "key_sync_request" -> {
                // WebChat fordert Key-Sync an → Android antwortet mit verschlüsseltem Public Key
                val payload = msg.payload as? Map<*, *> ?: return
                val webSessionPub = payload["web_session_pub"] as? String
                if (webSessionPub.isNullOrBlank()) {
                    Timber.tag("LETHE_KEY_SYNC").w("key_sync_request: web_session_pub fehlt")
                    return
                }
                val user = _currentUser.value
                if (user == null) {
                    Timber.tag("LETHE_KEY_SYNC").w("key_sync_request: kein User eingeloggt")
                    return
                }
                viewModelScope.launch(Dispatchers.IO) {
                    try {
                        // Eigenen Android-Public-Key holen
                        val ownAndroidPub = CryptoManager.ensureKeyPair(context, user.privateKey)
                        // Eigenen UMK mitschicken (Base64), damit der WebChat v3-Nachrichten
                        // (Conversation Key) entschlüsseln kann – der WebChat hat kein Passwort
                        // um den serverseitigen umk_v1-Backup selbst zu entschlüsseln.
                        val umkBase64 = CryptoManager.exportUmkBase64()
                        // Alle Gruppen-Sender-Keys (eigener + die aller Mitglieder) für den WebChat
                        // einpacken. Der Browser besitzt nur einen ephemeren ECDH-Key und kann die an
                        // die Android-Identität adressierten Sender-Key-Bundles nicht selbst
                        // entschlüsseln – das Handy liefert die Klartext-Keys über diesen bereits
                        // Ende-zu-Ende-verschlüsselten Key-Sync-Kanal mit. Struktur:
                        // {"<groupId>":{"<ownerId>":"<keyBase64>", …}, …}
                        val groupKeysJson = try {
                            val allKeys = groupSenderKeyDao.getAllKeys()
                            if (allKeys.isEmpty()) {
                                null
                            } else {
                                val root = com.google.gson.JsonObject()
                                for ((gid, keys) in allKeys.groupBy { it.groupId }) {
                                    val inner = com.google.gson.JsonObject()
                                    for (k in keys) inner.addProperty(k.ownerId, k.keyBase64)
                                    root.add(gid, inner)
                                }
                                root.toString()
                            }
                        } catch (e: Exception) {
                            Timber.tag("LETHE_KEY_SYNC").w("Gruppen-Keys für Sync nicht ladbar: ${e.message}")
                            null
                        }
                        // Alle bekannten Partner-UMKs mitschicken, damit der WebChat die
                        // Conversation Keys (v3) für ALLE Kontakte direkt ableiten kann – ohne
                        // dass der jeweilige Partner online sein und einen Live-UMK-Exchange
                        // beantworten muss. Sonst bleibt die 1:1-Historie (eigene + empfangene
                        // v3-Nachrichten) von offline-Kontakten im WebChat unentschlüsselbar.
                        // Struktur: {"<partnerId>":"<umkBase64>", …}
                        val partnerUmksJson = try {
                            val partnerUmks = CryptoManager.exportPartnerUmks()
                            if (partnerUmks.isEmpty()) null
                            else com.google.gson.JsonObject().apply {
                                for ((pid, b64) in partnerUmks) addProperty(pid, b64)
                            }.toString()
                        } catch (e: Exception) {
                            Timber.tag("LETHE_KEY_SYNC").w("Partner-UMKs für Sync nicht ladbar: ${e.message}")
                            null
                        }
                        // Payload mit ephemerem ECDH(android_priv, web_session_pub) verschlüsseln
                        val encryptedPayload = CryptoManager.encryptKeySyncPayload(webSessionPub, ownAndroidPub, umkBase64, groupKeysJson, partnerUmksJson)
                        if (encryptedPayload == null) {
                            Timber.tag("LETHE_KEY_SYNC").e("encryptKeySyncPayload fehlgeschlagen")
                            return@launch
                        }
                        // Antwort ans Backend senden → Backend leitet weiter an WebChat
                        webSocketManager.sendRaw(mapOf(
                            "type" to "key_sync_response",
                            "receiver_id" to user.userId,
                            "payload" to mapOf(
                                "encrypted_sync_key" to encryptedPayload,
                                "android_pub" to ownAndroidPub
                            )
                        ))
                        Timber.tag("LETHE_KEY_SYNC").i("key_sync_response gesendet an WebChat")
                    } catch (e: Exception) {
                        Timber.tag("LETHE_KEY_SYNC").e("key_sync_response Fehler: ${e.message}")
                    }
                }
            }

            // Phase 4: Partner schickt seinen UMK (ECDH-verschlüsselt) → Conversation Key ableiten
            "umk_exchange" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val senderId = msg.senderId ?: (payload["sender_id"] as? String) ?: return
                val encUmk = payload["encrypted_umk"] as? String ?: return
                viewModelScope.launch(Dispatchers.IO) {
                    val partnerUmkBytes = decryptPartnerUmk(encUmk, senderId)
                    if (partnerUmkBytes != null) {
                        val ok = CryptoManager.registerPartnerUmk(senderId, partnerUmkBytes)
                        if (ok) {
                            saveConversationKeysToPrefs()
                            savePartnerUmksToPrefs()
                            Timber.tag("LETHE_UMK").i("umk_exchange: Partner-UMK von $senderId empfangen, Conversation Key abgeleitet")
                            sendUmkExchangeResponse(senderId)
                            reencryptLegacyMessages(senderId)
                        }
                    }
                }
            }

            // Phase 4: Antwort auf eigenen UMK-Exchange → Conversation Key mit Partner ableiten
            "umk_exchange_response" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val senderId = msg.senderId ?: (payload["sender_id"] as? String) ?: return
                val encUmk = payload["encrypted_umk"] as? String ?: return
                viewModelScope.launch(Dispatchers.IO) {
                    val partnerUmkBytes = decryptPartnerUmk(encUmk, senderId)
                    if (partnerUmkBytes != null) {
                        val ok = CryptoManager.registerPartnerUmk(senderId, partnerUmkBytes)
                        if (ok) {
                            saveConversationKeysToPrefs()
                            savePartnerUmksToPrefs()
                            Timber.tag("LETHE_UMK").i("umk_exchange_response: Partner-UMK von $senderId empfangen")
                            reencryptLegacyMessages(senderId)
                        }
                    }
                }
            }

            // EPIC 5: Kontakt hat einen neuen Web-ECDH-Key registriert → Web-Secret sofort neu ableiten.
            // Force-Rederive: bei Key-Rotation (neuer Browser-Tab, gelöschtes IndexedDB) muss der
            // veraltete Cache-Eintrag ersetzt werden, damit web_content_blob korrekt verschlüsselt wird.
            "web_key_updated" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val userId = payload["user_id"] as? String ?: return
                val newWebKey = payload["web_public_key"] as? String ?: return
                if (newWebKey.length > 80) {
                    viewModelScope.launch(Dispatchers.IO) {
                        CryptoManager.forceRederiveWebSharedSecret(userId, newWebKey)
                        Timber.tag("LETHE_E2EE").i("web_key_updated: Web-Secret für $userId force-rederived.")
                    }
                }
            }

            // Gerätewechsel: Kontakt hat seinen ECDH-Key rotiert → Shared Secret neu ableiten
            "key_rotated" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val userId = payload["user_id"] as? String ?: return
                val newPublicKey = payload["new_public_key"] as? String ?: return
                viewModelScope.launch(Dispatchers.IO) {
                    // Kontakt-Eintrag in Room immer aktualisieren (auch bei Legacy-Keys)
                    val existing = contactDao.getContactById(userId)
                    if (existing != null && existing.publicKey != newPublicKey) {
                        contactDao.updateContact(existing.copy(publicKey = newPublicKey))
                    }
                    // Altes Shared Secret immer leeren (verhindert Entschlüsselung mit veraltetem Key)
                    CryptoManager.clearSecretForContact(userId)
                    if (newPublicKey.length > 100) {
                        // Echte ECDH P-384 Key: Shared Secret neu ableiten
                        val ok = CryptoManager.forceRederiveSharedSecret(userId, newPublicKey)
                        Timber.tag("LETHE_E2EE").i("key_rotated: Shared-Secret für $userId neu abgeleitet (ok=$ok).")
                    } else {
                        // Legacy/SHA-256-Key: Cache geleert, Nachrichten bleiben verschlüsselt bis Handshake-Erneuerung
                        Timber.tag("LETHE_E2EE").w("key_rotated: Ungültiger ECDH-Key für $userId (length=${newPublicKey.length}) – Cache geleert, kein Secret ableitbar.")
                    }
                }
            }

            // ── Sketch 'n' Check: globale Lobby-Events ─────────────────────────
            "sknch_game_opened" -> {
                val payload = msg.payload as? Map<*, *>
                val creatorUsername = payload?.get("creator_username") as? String ?: "Jemand"
                val playersRequired = (payload?.get("players_required") as? Number)?.toInt() ?: 4
                _sknChOpenGamesCount.value = _sknChOpenGamesCount.value + 1
                val myUsername = _currentUser.value?.name ?: ""
                if (creatorUsername != myUsername && !_onlyFcmMode.value) {
                    notificationHelper.showSknChGameOpenedNotification(creatorUsername, playersRequired)
                }
            }

            "sknch_game_closed" -> {
                _sknChOpenGamesCount.value = maxOf(0, _sknChOpenGamesCount.value - 1)
            }

            // ── Spiel-Nachrichten ───────────────────────────────────────────────
            "game_invite", "game_accept", "game_decline", "game_cancel",
            "game_char_select", "game_level_select", "game_ready", "game_state", "game_end",
            "game_sky_fall", "play_again",
            "ttt_move", "ttt_end", "ttt_rematch",
            "activity_word_chosen", "activity_draw_partial", "activity_draw_stroke",
            "activity_draw_clear", "activity_guess", "activity_correct", "activity_end",
            "sknch_pre_start", "sknch_word_options", "sknch_word_chosen",
            "sknch_draw_partial", "sknch_draw_stroke", "sknch_draw_clear", "sknch_draw_undo",
            "sknch_guess", "sknch_correct", "sknch_round_end", "sknch_next_round",
            "sknch_player_left",
            "tnd_player_practicing", "tnd_player_ready", "tnd_start_game", "tnd_final_score",
            "tnd_angle", "tnd_ball" -> {
                if (msg.type == "game_invite") {
                    val payload = msg.payload as? Map<*, *>
                    val fromName = payload?.get("from_name") as? String ?: "Unbekannt"
                    val gameType = payload?.get("game_type") as? String ?: "JUMP_AND_RUN"
                    val senderId = msg.senderId
                    if (senderId != null) {
                        _pendingGameInvite.value = PendingGameInvite(senderId, fromName, gameType)
                        if (!_onlyFcmMode.value) notificationHelper.showGameInviteNotification(fromName)
                        // Systemnachricht in den Chat des Empfängers einfügen
                        val gameDisplayName = when (gameType) {
                            "ACTIVITY"    -> "Zeichnen & Raten"
                            "TIC_TAC_TOE" -> "Tic Tac Toe"
                            "TILT_N_DROP" -> "Neon Tilt 'n' Drop"
                            else          -> "JUMP and Run"
                        }
                        val myId = _currentUser.value?.userId ?: ""
                        viewModelScope.launch(Dispatchers.IO) {
                            messageDao.insertMessage(
                                MessageEntity(
                                    chatId          = senderId,
                                    senderId        = "lethe_system",
                                    receiverId      = myId,
                                    content         = "🎮 $fromName hat dich zu \"$gameDisplayName\" eingeladen",
                                    mediaType       = "text",
                                    timestamp       = System.currentTimeMillis(),
                                    isRead          = true,
                                    isSent          = false,
                                    deliveryStatus  = 3,
                                    replyToSenderId = senderId
                                )
                            )
                        }
                    }
                }
                viewModelScope.launch { _incomingGameEvent.emit(msg) }
                Timber.tag("LETHE_GAME").d("Game-Event empfangen: ${msg.type} von ${msg.senderId}")
            }

            // ── Lethe Family: Eltern haben Permissions für diesen Kind-Account geändert ──
            "permissions_updated" -> {
                val payload = msg.payload as? Map<*, *> ?: run {
                    // Fallback: Nachricht selbst ist das Payload (Server sendet flaches JSON)
                    Timber.tag("LETHE_FAMILY").w("permissions_updated: payload leer, übersprungen")
                    return
                }
                val relationId = _familyStatus.value?.parent?.relationId ?: ""
                val childId = _currentUser.value?.userId ?: ""
                val updated = com.securechat.app.data.network.ChildPermissionsResponse(
                    relationId = relationId,
                    childId = childId,
                    canVideoCall = payload["can_video_call"] as? Boolean ?: true,
                    canAudioCall = payload["can_audio_call"] as? Boolean ?: true,
                    canSendMedia = payload["can_send_media"] as? Boolean ?: true,
                    canViewSparks = payload["can_view_sparks"] as? Boolean ?: true,
                    canUseNearby = payload["can_use_nearby"] as? Boolean ?: false,
                    canPlayGames = payload["can_play_games"] as? Boolean ?: true,
                    allowedGameMinutesPerDay = (payload["allowed_game_minutes_per_day"] as? Double)?.toInt()
                        ?: (payload["allowed_game_minutes_per_day"] as? Int) ?: 0,
                    gameTimeStart = payload["game_time_start"] as? String,
                    gameTimeEnd = payload["game_time_end"] as? String,
                    contactWhitelist = payload["contact_whitelist"] as? String
                )
                _myChildPermissions.value = updated
                Timber.tag("LETHE_FAMILY").i(
                    "permissions_updated: video=${updated.canVideoCall}, " +
                    "audio=${updated.canAudioCall}, media=${updated.canSendMedia}, " +
                    "sparks=${updated.canViewSparks}, nearby=${updated.canUseNearby}, " +
                    "games=${updated.canPlayGames}"
                )
            }

            // ── Lethe Family: Kind-Account hat Einladung akzeptiert (Push an Parent) ──
            "family_child_joined" -> {
                val payload = msg.payload as? Map<*, *> ?: return
                val childName = payload["child_name"] as? String ?: "Unbekannt"
                Timber.tag("LETHE_FAMILY").i("family_child_joined: $childName hat die Einladung angenommen")
                // Family-Status neu laden damit Kinder-Liste aktuell ist
                loadFamilyStatus()
            }

            "audio_listened", "audio_all_listened" -> {
                // Sender empfängt: Empfänger hat Sprachnachricht vollständig gehört
                // Bei Gruppen: alle Mitglieder haben gehört (audio_all_listened)
                val payload = msg.payload as? Map<*, *> ?: return
                val listenedMsgId = payload["message_id"] as? String ?: return
                viewModelScope.launch {
                    messageDao.markAudioPlayedByMessageId(listenedMsgId)
                    Timber.tag("LETHE_AUDIO").d("${msg.type}: messageId=$listenedMsgId als abgespielt markiert")
                }
            }

            else -> {
                Timber.tag("LETHE_WS").d("Unbekannter Nachrichtentyp: ${msg.type}")
            }
        }
    }

    /** Prüft ob ein globaler Lumis-Broadcast ausstehend ist (nach App-Neustart). */
    fun checkPendingGlobalLumis() {
        val saved = lumisPrefs.getString("global_lumis", null) ?: return
        try {
            _globalLumis.value = com.securechat.app.ui.screens.LumisType.valueOf(saved)
        } catch (_: IllegalArgumentException) {
            lumisPrefs.edit().remove("global_lumis").apply()
        }
    }

    // --- CHAT & STATUS ---

    fun getMessagesForChat(chatId: String): Flow<List<MessageEntity>> {
        return getDisplayLimitFlow(chatId)
            .flatMapLatest { limit ->
                // Room lädt nur die neuesten `limit` Zeilen – nie alle Nachrichten auf einmal.
                messageDao.getMessagesForChat(chatId, limit)
            }
            .distinctUntilChanged()
    }

    fun getLastMessageForChat(chatId: String): Flow<MessageEntity?> {
        return messageDao.getLastMessageForChat(chatId)
    }

    fun loadGroups() {
        viewModelScope.launch {
            try {
                val response = apiService.getGroups()
                if (response.isSuccessful) {
                    response.body()?.forEach { g ->
                        groupDao.insertGroup(GroupEntity(
                            groupId = g.id, name = g.name, createdBy = g.createdBy,
                            memberCount = g.memberCount,
                            createdAt = System.currentTimeMillis(),
                            groupImageUrl = g.groupImageUrl?.let { url ->
                                if (url.startsWith("http")) url else "https://letheapp.de$url"
                            },
                            description = g.description
                        ))
                    }
                }
            } catch (e: Exception) { Timber.tag("Groups").e("loadGroups failed", e) }
        }
    }

    fun createGroup(name: String, memberIds: List<String>) {
        viewModelScope.launch {
            try {
                val response = apiService.createGroup(GroupCreateRequest(name, memberIds))
                if (response.isSuccessful) {
                    // Gruppe ist zunächst "pending" – E2EE-Handshake läuft via group_invite_pending WS-Event.
                    // Die Gruppe erscheint erst in der Liste wenn group_created empfangen wird.
                    _statusMessage.value = "Gruppe '$name' wird eingerichtet…"
                } else {
                    _statusMessage.value = "Fehler beim Erstellen der Gruppe."
                }
            } catch (e: Exception) {
                _statusMessage.value = "Netzwerkfehler: ${e.message}"
            }
        }
    }

    fun sendGroupMessage(groupId: String, content: String,
        replyToContent: String? = null, replyToSenderId: String? = null,
        replyToMediaType: String? = null, mediaType: String = "text",
        replyToMessageId: String? = null) {
        viewModelScope.launch {
            val me = _currentUser.value ?: return@launch
            val clientId = UUID.randomUUID().toString()

            // E2EE: Nur Text-Nachrichten verschlüsseln (keine Slash-Commands, keine strukturierten Typen).
            // Slash-Commands beginnen mit "/" → der Server muss sie im Klartext erkennen.
            // Poll/Appointment/Appointment_proposal enthalten strukturierte JSON-Daten, die der Client parst.
            val shouldEncrypt = mediaType == "text" && !content.startsWith("/")
            val encryptedContent: String
            val isEncrypted: Boolean

            if (shouldEncrypt) {
                val senderKeyEntity = withContext(Dispatchers.IO) {
                    groupSenderKeyDao.getKey(groupId, me.userId)
                        ?: run {
                            // Kein Key vorhanden → jetzt generieren und sofort für diese Nachricht nutzen
                            generateAndDistributeGroupSenderKey(groupId)
                            groupSenderKeyDao.getKey(groupId, me.userId)
                        }
                }
                if (senderKeyEntity != null) {
                    val rawKey = android.util.Base64.decode(senderKeyEntity.keyBase64, android.util.Base64.NO_WRAP)
                    encryptedContent = CryptoManager.encryptGroupMessage(rawKey, content)
                    isEncrypted = true
                } else {
                    // Fallback: Klartext senden wenn Key-Generierung fehlschlug
                    Timber.tag("LETHE_E2EE").w("Kein Sender-Key für $groupId – sende Klartext als Fallback")
                    encryptedContent = content
                    isEncrypted = false
                }
            } else {
                encryptedContent = content
                isEncrypted = false
            }

            val sendTimestamp = System.currentTimeMillis()
            val payload = buildMap<String, Any?> {
                put("content_blob", encryptedContent)
                put("media_type", mediaType)
                put("group_id", groupId)
                put("client_message_id", clientId)
                put("is_e2ee", isEncrypted)
                put("sender_timestamp", sendTimestamp)
                if (replyToContent != null) put("reply_to_content", replyToContent)
                if (replyToSenderId != null) put("reply_to_sender_id", replyToSenderId)
                if (replyToMediaType != null) put("reply_to_media_type", replyToMediaType)
                if (replyToMessageId != null) put("reply_to_message_id", replyToMessageId)
            }

            // Lokal speichern: immer den Klartext (nicht den Ciphertext)
            messageDao.insertMessage(MessageEntity(
                chatId = groupId, senderId = me.userId, receiverId = groupId,
                content = content,       // Klartext für lokale Anzeige
                mediaType = mediaType,
                timestamp = sendTimestamp,
                clientMessageId = clientId,
                isEncrypted = isEncrypted,
                replyToContent = replyToContent, replyToSenderId = replyToSenderId,
                replyToMediaType = replyToMediaType,
                replyToMessageId = replyToMessageId
            ))
            webSocketManager.sendMessage("group_message", groupId, payload)
        }
    }

    /**
     * Ermittelt den Anzeigenamen (Dateiname) einer URI, soweit verfügbar.
     * Für content://-URIs via DISPLAY_NAME, sonst über das letzte Pfadsegment.
     */
    private fun displayNameOfUri(uri: Uri): String? = when (uri.scheme) {
        "content" -> try {
            context.contentResolver.query(
                uri, arrayOf(android.provider.OpenableColumns.DISPLAY_NAME), null, null, null
            )?.use { c -> if (c.moveToFirst()) c.getString(0) else null }
        } catch (_: Exception) { null }
        else -> uri.lastPathSegment
    }

    /**
     * Von Lethe selbst erzeugte Videos (Ausgabe des Video-Editors
     * "chat_video_edit_…", in die Galerie gespeicherte "Lethe_…") sind bereits
     * final komprimiert und dürfen beim Senden NICHT erneut transkodiert werden.
     */
    private fun isLetheCreatedVideo(uri: Uri): Boolean {
        val name = displayNameOfUri(uri)?.lowercase() ?: return false
        return name.startsWith("chat_video_edit") || name.startsWith("lethe_")
    }

    /**
     * Bereitet ein Video für den Upload vor. Von Lethe erzeugte Videos
     * (Editor-Ausgabe) sind bereits komprimiert und werden – sofern sie
     * innerhalb des Upload-Limits liegen – ohne erneute Kompression direkt
     * hochgeladen. Fremd-Videos ODER zu große Lethe-Videos werden auf H.264
     * heruntertranskodiert, damit sie das 80-MB-Limit nicht überschreiten
     * (sonst würde die Datei-zu-groß-Prüfung die Nachricht kommentarlos löschen).
     */
    private suspend fun prepareVideoForUpload(uri: Uri, clientId: String): File {
        if (isLetheCreatedVideo(uri)) {
            val direct = uriToFile(uri, "video")
            if (direct != null && direct.length() in 1..MAX_UPLOAD_BYTES) return direct
            direct?.delete()
        }
        val outFile = File(context.cacheDir, "tc_${clientId}.mp4")
        val success = com.securechat.app.data.local.VideoTranscoder.transcode(
            context = context, inputUri = uri, outputFile = outFile
        )
        return if (success && outFile.exists() && outFile.length() > 0) {
            outFile
        } else {
            outFile.delete()
            uriToFile(uri, "video") ?: throw Exception("Datei nicht lesbar")
        }
    }

    fun sendGroupMediaMessage(groupId: String, uri: Uri, mediaType: String) {
        viewModelScope.launch {
            _isLoading.value = true
            val me = _currentUser.value ?: return@launch
            val clientId = UUID.randomUUID().toString()

            if (mediaType == "video") {
                messageDao.insertMessage(
                    MessageEntity(
                        chatId = groupId, senderId = me.userId, receiverId = groupId,
                        content = "[video]", mediaType = "video", mediaUrl = null,
                        timestamp = System.currentTimeMillis(),
                        isSent = false, clientMessageId = clientId, deliveryStatus = 0
                    )
                )
                _videoUploadProgress.update { it + (clientId to -1f) }
            } else if (mediaType == "audio_music") {
                // Sofort Placeholder in DB einfügen (wie bei sendMediaMessage)
                messageDao.insertMessage(
                    MessageEntity(
                        chatId = groupId, senderId = me.userId, receiverId = groupId,
                        content = "[audio_music]", mediaType = "audio_music", mediaUrl = null,
                        timestamp = System.currentTimeMillis(),
                        isSent = false, clientMessageId = clientId, deliveryStatus = 0
                    )
                )
                _uploadProgress.value = 0f
            }

            try {
                val fileToUpload: File
                val mimeType: String
                var originalFileName: String? = null
                if (mediaType == "video") {
                    // Von Lethe erstellte Videos (Editor-Ausgabe) sind bereits
                    // komprimiert → direkt hochladen (Passthrough), zu große
                    // Editor-Videos werden dennoch heruntertranskodiert.
                    fileToUpload = prepareVideoForUpload(uri, clientId)
                    mimeType = "video/mp4"
                    _videoUploadProgress.update { it + (clientId to 0f) }
                } else if (mediaType == "audio_music") {
                    // Originalen Dateinamen beibehalten damit ID3-Tags serverseitig korrekt sind
                    val displayName = context.contentResolver.query(
                        uri, arrayOf(android.provider.OpenableColumns.DISPLAY_NAME), null, null, null
                    )?.use { c -> if (c.moveToFirst()) c.getString(0) else null }
                        ?: "audio_${System.currentTimeMillis()}.mp3"
                    originalFileName = displayName
                    val ext = displayName.substringAfterLast('.', "mp3").lowercase()
                    val cacheFile = File(context.cacheDir, "music_${System.currentTimeMillis()}.$ext")
                    withContext(Dispatchers.IO) {
                        context.contentResolver.openInputStream(uri)?.use { input ->
                            java.io.FileOutputStream(cacheFile).use { out -> input.copyTo(out) }
                        }
                    }
                    fileToUpload = cacheFile
                    mimeType = "audio/*"
                } else {
                    val rawFile = uriToFile(uri, mediaType) ?: throw Exception("Datei nicht lesbar")
                    fileToUpload = if (mediaType == "image") fixImageOrientation(rawFile) else rawFile
                    mimeType = when (mediaType) {
                        "image" -> "image/*"
                        "audio" -> "audio/*"
                        else -> "*/*"
                    }
                }

                // Sprachnachricht in Gruppen: bei aktivem Toggle mit dem eigenen Sender-Key
                // verschlüsseln (bei Bedarf generieren+verteilen). Kein Key → stiller Fallback
                // auf unverschlüsselten Versand.
                var effectiveMediaType = mediaType
                if (mediaType == "audio" && _userPrefs.value.mediaEncryptionEnabled) {
                    val keyEntity = groupSenderKeyDao.getKey(groupId, me.userId) ?: run {
                        generateAndDistributeGroupSenderKey(groupId)
                        groupSenderKeyDao.getKey(groupId, me.userId)
                    }
                    if (keyEntity != null) {
                        val rawKey = android.util.Base64.decode(keyEntity.keyBase64, android.util.Base64.NO_WRAP)
                        val encrypted = com.securechat.app.data.crypto.CryptoManager
                            .encryptBytesWithSenderKey(rawKey, fileToUpload.readBytes())
                        withContext(Dispatchers.IO) { fileToUpload.writeBytes(encrypted) }
                        effectiveMediaType = "audio_e2ee"
                    }
                }

                if (fileToUpload.length() > MAX_UPLOAD_BYTES) {
                    if (mediaType == "video") {
                        messageDao.deleteMessageByClientId(clientId)
                        _videoUploadProgress.update { it - clientId }
                    } else if (mediaType == "audio_music") {
                        messageDao.deleteMessageByClientId(clientId)
                        _uploadProgress.value = -1f
                        _mediaUploadStatus.value = MediaUploadStatus.Idle
                    }
                    _statusMessage.value = "Datei zu groß (max. 80 MB)"
                    _isLoading.value = false
                    return@launch
                }

                val rawRequest = fileToUpload.asRequestBody(mimeType.toMediaTypeOrNull())
                val requestFile = when (mediaType) {
                    "video" -> ProgressRequestBody(
                        delegate = rawRequest,
                        onProgress = { sent, total ->
                            if (total > 0) {
                                val pct = (sent * 100f / total).coerceIn(0f, 99f)
                                _videoUploadProgress.update { it + (clientId to pct) }
                            }
                        }
                    )
                    "audio_music" -> ProgressRequestBody(
                        delegate = rawRequest,
                        onProgress = { sent, total ->
                            if (total > 0) {
                                val pct = (sent.toFloat() / total * 100).toInt().coerceIn(0, 99)
                                _uploadProgress.value = sent.toFloat() / total
                                _mediaUploadStatus.value = MediaUploadStatus.Uploading(pct)
                            }
                        }
                    )
                    else -> rawRequest
                }

                val body = MultipartBody.Part.createFormData("file", originalFileName ?: fileToUpload.name, requestFile)
                val uploadType = if (mediaType == "circle_video") "video" else effectiveMediaType
                val typeBody = uploadType.toRequestBody("text/plain".toMediaTypeOrNull())
                val response = apiService.uploadMedia(typeBody, body)

                if (mediaType == "video" || mediaType == "audio_music") {
                    withContext(Dispatchers.IO) { fileToUpload.delete() }
                }

                if (response.isSuccessful) {
                    val mediaUrl = response.body()?.get("url")?.let { toAbsoluteUrl(it) }
                    if (mediaUrl != null) {
                        val label = "[$mediaType]"
                        if (mediaType == "video") {
                            messageDao.updateMessageUrl(clientId, mediaUrl)
                            _videoUploadProgress.update { it - clientId }
                        } else if (mediaType == "audio_music") {
                            messageDao.updateMessageUrl(clientId, mediaUrl)
                            _uploadProgress.value = -1f
                            _mediaUploadStatus.value = MediaUploadStatus.Idle
                        } else {
                            messageDao.insertMessage(
                                MessageEntity(
                                    chatId = groupId, senderId = me.userId, receiverId = groupId,
                                    content = label, mediaType = effectiveMediaType, mediaUrl = mediaUrl,
                                    timestamp = System.currentTimeMillis(),
                                    isSent = false, clientMessageId = clientId, deliveryStatus = 0
                                )
                            )
                        }
                        webSocketManager.sendMessage("group_message", groupId, mapOf(
                            "content_blob" to label,
                            "media_type" to effectiveMediaType,
                            "media_url" to mediaUrl,
                            "group_id" to groupId,
                            "client_message_id" to clientId,
                            "sender_timestamp" to System.currentTimeMillis()
                        ))
                    }
                } else {
                    if (mediaType == "video") {
                        messageDao.deleteMessageByClientId(clientId)
                        _videoUploadProgress.update { it - clientId }
                    } else if (mediaType == "audio_music") {
                        messageDao.deleteMessageByClientId(clientId)
                        _uploadProgress.value = -1f
                        _mediaUploadStatus.value = MediaUploadStatus.Idle
                    }
                    _statusMessage.value = "Upload fehlgeschlagen (${response.code()})"
                }
            } catch (e: Exception) {
                if (mediaType == "video") {
                    messageDao.deleteMessageByClientId(clientId)
                    _videoUploadProgress.update { it - clientId }
                } else if (mediaType == "audio_music") {
                    messageDao.deleteMessageByClientId(clientId)
                    _uploadProgress.value = -1f
                    _mediaUploadStatus.value = MediaUploadStatus.Idle
                }
                _statusMessage.value = "Upload fehlgeschlagen: ${e.message}"
                Timber.tag("Chat").e("sendGroupMediaMessage failed", e)
            } finally {
                _isLoading.value = false
            }
        }
    }

    /**
     * Lädt die Chat-Historie vom Server und synchronisiert mit der lokalen DB.
     * Stellt sicher dass auch verpasste Nachrichten (wenn offline) angezeigt werden.
     */
    fun loadMessages(contactId: String) {
        viewModelScope.launch { loadMessagesSuspend(contactId) }
    }

    /**
     * Kernlogik von [loadMessages] als suspend-Funktion. Wird auch von [syncMissedMessages]
     * mit begrenzter Parallelität (Semaphore) direkt awaited, statt wie zuvor pro Kontakt
     * fire-and-forget über [loadMessages] gestartet zu werden.
     */
    private suspend fun loadMessagesSuspend(contactId: String) {
        // Self-Notes sind rein lokal – kein Server-Abruf nötig
        if (contactId == "self_notes") return

        // Guard: verhindert gleichzeitige Server-Abfragen für denselben Chat
        val shouldRun = loadMessagesMutex.withLock {
            if (contactId in loadMessagesInProgress) {
                Timber.tag("Chat").d("loadMessages($contactId) übersprungen – läuft bereits")
                false
            } else {
                loadMessagesInProgress.add(contactId)
                true
            }
        }
        if (!shouldRun) return

        try {
            val localCount = messageDao.getLocalMessageCount(contactId)
            val newestLocalId = messageDao.getNewestServerMessageId(contactId)

            if (localCount > 0 && newestLocalId != null) {
                // INKREMENTELLER SYNC: Lokale Nachrichten vorhanden → nur neue vom Server laden
                Timber.tag("Chat").d("Inkrementeller Sync für $contactId (lokal: $localCount, newestId: $newestLocalId)")
                doIncrementalSync(contactId, newestLocalId)
            } else {
                // ERSTLADEN: Keine lokalen Nachrichten → 300 neueste vom Server laden
                Timber.tag("Chat").d("Erstladen für $contactId (keine lokalen Nachrichten)")
                doLoadMessagesFromServer(contactId, limit = 300, beforeId = null)
            }

            // Oldest-ID für Pagination setzen (für loadOlderMessages)
            val oldestLocalId = messageDao.getOldestServerMessageId(contactId)
            if (oldestLocalId != null) {
                _oldestServerMessageId[contactId] = oldestLocalId
                // Wenn wir lokal weniger als 300 haben, gibt es wahrscheinlich noch mehr auf dem Server
                if (_hasMoreMessages[contactId] == null) {
                    _hasMoreMessages[contactId] = true
                }
            }
        } finally {
            // Guard freigeben damit spätere Aufrufe wieder durchkommen
            loadMessagesMutex.withLock { loadMessagesInProgress.remove(contactId) }
        }
    }

    /**
     * Inkrementeller Sync: Ruft den leichtgewichtigen /sync-Endpoint auf,
     * vergleicht mit lokaler DB und lädt nur fehlende Nachrichten stückweise nach.
     */
    private suspend fun doIncrementalSync(contactId: String, newestLocalId: String) {
        try {
            // Schritt 1: Leichtgewichtige Sync-Liste vom Server holen (nur IDs + Metadaten, keine Blobs)
            val syncResponse = apiService.syncMessages(contactId, afterId = newestLocalId, limit = 1000)
            if (!syncResponse.isSuccessful) {
                Timber.tag("Chat").w("Sync-Endpoint fehlgeschlagen (${syncResponse.code()}), Fallback auf Vollladen")
                doLoadMessagesFromServer(contactId, limit = 50, beforeId = null)
                return
            }

            val syncItems = syncResponse.body() ?: emptyList()
            if (syncItems.isEmpty()) {
                Timber.tag("Chat").d("Sync: keine neuen Nachrichten für $contactId")
                // Trotzdem Status-Updates für bestehende Nachrichten synchronisieren
                doSyncStatusUpdates(contactId)
                return
            }

            Timber.tag("Chat").d("Sync: ${syncItems.size} neue Nachrichten für $contactId gefunden")

            // Schritt 2: Prüfen welche IDs lokal fehlen
            val serverIds = syncItems.map { it.id }
            // In Batches von 500 abfragen (SQLite IN-Clause Limit)
            val existingIds = serverIds.chunked(500).flatMap { chunk ->
                messageDao.getExistingMessageIds(chunk)
            }.toSet()

            val missingIds = serverIds.filter { it !in existingIds }
            Timber.tag("Chat").d("Sync: ${missingIds.size} fehlende Nachrichten zum Nachladen")

            if (missingIds.isEmpty()) {
                // Alle Nachrichten bereits vorhanden, nur Status synchronisieren
                doSyncStatusUpdates(contactId)
                return
            }

            // Schritt 3: Fehlende Nachrichten stückweise nachladen (50er-Batches via after_id)
            doLoadMessagesFromServer(contactId, limit = missingIds.size.coerceAtMost(300), beforeId = null, afterId = newestLocalId)

        } catch (e: Exception) {
            Timber.tag("Chat").e(e, "Inkrementeller Sync fehlgeschlagen für $contactId, Fallback")
            // Fallback: Lade nur die letzten 50 Nachrichten (schnell genug für Retry)
            try {
                doLoadMessagesFromServer(contactId, limit = 50, beforeId = null)
            } catch (e2: Exception) {
                Timber.tag("Chat").e(e2, "Fallback-Laden ebenfalls fehlgeschlagen")
            }
        }
    }

    /**
     * Synchronisiert Delivery-Status, Reaktionen und isEdited für bereits lokal vorhandene Nachrichten.
     * Nutzt den leichtgewichtigen /sync-Endpoint rückwirkend (letzte 100 Nachrichten).
     */
    private suspend fun doSyncStatusUpdates(contactId: String) {
        try {
            val recentLocal = messageDao.getRecentMessagesForChat(contactId, 100)
            if (recentLocal.isEmpty()) return

            val myId = _currentUser.value?.userId ?: return

            // Status-Updates für die letzten 100 lokalen Nachrichten synchronisieren
            // Wir nutzen den normalen Endpoint mit kleinem Limit
            val response = apiService.getMessages(contactId, limit = 100, beforeId = null)
            if (!response.isSuccessful) return

            val serverMessages = response.body() ?: return
            val serverMap = serverMessages.associateBy { it.id }

            recentLocal.forEach { local ->
                val serverId = local.messageId ?: return@forEach
                val server = serverMap[serverId] ?: return@forEach

                // Reaction synchronisieren
                if (server.reaction != local.reaction) {
                    messageDao.setReactionByServerId(serverId, server.reaction)
                }
                // isEdited synchronisieren
                if (server.isEdited && !local.isEdited) {
                    val editedBlob = server.contentBlob ?: local.content ?: ""
                    val editedContent = if (server.mediaType == "text" && (editedBlob.startsWith("v2:") || editedBlob.startsWith("v3:"))) {
                        val chatPartner = if (server.senderId == myId) server.receiverId else server.senderId
                        try { CryptoManager.decryptUniversal(chatPartner, editedBlob) } catch (_: Exception) { editedBlob }
                    } else {
                        editedBlob
                    }
                    messageDao.editMessageByServerId(serverId, editedContent)
                }
                // DeliveryStatus synchronisieren
                val syncedStatus = if (server.senderId == myId) {
                    when {
                        server.isRead -> 3
                        server.isDelivered -> 2
                        else -> 1
                    }
                } else {
                    if (server.isRead) 3 else 2
                }
                if (syncedStatus > local.deliveryStatus) {
                    messageDao.updateDeliveryStatus(local.localId, syncedStatus)
                }
            }
        } catch (e: Exception) {
            Timber.tag("Chat").d("Status-Sync fehlgeschlagen: ${e.message}")
        }
    }

    /**
     * Batch-Nachladen älterer Nachrichten (Paginierung): wird nur ausgelöst, wenn der Nutzer
     * tatsächlich zum oberen Rand der aktuell geladenen Nachrichten hochgescrollt hat (ChatScreen
     * triggert dies erst, wenn das Lade-Sentinel am oberen Listenende sichtbar wird – kein
     * kontinuierliches Nachladen mehr während des Scrollens). Lädt genau einen Batch von 50
     * Nachrichten, zeigt währenddessen den Ladekreis, und lädt erst beim erneuten Erreichen
     * des oberen Randes den nächsten Batch. Ein bereits laufender Ladevorgang für denselben
     * Chat wird nicht doppelt gestartet.
     */
    fun loadOlderMessages(contactId: String) {
        if (_hasMoreMessages[contactId] != true) return
        if (_oldestServerMessageId[contactId] == null) return

        viewModelScope.launch {
            val shouldRun = loadMessagesMutex.withLock {
                if (contactId in loadMessagesInProgress) {
                    Timber.tag("Chat").d("loadOlderMessages($contactId) läuft bereits – übersprungen")
                    false
                } else {
                    loadMessagesInProgress.add(contactId)
                    true
                }
            }
            if (!shouldRun) return@launch

            _isLoadingOlderMessages.update { it + contactId }
            try {
                val oldestId = _oldestServerMessageId[contactId] ?: return@launch
                // Gruppe vs. 1:1 erkennen – Gruppen-Nachrichten kommen aus einer anderen Tabelle/Endpoint.
                val isGroup = withContext(Dispatchers.IO) { groupDao.getGroupById(contactId) != null }
                if (isGroup) {
                    doLoadGroupMessagesFromServer(contactId, limit = 50, beforeId = oldestId)
                } else {
                    doLoadMessagesFromServer(contactId, limit = 50, beforeId = oldestId)
                }
                getDisplayLimitFlow(contactId).update { it + 50 }
                Timber.tag("Chat").d("loadOlderMessages($contactId) Batch (50) geladen")
            } finally {
                loadMessagesMutex.withLock { loadMessagesInProgress.remove(contactId) }
                _isLoadingOlderMessages.update { it - contactId }
            }
        }
    }

    /** Gibt zurück ob für den gegebenen Chat noch ältere Nachrichten vom Server geladen werden können. */
    fun hasMoreMessages(chatId: String): Boolean = _hasMoreMessages[chatId] == true

    /** Kernlogik: Lädt Nachrichten vom Server und schreibt sie in Room (mit E2EE-Entschlüsselung). */
    private suspend fun doLoadMessagesFromServer(contactId: String, limit: Int, beforeId: String?, afterId: String? = null) {
        try {
            val response = apiService.getMessages(contactId, limit = limit, beforeId = beforeId, afterId = afterId)
            if (response.isSuccessful) {
                val serverMessages = response.body() ?: emptyList()

                // Pagination-Tracking: älteste ID + ob mehr vorhanden sind
                if (serverMessages.isNotEmpty()) {
                    _oldestServerMessageId[contactId] = serverMessages.first().id
                    _hasMoreMessages[contactId] = serverMessages.size >= limit
                } else if (beforeId == null) {
                    _hasMoreMessages[contactId] = false
                }

                val myId = _currentUser.value?.userId ?: return
                serverMessages.forEach { item ->
                    // DEDUP-1: Prüfen ob Nachricht via Server-ID bereits vorhanden
                    val existingById = if (item.id.isNotBlank()) messageDao.getMessageById(item.id) else null
                    if (existingById != null) {
                        // isDeliveredAsNotification vom Server synchronisieren
                        if (item.isDeliveredAsNotification && !existingById.isDeliveredAsNotification) {
                            messageDao.markDeliveredAsNotification(item.id)
                        }
                        // reaction + isEdited vom Server synchronisieren (können sich nach dem ersten Insert ändern)
                        if (item.reaction != existingById.reaction) {
                            messageDao.setReactionByServerId(item.id, item.reaction)
                        }
                        if (item.isEdited && !existingById.isEdited) {
                            val editedBlob = item.contentBlob ?: existingById.content ?: ""
                            val editedContent = if (item.mediaType == "text" && (editedBlob.startsWith("v2:") || editedBlob.startsWith("v3:"))) {
                                val chatPartner = if (item.senderId == myId) item.receiverId else item.senderId
                                try { CryptoManager.decryptUniversal(chatPartner, editedBlob) } catch (_: Exception) { editedBlob }
                            } else {
                                editedBlob
                            }
                            messageDao.editMessageByServerId(item.id, editedContent)
                        }
                        // Entschlüsselung nachholen: falls beim WS-Empfang Schlüssel noch nicht verfügbar waren,
                        // kann entweder der Chiffretext (v2:...) oder eine der Fehlermeldungen gespeichert sein.
                        // Alle bekannten Fehler-Präfixe prüfen um lückenlose Nachentschlüsselung zu gewährleisten.
                        val existingContent = existingById.content
                        val needsRetry = existingContent != null && (
                            existingContent.startsWith("v2:") ||
                            existingContent.startsWith("v3:") ||
                            existingContent.startsWith("[🔐") ||
                            existingContent.startsWith("🔐") ||
                            existingContent.startsWith("⚠️") ||
                            existingContent.startsWith("\uD83D\uDD10")  // 🔐 Unicode-Variante
                        )
                        if (item.mediaType == "text" && needsRetry) {
                            val rawBlob = item.contentBlob ?: existingById.content ?: ""
                            val chatPartner = when {
                                item.senderId == myId -> item.receiverId
                                else -> item.senderId
                            }
                            // v3 (UMK): direkt mit decryptUniversal
                            if (rawBlob.startsWith("v3:")) {
                                val retried = try { CryptoManager.decryptUniversal(chatPartner, rawBlob) } catch (_: Exception) { null }
                                if (retried != null && !retried.startsWith("v3:") && !retried.startsWith("[🔐") &&
                                    !retried.startsWith("⚠️")) {
                                    messageDao.editMessageByServerId(item.id, retried)
                                    Timber.tag("LETHE_E2EE").i("Nachentschlüsselung (v3) erfolgreich für ${item.id}")
                                }
                            } else {
                                // Legacy v2: ECDH-basiert
                                if (!item.senderWebPub.isNullOrBlank()) {
                                    CryptoManager.forceRederiveWebSharedSecret(item.senderId, item.senderWebPub!!)
                                }
                                if (!CryptoManager.hasSharedSecret(chatPartner)) {
                                    val contact = contactDao.getContactById(chatPartner)
                                    if (contact != null && contact.publicKey.length > 100) {
                                        CryptoManager.deriveSharedSecret(chatPartner, contact.publicKey)
                                    }
                                }
                                // Versuch 1: Für eigene Nachrichten mit selfContentBlob (eigener Schlüssel)
                                val selfBlob = item.selfContentBlob
                                val retriedSelf = if (item.senderId == myId && !selfBlob.isNullOrBlank()) {
                                    try { CryptoManager.decryptBestEffort(myId, selfBlob) } catch (_: Exception) { null }
                                } else null
                                val retried = if (retriedSelf != null &&
                                    !retriedSelf.startsWith("v2:") && !retriedSelf.startsWith("[🔐") &&
                                    !retriedSelf.startsWith("⚠️") && !retriedSelf.startsWith("🔐")
                                ) {
                                    retriedSelf
                                } else {
                                    try { CryptoManager.decryptUniversal(chatPartner, rawBlob) } catch (_: Exception) { null }
                                }
                                if (retried != null && !retried.startsWith("v2:") && !retried.startsWith("[🔐") &&
                                    !retried.startsWith("⚠️") && !retried.startsWith("🔐")
                                ) {
                                    messageDao.editMessageByServerId(item.id, retried)
                                    Timber.tag("LETHE_E2EE").i("Nachentschlüsselung erfolgreich für ${item.id}")
                                }
                            }
                        }
                        // deliveryStatus vom Server synchronisieren (z.B. nach Neuinstallation)
                        val syncedStatus = if (item.senderId == myId) {
                            when {
                                item.isRead -> 3
                                item.isDelivered -> 2
                                else -> 1
                            }
                        } else {
                            if (item.isRead) 3 else 2
                        }
                        if (syncedStatus > existingById.deliveryStatus) {
                            messageDao.updateDeliveryStatus(existingById.localId, syncedStatus)
                        }
                        return@forEach
                    }

                    // DEDUP-2: Prüfen ob Nachricht via clientMessageId bereits vorhanden
                    // (verhindert Doppelpost wenn ACK noch nicht verarbeitet wurde)
                    val existingByClientId = if (!item.clientMessageId.isNullOrBlank()) {
                        messageDao.getMessageByClientId(item.clientMessageId)
                    } else null
                    if (existingByClientId != null) {
                        // messageId rückwärts synchronisieren falls noch nicht gesetzt
                        if (item.id.isNotBlank() && existingByClientId.messageId == null) {
                            messageDao.ackMessage(item.clientMessageId!!, item.id)
                        }
                        // deliveryStatus aus Server-Flags aktualisieren
                        val dedup2Status = when {
                            item.isRead -> 3
                            item.isDelivered -> 2
                            else -> 1
                        }
                        if (dedup2Status > existingByClientId.deliveryStatus) {
                            messageDao.updateDeliveryStatus(existingByClientId.localId, dedup2Status)
                        }
                        return@forEach
                    }

                    // Entschlüsseln: is_encrypted=true (oder v2:/v3:-Präfix) → AES-256-GCM
                    // is_encrypted=false → Klartext (Altlast), unverändert anzeigen
                    val decryptedContent = if (item.mediaType == "text" &&
                        (item.isEncrypted || item.contentBlob?.startsWith("v2:") == true || item.contentBlob?.startsWith("v3:") == true)) {
                        val chatPartner = when {
                            item.senderId == "lethe_system" -> item.replyToSenderId ?: contactId
                            item.senderId == myId -> item.receiverId
                            else -> item.senderId
                        }
                        val rawBlob = item.contentBlob ?: ""
                        // v3 (UMK): geräteunabhängig – gleicher Conversation Key auf allen Geräten
                        if (rawBlob.startsWith("v3:")) {
                            try {
                                CryptoManager.decryptUniversal(chatPartner, rawBlob)
                            } catch (decEx: Exception) {
                                Timber.tag("LETHE_E2EE").w("v3-History-Entschlüsselung fehlgeschlagen ${item.id}: ${decEx.message}")
                                "⚠️ Diese Nachricht konnte nicht entschlüsselt werden."
                            }
                        } else {
                            // Legacy v2: ECDH-basiert
                            val itemSenderWebPub = item.senderWebPub
                            val itemSelfContentBlob = item.selfContentBlob
                            if (item.senderId == myId && !itemSenderWebPub.isNullOrBlank() && !itemSelfContentBlob.isNullOrBlank()) {
                                // Eigene Nachricht aus Webchat-History: self_content_blob entschlüsseln
                                CryptoManager.forceRederiveWebSharedSecret(myId, itemSenderWebPub)
                                try {
                                    CryptoManager.decryptBestEffort(myId, itemSelfContentBlob)
                                } catch (decEx: Exception) {
                                    Timber.tag("LETHE_E2EE").w("Self-Web-History-Entschlüsselung fehlgeschlagen ${item.id}: ${decEx.message}")
                                    "⚠️ Diese Nachricht konnte nicht entschlüsselt werden."
                                }
                            } else {
                                // Vom Kontakt gesendete Nachricht (ggf. von dessen Webchat):
                                // Web-Secret ZUERST force-rederiven, dann erst entschlüsseln
                                if (!itemSenderWebPub.isNullOrBlank()) {
                                    CryptoManager.forceRederiveWebSharedSecret(item.senderId, itemSenderWebPub)
                                }
                                // Race-Condition-Schutz: Android-Secret aus Room DB ableiten falls noch nicht gecacht
                                if (!CryptoManager.hasSharedSecret(chatPartner)) {
                                    val contact = contactDao.getContactById(chatPartner)
                                    if (contact != null && contact.publicKey.length > 100) {
                                        CryptoManager.deriveSharedSecret(chatPartner, contact.publicKey)
                                    }
                                }
                                try {
                                    CryptoManager.decryptUniversal(chatPartner, rawBlob)
                                } catch (decEx: Exception) {
                                    Timber.tag("LETHE_E2EE").w("Entschlüsselung fehlgeschlagen für Msg ${item.id}: ${decEx.message}")
                                    "⚠️ Diese Nachricht konnte nicht entschlüsselt werden."
                                }
                            }
                        }
                    } else {
                        item.contentBlob
                    }

                    // deliveryStatus aus Server-Flags berechnen (für korrekte Häkchen nach Neuinstallation)
                    val computedDeliveryStatus = if (item.senderId == myId) {
                        when {
                            item.isRead -> 3       // Gelesen (beide Häkchen farbig)
                            item.isDelivered -> 2  // Zugestellt (zwei graue Häkchen)
                            else -> 1              // Gesendet (ein Häkchen) – liegt bereits auf Server
                        }
                    } else {
                        if (item.isRead) 3 else 2  // Eingehende: gelesen=3, sonst zugestellt=2
                    }

                    messageDao.insertMessage(
                        MessageEntity(
                            messageId = item.id,
                            chatId = when {
                                item.senderId == "lethe_system" -> item.replyToSenderId ?: contactId
                                item.senderId == myId -> item.receiverId
                                else -> item.senderId
                            },
                            senderId = item.senderId,
                            receiverId = item.receiverId,
                            content = decryptedContent,
                            mediaType = item.mediaType,
                            mediaUrl = item.mediaUrl,
                            timestamp = item.timestamp?.let {
                                try { java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss", java.util.Locale.US).parse(it)?.time }
                                catch (e: Exception) { System.currentTimeMillis() }
                            } ?: System.currentTimeMillis(),
                            isSent = item.senderId == myId,
                            isRead = item.isRead,
                            replyToContent = item.replyToContent,
                            replyToSenderId = item.replyToSenderId,
                            replyToMediaType = item.replyToMediaType,
                            isDeliveredAsNotification = item.isDeliveredAsNotification,
                            reaction = item.reaction,
                            isEdited = item.isEdited,
                            senderDeviceId = item.senderDeviceId,
                            deliveryStatus = computedDeliveryStatus
                        )
                    )
                }
                Timber.tag("Chat").d("${serverMessages.size} Nachrichten vom Server geladen für: $contactId (limit=$limit, beforeId=$beforeId, afterId=$afterId)")

                // Media-Download-Queue: Videos und Sprachnachrichten im Hintergrund nachladen
                val mediaMessages = serverMessages.filter { msg ->
                    !msg.mediaUrl.isNullOrBlank() && msg.mediaType in listOf("video", "audio")
                }
                if (mediaMessages.isNotEmpty()) {
                    enqueueMediaDownloads(contactId, mediaMessages)
                }
            }
        } catch (e: Exception) {
            Timber.tag("Chat").e("Nachrichten laden fehlgeschlagen", e)
        }
    }

    /**
     * Reiht Video- und Sprachnachrichten in die Download-Warteschlange ein.
     * Maximal 2 gleichzeitige Downloads (via Semaphore), sequentiell pro Nachricht.
     * Sprachnachrichten haben Priorität vor Videos (kleinere Dateien → schnellere UX).
     */
    private fun enqueueMediaDownloads(contactId: String, messages: List<MessageItemResponse>) {
        // Sortieren: Audio zuerst (kleinere Dateien), dann Video
        val sorted = messages.sortedBy { if (it.mediaType == "audio") 0 else 1 }

        sorted.forEach { msg ->
            val url = msg.mediaUrl ?: return@forEach
            // Skip wenn bereits in Bearbeitung
            if (mediaDownloadInProgress.putIfAbsent(url, true) != null) return@forEach

            viewModelScope.launch(kotlinx.coroutines.Dispatchers.IO) {
                mediaDownloadSemaphore.acquire()
                try {
                    Timber.tag("MediaQueue").d("Download gestartet: ${msg.mediaType} ${msg.id}")
                    // OkHttp-Download mit Streaming
                    val request = okhttp3.Request.Builder().url(url).build()
                    val client = okhttp3.OkHttpClient.Builder()
                        .connectTimeout(30, java.util.concurrent.TimeUnit.SECONDS)
                        .readTimeout(120, java.util.concurrent.TimeUnit.SECONDS)
                        .build()
                    val response = client.newCall(request).execute()
                    if (response.isSuccessful) {
                        val body = response.body
                        if (body != null) {
                            // In App-Cache schreiben
                            val ext = when (msg.mediaType) {
                                "audio" -> ".aac"
                                "video" -> ".mp4"
                                else -> ".bin"
                            }
                            val cacheDir = java.io.File(
                                context.cacheDir,
                                "media_cache/$contactId"
                            ).also { it.mkdirs() }
                            val file = java.io.File(cacheDir, "${msg.id}$ext")
                            file.outputStream().use { output ->
                                body.byteStream().use { input ->
                                    input.copyTo(output, bufferSize = 8192)
                                }
                            }
                            Timber.tag("MediaQueue").d("Download fertig: ${msg.mediaType} ${msg.id} (${file.length() / 1024}KB)")
                        }
                    }
                    response.close()
                } catch (e: Exception) {
                    Timber.tag("MediaQueue").w("Download fehlgeschlagen: ${msg.id} - ${e.message}")
                } finally {
                    mediaDownloadInProgress.remove(url)
                    mediaDownloadSemaphore.release()
                }
            }
        }
    }

    /** Wird aufgerufen wenn der Chat-Screen geöffnet wird: Status laden + Read-Receipts senden. */
    fun onChatOpened(contactId: String, isGroup: Boolean = false) {
        _activeChatId.value = contactId
        _activeChatIsGroup.value = isGroup
        // Display-Limit auf 300 zurücksetzen (neuer Chat-Besuch startet frisch)
        getDisplayLimitFlow(contactId).value = 300

        // v3: fehlt ein Conversation Key (Partner war beim Login offline), Exchange jetzt erneut anstoßen
        if (!isGroup) ensureConversationKeyForChat(contactId)

        // Bestehende Benachrichtigung dieses Absenders sofort entfernen
        notificationHelper.cancelNotificationForSender(contactId)

        // Server informieren: dieser Chat ist jetzt geöffnet → FCM-Push unterdrücken
        if (isGroup) {
            webSocketManager.sendRaw(mapOf(
                "type" to "set_chat_focus",
                "group_id" to contactId
            ))
        } else {
            webSocketManager.sendRaw(mapOf(
                "type" to "set_chat_focus",
                "chat_user_id" to contactId
            ))
        }

        // Falls eine Lumis-Animation für diesen Kontakt ausstehend ist, jetzt abspielen
        pendingLumisMap[contactId]?.let { pendingType ->
            removePendingLumis(contactId)
            _activeLumis.value = pendingType
        }

        viewModelScope.launch {
            // Online-Status des Kontakts laden
            try {
                val response = apiService.getUserStatus(contactId)
                if (response.isSuccessful) {
                    _contactStatus.value = response.body()
                }
            } catch (e: Exception) {
                Timber.tag("Chat").e("Status-Abfrage fehlgeschlagen", e)
            }

            // EIGENE LOKALE NACHRICHTEN SOFORT ALS GELESEN MARKIEREN
            // Damit verschwindet der Unread-Indikator aus der ContactlistScreen im gleichen Moment.
            val myId = _currentUser.value?.userId
            if (myId != null) {
                if (isGroup) {
                    messageDao.markGroupMessagesRead(contactId, myId)
                } else {
                    messageDao.markAllRead(contactId, myId)
                }
            }

            // Beim Chat-Betreten: alle unzugestellten Nachrichten als "delivered" markieren.
            // Dies geschieht unabhängig von readReceiptAfterReply, damit der Absender immer
            // den Zugestellt-Haken bekommt, sobald der Empfänger den Chat öffnet.
            val pendingMessages = if (isGroup) {
                messageDao.getUnreadGroupMessages(contactId, myId ?: "")
            } else {
                messageDao.getUnreadMessagesFrom(contactId, myId ?: "")
            }
            pendingMessages.filter { it.deliveryStatus < 2 && !it.messageId.isNullOrBlank() }.forEach { msg ->
                webSocketManager.sendMessage(
                    "delivered", contactId, mapOf("message_id" to msg.messageId!!)
                )
            }

            // Lesebestätigungen senden – nur wenn "erst nach Antwort" NICHT aktiviert ist
            if (!_userPrefs.value.readReceiptAfterReply) {
                pendingMessages.forEach { msg ->
                    // deliveryStatus < 2 wurde oben schon als delivered gesendet;
                    // jetzt alle (inkl. status == 2) auf gelesen setzen.
                    messageDao.updateDeliveryStatus(msg.localId, 3)
                    if (!msg.messageId.isNullOrBlank()) {
                        webSocketManager.sendMessage(
                            "read_receipt", contactId, mapOf("message_id" to msg.messageId)
                        )
                    }
                }
                if (!isGroup) {
                    // Sammel-Read-Receipt an den Partner (Legacy-Kompatibilität, nur 1:1)
                    webSocketManager.sendMessage(
                        "read_receipt", contactId, mapOf("chat_partner" to contactId)
                    )
                }
            } else {
                // readReceiptAfterReply aktiv: nur lokal als delivered markieren (Status 2),
                // falls noch auf 0 oder 1 – aber noch NICHT als gelesen (3).
                pendingMessages.filter { it.deliveryStatus < 2 }.forEach { msg ->
                    messageDao.updateDeliveryStatus(msg.localId, 2)
                }
            }
        }
    }

    fun onChatClosed() {
        val chatId = _activeChatId.value
        _activeChatId.value = null
        _partnerIsTyping.value = false
        typingResetJob?.cancel()
        // Laufende Lumis-Animation beim Verlassen des Chats stoppen
        _activeLumis.value = com.securechat.app.ui.screens.LumisType.NONE

        // Server informieren: Chat verlassen → FCM-Push wieder aktivieren
        webSocketManager.sendRaw(mapOf("type" to "clear_chat_focus"))

        // In-memory Caches aufräumen. WICHTIG: Der Disk-Cache des Chats wird NICHT mehr
        // gelöscht – die vorgeladenen Medien (Bilder/Audio/Videos) bleiben persistent,
        // damit Videos nicht bei jedem Öffnen erneut gestreamt werden (Datenvolumen).
        // Die Disk-Größe wird stattdessen global via LetheCacheManager.enforceMaxCacheSize
        // (500 MB, LRU) und cleanOldMedia (7 Tage) in MainActivity.onStop begrenzt.
        if (chatId != null) {
            _chatMediaUrls.forEach { url ->
                _videoThumbnailCache.remove(url)
                _musicCoverCache.remove(url)
                _waveformCache.remove(url)
            }
            _chatMediaUrls.clear()
            _videoThumbnailMap.value = buildMap { putAll(_videoThumbnailCache.snapshot()) }
            _waveformMap.value = buildMap { putAll(_waveformCache.snapshot()) }
        }
    }

    fun onNearbyMatchOpened(matchId: String) {
        _activeNearbyMatchId.value = matchId
        markNearbyMessagesRead(matchId)
    }

    fun onNearbyMatchClosed() {
        _activeNearbyMatchId.value = null
    }

    private fun markNearbyMessagesRead(matchId: String) {
        // Setzt hasUnreadNearbyMessages auf false für dieses Match
        val current = _unreadNearbyMatchIds.value.toMutableSet()
        current.remove(matchId)
        _unreadNearbyMatchIds.value = current
        _hasUnreadNearbyMessages.value = current.isNotEmpty()
    }

    /**
     * Sendet einen Lumis-Effekt an den Chat-Partner und spielt ihn gleichzeitig lokal ab.
     * Der Effekt wird via WebSocket an [contactId] weitergeleitet.
     */
    fun sendLumis(contactId: String, lumisType: com.securechat.app.ui.screens.LumisType, isGroup: Boolean = false) {
        // Eigene Animation sofort starten
        _activeLumis.value = lumisType

        // Lumis-Event via WebSocket senden (Gruppe: an alle Mitglieder, 1:1: direkt an Partner)
        if (isGroup) {
            webSocketManager.sendMessage(
                type       = "group_lumis",
                receiverId = contactId,
                payload    = mapOf("lumis_type" to lumisType.name, "group_id" to contactId)
            )
        } else {
            webSocketManager.sendMessage(
                type       = "lumis",
                receiverId = contactId,
                payload    = mapOf("lumis_type" to lumisType.name)
            )
        }
        Timber.tag("LETHE_WS").d("Lumis gesendet: ${lumisType.name} an $contactId (isGroup=$isGroup)")

        // Systemnachricht lokal einfügen (erscheint für den Absender im Chat)
        viewModelScope.launch {
            val me = _currentUser.value ?: return@launch
            val contact = contactDao.getContactById(contactId)
            val senderLabel = if (!isGroup && contact?.isAnonymous == true) {
                me.letheId ?: me.fakeNumber
            } else {
                me.name.takeIf { it.isNotBlank() } ?: me.fakeNumber
            }
            val displayName = lumisTypeDisplayName(lumisType)
            messageDao.insertMessage(
                MessageEntity(
                    chatId          = contactId,
                    senderId        = "system",
                    receiverId      = contactId,
                    content         = "$senderLabel hat ein \"$displayName\" Lumis gesendet",
                    mediaType       = "system",
                    timestamp       = System.currentTimeMillis(),
                    isRead          = true,
                    deliveryStatus  = 3
                )
            )
        }
    }

    private fun lumisTypeDisplayName(lumisType: com.securechat.app.ui.screens.LumisType): String = when (lumisType) {
        com.securechat.app.ui.screens.LumisType.LOVE            -> "Love"
        com.securechat.app.ui.screens.LumisType.SNOW            -> "Snow"
        com.securechat.app.ui.screens.LumisType.KISS            -> "Kiss"
        com.securechat.app.ui.screens.LumisType.RAIN            -> "Rain"
        com.securechat.app.ui.screens.LumisType.SUMMER          -> "Summer"
        com.securechat.app.ui.screens.LumisType.CHRISTMAS       -> "Weihnachten"
        com.securechat.app.ui.screens.LumisType.STRANGER_THINGS -> "Upside Down"
        com.securechat.app.ui.screens.LumisType.LAST_OF_US      -> "The Last of Us"
        com.securechat.app.ui.screens.LumisType.MARIO           -> "Mario & Peach"
        com.securechat.app.ui.screens.LumisType.NONE            -> ""
    }

