    /** Zeitstempel des letzten gesendeten Typing-Events pro Kontakt (Throttle). */
    private val lastTypingSentAt = mutableMapOf<String, Long>()
    private val typingThrottleMs = 2000L

    /** Sendet ein "tippt..." Signal an den Chat-Partner via WebSocket.
     *  Wird sofort beim ersten Tastendruck gesendet, danach gedrosselt (max. alle 2 Sekunden). */
    fun sendTypingEvent(contactId: String) {
        val now = System.currentTimeMillis()
        val last = lastTypingSentAt[contactId] ?: 0L
        if (now - last >= typingThrottleMs) {
            lastTypingSentAt[contactId] = now
            viewModelScope.launch {
                // Gruppen-Tipp trägt group_id, damit der Server nur an Mitglieder relayt
                // und der 1:1-Chat des Senders nicht fälschlich "tippt..." zeigt.
                val isGroup = groupDao.getGroupById(contactId) != null
                if (isGroup) {
                    webSocketManager.sendMessage("typing", contactId, mapOf("group_id" to contactId))
                } else {
                    webSocketManager.sendMessage("typing", contactId, emptyMap<String, Any>())
                }
            }
        }
    }

    /** Setzt oder entfernt eine Emoji-Reaktion auf eine Nachricht (lokal + WS-Relay an Partner). */
    fun sendReaction(messageId: String, chatPartnerId: String, localId: Long, emoji: String) {
        viewModelScope.launch {
            messageDao.setReactionByLocalId(localId, emoji)
            if (messageId.isNotBlank()) {
                webSocketManager.sendMessage(
                    "reaction", chatPartnerId,
                    mapOf("message_id" to messageId, "emoji" to emoji)
                )
            }
            Timber.tag("LETHE_WS").d("Reaktion gesendet: $emoji auf $messageId an $chatPartnerId")
        }
    }

    /** Bearbeitet den Text einer eigenen gesendeten Nachricht lokal und auf dem Server. */
    fun editMessage(localId: Long, newContent: String) {
        viewModelScope.launch {
            try {
                messageDao.editMessage(localId, newContent)
                val msg = messageDao.getMessageByLocalId(localId)
                if (msg?.messageId != null) {
                    // Bearbeitung an alle Teilnehmer propagieren (1:1 + Gruppe, inkl. eigener Geräte).
                    val isGroup = groupDao.getGroupById(msg.chatId) != null
                    val payload = buildMap<String, Any> {
                        put("message_id", msg.messageId)
                        put("content", newContent)
                        if (isGroup) put("group_id", msg.chatId)
                    }
                    webSocketManager.sendMessage("edit_message", msg.chatId, payload)
                }
            } catch (e: Exception) {
                Timber.tag("MainViewModel").e("Nachricht bearbeiten fehlgeschlagen: ${e.message}")
            }
        }
    }

    /** Lädt Online-Status eines Kontakts (z.B. für Kontaktliste). */
    fun loadContactStatus(contactId: String) {
        viewModelScope.launch {
            try {
                val response = apiService.getUserStatus(contactId)
                if (response.isSuccessful) _contactStatus.value = response.body()
