    }

    fun sendMessage(chatId: String, content: String,
        replyToContent: String? = null, replyToSenderId: String? = null,
        mediaType: String = "text", replyToMediaType: String? = null,
        replyToMessageId: String? = null) {
        viewModelScope.launch {
            val me = _currentUser.value ?: return@launch
            val clientId = UUID.randomUUID().toString()

            // Self-Notes: nur lokal speichern, kein Server/WebSocket
            if (chatId == "self_notes") {
                messageDao.insertMessage(
                    MessageEntity(
                        chatId = "self_notes",
                        senderId = me.userId,
                        receiverId = "self_notes",
                        content = content,
                        mediaType = mediaType,
                        timestamp = System.currentTimeMillis(),
                        isSent = true,
                        clientMessageId = clientId,
                        deliveryStatus = 3,
                        replyToContent = replyToContent,
                        replyToSenderId = replyToSenderId,
                        replyToMediaType = replyToMediaType,
                        replyToMessageId = replyToMessageId
                    )
                )
                return@launch
            }

            // Ungelesene Nachrichten vom Partner als gelesen markieren (implizite Lesebestätigung beim Antworten)
            if (!_userPrefs.value.readReceiptAfterReply) {
                val unread = messageDao.getUnreadMessagesFrom(chatId, me.userId)
                if (unread.isNotEmpty()) {
                    unread.forEach { unreadMsg ->
                        messageDao.updateDeliveryStatus(unreadMsg.localId, 3)
                        webSocketManager.sendMessage(
                            "read_receipt", chatId, mapOf("message_id" to (unreadMsg.messageId ?: ""))
                        )
                    }
                    webSocketManager.sendMessage("read_receipt", chatId, mapOf("chat_partner" to chatId))
                    messageDao.markAllRead(chatId, me.userId)
                }
            }

            // P2P-Direktzustellung versuchen (nur Text, wenn DataChannel CONNECTED).
            // Envelope {cmid, content}: die clientMessageId erlaubt dem Partner, die parallel
            // über den Server gespiegelte WS-new_message zu deduplizieren (sonst Doppel-Anzeige).
            val p2pSent = mediaType == "text" &&
                webRTCDataChannelManager.getState(chatId) == com.securechat.app.data.webrtc.WebRTCDataChannelManager.P2PState.CONNECTED &&
                webRTCDataChannelManager.sendMessage(
                    chatId,
                    org.json.JSONObject().put("cmid", clientId).put("content", content).toString()
                )

            // Nachricht lokal speichern (PENDING-Status, oder SENT wenn P2P-Direktzustellung)
            val msg = MessageEntity(
                chatId = chatId,
                senderId = me.userId,
                receiverId = chatId,
                content = content,
                mediaType = mediaType,
                timestamp = System.currentTimeMillis(),
                isSent = p2pSent,
                clientMessageId = clientId,
                deliveryStatus = if (p2pSent) 1 else 0,
                replyToContent = replyToContent,
                replyToSenderId = replyToSenderId,
                replyToMediaType = replyToMediaType,
                replyToMessageId = replyToMessageId,
                isP2pDelivered = p2pSent
            )
            messageDao.insertMessage(msg)

            // Sicherheitsnetz: nach 10 gesendeten Nachrichten Key-Backup sicherstellen (auch ohne frischen Login)
            maybeDeferredKeyBackup()

            // v3 Lazy-Fetch: fehlt der Conversation Key, kurz auf den UMK-Exchange warten,
            // bevor auf v2 zurückgefallen wird (Partner war beim Login evtl. offline).
            if (mediaType == "text") tryLazyConversationKey(chatId)

            // Verschlüsselung: bevorzugt UMK-basiert (v3), Fallback auf ECDH (v2)
            val wireContent = if (mediaType == "text") {
                CryptoManager.encryptUniversal(chatId, content)
            } else {
                content
            }

            // Legacy Web-Blob: nur wenn kein UMK-Conversation-Key vorhanden (v2-Modus)
            val isV3 = wireContent.startsWith("v3:")
            val webWireContent: String? = if (!isV3 && mediaType == "text" && CryptoManager.hasWebSharedSecret(chatId)) {
                CryptoManager.encryptForWeb(chatId, content)
            } else {
                null
            }

            // Legacy Self-Web-Copy: nur im v2-Modus nötig (v3 ist geräteunabhängig)
            val myId = me.userId
            val selfWebContent: String? = if (!isV3 && mediaType == "text" && CryptoManager.hasWebSharedSecret(myId)) {
                CryptoManager.encryptForWeb(myId, content)
            } else {
                null
            }

            // Über WebSocket senden — client_message_id im Payload für Server-ACK
            val payload = buildMap<String, Any?> {
                put("content_blob", wireContent)
                put("media_type", mediaType)
                put("client_message_id", clientId)
                put("sender_timestamp", msg.timestamp) // Sender-Zeitstempel für konsistente Anzeige beim Empfänger
                if (webWireContent != null) put("web_content_blob", webWireContent)
                if (selfWebContent != null) put("self_content_blob", selfWebContent)
                if (replyToContent != null) put("reply_to_content", replyToContent)
                if (replyToSenderId != null) put("reply_to_sender_id", replyToSenderId)
                if (replyToMediaType != null) put("reply_to_media_type", replyToMediaType)
                if (replyToMessageId != null) put("reply_to_message_id", replyToMessageId)
            }
            webSocketManager.sendMessage("message", chatId, payload)
            Timber.tag("Chat").d("Nachricht gesendet an: $chatId mediaType=$mediaType (clientId: $clientId)")
        }
    }

    /**
     * Sendet alle ausstehenden eigenen Text-Nachrichten (deliveryStatus=0) erneut über den WebSocket.
     * Wird beim Reconnect und beim manuellen Retry aufgerufen.
     */
    fun retryPendingMessages() {
        viewModelScope.launch {
            val me = _currentUser.value ?: return@launch
            val pending = messageDao.getPendingOutgoingTextMessages(me.userId)
            if (pending.isEmpty()) return@launch
            Timber.tag("Chat").d("Sende ${pending.size} ausstehende Nachrichten erneut")
            for (msg in pending) {
                val clientId = msg.clientMessageId ?: continue
                val content = msg.content ?: continue
                val chatId = msg.chatId

                // Gruppen-Nachrichten NICHT als 1:1 erneut senden (falsche Route → Gruppe erhält sie nie).
                // Stattdessen korrekt als group_message mit Gruppen-Sender-Key erneut zustellen.
                if (groupDao.getGroupById(chatId) != null) {
                    val shouldEncrypt = msg.mediaType == "text" && !content.startsWith("/")
                    val senderKeyEntity = if (shouldEncrypt) groupSenderKeyDao.getKey(chatId, me.userId) else null
                    val groupBlob: String
                    val groupIsEncrypted: Boolean
                    if (shouldEncrypt && senderKeyEntity != null) {
                        val rawKey = android.util.Base64.decode(senderKeyEntity.keyBase64, android.util.Base64.NO_WRAP)
                        groupBlob = com.securechat.app.data.crypto.CryptoManager.encryptGroupMessage(rawKey, content)
                        groupIsEncrypted = true
                    } else {
                        groupBlob = content
                        groupIsEncrypted = false
                    }
                    val groupPayload = buildMap<String, Any?> {
                        put("content_blob", groupBlob)
                        put("media_type", msg.mediaType)
                        put("group_id", chatId)
                        put("client_message_id", clientId)
                        put("is_e2ee", groupIsEncrypted)
                        put("sender_timestamp", msg.timestamp)
                        if (msg.replyToContent != null) put("reply_to_content", msg.replyToContent)
                        if (msg.replyToSenderId != null) put("reply_to_sender_id", msg.replyToSenderId)
                        if (msg.replyToMediaType != null) put("reply_to_media_type", msg.replyToMediaType)
                        if (msg.replyToMessageId != null) put("reply_to_message_id", msg.replyToMessageId)
                    }
                    webSocketManager.sendMessage("group_message", chatId, groupPayload)
                    Timber.tag("Chat").d("Pending-Gruppennachricht erneut gesendet: groupId=$chatId clientId=$clientId")
                    continue
                }

                val wireContent = com.securechat.app.data.crypto.CryptoManager.encryptUniversal(chatId, content)
                // Legacy Web-Blob: nur wenn kein v3 (UMK) verwendet wird
                val isV3 = wireContent.startsWith("v3:")
                val webWireContent: String? = if (!isV3 && com.securechat.app.data.crypto.CryptoManager.hasWebSharedSecret(chatId)) {
                    com.securechat.app.data.crypto.CryptoManager.encryptForWeb(chatId, content)
                } else null
                val selfWebContent: String? = if (!isV3 && com.securechat.app.data.crypto.CryptoManager.hasWebSharedSecret(me.userId)) {
                    com.securechat.app.data.crypto.CryptoManager.encryptForWeb(me.userId, content)
                } else null

                val payload = buildMap<String, Any?> {
                    put("content_blob", wireContent)
                    put("media_type", msg.mediaType)
                    put("client_message_id", clientId)
                    put("sender_timestamp", msg.timestamp)
                    if (webWireContent != null) put("web_content_blob", webWireContent)
                    if (selfWebContent != null) put("self_content_blob", selfWebContent)
                    if (msg.replyToContent != null) put("reply_to_content", msg.replyToContent)
                    if (msg.replyToSenderId != null) put("reply_to_sender_id", msg.replyToSenderId)
                    if (msg.replyToMediaType != null) put("reply_to_media_type", msg.replyToMediaType)
                }
                webSocketManager.sendMessage("message", chatId, payload)
                Timber.tag("Chat").d("Pending-Nachricht erneut gesendet: chatId=$chatId clientId=$clientId")
            }
        }
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Zeitgeplante Nachrichten
    // ─────────────────────────────────────────────────────────────────────────

    /** Lädt alle noch nicht versendeten geplanten Nachrichten vom Server. */
    fun loadScheduledMessages() {
        viewModelScope.launch {
            val token = tokenManager.getToken() ?: return@launch
            try {
                val resp = apiService.getScheduledMessages("Bearer $token")
                if (resp.isSuccessful) {
                    _scheduledMessages.value = resp.body() ?: emptyList()
                }
            } catch (e: Exception) {
                Timber.tag("Chat").w(e, "Fehler beim Laden der geplanten Nachrichten")
            }
        }
    }

    /**
     * Plant eine Nachricht für den angegebenen Zeitpunkt.
     * @param chatId  Empfänger-ID
     * @param content Klartext-Nachricht (wird hier verschlüsselt)
     * @param scheduledAt ISO-8601-String (UTC), z. B. "2026-04-25T14:30:00"
     * @param onResult Callback mit (ok, errorMsg)
     */
    fun scheduleMessage(
        chatId: String,
        content: String,
        scheduledAt: String,
        mediaType: String = "text",
        replyToContent: String? = null,
        replyToSenderId: String? = null,
        replyToMediaType: String? = null,
        replyToMessageId: String? = null,
        onResult: (Boolean, String?) -> Unit,
    ) {
        viewModelScope.launch {
            val token = tokenManager.getToken() ?: run { onResult(false, "Kein Token"); return@launch }
            val clientId = java.util.UUID.randomUUID().toString()

            // "self_notes" ist keine gültige User-ID — auf eigene ID mappen
            val resolvedReceiverId = if (chatId == "self_notes") {
                _currentUser.value?.userId ?: run { onResult(false, "User nicht geladen"); return@launch }
            } else chatId

            val wireContent = if (mediaType == "text") {
                com.securechat.app.data.crypto.CryptoManager.encryptUniversal(chatId, content)
            } else content

            // v3 (UMK Conversation Key) ist geräteunabhängig → keine separaten Web-/Self-Blobs nötig.
            val isV3 = wireContent.startsWith("v3:")

            val webWireContent: String? = if (!isV3 && mediaType == "text" &&
                com.securechat.app.data.crypto.CryptoManager.hasWebSharedSecret(chatId)
            ) com.securechat.app.data.crypto.CryptoManager.encryptForWeb(chatId, content)
            else null

            val me = _currentUser.value
            val selfWebContent: String? = if (!isV3 && me != null &&
                com.securechat.app.data.crypto.CryptoManager.hasWebSharedSecret(me.userId)
            ) com.securechat.app.data.crypto.CryptoManager.encryptForWeb(me.userId, content)
            else null

            val req = ScheduleMessageRequest(
                receiverId = resolvedReceiverId,
                contentBlob = wireContent,
                scheduledAt = scheduledAt,
                selfContentBlob = selfWebContent,
                webContentBlob = webWireContent,
                clientMessageId = clientId,
                mediaType = mediaType,
                replyToContent = replyToContent,
                replyToSenderId = replyToSenderId,
                replyToMediaType = replyToMediaType,
                replyToMessageId = replyToMessageId,
            )
            try {
                val resp = apiService.scheduleMessage("Bearer $token", req)
                if (resp.isSuccessful) {
                    loadScheduledMessages()
                    onResult(true, null)
                } else {
                    onResult(false, resp.errorBody()?.string() ?: "Fehler beim Planen")
                }
            } catch (e: Exception) {
                Timber.tag("Chat").e(e, "scheduleMessage fehlgeschlagen")
                onResult(false, e.localizedMessage)
            }
        }
    }

    /** Storniert eine geplante Nachricht. */
    fun cancelScheduledMessage(id: String, onResult: (Boolean) -> Unit = {}) {
        viewModelScope.launch {
            val token = tokenManager.getToken() ?: return@launch
            try {
                val resp = apiService.cancelScheduledMessage("Bearer $token", id)
                if (resp.isSuccessful) {
                    _scheduledMessages.value = _scheduledMessages.value.filter { it.id != id }
                    onResult(true)
                } else {
                    onResult(false)
                }
            } catch (e: Exception) {
                Timber.tag("Chat").e(e, "cancelScheduledMessage fehlgeschlagen")
                onResult(false)
            }
        }
    }

    /**
     * Sendet eine einzelne ausstehende Nachricht (per localId) erneut. Für manuellen Retry per Long-Press.
     */
    fun retrySingleMessage(localId: Long) {
        viewModelScope.launch {
            val me = _currentUser.value ?: return@launch
            val msg = messageDao.getMessageByLocalId(localId) ?: return@launch
            if (msg.deliveryStatus != 0 || msg.mediaType != "text") return@launch
            val clientId = msg.clientMessageId ?: return@launch
            val content = msg.content ?: return@launch
            val chatId = msg.chatId

            val wireContent = com.securechat.app.data.crypto.CryptoManager.encryptUniversal(chatId, content)
            // v3 (UMK Conversation Key) ist geräteunabhängig → keine separaten Web-/Self-Blobs nötig.
            val isV3 = wireContent.startsWith("v3:")
            val webWireContent: String? = if (!isV3 && com.securechat.app.data.crypto.CryptoManager.hasWebSharedSecret(chatId)) {
                com.securechat.app.data.crypto.CryptoManager.encryptForWeb(chatId, content)
            } else null
            val selfWebContent: String? = if (!isV3 && com.securechat.app.data.crypto.CryptoManager.hasWebSharedSecret(me.userId)) {
                com.securechat.app.data.crypto.CryptoManager.encryptForWeb(me.userId, content)
            } else null

            val payload = buildMap<String, Any?> {
                put("content_blob", wireContent)
                put("media_type", msg.mediaType)
                put("client_message_id", clientId)
                put("sender_timestamp", msg.timestamp)
                if (webWireContent != null) put("web_content_blob", webWireContent)
                if (selfWebContent != null) put("self_content_blob", selfWebContent)
                if (msg.replyToContent != null) put("reply_to_content", msg.replyToContent)
                if (msg.replyToSenderId != null) put("reply_to_sender_id", msg.replyToSenderId)
                if (msg.replyToMediaType != null) put("reply_to_media_type", msg.replyToMediaType)
            }
            webSocketManager.sendMessage("message", chatId, payload)
            Timber.tag("Chat").d("Einzelne Pending-Nachricht erneut gesendet: localId=$localId chatId=$chatId")
        }
    }

    /**
     * Lädt eine Mediendatei hoch und sendet sie als Nachricht.
     * Für Videos: Placeholder-Nachricht (mediaUrl=null) wird sofort eingefügt,
     * der Upload-Fortschritt wird per _videoUploadProgress getrackt.
     */
    fun sendMediaMessage(chatId: String, uri: Uri, mediaType: String) {
        val clientId = UUID.randomUUID().toString()
        val job = viewModelScope.launch {
            _isLoading.value = true
            val me = _currentUser.value ?: return@launch
            if (_userPrefs.value.decentralizedMode && (mediaType == "image" || mediaType == "video" || mediaType == "circle_video")) {
                _isLoading.value = false
                _statusMessage.value = "Dezentral-Modus: Bild- und Videoversand sind deaktiviert."
                return@launch
            }

            // Videos, Musik und Sprachnachrichten: Placeholder sofort in den Chat einfügen
            if (mediaType == "video" || mediaType == "circle_video" || mediaType == "audio_music" || mediaType == "audio") {
                messageDao.insertMessage(
                    MessageEntity(
                        chatId = chatId,
                        senderId = me.userId,
                        receiverId = chatId,
                        content = "[$mediaType]",
                        mediaType = mediaType,
                        mediaUrl = null,
                        timestamp = System.currentTimeMillis(),
                        isSent = false,
                        clientMessageId = clientId,
                        deliveryStatus = 0
                    )
                )
                if (mediaType == "video" || mediaType == "circle_video") {
                    _videoUploadProgress.update { it + (clientId to -1f) }
                } else if (mediaType == "audio_music") {
                    _uploadProgress.value = 0f
                } else {
                    _voiceUploadProgress.value = 0f
                }
            }

            try {
                // Für Videos: lokal transkodieren (H.264 max 720p), dann hochladen
                val fileToUpload: File
                val mimeType: String
                var originalFileName: String? = null
                if (mediaType == "video" || mediaType == "circle_video") {
                    // Von Lethe erstellte Videos (Editor-Ausgabe) sind bereits
                    // komprimiert → direkt hochladen (Passthrough), zu große
                    // Editor-Videos werden dennoch heruntertranskodiert.
                    fileToUpload = prepareVideoForUpload(uri, clientId)
                    mimeType = "video/mp4"

                    // Thumbnail aus der lokalen Datei generieren, bevor sie gelöscht wird
                    withContext(Dispatchers.IO) {
                        runCatching {
                            val retriever = MediaMetadataRetriever()
                            retriever.setDataSource(fileToUpload.absolutePath)
                            val frame = retriever.getFrameAtTime(
                                0L, MediaMetadataRetriever.OPTION_CLOSEST_SYNC
                            )
                            retriever.release()
                            if (frame != null) {
                                val scaled = scaleBitmapToMaxWidth(frame, 320)
                                if (frame !== scaled) frame.recycle()
                                _videoThumbnailCache.put(clientId, scaled)
                                _videoThumbnailMap.value = buildMap { putAll(_videoThumbnailCache.snapshot()) }
                            }
                        }
                    }

                    // Transkodierung fertig → jetzt Upload-Phase (0–99 %)
                    _videoUploadProgress.update { it + (clientId to 0f) }
                } else if (mediaType == "audio_music") {
                    // Originale Dateiendung beibehalten (mp3, flac, ogg…) damit MediaMetadataRetriever
                    // auf dem Server die ID3-Tags korrekt auslesen kann
                    val displayName = context.contentResolver.query(
                        uri, arrayOf(android.provider.OpenableColumns.DISPLAY_NAME), null, null, null
                    )?.use { c -> if (c.moveToFirst()) c.getString(0) else null }
                        ?: "audio_${System.currentTimeMillis()}.mp3"
                    originalFileName = displayName
                    val ext = displayName.substringAfterLast('.', "mp3").lowercase()
                    val cacheFile = File(context.cacheDir, "music_${System.currentTimeMillis()}.$ext")
                    withContext(Dispatchers.IO) {
                        context.contentResolver.openInputStream(uri)?.use { input ->
                            java.io.FileOutputStream(cacheFile).use { out -> input.copyTo(out) }
                        }
                    }
                    fileToUpload = cacheFile
                    mimeType = "audio/*"
                } else {
                    val rawFile = uriToFile(uri, mediaType) ?: throw Exception("Datei nicht lesbar")
                    if (mediaType == "image") {
                        val speedMbps = SpeedTestHelper.getLastUploadSpeedMbps(context)
                        fileToUpload = prepareImageForUpload(rawFile, clientId, speedMbps)
                    } else {
                        fileToUpload = rawFile
                    }
                    mimeType = when (mediaType) {
                        "image" -> "image/jpeg"
                        "audio" -> "audio/*"
                        else -> "*/*"
                    }
                }

                // Sprachnachricht: bei aktivem Toggle Ende-zu-Ende verschlüsseln (Conversation Key).
                // Kein Key vorhanden (z. B. noch kein Kontakt-Handshake) → stiller Fallback auf
                // unverschlüsselten Versand, analog zum bestehenden Verhalten bei Textnachrichten.
                var effectiveMediaType = mediaType
                if (mediaType == "audio" && _userPrefs.value.mediaEncryptionEnabled) {
                    val encrypted = com.securechat.app.data.crypto.CryptoManager
                        .encryptBytesWithConversationKey(chatId, fileToUpload.readBytes())
                    if (encrypted != null) {
                        withContext(Dispatchers.IO) { fileToUpload.writeBytes(encrypted) }
                        effectiveMediaType = "audio_e2ee"
                    }
                }

                // Bild-Placeholder sofort einfügen (mediaUrl=null → schwarzer Platzhalter mit Fortschritt)
                if (mediaType == "image") {
                    messageDao.insertMessage(
                        MessageEntity(
                            chatId = chatId,
                            senderId = me.userId,
                            receiverId = chatId,
                            content = "[image]",
                            mediaType = "image",
                            mediaUrl = null,
                            timestamp = System.currentTimeMillis(),
                            isSent = false,
                            clientMessageId = clientId,
                            deliveryStatus = 0
                        )
                    )
                    _imageUploadProgress.update { it + (clientId to 0f) }
                }

                // Upload-Größenlimit prüfen (80 MB)
                if (fileToUpload.length() > MAX_UPLOAD_BYTES) {
                    if (mediaType == "video" || mediaType == "circle_video") {
                        messageDao.deleteMessageByClientId(clientId)
                        _videoUploadProgress.update { it - clientId }
                    } else if (mediaType == "audio_music") {
                        messageDao.deleteMessageByClientId(clientId)
                        _uploadProgress.value = -1f
                        _mediaUploadStatus.value = MediaUploadStatus.Idle
                    } else if (mediaType == "audio") {
                        messageDao.deleteMessageByClientId(clientId)
                        _voiceUploadProgress.value = -1f
                    }
                    _statusMessage.value = "Datei zu groß (max. 80 MB)"
                    _isLoading.value = false
                    return@launch
                }

                val rawRequest = fileToUpload.asRequestBody(mimeType.toMediaTypeOrNull())
                val requestFile = when (mediaType) {
                    "video", "circle_video" -> ProgressRequestBody(
                        delegate = rawRequest,
                        onProgress = { sent, total ->
                            if (total > 0) {
                                val pct = (sent * 100f / total).coerceIn(0f, 99f)
                                _videoUploadProgress.update { it + (clientId to pct) }
                            }
                        }
                    )
                    "audio_music" -> ProgressRequestBody(
                        delegate = rawRequest,
                        onProgress = { sent, total ->
                            if (total > 0) {
                                val pct = (sent.toFloat() / total * 100).toInt().coerceIn(0, 99)
                                _uploadProgress.value = sent.toFloat() / total
                                _mediaUploadStatus.value = MediaUploadStatus.Uploading(pct)
                            }
                        }
                    )
                    "audio" -> ProgressRequestBody(
                        delegate = rawRequest,
                        onProgress = { sent, total ->
                            if (total > 0) {
                                _voiceUploadProgress.value = (sent.toFloat() / total).coerceIn(0f, 0.99f)
                            }
                        }
                    )
                    "image" -> ProgressRequestBody(
                        delegate = rawRequest,
                        onProgress = { sent, total ->
                            if (total > 0) {
                                val pct = (sent * 100f / total).coerceIn(0f, 99f)
                                _imageUploadProgress.update { it + (clientId to pct) }
                            }
                        }
                    )
                    else -> rawRequest
                }

                val body = MultipartBody.Part.createFormData("file", originalFileName ?: fileToUpload.name, requestFile)
                val uploadType = if (mediaType == "circle_video") "video" else effectiveMediaType
                val typeBody = uploadType.toRequestBody("text/plain".toMediaTypeOrNull())
                val response = apiService.uploadMedia(typeBody, body)

                // Temporäre Dateien aufräumen
                if (mediaType == "video" || mediaType == "circle_video" || mediaType == "audio_music") {
                    withContext(Dispatchers.IO) { fileToUpload.delete() }
                }

                if (response.isSuccessful) {
                    val mediaUrl = response.body()?.get("url")?.let { toAbsoluteUrl(it) }
                    if (mediaUrl != null) {
                        val label = "[$mediaType]"
                        if (mediaType == "video" || mediaType == "circle_video") {
                            messageDao.updateMessageUrl(clientId, mediaUrl)
                            _videoUploadProgress.update { it - clientId }
                            // Thumbnail auch unter der Server-URL zugänglich machen
                            _videoThumbnailCache.get(clientId)?.let { thumb ->
                                _videoThumbnailCache.put(mediaUrl, thumb)
                                _videoThumbnailMap.value = buildMap { putAll(_videoThumbnailCache.snapshot()) }
                            }
                        } else if (mediaType == "audio_music") {
                            // Placeholder-Nachricht mit der echten URL aktualisieren
                            messageDao.updateMessageUrl(clientId, mediaUrl)
                            // Server-seitig ausgelesene ID3-Metadaten (Titel/Artist/Cover/Dauer)
                            // sofort unter der Server-URL cachen → Cover+Titel erscheinen ohne
                            // den unzuverlässigen MediaMetadataRetriever-über-HTTP-Fallback.
                            try {
                                val body = response.body()
                                val srvTitle = body?.get("title")?.takeIf { it.isNotBlank() }
                                val srvArtist = body?.get("artist")?.takeIf { it.isNotBlank() }
                                val srvCoverUrl = body?.get("cover_url")?.let { toAbsoluteUrl(it) }
                                val srvDurMs = body?.get("duration")?.toDoubleOrNull()?.let { (it * 1000).toLong() } ?: 0L
                                _musicTitleArtistCache[mediaUrl] = Pair(srvTitle, srvArtist)
                                var coverPath: String? = null
                                if (srvCoverUrl != null) {
                                    val art = withContext(Dispatchers.IO) {
                                        try {
                                            val conn = java.net.URL(srvCoverUrl).openConnection() as java.net.HttpURLConnection
                                            conn.connectTimeout = 8000; conn.readTimeout = 8000
                                            conn.inputStream.use { it.readBytes() }
                                        } catch (_: Exception) { null }
                                    }
                                    if (art != null) {
                                        val bm = decodeSampledBitmap(art)
                                        if (bm != null) {
                                            _musicCoverCache.put(mediaUrl, bm)
                                            val coverDir = java.io.File(context.cacheDir, "music_covers").also { it.mkdirs() }
                                            val file = java.io.File(coverDir, "${mediaUrl.hashCode()}.jpg")
                                            try {
                                                withContext(Dispatchers.IO) { file.outputStream().use { it.write(art) } }
                                                coverPath = file.absolutePath
                                            } catch (_: Exception) {}
                                        }
                                    }
                                }
                                musicMetadataDao.upsert(com.securechat.app.data.local.MusicMetadataEntity(
                                    url = mediaUrl,
                                    title = srvTitle,
                                    artist = srvArtist,
                                    coverPath = coverPath,
                                    durationMs = srvDurMs,
                                    cachedAt = System.currentTimeMillis()
                                ))
                            } catch (_: Exception) {}
                            _uploadProgress.value = -1f
                            _mediaUploadStatus.value = MediaUploadStatus.Idle
                        } else if (mediaType == "audio") {
                            // Sprachnachricht: Placeholder mit echter URL (+ ggf. audio_e2ee) aktualisieren
                            messageDao.updateMessageUrlAndMediaType(clientId, mediaUrl, effectiveMediaType)
                            _voiceUploadProgress.value = -1f
                            // Waveform-Cache-Key von lokalem Dateipfad auf Server-URL umschreiben
                            uri.path?.let { localPath ->
                                _waveformCache.get(localPath)?.let { wf ->
                                    _waveformCache.put(mediaUrl, wf)
                                    _waveformMap.value = buildMap { putAll(_waveformCache.snapshot()) }
                                }
                            }
                            withContext(Dispatchers.IO) { fileToUpload.delete() }
                        } else if (mediaType == "image") {
                            // Placeholder → Server-URL aktualisieren + Fortschritt entfernen
                            messageDao.updateMessageUrl(clientId, mediaUrl)
                            _imageUploadProgress.update { it - clientId }
                            _failedUploads.update { it - clientId }
                            withContext(Dispatchers.IO) { fileToUpload.delete() }
                        } else {
                            messageDao.insertMessage(
                                MessageEntity(
                                    chatId = chatId,
                                    senderId = me.userId,
                                    receiverId = chatId,
                                    content = label,
                                    mediaType = mediaType,
                                    mediaUrl = mediaUrl,
                                    timestamp = System.currentTimeMillis(),
                                    isSent = chatId == "self_notes",
                                    clientMessageId = clientId,
                                    deliveryStatus = if (chatId == "self_notes") 3 else 0
                                )
                            )
                        }
                        if (chatId == "self_notes") {
                            messageDao.markSelfNoteDelivered(clientId)
                        } else {
                            webSocketManager.sendMessage("message", chatId, mapOf(
                                "content_blob" to label,
                                "media_type" to effectiveMediaType,
                                "media_url" to mediaUrl,
                                "client_message_id" to clientId
                            ))
                        }
                    }
                } else {
                    if (mediaType == "video" || mediaType == "circle_video") {
                        _videoUploadProgress.update { it + (clientId to -2f) }
                        _failedUploads.update { it + (clientId to PendingUpload(chatId, uri, mediaType, clientId)) }
                    } else if (mediaType == "audio_music") {
                        messageDao.deleteMessageByClientId(clientId)
                        _uploadProgress.value = -1f
                        _mediaUploadStatus.value = MediaUploadStatus.Idle
                    } else if (mediaType == "audio") {
                        messageDao.deleteMessageByClientId(clientId)
                        _voiceUploadProgress.value = -1f
                    } else if (mediaType == "image") {
                        _imageUploadProgress.update { it + (clientId to -2f) }
                        _failedUploads.update { it + (clientId to PendingUpload(chatId, uri, mediaType, clientId)) }
                    }
                    _statusMessage.value = "Upload fehlgeschlagen (${response.code()})"
                }
            } catch (e: kotlinx.coroutines.CancellationException) {
                // Upload abgebrochen → für Wiederholen markieren
                if (mediaType == "video" || mediaType == "circle_video") {
                    _videoUploadProgress.update { it + (clientId to -2f) }
                    _failedUploads.update { it + (clientId to PendingUpload(chatId, uri, mediaType, clientId)) }
                } else if (mediaType == "audio_music") {
                    messageDao.deleteMessageByClientId(clientId)
                    _uploadProgress.value = -1f
                    _mediaUploadStatus.value = MediaUploadStatus.Idle
                } else if (mediaType == "audio") {
                    messageDao.deleteMessageByClientId(clientId)
                    _voiceUploadProgress.value = -1f
                } else if (mediaType == "image") {
                    _imageUploadProgress.update { it + (clientId to -2f) }
                    _failedUploads.update { it + (clientId to PendingUpload(chatId, uri, mediaType, clientId)) }
                }
                Timber.tag("Chat").d("sendMediaMessage abgebrochen: $clientId")
            } catch (e: Exception) {
                if (mediaType == "video" || mediaType == "circle_video") {
                    _videoUploadProgress.update { it + (clientId to -2f) }
                    _failedUploads.update { it + (clientId to PendingUpload(chatId, uri, mediaType, clientId)) }
                } else if (mediaType == "audio_music") {
                    messageDao.deleteMessageByClientId(clientId)
                    _uploadProgress.value = -1f
                    _mediaUploadStatus.value = MediaUploadStatus.Idle
                } else if (mediaType == "audio") {
                    messageDao.deleteMessageByClientId(clientId)
                    _voiceUploadProgress.value = -1f
                } else if (mediaType == "image") {
                    _imageUploadProgress.update { it + (clientId to -2f) }
                    _failedUploads.update { it + (clientId to PendingUpload(chatId, uri, mediaType, clientId)) }
                }
                _statusMessage.value = "Upload fehlgeschlagen: ${e.message}"
                Timber.tag("Chat").e("sendMediaMessage failed", e)
            } finally {
                _isLoading.value = false
                activeUploadJobs.remove(clientId)
            }
        }
        activeUploadJobs[clientId] = job
    }

    /**
     * Lädt ein Bild im Hintergrund hoch. Erstellt sofort einen Placeholder im Chat
     * (schwarzes Bild mit Fortschrittsanzeige). Gibt sofort true zurück damit der
     * ImageEditor den Chat anzeigen kann. Upload + WS-Dispatch laufen asynchron.
     */
    suspend fun sendImageMessageSuspend(chatId: String, uri: Uri, isGroup: Boolean = false): Boolean {
        val me = _currentUser.value ?: return false
        if (_userPrefs.value.decentralizedMode) {
            _statusMessage.value = "Dezentral-Modus: Bildversand ist deaktiviert."
            return false
        }
        val clientId = UUID.randomUUID().toString()

        // Placeholder sofort einfügen (mediaUrl = null → schwarzer Platzhalter im Chat)
        messageDao.insertMessage(
            MessageEntity(
                chatId = chatId,
                senderId = me.userId,
                receiverId = chatId,
                content = "[image]",
                mediaType = "image",
                mediaUrl = null,
                timestamp = System.currentTimeMillis(),
                isSent = false,
                clientMessageId = clientId,
                deliveryStatus = 0
            )
        )
        _imageUploadProgress.update { it + (clientId to 0f) }

        // Upload im Hintergrund starten
        val job = viewModelScope.launch {
            try {
                val speedMbps = SpeedTestHelper.getLastUploadSpeedMbps(context)
                val rawFile = uriToFile(uri, "image") ?: throw Exception("Datei nicht lesbar")
                val fileToUpload = prepareImageForUpload(rawFile, clientId, speedMbps)

                val rawRequest = fileToUpload.asRequestBody("image/jpeg".toMediaTypeOrNull())
                val requestFile = ProgressRequestBody(
                    delegate = rawRequest,
                    onProgress = { sent, total ->
                        if (total > 0) {
                            val pct = (sent * 100f / total).coerceIn(0f, 99f)
                            _imageUploadProgress.update { it + (clientId to pct) }
                        }
                    }
                )
                val body = MultipartBody.Part.createFormData("file", fileToUpload.name, requestFile)
                val typeBody = "image".toRequestBody("text/plain".toMediaTypeOrNull())
                val response = apiService.uploadMedia(typeBody, body)
                withContext(Dispatchers.IO) { fileToUpload.delete() }

                if (response.isSuccessful) {
                    val mediaUrl = response.body()?.get("url")?.let { toAbsoluteUrl(it) }
                    if (mediaUrl != null) {
                        messageDao.updateMessageUrl(clientId, mediaUrl)
                        _imageUploadProgress.update { it - clientId }
                        _failedUploads.update { it - clientId }
                        activeUploadJobs.remove(clientId)
                        if (chatId == "self_notes") {
                            messageDao.markSelfNoteDelivered(clientId)
                        } else if (isGroup) {
                            webSocketManager.sendMessage("group_message", chatId, mapOf(
                                "content_blob" to "[image]",
                                "media_type" to "image",
                                "media_url" to mediaUrl,
                                "group_id" to chatId,
                                "client_message_id" to clientId,
                                "sender_timestamp" to System.currentTimeMillis()
                            ))
                        } else {
                            webSocketManager.sendMessage("message", chatId, mapOf(
                                "content_blob" to "[image]",
                                "media_type" to "image",
                                "media_url" to mediaUrl,
                                "client_message_id" to clientId
                            ))
                        }
                    } else {
                        markImageUploadFailed(clientId, chatId, uri, "image", isGroup)
                    }
                } else {
                    markImageUploadFailed(clientId, chatId, uri, "image", isGroup)
                    _statusMessage.value = "Upload fehlgeschlagen (${response.code()})"
                }
            } catch (e: kotlinx.coroutines.CancellationException) {
                // Abgebrochen durch Benutzer → als fehlgeschlagen markieren für Wiederholen
                markImageUploadFailed(clientId, chatId, uri, "image", isGroup)
                Timber.tag("Chat").d("Bild-Upload abgebrochen: $clientId")
            } catch (e: Exception) {
                markImageUploadFailed(clientId, chatId, uri, "image", isGroup)
                _statusMessage.value = "Upload fehlgeschlagen: ${e.message}"
                Timber.tag("Chat").e("sendImageMessageSuspend failed", e)
            }
        }
        activeUploadJobs[clientId] = job
        return true // Sofort zurückgeben, Chat wird angezeigt
    }

    /**
     * Lädt mehrere Bilder im Hintergrund hoch. Erstellt sofort einen Placeholder
     * und navigiert den User zurück zum Chat.
     */
    suspend fun sendMultiImageMessageSuspend(chatId: String, uris: List<Uri>, isGroup: Boolean = false): Boolean {
        if (uris.isEmpty()) return false
        if (uris.size == 1) return sendImageMessageSuspend(chatId, uris[0], isGroup)
        val me = _currentUser.value ?: return false
        val clientId = UUID.randomUUID().toString()

        // Placeholder sofort einfügen
        messageDao.insertMessage(
            MessageEntity(
                chatId = chatId,
                senderId = me.userId,
                receiverId = chatId,
                content = "[multi_image]",
                mediaType = "multi_image",
                mediaUrl = null,
                timestamp = System.currentTimeMillis(),
                isSent = false,
                clientMessageId = clientId,
                deliveryStatus = 0
            )
        )
        _imageUploadProgress.update { it + (clientId to 0f) }

        val job = viewModelScope.launch {
            try {
                val speedMbps = SpeedTestHelper.getLastUploadSpeedMbps(context)
                val urls = mutableListOf<String>()
                for ((index, uri) in uris.withIndex()) {
                    val rawFile = uriToFile(uri, "image") ?: throw Exception("Datei nicht lesbar")
                    val fileToUpload = prepareImageForUpload(rawFile, clientId, speedMbps)
                    val rawRequest = fileToUpload.asRequestBody("image/jpeg".toMediaTypeOrNull())
                    val requestFile = ProgressRequestBody(
                        delegate = rawRequest,
                        onProgress = { sent, total ->
                            if (total > 0) {
                                // Gesamt-Fortschritt: (abgeschlossene Bilder + aktueller Fortschritt) / Gesamtanzahl
                                val singlePct = sent.toFloat() / total
                                val overallPct = ((index + singlePct) / uris.size * 100f).coerceIn(0f, 99f)
                                _imageUploadProgress.update { it + (clientId to overallPct) }
                            }
                        }
                    )
                    val body = MultipartBody.Part.createFormData("file", fileToUpload.name, requestFile)
                    val typeBody = "image".toRequestBody("text/plain".toMediaTypeOrNull())
                    val response = apiService.uploadMedia(typeBody, body)
                    withContext(Dispatchers.IO) { fileToUpload.delete() }
                    if (response.isSuccessful) {
                        val url = response.body()?.get("url") ?: throw Exception("URL fehlt")
                        urls.add(url)
                    } else {
                        throw Exception("Upload fehlgeschlagen (${response.code()})")
                    }
                }
                val urlsJson = com.google.gson.Gson().toJson(urls)
                messageDao.updateMessageUrl(clientId, urlsJson)
                _imageUploadProgress.update { it - clientId }
                _failedUploads.update { it - clientId }
                activeUploadJobs.remove(clientId)
                if (chatId == "self_notes") {
                    messageDao.markSelfNoteDelivered(clientId)
                } else if (isGroup) {
                    webSocketManager.sendMessage("group_message", chatId, mapOf(
                        "content_blob" to "[multi_image]",
                        "media_type" to "multi_image",
                        "media_url" to urlsJson,
                        "group_id" to chatId,
                        "client_message_id" to clientId,
                        "sender_timestamp" to System.currentTimeMillis()
                    ))
                } else {
                    webSocketManager.sendMessage("message", chatId, mapOf(
                        "content_blob" to "[multi_image]",
                        "media_type" to "multi_image",
                        "media_url" to urlsJson,
                        "client_message_id" to clientId
                    ))
                }
            } catch (e: kotlinx.coroutines.CancellationException) {
                markImageUploadFailed(clientId, chatId, uris[0], "multi_image", isGroup)
                Timber.tag("Chat").d("Multi-Bild-Upload abgebrochen: $clientId")
            } catch (e: Exception) {
                markImageUploadFailed(clientId, chatId, uris[0], "multi_image", isGroup)
                _statusMessage.value = "Upload fehlgeschlagen: ${e.message}"
                Timber.tag("Chat").e("sendMultiImageMessageSuspend failed", e)
            }
        }
        activeUploadJobs[clientId] = job
        return true
    }

    /** Markiert einen Bild-Upload als fehlgeschlagen und speichert die Daten für Wiederholen. */
    private fun markImageUploadFailed(clientId: String, chatId: String, uri: Uri, mediaType: String, isGroup: Boolean) {
        _imageUploadProgress.update { it + (clientId to -2f) } // -2 = fehlgeschlagen
        _failedUploads.update { it + (clientId to PendingUpload(chatId, uri, mediaType, clientId, isGroup)) }
        activeUploadJobs.remove(clientId)
    }

    /** Bricht einen laufenden Upload ab. */
    fun cancelUpload(clientId: String) {
        activeUploadJobs[clientId]?.cancel()
        activeUploadJobs.remove(clientId)
        // Fortschritt auf -2 setzen (fehlgeschlagen) um "Wiederholen" anzuzeigen
        if (_imageUploadProgress.value.containsKey(clientId)) {
            _imageUploadProgress.update { it + (clientId to -2f) }
        }
        if (_videoUploadProgress.value.containsKey(clientId)) {
            _videoUploadProgress.update { it + (clientId to -2f) }
        }
    }

    /** Versucht einen fehlgeschlagenen Upload erneut. */
    fun retryUpload(clientId: String) {
        val pending = _failedUploads.value[clientId] ?: return
        // Alte Nachricht + Daten entfernen
        viewModelScope.launch {
            messageDao.deleteMessageByClientId(clientId)
            _imageUploadProgress.update { it - clientId }
            _videoUploadProgress.update { it - clientId }
            _failedUploads.update { it - clientId }
            // Neuen Upload starten
            if (pending.mediaType == "image" || pending.mediaType == "multi_image") {
                sendImageMessageSuspend(pending.chatId, pending.uri, pending.isGroup)
            } else {
                sendMediaMessage(pending.chatId, pending.uri, pending.mediaType)
            }
        }
    }

    /** Lädt eine 3D-Datei (STL/3MF/OBJ) hoch und sendet sie als Nachricht mit Preview. */
    fun send3DFileMessage(chatId: String, uri: Uri, textureUri: Uri? = null, isGroup: Boolean = false, price: Int = 0) {
        viewModelScope.launch {
            _mediaUploadStatus.value = MediaUploadStatus.Processing
            _isLoading.value = true
            val me = _currentUser.value ?: return@launch
            try {
                // Originalname + Tempfile auf IO-Thread erstellen (gleich wie uriToFile)
                val originalName = withContext(Dispatchers.IO) {
                    context.contentResolver.query(uri, null, null, null, null)?.use { c ->
                        val idx = c.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME)
                        if (c.moveToFirst() && idx >= 0) c.getString(idx) else null
                    } ?: "model.stl"
                }
                val tempFile = withContext(Dispatchers.IO) {
                    val f = File(context.cacheDir, "threed_${System.currentTimeMillis()}_$originalName")
                    context.contentResolver.openInputStream(uri)?.use { input ->
                        FileOutputStream(f).use { output -> input.copyTo(output) }
                    }
                    f
                }

                // Upload-Größenlimit prüfen (80 MB)
                if (tempFile.length() > MAX_UPLOAD_BYTES) {
                    withContext(Dispatchers.IO) { tempFile.delete() }
                    _statusMessage.value = "Datei zu groß (max. 80 MB)"
                    _mediaUploadStatus.value = MediaUploadStatus.Idle
                    _isLoading.value = false
                    return@launch
                }

                val requestFile = tempFile.asRequestBody("application/octet-stream".toMediaTypeOrNull())
                val body = MultipartBody.Part.createFormData("file", originalName, requestFile)
                _mediaUploadStatus.value = MediaUploadStatus.Uploading(0)
                val response = apiService.upload3dFile(body)

                withContext(Dispatchers.IO) { tempFile.delete() }

                if (response.isSuccessful) {
                    val upload = response.body() ?: run {
                        _statusMessage.value = "3D-Upload: Keine Server-Antwort (Body null)"
                        Timber.tag("Chat").e("send3DFileMessage: response.body() is null despite 200")
                        return@launch
                    }
                    _mediaUploadStatus.value = MediaUploadStatus.GeneratingPreview
                    val absFileUrl    = toAbsoluteUrl(upload.fileUrl)
                    val absPreviewUrl = toAbsoluteUrl(upload.previewUrl)
                    // Optionaler Textur-Upload für OBJ-Dateien
                    var absTextureUrl = ""
                    if (textureUri != null) {
                        try {
                            val texName = withContext(Dispatchers.IO) {
                                context.contentResolver.query(textureUri, null, null, null, null)?.use { c ->
                                    val idx = c.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME)
                                    if (c.moveToFirst() && idx >= 0) c.getString(idx) else null
                                } ?: "texture.jpg"
                            }
                            val texFile = withContext(Dispatchers.IO) {
                                val f = File(context.cacheDir, "tex_${System.currentTimeMillis()}_$texName")
                                context.contentResolver.openInputStream(textureUri)?.use { input ->
                                    FileOutputStream(f).use { output -> input.copyTo(output) }
                                }
                                f
                            }
                            val texBody = MultipartBody.Part.createFormData("file", texName, texFile.asRequestBody("image/*".toMediaTypeOrNull()))
                            val texResponse = apiService.upload3dFile(texBody)
                            withContext(Dispatchers.IO) { texFile.delete() }
                            if (texResponse.isSuccessful) {
                                absTextureUrl = toAbsoluteUrl(texResponse.body()?.fileUrl ?: "")
                            }
                        } catch (e: Exception) {
                            Timber.tag("Chat").w("Textur-Upload fehlgeschlagen: ${e.message}")
                        }
                    }
                    val contentBlob = JSONObject().apply {
                        put("file_url", absFileUrl)
                        put("preview_url", absPreviewUrl)
                        put("filename", upload.filename)
                        put("file_size", upload.fileSize)
                        if (absTextureUrl.isNotEmpty()) put("texture_url", absTextureUrl)
                        if (price > 0) put("price", price)
                    }.toString()
                    val clientId = UUID.randomUUID().toString()
                    messageDao.insertMessage(
                        MessageEntity(
                            chatId = chatId,
                            senderId = me.userId,
                            receiverId = chatId,
                            content = contentBlob,
                            mediaType = "3dprint",
                            mediaUrl = absFileUrl,
                            timestamp = System.currentTimeMillis(),
                            isSent = false,
                            clientMessageId = clientId,
                            deliveryStatus = 0
                        )
                    )
                    Timber.tag("Chat").d("3D-Datei in Room eingefügt: chatId=$chatId mediaType=3dprint content=${contentBlob.take(80)}")
                    if (isGroup) {
                        webSocketManager.sendMessage("group_message", chatId, mapOf(
                            "content_blob" to contentBlob,
                            "media_type" to "3dprint",
                            "media_url" to absFileUrl,
                            "group_id" to chatId,
                            "client_message_id" to clientId,
                            "sender_timestamp" to System.currentTimeMillis()
                        ))
                    } else {
                        webSocketManager.sendMessage("message", chatId, mapOf(
                            "content_blob" to contentBlob,
                            "media_type" to "3dprint",
                            "media_url" to absFileUrl,
                            "client_message_id" to clientId
                        ))
                    }
                } else {
                    val errorBody = response.errorBody()?.string() ?: ""
                    _statusMessage.value = "3D-Upload fehlgeschlagen (${response.code()}): $errorBody"
                    Timber.tag("Chat").e("3D-Upload HTTP ${response.code()}: $errorBody")
                }
            } catch (e: Exception) {
                _statusMessage.value = "3D-Upload fehlgeschlagen: ${e.message}"
                Timber.tag("Chat").e("send3DFileMessage failed", e)
            } finally {
                _mediaUploadStatus.value = MediaUploadStatus.Idle
                _isLoading.value = false
            }
        }
    }

    /**
     * Kauft eine kostenpflichtige 3D-Datei: zieht Styx ab und gibt das neue Guthaben zurück.
     * Der Preis wird serverseitig aus der Nachricht (messageId) gelesen - hier NICHT mitgesendet,
     * damit ein manipulierter Client keinen niedrigeren Preis erzwingen kann.
     */
    fun purchase3DFile(
        messageId: String,
        onSuccess: (newBalance: Int) -> Unit,
        onError: (String) -> Unit
    ) {
        viewModelScope.launch {
            try {
                val response = apiService.purchase3DFile(
                    mapOf("message_id" to messageId)
                )
                if (response.isSuccessful) {
                    val body = response.body()
                    if (body?.success == true) {
                        val newBal = body.newBalance
                        _currentUser.value?.let { user ->
                            val updated = user.copy(styx = newBal)
                            userDao.insertUser(updated)
                            _currentUser.value = updated
                        }
                        onSuccess(newBal)
                    } else {
                        onError(body?.message ?: "Zahlung fehlgeschlagen")
                    }
                } else {
                    onError("Fehler ${response.code()}")
                }
            } catch (e: Exception) {
                onError(e.message ?: "Unbekannter Fehler")
            }
        }
    }

    // --- STATUS ERSTELLEN ---

    /** Lädt einen Status-Beitrag (Bild, Video oder Audio) hoch. */
    fun createStatus(
        uri: Uri,
        mediaType: String,
        durationHours: Int = 24,
        asLetheTeam: Boolean = false,
        musicUrl: String? = null,
        musicTitle: String? = null,
        musicArtist: String? = null,
        musicDurationSec: Int? = null,
        musicOffsetSec: Float? = null,
        linkUrl: String? = null,
        linkLabel: String? = null,
        onResult: (Boolean) -> Unit
    ) {
        viewModelScope.launch {
            _isLoading.value = true
            try {
                var file = uriToFile(uri, mediaType) ?: throw Exception("Datei nicht lesbar")
                if (mediaType == "image") file = fixImageOrientation(file)
                val mimeType = when (mediaType) {
                    "image" -> "image/*"
                    "video" -> "video/*"
                    "audio" -> "audio/*"
                    else -> "*/*"
                }
                val requestFile = file.asRequestBody(mimeType.toMediaTypeOrNull())
                val body = MultipartBody.Part.createFormData("file", file.name, requestFile)
                val durationBody = durationHours.toString().toRequestBody("text/plain".toMediaTypeOrNull())
                val typeBody = mediaType.toRequestBody("text/plain".toMediaTypeOrNull())
                val letheTeamBody = asLetheTeam.toString().toRequestBody("text/plain".toMediaTypeOrNull())
                val musicUrlBody = musicUrl?.toRequestBody("text/plain".toMediaTypeOrNull())
                val musicTitleBody = musicTitle?.toRequestBody("text/plain".toMediaTypeOrNull())
                val musicArtistBody = musicArtist?.toRequestBody("text/plain".toMediaTypeOrNull())
                val musicDurBody = musicDurationSec?.toString()?.toRequestBody("text/plain".toMediaTypeOrNull())
                val musicOffBody = musicOffsetSec?.toString()?.toRequestBody("text/plain".toMediaTypeOrNull())
                val linkUrlBody = linkUrl?.takeIf { it.isNotBlank() }?.toRequestBody("text/plain".toMediaTypeOrNull())
                val linkLabelBody = linkLabel?.takeIf { it.isNotBlank() }?.toRequestBody("text/plain".toMediaTypeOrNull())
                val response = apiService.createStatus(durationBody, typeBody, body, letheTeamBody, musicUrlBody, musicTitleBody, musicArtistBody, musicDurBody, musicOffBody, linkUrlBody, linkLabelBody)
                if (response.isSuccessful) {
                    _statusMessage.value = if (asLetheTeam) "Als Lethe Team veröffentlicht ✓" else "Status wurde veröffentlicht ✓"
                    loadContactStatuses()
                    loadMyStatuses()
                    onResult(true)
                } else {
                    _statusMessage.value = "Status-Upload fehlgeschlagen (${response.code()})"
                    onResult(false)
                }
            } catch (e: Exception) {
                _statusMessage.value = "Fehler: ${e.message}"
                Timber.tag("Status").e("createStatus failed", e)
                onResult(false)
            } finally {
                _isLoading.value = false
            }
        }
    }

    /** Erstellt mehrere Statuses sequenziell (ein Status pro URI). */
    fun createMultipleStatuses(
        uris: List<Uri>,
        mediaType: String,
        durationHours: Int = 24,
        asLetheTeam: Boolean = false,
        musicUrl: String? = null,
        musicTitle: String? = null,
        musicArtist: String? = null,
        musicDurationSec: Int? = null,
        musicOffsetSec: Float? = null,
        linkUrl: String? = null,
        linkLabel: String? = null,
        onResult: (Boolean) -> Unit
    ) {
        viewModelScope.launch {
            _isLoading.value = true
            try {
                for (uri in uris) {
                    var file = uriToFile(uri, mediaType) ?: throw Exception("Datei nicht lesbar")
                    if (mediaType == "image") file = fixImageOrientation(file)
                    val mimeType = when (mediaType) {
                        "image" -> "image/*"
                        "video" -> "video/*"
                        "audio" -> "audio/*"
                        else -> "*/*"
                    }
                    val requestFile = file.asRequestBody(mimeType.toMediaTypeOrNull())
                    val body = MultipartBody.Part.createFormData("file", file.name, requestFile)
                    val durationBody = durationHours.toString().toRequestBody("text/plain".toMediaTypeOrNull())
                    val typeBody = mediaType.toRequestBody("text/plain".toMediaTypeOrNull())
                    val letheTeamBody = asLetheTeam.toString().toRequestBody("text/plain".toMediaTypeOrNull())
                    val musicUrlBody = musicUrl?.toRequestBody("text/plain".toMediaTypeOrNull())
                    val musicTitleBody = musicTitle?.toRequestBody("text/plain".toMediaTypeOrNull())
                    val musicArtistBody = musicArtist?.toRequestBody("text/plain".toMediaTypeOrNull())
                    val musicDurBody = musicDurationSec?.toString()?.toRequestBody("text/plain".toMediaTypeOrNull())
                    val musicOffBody = musicOffsetSec?.toString()?.toRequestBody("text/plain".toMediaTypeOrNull())
                    val linkUrlBody = linkUrl?.takeIf { it.isNotBlank() }?.toRequestBody("text/plain".toMediaTypeOrNull())
                    val linkLabelBody = linkLabel?.takeIf { it.isNotBlank() }?.toRequestBody("text/plain".toMediaTypeOrNull())
                    val response = apiService.createStatus(durationBody, typeBody, body, letheTeamBody, musicUrlBody, musicTitleBody, musicArtistBody, musicDurBody, musicOffBody, linkUrlBody, linkLabelBody)
                    if (!response.isSuccessful) {
                        _statusMessage.value = "Status-Upload fehlgeschlagen (${response.code()})"
                        onResult(false)
                        return@launch
                    }
                }
                _statusMessage.value = if (asLetheTeam) "Als Lethe Team veröffentlicht ✓" else "${uris.size} Statuse veröffentlicht ✓"
                loadContactStatuses()
                loadMyStatuses()
                onResult(true)
            } catch (e: Exception) {
                _statusMessage.value = "Fehler: ${e.message}"
                Timber.tag("Status").e("createMultipleStatuses failed", e)
                onResult(false)
            } finally {
                _isLoading.value = false
            }
        }
    }

