    /**
     * Prüft einmalig nach Login ob das Nearby-Profil deaktiviert ist und zeigt
     * ggf. einen Hinweis-Push an. Die Benachrichtigung wird nur einmal angezeigt
     * (Flag in SharedPreferences) und nur wenn das Profil nicht aktiv ist.
     */
    fun checkAndShowNearbyProfilePrompt() {
        viewModelScope.launch(Dispatchers.IO) {
            val prefs = context.getSharedPreferences("nearby_profile_prompt", android.content.Context.MODE_PRIVATE)
            if (prefs.getBoolean("prompt_shown", false)) return@launch
            try {
                val response = apiService.getMyNearbyProfile()
                if (response.isSuccessful) {
                    val profile = response.body()
                    if (profile == null || !profile.isActive) {
                        prefs.edit().putBoolean("prompt_shown", true).apply()
                        notificationHelper.showNearbyProfileActivationPromptNotification()
                    }
                }
            } catch (_: Exception) { }
        }
    }

