    fun reactToNearbyQuestion(questionId: String, emoji: String, profileUserId: String) {
        viewModelScope.launch {
            try {
                // Optimistisches Update
                val current = _nearbyAnonQuestions.value.toMutableMap()
                val list = current[profileUserId]?.toMutableList() ?: return@launch
                val idx = list.indexOfFirst { it.id == questionId }
                if (idx >= 0) {
                    val q = list[idx]
                    val oldEmoji = q.myReaction
                    val newReactions = q.reactions.toMutableMap()
                    if (oldEmoji != null) {
                        val prev = newReactions[oldEmoji] ?: 1
                        if (prev <= 1) newReactions.remove(oldEmoji) else newReactions[oldEmoji] = prev - 1
                    }
                    val newMyReaction: String? = if (oldEmoji == emoji) null else emoji
                    if (newMyReaction != null) newReactions[emoji] = (newReactions[emoji] ?: 0) + 1
                    list[idx] = q.copy(reactions = newReactions, myReaction = newMyReaction)
                    current[profileUserId] = list
                    _nearbyAnonQuestions.value = current
                }
                apiService.reactToNearbyQuestion(questionId, NearbyReactionRequest(emoji))
            } catch (_: Exception) {
                loadNearbyAnonQuestions(profileUserId)
            }
        }
    }

