    /** Beantwortet eine anonyme Frage, optional mit Bild-Upload. */
    fun answerNearbyQuestion(
        questionId: String,
        answer: String,
        imageUri: android.net.Uri?,
        onSuccess: () -> Unit,
        onError: (String) -> Unit
    ) {
        viewModelScope.launch {
            try {
                val resp = apiService.answerNearbyQuestion(questionId, NearbyAnonAnswerRequest(answer))
                if (resp.isSuccessful) {
                    if (imageUri != null) {
                        try {
                            val stream = context.contentResolver.openInputStream(imageUri)
                            val bytes = stream?.readBytes()
                            stream?.close()
                            if (bytes != null) {
                                val body = bytes.toRequestBody("image/*".toMediaTypeOrNull())
                                val part = okhttp3.MultipartBody.Part.createFormData("image", "answer.jpg", body)
                                apiService.uploadAnswerImage(questionId, part)
                            }
                        } catch (imgE: Exception) {
                            Timber.tag("NearbyQ").e("Bild-Upload fehlgeschlagen", imgE)
                        }
                    }
                    loadMyNearbyQuestions()
                    onSuccess()
                } else {
                    onError("Fehler beim Antworten")
                }
            } catch (e: Exception) {
                onError(e.message ?: "Unbekannter Fehler")
            }
        }
    }

    /** Blendet ein Nearby-Profil lokal aus (X-Button gedrückt) und speichert es persistent. */
    fun dismissNearbyProfile(userId: String) {
        val profile = _nearbyProfiles.value.find { it.userId == userId }
        saveHiddenNearbyId(userId)
        _nearbyProfiles.value = _nearbyProfiles.value.filter { it.userId != userId }
        if (profile != null) {
            _hiddenNearbyProfiles.value = _hiddenNearbyProfiles.value + profile
        }
    }

    /** Stellt ein ausgeblendetes Nearby-Profil wieder her. */
    fun restoreNearbyProfile(userId: String) {
        val profile = _hiddenNearbyProfiles.value.find { it.userId == userId } ?: return
        removeHiddenNearbyId(userId)
        _hiddenNearbyProfiles.value = _hiddenNearbyProfiles.value.filter { it.userId != userId }
        _nearbyProfiles.value = _nearbyProfiles.value + profile
    }

    fun sendLike(targetId: String) {
        viewModelScope.launch {
            try {
                val response = apiService.sendLike(NearbyLikeRequest(targetId))
                if (response.isSuccessful) {
                    _nearbyProfiles.value = _nearbyProfiles.value.filter { it.userId != targetId }
                    val status = response.body()?.get("status")
                    if (status == "matched") {
                        _statusMessage.value = "Es ist ein Match!"
                        loadNearbyMatches()
                    } else {
                        _statusMessage.value = "Interesse gesendet!"
                    }
                }
            } catch (e: Exception) {
                _statusMessage.value = "Like-Fehler."
            }
        }
    }

