    fun restoreNearbyProfileWithCoins(targetUserId: String, onSuccess: () -> Unit, onError: (String) -> Unit) {
        viewModelScope.launch {
            try {
                val response = apiService.restoreNearbyProfileWithCoins(NearbyRestoreRequest(targetUserId))
                if (response.isSuccessful) {
                    val styxRemaining = (response.body()?.get("styx_remaining") as? Number)?.toInt()
                    // Styx im currentUser lokal aktualisieren
                    _currentUser.value?.let { user ->
                        val updated = user.copy(styx = styxRemaining ?: (user.styx - 5))
                        userDao.insertUser(updated)
                        _currentUser.value = updated
                    }
                    removeHiddenNearbyId(targetUserId)
                    val profile = _hiddenNearbyProfiles.value.find { it.userId == targetUserId }
                    if (profile != null) {
                        _hiddenNearbyProfiles.value = _hiddenNearbyProfiles.value.filter { it.userId != targetUserId }
                        _nearbyProfiles.value = _nearbyProfiles.value + profile
                    }
                    onSuccess()
                } else if (response.code() == 402) {
                    onError("Nicht genug Styx-Coins (min. 5 benötigt)")
                } else {
                    onError("Fehler beim Wiederherstellen")
                }
            } catch (e: Exception) {
                onError("Netzwerkfehler")
            }
        }
    }

