    /** Kauft das Aufrufe-Feature für diesen Monat (300 Styx). */
    fun subscribeToNearbyVisitors(onSuccess: () -> Unit, onError: (String) -> Unit) {
        viewModelScope.launch {
            try {
                val response = apiService.subscribeToNearbyVisitors()
                if (response.isSuccessful) {
                    val styx = (response.body()?.get("styx_remaining") as? Number)?.toInt()
                    _currentUser.value?.let { user ->
                        val updated = user.copy(styx = styx ?: (user.styx - 300))
                        userDao.insertUser(updated)
                        _currentUser.value = updated
                    }
                    _hasVisitorsSubscription.value = true
                    loadNearbyProfileVisitors()
                    onSuccess()
                } else {
                    val body = response.errorBody()?.string() ?: ""
                    onError(if ("Styx" in body) "Nicht genug Styx (300 benötigt)" else "Fehler beim Freischalten")
                }
            } catch (e: Exception) {
                onError("Netzwerkfehler")
            }
        }
    }

