    fun loadNearbyMessages(matchId: String) {
        _activeMatchId.value = matchId
        viewModelScope.launch {
            try {
                val response = apiService.getNearbyMessages(matchId)
                if (response.isSuccessful) {
                    val fromServer = response.body() ?: emptyList()
                    // Merge: lokal bereits vorhandene Nachrichten (z.B. gerade gesendet) behalten,
                    // damit kein Race-Condition-Verlust entsteht wenn Send-Response und Load-Response
                    // sich überschneiden.
                    val serverIds = fromServer.map { it.id }.toSet()
                    val localOnly = _nearbyMessages.value.filter { it.id !in serverIds }
                    _nearbyMessages.value = (fromServer + localOnly).sortedBy { it.createdAt }
                }
            } catch (e: Exception) {
                Timber.tag("Nearby").e("loadNearbyMessages fehlgeschlagen", e)
            }
        }
    }

