    /** Lädt den Giphy API-Key vom Server und speichert ihn lokal. */
    fun fetchGiphyApiKey() {
        viewModelScope.launch(Dispatchers.IO) {
            // Falls vorheriger Versuch fehlschlug (leerer String), Spinner anzeigen während Retry
            if (_giphyApiKey.value?.isBlank() == true) _giphyApiKey.value = null
            try {
                val resp = apiService.getAppSettings()
                if (resp.isSuccessful) {
                    val body = resp.body()
                    val key = body?.giphyApiKey
                    if (!key.isNullOrBlank()) {
                        _giphyApiKey.value = key
                        giphyPrefs.edit().putString("api_key", key).apply()
                    } else {
                        // Key fehlt auf Server
                        _giphyApiKey.value = ""
                    }

                } else {
                    Timber.tag("Giphy").w("getAppSettings HTTP ${resp.code()}")
                    _giphyApiKey.value = ""
                }
            } catch (e: Exception) {
                Timber.tag("Giphy").w("API-Key-Fetch fehlgeschlagen: ${e.message}")
                _giphyApiKey.value = ""
            }
        }
    }

