    /**
     * Lädt eine fertige GIF-Datei als Sticker auf den Server hoch.
     * @param gifFile  Fertige GIF-Datei im Cache-Verzeichnis
     * @param onDone   Callback mit true bei Erfolg, false bei Fehler
     */
    fun uploadSticker(gifFile: java.io.File, onDone: (Boolean) -> Unit, mimeType: String = "image/gif") {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val reqBody = gifFile.asRequestBody(mimeType.toMediaTypeOrNull())
                val part = MultipartBody.Part.createFormData("file", gifFile.name, reqBody)
                val resp = apiService.uploadSticker(part)
                if (resp.isSuccessful) {
                    val newSticker = resp.body()
                    if (newSticker != null) {
                        _myStickers.value = listOf(newSticker) + _myStickers.value
                    }
                    withContext(Dispatchers.Main) { onDone(true) }
                } else {
                    Timber.tag("Sticker").e("uploadSticker HTTP ${resp.code()}: ${resp.errorBody()?.string()}")
                    withContext(Dispatchers.Main) { onDone(false) }
                }
            } catch (e: Exception) {
                Timber.tag("Sticker").e("uploadSticker Exception: ${e.message}")
                withContext(Dispatchers.Main) { onDone(false) }
            }
        }
    }

