    fun sendNearbyMessage(
        matchId: String,
        content: String?,
        mediaType: String = "text",
        viewMode: String = "permanent",
        imageUri: Uri? = null,
        directMediaUrl: String? = null
    ) {
        viewModelScope.launch {
            try {
                var mediaUrl: String? = directMediaUrl  // Für GIFs: direkt verwenden, kein Upload
                var previewUrl: String? = null

                if (imageUri != null && mediaType == "image") {
                    withContext(Dispatchers.IO) {
                        val originalFile = uriToFile(imageUri)
                        if (originalFile != null) {
                            // Original-Bild hochladen
                            val reqFile = originalFile.asRequestBody("image/jpeg".toMediaTypeOrNull())
                            val part = MultipartBody.Part.createFormData("file", originalFile.name, reqFile)
                            val uploadResp = apiService.uploadNearbyChatImage(part)
                            if (uploadResp.isSuccessful) {
                                mediaUrl = uploadResp.body()?.get("url")
                            }

                            // Fuer once/twice: verschwommene Vorschau generieren und hochladen
                            if (viewMode in listOf("once", "twice")) {
                                val bitmap = BitmapFactory.decodeFile(originalFile.absolutePath)
                                if (bitmap != null) {
                                    val blurred = generateBlurredPreview(bitmap)
                                    bitmap.recycle()
                                    val previewFile = File(
                                        originalFile.parent,
                                        "preview_${originalFile.name}"
                                    )
                                    FileOutputStream(previewFile).use { out ->
                                        blurred.compress(Bitmap.CompressFormat.JPEG, 70, out)
                                    }
                                    blurred.recycle()
                                    val previewReqFile = previewFile.asRequestBody("image/jpeg".toMediaTypeOrNull())
                                    val previewPart = MultipartBody.Part.createFormData("file", previewFile.name, previewReqFile)
                                    val previewResp = apiService.uploadNearbyChatImage(previewPart)
                                    if (previewResp.isSuccessful) {
                                        previewUrl = previewResp.body()?.get("url")
                                    }
                                    previewFile.delete()
                                }
                            }
                        }
                    }
                }

                val response = apiService.sendNearbyMessage(
                    matchId,
                    NearbySendMessageRequest(
                        content = content,
                        mediaUrl = mediaUrl,
                        previewUrl = previewUrl,
                        mediaType = mediaType,
                        viewMode = viewMode
                    )
                )
                if (response.isSuccessful) {
                    response.body()?.let { msg ->
                        if (_nearbyMessages.value.none { it.id == msg.id }) {
                            _nearbyMessages.value = _nearbyMessages.value + msg
                        }
                        // lastMessage in der Match-Liste lokal aktualisieren
                        val preview = msg.content?.takeIf { it.isNotBlank() } ?: "[${msg.mediaType}]"
                        _nearbyMatches.value = _nearbyMatches.value.map { m ->
                            if (m.id == matchId)
                                m.copy(lastMessage = preview, lastMessageAt = msg.createdAt)
                            else m
                        }
                    }
                }
            } catch (e: Exception) {
                Timber.tag("Nearby").e("sendNearbyMessage fehlgeschlagen", e)
            }
        }
    }

    /** Erstellt eine stark verpixelte/verschwommene Vorschau (API-level-agnostisch). */
    private fun generateBlurredPreview(source: Bitmap): Bitmap {
        val thumbW = 4.coerceAtLeast(source.width / 400)
        val thumbH = 4.coerceAtLeast(source.height / 400)
        val small = Bitmap.createScaledBitmap(source, thumbW, thumbH, false)
        val result = Bitmap.createScaledBitmap(small, source.width, source.height, false)
        small.recycle()
        return result
    }

    fun markNearbyMessageViewed(msgId: String) {
        viewModelScope.launch {
            try {
                val myId = _currentUser.value?.userId ?: return@launch
                val msg = _nearbyMessages.value.find { it.id == msgId } ?: return@launch
                // Eigene Nachrichten nicht als "angeschaut" werten
                if (msg.senderId == myId) return@launch
                apiService.markNearbyMessageViewed(msgId)
                // view_count lokal erhöhen und bei Limit URLs löschen
                _nearbyMessages.value = _nearbyMessages.value.map { m ->
                    if (m.id == msgId) {
                        val newCount = m.viewCount + 1
                        val cleared = when {
                            m.viewMode == "once" && newCount >= 1 -> true
                            m.viewMode == "twice" && newCount >= 2 -> true
                            else -> false
                        }
                        NearbyMessage(
                            id = m.id, matchId = m.matchId, senderId = m.senderId,
                            content = m.content,
                            mediaUrl = if (cleared) null else m.mediaUrl,
                            previewUrl = if (cleared) null else m.previewUrl,
                            mediaType = m.mediaType, viewMode = m.viewMode,
                            viewCount = newCount, createdAt = m.createdAt
                        )
                    } else m
                }
            } catch (e: Exception) {
                Timber.tag("Nearby").e("markNearbyMessageViewed fehlgeschlagen", e)
            }
        }
    }

