    fun updateDatingProfile(
        username: String, description: String, age: Int,
        gender: String, lookingFor: String, lat: Double, lng: Double,
        height: Int = 0, isVisible: Boolean = true, imageUri: Uri? = null,
        hasChildren: String? = null, wantsChildren: String? = null,
        galleryUri1: Uri? = null, galleryUri2: Uri? = null, galleryUri3: Uri? = null,
        deleteGallery1: Boolean = false, deleteGallery2: Boolean = false, deleteGallery3: Boolean = false
    ) {
        viewModelScope.launch {
            _isLoading.value = true
            try {
                val me = _currentUser.value ?: return@launch
                val profile = NearbyProfileCreate(
                    userId = me.userId,
                    username = username,
                    description = description,
                    age = age,
                    gender = gender,
                    lookingFor = lookingFor,
                    latitude = lat,
                    longitude = lng,
                    height = height.takeIf { it > 0 },
                    isActive = isVisible,
                    hasChildren = hasChildren,
                    wantsChildren = wantsChildren
                )
                val response = apiService.updateNearbyProfile(profile)
                if (response.isSuccessful) {
                    // Profilbild hochladen
                    if (imageUri != null) {
                        val file = uriToFile(imageUri)
                        if (file != null) {
                            val requestFile = file.asRequestBody("image/*".toMediaTypeOrNull())
                            val body = MultipartBody.Part.createFormData("file", file.name, requestFile)
                            apiService.uploadNearbyImage(me.userId, body)
                        }
                    }
                    // Galerie-Fotos hochladen oder löschen
                    suspend fun handleGallerySlot(slot: Int, uri: Uri?, delete: Boolean) {
                        if (delete) {
                            runCatching { apiService.deleteNearbyGalleryPhoto(me.userId, slot) }
                        } else if (uri != null) {
                            val file = uriToFile(uri)
                            if (file != null) {
                                val requestFile = file.asRequestBody("image/*".toMediaTypeOrNull())
                                val body = MultipartBody.Part.createFormData("file", file.name, requestFile)
                                runCatching { apiService.uploadNearbyGalleryPhoto(me.userId, slot, body) }
                            }
                        }
                    }
                    handleGallerySlot(1, galleryUri1, deleteGallery1)
                    handleGallerySlot(2, galleryUri2, deleteGallery2)
                    handleGallerySlot(3, galleryUri3, deleteGallery3)
                    _statusMessage.value = "Profil aktualisiert."
                    loadMyDatingProfile()
                    loadNearbyUsers()
                }
            } catch (e: Exception) {
                _statusMessage.value = "Fehler beim Speichern."
            } finally {
                _isLoading.value = false
            }
        }
    }

    /** Lädt ein Fremdprofil per ID für den NearbyDetailScreen. */
    fun loadNearbyProfileById(userId: String) {
        viewModelScope.launch {
            try {
                // Erst aus der bereits geladenen Liste suchen
                val cached = _nearbyProfiles.value.find { it.userId == userId }
                if (cached != null) {
                    _selectedNearbyProfile.value = cached
                }
                // Immer auch frisch vom Server laden (für Galerie-Fotos + has_children etc.)
                val resp = apiService.getNearbyProfileById(userId)
                if (resp.isSuccessful) {
                    _selectedNearbyProfile.value = resp.body()
                }
            } catch (e: Exception) {
                Timber.tag("Nearby").e(e, "Profil laden fehlgeschlagen: $userId")
            }
        }
    }

