    // --- VERKNÜPFTE GERÄTE (Linked Devices) ---

    private val _linkedDevices = MutableStateFlow<List<com.securechat.app.data.network.LinkedDevice>>(emptyList())
    val linkedDevices: StateFlow<List<com.securechat.app.data.network.LinkedDevice>> = _linkedDevices.asStateFlow()

    fun loadLinkedDevices() {
        viewModelScope.launch {
            try {
                val response = apiService.getLinkedDevices()
                if (response.isSuccessful) {
                    _linkedDevices.value = response.body() ?: emptyList()
                    // Self-Web-Secret ableiten: ECDH(android_priv, my_web_pub)
                    // Damit kann das eigene Web-Gerät App-Nachrichten lesen (self_content_blob)
                    val myId = _currentUser.value?.userId
                    if (myId != null && !CryptoManager.hasWebSharedSecret(myId)) {
                        val webDevice = _linkedDevices.value.firstOrNull {
                            !it.webPublicKey.isNullOrBlank() && it.webPublicKey.length > 80
                        }
                        if (webDevice != null) {
                            withContext(Dispatchers.IO) {
                                CryptoManager.deriveWebSharedSecret(myId, webDevice.webPublicKey!!)
                                Timber.tag("LETHE_E2EE").i("Self-Web-Secret abgeleitet (loadLinkedDevices)")
                            }
                        }
                    }
                }
            } catch (e: Exception) {
                Timber.e(e, "Fehler beim Laden der verknüpften Geräte")
            }
        }
    }

    fun removeLinkedDevice(deviceId: String) {
        viewModelScope.launch {
            try {
                val response = apiService.removeLinkedDevice(deviceId)
                if (response.isSuccessful) {
                    _linkedDevices.value = _linkedDevices.value.filter { it.id != deviceId }
                } else {
                    _statusMessage.value = "Fehler beim Trennen des Geräts."
                }
            } catch (e: Exception) {
                _statusMessage.value = "Verbindungsfehler."
            }
        }
    }

