    // ──────────────────────────────────────────────────────────────────────────
    // UMK – Initialisierung & Persistenz
    // ──────────────────────────────────────────────────────────────────────────

    private val UMK_PREF_KEY = "lethe_umk_raw_b64"

    private fun initUmkInBackground(password: String) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                // Persistierte Conversation Keys (v3) laden → kein WS-Round-Trip nötig wenn schon vorhanden
                loadConversationKeysFromPrefs()
                // Persistierte Partner-UMKs laden (leitet fehlende Conversation Keys neu ab sobald UMK da ist)
                loadPartnerUmksFromPrefs()
                // UMK sicherstellen (aus Prefs bereits geladen, vom Server holen oder neu generieren)
                if (!CryptoManager.hasUmk()) {
                    val resp = apiService.getUmk()
                    var loaded = false
                    if (resp.isSuccessful && resp.body()?.hasUmk == true) {
                        val blob = resp.body()?.encryptedUmk
                        if (!blob.isNullOrBlank() && CryptoManager.decryptUmkWithPassword(password, blob)) {
                            saveUmkToPrefs()
                            Timber.tag("LETHE_UMK").i("UMK vom Server geladen")
                            loaded = true
                        }
                    }
                    if (!loaded) {
                        CryptoManager.generateUmk()
                        val encBlob = CryptoManager.encryptUmkWithPassword(password) ?: return@launch
                        apiService.uploadUmk(UmkUploadRequest(encBlob))
                        saveUmkToPrefs()
                        Timber.tag("LETHE_UMK").i("Neuer UMK generiert und hochgeladen")
                    }
                }
                // Jetzt ist der eigene UMK garantiert vorhanden → persistierte Partner-UMKs erneut
                // einlesen, um fehlende Conversation Keys (v3) sofort abzuleiten.
                loadPartnerUmksFromPrefs()
                saveConversationKeysToPrefs()
                // Conversation Keys (v3) für alle bestehenden Kontakte ableiten:
                // löst den UMK-Exchange via WebSocket aus, damit Nachrichten als v3 verschlüsselt
                // werden und alte v2-Nachrichten migriert werden können.
                loadPartnerUmks()
            } catch (e: Exception) {
                Timber.tag("LETHE_UMK").e("UMK-Initialisierung fehlgeschlagen: ${e.message}")
            }
        }
    }

    private fun saveUmkToPrefs() {
        val b64 = CryptoManager.exportUmkBase64() ?: return
        try {
            val prefs = androidx.security.crypto.EncryptedSharedPreferences.create(
                "lethe_umk_store", "lethe_umk_master_key", context,
                androidx.security.crypto.EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
                androidx.security.crypto.EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
            )
            prefs.edit().putString(UMK_PREF_KEY, b64).apply()
        } catch (e: Exception) {
            Timber.tag("LETHE_UMK").w("saveUmkToPrefs fehlgeschlagen: ${e.message}")
        }
    }

    private fun loadUmkFromPrefs() {
        // Conversation Keys unabhängig vom UMK laden (v3 funktioniert auch ohne lokalen UMK).
        loadConversationKeysFromPrefs()
        if (CryptoManager.hasUmk()) return
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val prefs = androidx.security.crypto.EncryptedSharedPreferences.create(
                    "lethe_umk_store", "lethe_umk_master_key", context,
                    androidx.security.crypto.EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
                    androidx.security.crypto.EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
                )
                val b64 = prefs.getString(UMK_PREF_KEY, null) ?: return@launch
                if (CryptoManager.importUmkFromBase64(b64)) {
                    Timber.tag("LETHE_UMK").i("UMK aus Prefs geladen (Auto-Restore)")
                    // Persistierte Partner-UMKs einlesen → Conversation Keys (v3) ohne WS ableiten
                    loadPartnerUmksFromPrefs()
                    saveConversationKeysToPrefs()
                    // Conversation Keys (v3) für bestehende Kontakte ableiten (UMK-Exchange via WS)
                    loadPartnerUmks()
                }
            } catch (e: Exception) {
                Timber.tag("LETHE_UMK").w("loadUmkFromPrefs fehlgeschlagen: ${e.message}")
            }
        }
    }

    private val CONV_KEYS_PREF_KEY = "lethe_conversation_keys_json"

    /**
     * Persistiert die aktuell abgeleiteten Conversation Keys (v3) verschlüsselt.
     * Dadurch ist v3 nach App-Neustart sofort verfügbar – ohne den fragilen WS-Round-Trip,
     * der bisher pro Session einen erreichbaren Partner voraussetzte.
     */
    private fun saveConversationKeysToPrefs() {
        try {
            val keys = CryptoManager.exportConversationKeys()
            if (keys.isEmpty()) return
            val json = com.google.gson.Gson().toJson(keys)
            val prefs = androidx.security.crypto.EncryptedSharedPreferences.create(
                "lethe_umk_store", "lethe_umk_master_key", context,
                androidx.security.crypto.EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
                androidx.security.crypto.EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
            )
            prefs.edit().putString(CONV_KEYS_PREF_KEY, json).apply()
        } catch (e: Exception) {
            Timber.tag("LETHE_UMK").w("saveConversationKeysToPrefs fehlgeschlagen: ${e.message}")
        }
    }

    /** Lädt persistierte Conversation Keys (v3) in den CryptoManager-Cache. */
    private fun loadConversationKeysFromPrefs() {
        try {
            val prefs = androidx.security.crypto.EncryptedSharedPreferences.create(
                "lethe_umk_store", "lethe_umk_master_key", context,
                androidx.security.crypto.EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
                androidx.security.crypto.EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
            )
            val json = prefs.getString(CONV_KEYS_PREF_KEY, null) ?: return
            val type = object : com.google.gson.reflect.TypeToken<Map<String, String>>() {}.type
            val map: Map<String, String> = com.google.gson.Gson().fromJson(json, type) ?: return
            CryptoManager.importConversationKeys(map)
            Timber.tag("LETHE_UMK").i("${map.size} Conversation Keys aus Prefs geladen (v3 sofort verfügbar)")
        } catch (e: Exception) {
            Timber.tag("LETHE_UMK").w("loadConversationKeysFromPrefs fehlgeschlagen: ${e.message}")
        }
    }

    private val PARTNER_UMKS_PREF_KEY = "lethe_partner_umks_json"

    /**
     * Persistiert die bekannten Partner-UMKs verschlüsselt. Dadurch können Conversation Keys
     * nach App-Neustart neu abgeleitet werden, ohne den fragilen WS-Round-Trip – auch wenn der
     * eigene UMK erst nach den Conversation Keys verfügbar wird.
     */
    private fun savePartnerUmksToPrefs() {
        try {
            val umks = CryptoManager.exportPartnerUmks()
            if (umks.isEmpty()) return
            val json = com.google.gson.Gson().toJson(umks)
            val prefs = androidx.security.crypto.EncryptedSharedPreferences.create(
                "lethe_umk_store", "lethe_umk_master_key", context,
                androidx.security.crypto.EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
                androidx.security.crypto.EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
            )
            prefs.edit().putString(PARTNER_UMKS_PREF_KEY, json).apply()
        } catch (e: Exception) {
            Timber.tag("LETHE_UMK").w("savePartnerUmksToPrefs fehlgeschlagen: ${e.message}")
        }
    }

    /** Lädt persistierte Partner-UMKs und leitet fehlende Conversation Keys neu ab. */
    private fun loadPartnerUmksFromPrefs() {
        try {
            val prefs = androidx.security.crypto.EncryptedSharedPreferences.create(
                "lethe_umk_store", "lethe_umk_master_key", context,
                androidx.security.crypto.EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
                androidx.security.crypto.EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
            )
            val json = prefs.getString(PARTNER_UMKS_PREF_KEY, null) ?: return
            val type = object : com.google.gson.reflect.TypeToken<Map<String, String>>() {}.type
            val map: Map<String, String> = com.google.gson.Gson().fromJson(json, type) ?: return
            CryptoManager.importPartnerUmks(map)
            Timber.tag("LETHE_UMK").i("${map.size} Partner-UMKs aus Prefs geladen")
        } catch (e: Exception) {
            Timber.tag("LETHE_UMK").w("loadPartnerUmksFromPrefs fehlgeschlagen: ${e.message}")
        }
    }

    private val sentMsgCounter = java.util.concurrent.atomic.AtomicInteger(0)
    private val DEFERRED_BACKUP_PREF_KEY = "lethe_deferred_backup_checked"
    @Volatile private var deferredBackupChecked = false
    @Volatile private var deferredBackupGuardLoaded = false

    private fun deferredBackupPrefs() = androidx.security.crypto.EncryptedSharedPreferences.create(
        "lethe_umk_store", "lethe_umk_master_key", context,
        androidx.security.crypto.EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
        androidx.security.crypto.EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM
    )

    /**
     * Sicherheitsnetz: In Sessions OHNE frischen Login (Auto-Restore aus Token) läuft das
     * Auto-Key-Backup nach Login nicht. Damit ein neues Gerät später trotzdem wiederherstellen kann,
     * wird nach 10 gesendeten Nachrichten geprüft, ob ein Backup existiert – falls nicht, eines erstellt.
     * Nutzt das gespeicherte Login-Passwort (für Biometrie-Login bereits verschlüsselt persistiert).
     * Der Guard ist permanent (in Prefs persistiert) – der Zähler startet nach App-Neustart NICHT neu.
     */
    private fun maybeDeferredKeyBackup() {
        if (!deferredBackupGuardLoaded) {
            deferredBackupGuardLoaded = true
            try {
                if (deferredBackupPrefs().getBoolean(DEFERRED_BACKUP_PREF_KEY, false)) {
                    deferredBackupChecked = true
                }
            } catch (_: Exception) { /* nicht-kritisch */ }
        }
        if (deferredBackupChecked) return
        if (sentMsgCounter.incrementAndGet() < 10) return
        deferredBackupChecked = true
        try {
            deferredBackupPrefs().edit().putBoolean(DEFERRED_BACKUP_PREF_KEY, true).apply()
        } catch (_: Exception) { /* nicht-kritisch */ }
        val pw = userPrefs.value.password
        if (pw.isBlank()) return
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val resp = apiService.getKeyBackup()
                val existing = if (resp.isSuccessful) resp.body()?.encryptedBlob else null
                val noBackup = existing.isNullOrBlank()
                val softKeyActive = CryptoManager.exportSoftPrivateKey() != null
                if (noBackup || softKeyActive) {
                    backupKeys(pw, automatic = true) { success, msg ->
                        Timber.tag("LETHE_KEYS").d("Deferred-Backup nach 10 Nachrichten: $success – $msg")
                    }
                }
            } catch (_: Exception) { /* nicht-kritisch */ }
        }
    }

    // ──────────────────────────────────────────────────────────────────────────
    // UMK-EXCHANGE (Phase 4: Conversation Key via WebSocket)
    // ──────────────────────────────────────────────────────────────────────────

    fun initiateUmkExchange(partnerId: String) {
        if (CryptoManager.hasConversationKey(partnerId)) return
        if (!CryptoManager.hasUmk()) return
        if (!CryptoManager.hasSharedSecret(partnerId)) return
        val myUmk = CryptoManager.getUmkBytes() ?: return
        val umkBase64 = android.util.Base64.encodeToString(myUmk, android.util.Base64.NO_WRAP)
        val encrypted = CryptoManager.encrypt(partnerId, umkBase64)
        webSocketManager.sendRaw(mapOf(
            "type" to "umk_exchange",
            "receiver_id" to partnerId,
            "payload" to mapOf("encrypted_umk" to encrypted)
        ))
        Timber.tag("LETHE_UMK").i("UMK-Exchange initiiert mit $partnerId")
    }

    private fun sendUmkExchangeResponse(partnerId: String) {
        val myUmk = CryptoManager.getUmkBytes() ?: return
        if (!CryptoManager.hasSharedSecret(partnerId)) return
        val umkBase64 = android.util.Base64.encodeToString(myUmk, android.util.Base64.NO_WRAP)
        val encrypted = CryptoManager.encrypt(partnerId, umkBase64)
        webSocketManager.sendRaw(mapOf(
            "type" to "umk_exchange_response",
            "receiver_id" to partnerId,
            "payload" to mapOf("encrypted_umk" to encrypted)
        ))
    }

    private suspend fun decryptPartnerUmk(encUmk: String, partnerId: String): ByteArray? {
        return withContext(Dispatchers.IO) {
            try {
                if (!CryptoManager.hasSharedSecret(partnerId)) {
                    val contact = contactDao.getContactById(partnerId) ?: return@withContext null
                    if (contact.publicKey.length <= 100) return@withContext null
                    CryptoManager.deriveSharedSecret(partnerId, contact.publicKey)
                }
                val umkBase64 = CryptoManager.decrypt(partnerId, encUmk)
                if (umkBase64.startsWith("[🔐") || umkBase64 == encUmk) return@withContext null
                android.util.Base64.decode(umkBase64, android.util.Base64.NO_WRAP)
            } catch (e: Exception) {
                Timber.tag("LETHE_UMK").e("decryptPartnerUmk Fehler: ${e.message}")
                null
            }
        }
    }

    // ──────────────────────────────────────────────────────────────────────────
    // RE-ENCRYPTION (Phase 4: v2 → v3 Migration)
    // ──────────────────────────────────────────────────────────────────────────

    private fun reencryptLegacyMessages(contactId: String) {
        if (!CryptoManager.hasConversationKey(contactId)) return
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val allMsgs = messageDao.getRecentMessagesForChat(contactId, 200)
                val toReencrypt = allMsgs.filter { it.content?.startsWith("v2:") == true }
                if (toReencrypt.isEmpty()) return@launch

                val batch = mutableListOf<ReencryptItem>()
                val msgIdToNewContent = mutableMapOf<String, String>()

                for (msg in toReencrypt.take(50)) {
                    val msgContent = msg.content ?: continue
                    val decrypted = try {
                        CryptoManager.decrypt(contactId, msgContent)
                    } catch (_: Exception) { continue }
                    if (decrypted.startsWith("[🔐") || decrypted == msgContent) continue
                    val reencrypted = CryptoManager.encryptWithConversationKey(contactId, decrypted)
                        ?: continue
                    val msgId = msg.messageId ?: continue
                    batch.add(ReencryptItem(messageId = msgId, contentBlob = reencrypted))
                    msgIdToNewContent[msgId] = reencrypted
                }

                if (batch.isNotEmpty()) {
                    apiService.reencryptMessages(ReencryptRequest(batch))
                    for ((msgId, newContent) in msgIdToNewContent) {
                        messageDao.editMessageByServerId(msgId, newContent)
                    }
                    Timber.tag("LETHE_UMK").i("Re-Encryption: ${batch.size} Nachrichten v2→v3 (contactId=$contactId)")
                }
            } catch (e: Exception) {
                Timber.tag("LETHE_UMK").e("reencryptLegacyMessages Fehler: ${e.message}")
            }
        }
    }

    /**
     * Wird aufgerufen wenn der QR-Scanner einen Code gelesen hat.
     *
     * Unterstützte Formate:
     *   Neu (EPIC 5): JSON-String {"t":"<UUID>","wk":"<base64_spki_web_pubkey>"}
     *   Legacy:       "lethe://link-device?token=<UUID>"
     *
     * Anti-MITM: Der web_public_key wird mit dem ECDSA-Signing-Schlüssel aus dem AndroidKeyStore
     * signiert. Der Server verifiziert die Signatur gegen den gespeicherten Signing-Public-Key
     * des Users → beweist dass nur das legitime Gerät diesen Key autorisiert hat.
     */
    fun linkDeviceWithQrContent(qrContent: String) {
        viewModelScope.launch {
            try {
                // JSON-Format parsen (EPIC 5: neues Format) oder Legacy-URL fallback
                val (token, webPublicKey) = try {
                    val json = org.json.JSONObject(qrContent)
                    Pair(
                        json.optString("t").ifEmpty { null },
                        json.optString("wk").ifEmpty { null }
                    )
                } catch (_: Exception) {
                    // Legacy: lethe://link-device?token=UUID oder reiner UUID-String
                    val t = if (qrContent.contains("token=")) {
                        qrContent.substringAfterLast("token=").trim()
                    } else qrContent.trim()
                    Pair(t.ifEmpty { null }, null)
                }

                if (token.isNullOrBlank()) {
                    _statusMessage.value = "Ungültiger QR-Code"
                    return@launch
                }

                // Signing-Key sicherstellen + Web-Public-Key signieren (Anti-MITM)
                val (signature, signingPubKey) = if (webPublicKey != null) {
                    withContext(Dispatchers.IO) {
                        try {
                            val spk = CryptoManager.ensureSigningKeyPair()
                            val sig = CryptoManager.signBytes(webPublicKey.toByteArray(Charsets.UTF_8))
                            Pair(sig, spk)
                        } catch (e: Exception) {
                            Timber.tag("LETHE_E2EE").e("Signierung fehlgeschlagen: ${e.message}")
                            Pair(null, null)
                        }
                    }
                } else {
                    Pair(null, null)
                }

                // Web-Shared-Secret vorab ableiten (wenn beide Keys vorhanden)
                if (webPublicKey != null) {
                    withContext(Dispatchers.IO) {
                        // Wir ableiten das Secret jetzt noch nicht – der Contact-ID ist die User-ID
                        // des Geräte-Inhabers. Das passiert erst in loadContacts() nach dem Linking.
                    }
                }

                val deviceName = "${android.os.Build.MANUFACTURER} ${android.os.Build.MODEL}"
                val response = apiService.scanQrCode(
                    com.securechat.app.data.network.ScanQrRequest(
                        token = token,
                        deviceName = deviceName,
                        webPublicKey = webPublicKey,
                        signature = signature,
                        signingPublicKey = signingPubKey
                    )
                )
                if (response.isSuccessful) {
                    _statusMessage.value = "✓ Gerät erfolgreich verknüpft!"
                    loadLinkedDevices()
                } else {
                    _statusMessage.value = when (response.code()) {
                        401 -> "Authentifizierungsfehler (401). Bitte neu einloggen."
                        403 -> "Signatur ungültig (403). Sicherheitscheck fehlgeschlagen."
                        404 -> "QR-Code nicht gefunden (404). Bitte neu scannen."
                        410 -> "QR-Code abgelaufen (410). Bitte neu scannen."
                        422 -> "Ungültige Anfrage (422). App-Version veraltet?"
                        else -> "Fehler beim Verknüpfen (HTTP ${response.code()})."
                    }
                }
            } catch (e: Exception) {
                _statusMessage.value = "Verbindungsfehler beim Verknüpfen."
            }
        }
    }

    // --- KONTAKT-VERWALTUNG ---

    fun addContact(fakeNumber: String, name: String) {
        // Bots: kein Kontakt-Handshake, direkt starten
        if (fakeNumber.startsWith("bot_")) {
            startBotChat(fakeNumber, name)
            return
        }
        viewModelScope.launch {
            val me = _currentUser.value ?: run {
                _statusMessage.value = "Nicht eingeloggt"
                return@launch
            }

            try {
                val isLetheId = fakeNumber.startsWith("LID")
                val request = if (isLetheId)
                    AddContactRequest(requesterId = me.userId, targetLetheId = fakeNumber)
                else
                    AddContactRequest(targetFakeNumber = fakeNumber, requesterId = me.userId)
                val response = apiService.addContact(request)
                if (response.isSuccessful) {
                    val body = response.body()
                    val status = body?.get("status")
                    when (status) {
                        "anonymous_started" -> {
                            // Server sendet anonymous_chat_started via WS – hier nur Status-Meldung
                            val partnerLetheId = body["partner_lethe_id"] ?: fakeNumber
                            _statusMessage.value = "Anonymer Chat gestartet: $partnerLetheId"
                            Timber.tag("Contacts").d("Anonymer Chat gestartet: $partnerLetheId")
                        }
                        "reconnected" -> {
                            _statusMessage.value = "Verbindung wiederhergestellt!"
                            Timber.tag("Contacts").d("Kontakt re-verbunden: $fakeNumber")
                            val partnerId = body["partner_id"]
                            if (partnerId != null) loadMessages(partnerId)
                        }
                        else -> {
                            _statusMessage.value = "Kontaktanfrage gesendet!"
                            Timber.tag("Contacts").d("Kontaktanfrage gesendet an: $fakeNumber")
                        }
                    }
                } else {
                    _statusMessage.value = "Fehler: ${response.code()} - ${response.message()}"
                    Timber.tag("Contacts").e("Server Error: ${response.code()}")
                }
            } catch (e: Exception) {
                _statusMessage.value = "Netzwerkfehler: ${e.message}"
                Timber.tag("Contacts").e("Network Error", e)
            }
        }
    }

    /** Startet einen Bot-Chat ohne Handshake und fügt ihn direkt als Kontakt hinzu. */
    fun startBotChat(botFakeNumber: String, botName: String) {
        viewModelScope.launch {
            try {
                val response = apiService.startBotChat(botFakeNumber)
                if (response.isSuccessful) {
                    val bot = response.body() ?: return@launch
                    contactDao.insertContact(
                        ContactEntity(
                            userId = bot.botId,
                            fakeNumber = bot.botFakeNumber,
                            username = bot.botName,
                            publicKey = bot.botPublicKey,
                            profileImageUrl = bot.botProfileImageUrl?.let { toAbsoluteUrl(it) },
                            status = "accepted",
                            isBot = true
                        )
                    )
                    _statusMessage.value = "Bot ${bot.botName} hinzugefügt!"
                    Timber.tag("Bots").d("Bot-Chat gestartet: ${bot.botFakeNumber}")
                } else {
                    _statusMessage.value = "Bot nicht gefunden."
