    /**
     * Lädt alle akzeptierten Kontakte vom Server und synchronisiert sie mit der lokalen DB.
     * Wird nach jedem Login aufgerufen, damit Kontakte nach App-Neustart korrekt angezeigt werden.
     */
    fun loadContacts() {
        // Eigenen P2P-Status zum Server spiegeln, damit Partner ihn über /contacts sehen
        syncP2pSettingToServer(_userPrefs.value.p2pInternetEnabled)
        viewModelScope.launch {
            try {
                val response = apiService.getContacts()
                if (response.isSuccessful) {
                    val serverContacts = response.body() ?: emptyList()
                    // Partner-P2P-Status aus den Serverdaten in die Disabled-Map übernehmen:
                    // Partner ohne P2P → als deaktiviert markieren, damit gar kein P2P-Aufbau versucht wird.
                    var p2pMap = _p2pPartnerDisabled.value
                    serverContacts.forEach { item ->
                        p2pMap = if (item.partnerP2pEnabled) p2pMap - item.partnerId
                                 else p2pMap + (item.partnerId to true)
                    }
                    _p2pPartnerDisabled.value = p2pMap
                    serverContacts.forEach { item ->
                        val existingAlias = contactDao.getContactById(item.partnerId)?.customAlias
                        contactDao.insertContact(
                            ContactEntity(
                                userId = item.partnerId,
                                fakeNumber = item.partnerFakeNumber,
                                username = item.partnerName,
                                publicKey = item.partnerPublicKey,
                                profileImageUrl = item.partnerImage?.let { toAbsoluteUrl(it) },
                                status = "accepted",
                                isBot = item.partnerIsBot,
                                customAlias = existingAlias,
                                isAnonymous = item.isAnonymous,
                                instagram = item.partnerInstagram,
                                tiktok = item.partnerTiktok,
                                youtube = item.partnerYoutube,
                                info = item.partnerInfo,
                                letheId = item.partnerLetheId,
                                isVerified = item.partnerIsVerified,
                                blockedByPartner = item.blockedByPartner
                            )
                        )
                        withContext(Dispatchers.IO) {
                            // EPIC 1: Android-Shared-Secret ableiten
                            // forceRederive statt derive: stellt sicher dass nach Key-Rotation (z.B.
                            // Neuinstallation des Partners) der veraltete Cache-Eintrag ersetzt wird.
                            if (item.partnerPublicKey.length > 100) {
                                CryptoManager.forceRederiveSharedSecret(item.partnerId, item.partnerPublicKey)
                            }
                            // EPIC 5: Web-Shared-Secret ableiten wenn Partner aktives Web-Gerät hat
                            val webKey = item.partnerWebPublicKey
                            if (!webKey.isNullOrBlank() && webKey.length > 80) {
                                CryptoManager.deriveWebSharedSecret(item.partnerId, webKey)
                            }
                        }
                    }
                    Timber.tag("Contacts").d("${serverContacts.size} Kontakte vom Server geladen.")
                }
            } catch (e: Exception) {
                Timber.tag("Contacts").e("Fehler beim Laden der Kontakte", e)
            }
        }
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Periodischer Profilbild-Refresh
    // ─────────────────────────────────────────────────────────────────────────

    /** Laufender Refresh-Job – wird beim Login/Session-Restore gestartet. */
    private var profileRefreshJob: Job? = null

    /**
     * Startet eine Endlosschleife, die nacheinander (nicht parallel) für jeden Kontakt
     * das aktuelle Profilbild vom Server abruft und die Room-DB bei Änderung aktualisiert.
     *
     * - Initialer Delay: 15 s (App soll zuerst stabil laufen)
     * - Delay zwischen den Kontakten: 2 s (Server schonen)
     * - Interval pro Runde: 5 Minuten
     *
     * Ein laufender Job wird vor Neustart automatisch abgebrochen (z. B. bei Profil-Wechsel).
     * delay() ist ein Cancellation-Point – kein explizites isActive-Check nötig.
     */
    fun startProfileImageRefreshLoop() {
        // Globalen Medien-Prefetch im selben Login/Restore-Kontext mitstarten
        startMediaPrefetchLoop()
        profileRefreshJob?.cancel()
        profileRefreshJob = viewModelScope.launch {
            delay(15_000L)
            while (true) {
                refreshContactProfileImagesSequentially()
                delay(5 * 60_000L)
            }
        }
    }

    private suspend fun refreshContactProfileImagesSequentially() {
        val contacts = try {
            contactDao.getAllContacts().first()
        } catch (e: Exception) {
            return
        }
        for (contact in contacts) {
            try {
                val response = apiService.getUser(contact.userId)
                if (response.isSuccessful) {
                    val user = response.body() ?: continue
                    val newUrl = user.profileImageUrl?.let { toAbsoluteUrl(it) }
                    if (newUrl != contact.profileImageUrl) {
                        contactDao.insertContact(contact.copy(profileImageUrl = newUrl))
                        Timber.tag("LETHE_PROFILE").d("Profilbild aktualisiert: ${contact.userId}")
                    }
                }
            } catch (e: Exception) {
                Timber.tag("LETHE_PROFILE").w("Profilbild-Check fehlgeschlagen (${contact.userId}): ${e.message}")
            }
            delay(2_000L)
        }
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Globaler Medien-Prefetch (alle Chats, eine Datei nach der anderen)
    // ─────────────────────────────────────────────────────────────────────────

    /** Laufender Prefetch-Job – wird beim Login/Session-Restore gestartet. */
    private var mediaPrefetchJob: Job? = null

    /**
     * Startet eine Endlosschleife, die ALLE Chat-Medien (1:1 + Gruppen) im Hintergrund
     * vorab in den Cache lädt – streng nacheinander (eine Datei nach der anderen) und
     * chronologisch (älteste zuerst). Dadurch muss der Chat beim Öffnen nichts mehr
     * nachladen, sondern nur noch anzeigen. Das verhindert die OOM-/Ruckel-Probleme,
     * die durch paralleles Nachladen vieler Medien beim Öffnen eines vollen Chats entstehen.
     *
     * - Initialer Delay: 20 s (App soll zuerst stabil starten)
     * - Runde wiederholt sich alle 2 Minuten (neue Medien werden nachgezogen)
     */
    fun startMediaPrefetchLoop() {
        mediaPrefetchJob?.cancel()
        mediaPrefetchJob = viewModelScope.launch(Dispatchers.IO) {
            delay(20_000L)
            while (true) {
                prefetchAllChatMediaSequentially()
                delay(2 * 60_000L)
            }
        }
    }

    /**
     * Lädt alle Medien aus der lokalen DB chronologisch und streng sequentiell vorab.
     * Bereits gecachte Dateien werden übersprungen, sodass jede Runde nur die
     * tatsächlich neuen Medien herunterlädt.
     */
    private suspend fun prefetchAllChatMediaSequentially() {
        val mediaMessages = try {
            messageDao.getAllMediaMessages()
        } catch (e: Exception) {
            Timber.tag("MediaPrefetch").w("Laden der Medien-Liste fehlgeschlagen: ${e.message}")
            return
        }
        // Hinweis: Hier wird bewusst NICHT _chatMediaUrls befüllt – dieses Set steuert
        // ausschließlich das Cache-Cleanup des aktuell geöffneten Chats (onChatClosed).
        for (msg in mediaMessages) {
            val url = msg.mediaUrl?.takeIf { it.isNotBlank() } ?: continue
            val chatId = msg.chatId
            try {
                when (msg.mediaType) {
                    "image" -> {
                        // Bereits in die Galerie verschobene Bilder nicht erneut laden (Datenvolumen).
                        if (!mediaCache.isInPublicStore(url, false) &&
                            !mediaCache.isCachedForChat(url, chatId, "images")) {
                            mediaCache.getForChat(url, chatId, "images")
                        }
                    }
                    "audio" -> {
                        if (!mediaCache.isCachedForChat(url, chatId, "audio")) {
                            mediaCache.getForChat(url, chatId, "audio")
                        }
                    }
                    "audio_music" -> {
                        if (!mediaCache.isCachedForChat(url, chatId, "audio")) {
                            mediaCache.getForChat(url, chatId, "audio")
                        }
                    }
                    "video" -> {
                        // Videodatei dauerhaft auf Disk cachen, damit der Player sie lokal
                        // abspielt und NICHT bei jedem Öffnen erneut vom Netz streamt (Datenvolumen).
                        // Bereits in die Galerie (Movies) verschobene Videos überspringen.
                        if (!mediaCache.isInPublicStore(url, true) &&
                            !mediaCache.isCachedForChat(url, chatId, "video")) {
                            mediaCache.getForChat(url, chatId, "video")
                        }
                        // join(): wartet auf die Thumbnail-Generierung, damit wirklich nur
                        // ein Medium gleichzeitig verarbeitet wird (kein Speicher-Peak).
                        if (_videoThumbnailCache.get(url) == null) {
                            loadVideoThumbnailFromUrl(url)?.join()
                        }
                    }
                    "3dprint" -> {
                        try {
                            val meta = com.google.gson.Gson().fromJson(
                                msg.content, ThreeDFileMeta::class.java
                            )
                            meta?.previewUrl?.takeIf { it.isNotBlank() }?.let { previewUrl ->
                                if (!mediaCache.isCachedForChat(previewUrl, chatId, "3d")) {
                                    mediaCache.getForChat(previewUrl, chatId, "3d")
                                }
                            }
                        } catch (_: Exception) {}
                    }
                }
            } catch (_: Exception) {
                // Einzelnes Medium scheitert → nächstes versuchen
            }
            // Kleine Pause zwischen den Medien: schont CPU/IO und hält den Speicher niedrig
            delay(150L)
        }
    }

