    fun deleteContact(contact: ContactEntity) {
        viewModelScope.launch(Dispatchers.IO) {
            // Server: löscht Kontakt, alle Nachrichten, Polls, Call-Logs und Mediendateien
            try {
                apiService.deleteContactByPartner(contact.userId)
            } catch (e: Exception) {
                Timber.tag("MainViewModel").w("deleteContact server: ${e.message}")
            }
            // Lokal: alle Nachrichten dieses Chats löschen
            messageDao.clearMessagesForChat(contact.userId)
            // Lokal: Polls dieses Kontakts löschen
            pollDao.clearPollsForUser(contact.userId)
            // Lokal: Statuse des Kontakts löschen
            statusDao.deleteStatusesForUser(contact.userId)
            // Lokal: Kontakteintrag löschen — ZULETZT
            contactDao.delete(contact)
            // Shortcut aus Share Sheet entfernen + Liste neu aufbauen
            shortcutHelper.disableShortcut(contact.userId)
            try {
                val sorted = contactsSortedByRecent.first()
                val allGroups = groupDao.getAllGroups().first()
                val recentIds = messageDao.getRecentChatIds(50)
                shortcutHelper.refreshTopContactShortcuts(sorted, allGroups, recentIds)
            } catch (_: Exception) {}
            withContext(Dispatchers.Main) {
                _statusMessage.value = "Kontakt gelöscht"
            }
        }
    }

    fun renameContact(contact: ContactEntity, newAlias: String) {
        viewModelScope.launch(Dispatchers.IO) {
            val trimmed = newAlias.trim()
            contactDao.updateAlias(contact.userId, trimmed.ifEmpty { null })
            withContext(Dispatchers.Main) {
                _statusMessage.value = if (trimmed.isEmpty()) "Name zurückgesetzt" else "Name geändert"
            }
        }
    }

    /**
     * Erneuert den E2EE-Handshake mit einem Kontakt:
     * Sendet dem Partner eine Handshake-Erneuerungs-Anfrage via Server.
     * Der Partner bekommt eine Benachrichtigung und kann annehmen oder ablehnen.
     * Nach Annahme tauschen beide Seiten frische Public Keys aus und leiten neue Shared Secrets ab.
     */
    fun renewHandshake(contact: ContactEntity) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val resp = apiService.requestHandshakeRenew(HandshakeRenewRequest(contact.userId))
                withContext(Dispatchers.Main) {
                    if (resp.isSuccessful) {
                        _contactScreenMessage.value = "Handshake-Anfrage gesendet"
                    } else {
                        _contactScreenMessage.value = "Handshake-Anfrage fehlgeschlagen (${resp.code()})"
                    }
                }
            } catch (e: Exception) {
                Timber.tag("LETHE_E2EE").w("renewHandshake server: ${e.message}")
                // Fallback: lokal neu ableiten
                val pubKey = contact.publicKey
                if (pubKey.isNotBlank()) {
                    val ok = CryptoManager.forceRederiveSharedSecret(contact.userId, pubKey)
                    Timber.tag("LETHE_E2EE").i("renewHandshake fallback: lokal abgeleitet (ok=$ok)")
                }
                withContext(Dispatchers.Main) {
                    _contactScreenMessage.value = "Handshake lokal erneuert"
                }
            }
        }
    }

    fun respondHandshakeRenew(fromUserId: String, action: String) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                apiService.respondHandshakeRenew(HandshakeRenewRespond(fromUserId, action))
            } catch (e: Exception) {
                Timber.tag("LETHE_E2EE").w("respondHandshakeRenew: ${e.message}")
            }
            withContext(Dispatchers.Main) {
                _incomingHandshakeRenew.value = null
                if (action == "accept") _contactScreenMessage.value = "Handshake angenommen"
            }
        }
    }

    fun clearIncomingHandshakeRenew() { _incomingHandshakeRenew.value = null }

