    // --- SUPPORT ---

    fun submitSupportTicket(
        category: String,
        title: String,
        description: String,
        imageUris: List<android.net.Uri>,
        attachLogs: Boolean = false,
        onSuccess: () -> Unit,
        onError: (String) -> Unit
    ) {
        viewModelScope.launch {
            try {
                val catBody = category.toRequestBody("text/plain".toMediaTypeOrNull())
                val titleBody = title.toRequestBody("text/plain".toMediaTypeOrNull())
                val descBody = description.toRequestBody("text/plain".toMediaTypeOrNull())
                val fileParts = imageUris.mapIndexedNotNull { i, uri ->
                    try {
                        val stream = context.contentResolver.openInputStream(uri) ?: return@mapIndexedNotNull null
                        val bytes = stream.readBytes()
                        stream.close()
                        val body = bytes.toRequestBody("image/*".toMediaTypeOrNull())
                        MultipartBody.Part.createFormData("files", "support_$i.jpg", body)
                    } catch (e: Exception) { null }
                }.toMutableList()

                // Log-Datei anhängen wenn gewünscht
                if (attachLogs) {
                    val logFile = com.securechat.app.LetheLogger.getLogFile()
                    if (logFile != null && logFile.exists() && logFile.length() > 0) {
                        try {
                            val bytes = logFile.readBytes()
                            val body = bytes.toRequestBody("text/plain".toMediaTypeOrNull())
                            fileParts.add(MultipartBody.Part.createFormData("files", "lethe_logs.txt", body))
                        } catch (e: Exception) {
                            Timber.tag("LETHE_SUPPORT").w("Log-Anhang fehlgeschlagen: ${e.message}")
                        }
                    }
                }

                val resp = apiService.submitSupportTicket(catBody, titleBody, descBody, fileParts)
                if (resp.isSuccessful) onSuccess()
                else onError("Server-Fehler (${resp.code()})")
            } catch (e: Exception) {
                onError(e.message ?: "Unbekannter Fehler")
            }
        }
    }

    /**
     * Erstellt ein Support-Ticket wenn der SMS-Verifizierungscode (Login/Registrierung)
     * abgelaufen ist. Kein Login erforderlich – die Rufnummer wird direkt mitgeschickt,
     * auch wenn noch kein Account existiert.
     */
    fun submitOtpSupportTicket(
        phoneNumber: String,
        message: String,
        onResult: (Boolean, String) -> Unit
    ) {
        viewModelScope.launch {
            try {
                val phoneBody = phoneNumber.toRequestBody("text/plain".toMediaTypeOrNull())
                val msgBody = message.toRequestBody("text/plain".toMediaTypeOrNull())
                val resp = apiService.createOtpSupportTicket(phoneBody, msgBody)
                if (resp.isSuccessful) onResult(true, "Ticket erstellt – wir melden uns bei dir.")
                else onResult(false, "Server-Fehler (${resp.code()})")
            } catch (e: Exception) {
                onResult(false, e.message ?: "Unbekannter Fehler")
            }
        }
    }

