    fun cleanupExpiredStatuses() {
        viewModelScope.launch { statusDao.deleteExpired(System.currentTimeMillis()) }
    }

    fun loadContactStatuses() {
        viewModelScope.launch {
            statusDao.deleteExpired(System.currentTimeMillis())
            try {
                val response = loadSemaphore.withPermit { apiService.getContactStatuses() }
                if (response.isSuccessful) {
                    val freshList = response.body() ?: emptyList()
                    val myId = _currentUser.value?.userId ?: ""

                    // Veraltete Einträge entfernen die nicht mehr vom Server geliefert werden
                    // (verhindert Geist-Statuse die auf dem Server bereits abgelaufen sind)
                    val freshIds = freshList.map { it.id }.toSet()
                    if (freshIds.isEmpty()) {
                        statusDao.deleteAllContactStatuses(myId)
                    } else {
                        statusDao.deleteContactStatusesNotIn(freshIds, myId)
                    }

                    val insertedStatuses = mutableListOf<StatusEntity>()
                    freshList.forEach { s ->
                        val expiresMs = parseStatusTimestamp(s.expiresAt, s.durationHours)
                        val createdMs = parseStatusTimestamp(s.createdAt, 0)
                        val entity = StatusEntity(
                            statusId = s.id,
                            userId = s.userId,
                            userName = s.userName,
                            userImage = s.userImage?.let { toAbsoluteUrl(it) },
                            mediaUrl = toAbsoluteUrl(s.mediaUrl),
                            mediaType = s.mediaType,
                            durationHours = s.durationHours,
                            expiresAt = expiresMs,
                            createdAt = createdMs,
                            musicUrl = s.musicUrl,
                            musicTitle = s.musicTitle,
                            musicArtist = s.musicArtist,
                            musicDurationSec = s.musicDurationSec,
                            musicOffsetSec = s.musicOffsetSec,
                            linkUrl = s.linkUrl,
                            linkLabel = s.linkLabel
                        )
                        statusDao.insertStatus(entity)
                        insertedStatuses.add(entity)
                    }
                    // Badge nur für Kontakt-Statuse (nicht eigene) prüfen
                    checkForUnseenStatuses(insertedStatuses.filter { it.userId != myId })
                }
            } catch (e: Exception) {
                Timber.tag("Status").e("Laden fehlgeschlagen", e)
            }
        }
    }

    /**
     * Parst einen ISO-8601-Timestamp robust.
     * Unterstützt sowohl Timestamps mit Z/Offset ("2026-03-02T12:30:00Z") als auch
     * naive Timestamps ohne Timezone-Marker ("2026-03-02T12:30:00") die der Server
     * in UTC-Systemzeit sendet.
     *
     * @param iso ISO-8601 String vom Server
     * @param fallbackDurationHours Bei Parse-Fehler: aktuelle Zeit + diese Dauer (Stunden).
     *                              0 = aktuelle Zeit als Fallback.
     */
    private fun parseStatusTimestamp(iso: String?, fallbackDurationHours: Int = 0): Long {
        if (iso.isNullOrBlank()) return System.currentTimeMillis() + fallbackDurationHours * 3_600_000L
        return try {
            // Primär: mit Timezone-Marker (Z oder +HH:MM) – korrekte Methode
            java.time.Instant.parse(iso).toEpochMilli()
        } catch (_: Exception) {
            try {
                // Fallback: naiver ISO-String ohne Timezone (Server sendet UTC ohne Z)
                java.time.LocalDateTime.parse(iso)
                    .toInstant(java.time.ZoneOffset.UTC)
                    .toEpochMilli()
            } catch (_: Exception) {
                // Letzter Ausweg: aktuelle Zeit + gewählte Dauer
                System.currentTimeMillis() + fallbackDurationHours * 3_600_000L
            }
        }
    }

    fun uploadStatus(uri: Uri, durationHours: Int, mediaType: String) {
        viewModelScope.launch {
            _isLoading.value = true
            try {
                var file = uriToFile(uri) ?: throw Exception("Datei nicht lesbar.")
                if (mediaType == "image") file = fixImageOrientation(file)
                val mimeType = if (mediaType == "image") "image/*" else "video/*"
                val requestFile = file.asRequestBody(mimeType.toMediaTypeOrNull())
                val body = MultipartBody.Part.createFormData("file", file.name, requestFile)
                val durBody = durationHours.toString()
                    .toRequestBody("text/plain".toMediaTypeOrNull())
                val typeBody = mediaType.toRequestBody("text/plain".toMediaTypeOrNull())
                val letheTeamBody = "false".toRequestBody("text/plain".toMediaTypeOrNull())
                val response = apiService.createStatus(durBody, typeBody, body, letheTeamBody)
                if (response.isSuccessful) {
                    _statusMessage.value = "Status gepostet (${durationHours}h)."
                    loadContactStatuses()
                }
            } catch (e: Exception) {
                _statusMessage.value = "Upload fehlgeschlagen."
            } finally {
                _isLoading.value = false
            }
        }
    }

