    /**
     * Löscht alle lokalen Nachrichten eines Chats ("Nachrichten löschen"/Chat leeren) und
     * setzt zusätzlich einen serverseitigen Cleared-Marker für diesen Chat. Ohne den Marker
     * würde der nächste Öffnen-Sync die lokal gelöschten Nachrichten vom Server wieder
     * nachladen, da sie dort (für den Chatpartner bzw. andere Gruppenmitglieder) unverändert
     * weiter existieren.
     */
    fun clearChatMessages(chatId: String) = viewModelScope.launch {
        messageDao.clearMessagesForChat(chatId)
        try {
            val isGroup = groupDao.getGroupById(chatId) != null
            if (isGroup) {
                apiService.clearGroupChatMessagesOnServer(chatId)
            } else {
                apiService.clearChatMessagesOnServer(chatId)
            }
        } catch (e: Exception) {
            Timber.tag("Chat").e(e, "Serverseitiger Cleared-Marker fehlgeschlagen für $chatId")
        }
    }

    /** Löscht ausgewählte Nachrichten lokal und auf dem Server. */
    fun deleteMessages(localIds: Set<Long>) = viewModelScope.launch {
        val msgs = localIds.mapNotNull { messageDao.getMessageByLocalId(it) }
        messageDao.deleteMessagesByIds(localIds.toList())
        val myId = _currentUser.value?.userId
        msgs.forEach { msg ->
            if (msg.messageId != null) {
                // Löschung an alle Teilnehmer propagieren (1:1 + Gruppe, inkl. eigener Geräte).
                // Der Server entscheidet anhand der Absender-Berechtigung ob für alle gelöscht wird.
                val isGroup = groupDao.getGroupById(msg.chatId) != null
                val payload = buildMap<String, Any> {
                    put("message_id", msg.messageId)
                    if (isGroup) put("group_id", msg.chatId)
                }
                webSocketManager.sendMessage("delete_message", msg.chatId, payload)
            }
        }
    }

    /** Markiert Nachrichten als wichtig (lokal). */
    fun starMessages(localIds: Set<Long>, star: Boolean) = viewModelScope.launch {
        localIds.forEach { messageDao.setImportant(it, star) }
    }

    /** Leitet Nachrichten an einen anderen Kontakt oder eine Gruppe weiter. */
    fun forwardMessages(messages: List<com.securechat.app.data.local.MessageEntity>, targetId: String) = viewModelScope.launch {
        val me = _currentUser.value ?: return@launch
        messages.forEach { msg ->
            val clientId = UUID.randomUUID().toString()
            val entity = com.securechat.app.data.local.MessageEntity(
                chatId = targetId,
                senderId = me.userId,
                receiverId = targetId,
                content = msg.content,
                mediaType = msg.mediaType,
                mediaUrl = msg.mediaUrl,
                timestamp = System.currentTimeMillis(),
                clientMessageId = clientId,
                deliveryStatus = 0
            )
            messageDao.insertMessage(entity)
            webSocketManager.sendMessage("message", targetId, buildMap {
                put("content_blob", msg.content ?: "")
                put("media_type", msg.mediaType)
                if (msg.mediaUrl != null) put("media_url", msg.mediaUrl)
                put("client_message_id", clientId)
            })
        }
    }

    /** Leitet eine einzelne Mediendatei an einen anderen Chat weiter. */
    fun forwardMediaMessage(targetId: String, mediaUrl: String, mediaType: String) = viewModelScope.launch {
        val me = _currentUser.value ?: return@launch
        val clientId = UUID.randomUUID().toString()
        val entity = com.securechat.app.data.local.MessageEntity(
            chatId = targetId,
            senderId = me.userId,
            receiverId = targetId,
            content = null,
            mediaType = mediaType,
            mediaUrl = mediaUrl,
            timestamp = System.currentTimeMillis(),
            clientMessageId = clientId,
            deliveryStatus = 0
        )
        messageDao.insertMessage(entity)
        webSocketManager.sendMessage("message", targetId, buildMap {
            put("content_blob", "")
            put("media_type", mediaType)
            put("media_url", mediaUrl)
            put("client_message_id", clientId)
        })
    }

