                if (response.isSuccessful) {
                    val body = response.body()
                    _serverStatus.value = if (body?.server == "online")
                        com.securechat.app.data.network.ServiceStatus.ONLINE
                    else
                        com.securechat.app.data.network.ServiceStatus.OFFLINE
                    _turnStatus.value = when (body?.turn) {
                        "online"  -> com.securechat.app.data.network.ServiceStatus.ONLINE
                        "offline" -> com.securechat.app.data.network.ServiceStatus.OFFLINE
                        else      -> com.securechat.app.data.network.ServiceStatus.ERROR
                    }
                } else {
                    _serverStatus.value = com.securechat.app.data.network.ServiceStatus.ERROR
                    _turnStatus.value   = com.securechat.app.data.network.ServiceStatus.UNKNOWN
                }
            } catch (e: Exception) {
                _serverStatus.value = com.securechat.app.data.network.ServiceStatus.OFFLINE
                _turnStatus.value   = com.securechat.app.data.network.ServiceStatus.UNKNOWN
            }
