    fun restartServer() {
        viewModelScope.launch {
            _isRestarting.value = true
            _restartLog.value = emptyList()
            appendRestartLog("Sende Neustart-Befehl an Server…")
            try {
                apiService.restartServer()
                appendRestartLog("Befehl gesendet – alle Instanzen werden neu gestartet…")
            } catch (e: java.io.IOException) {
                // Connection reset ist erwartet: Server startet neu und trennt die Verbindung
                appendRestartLog("Verbindung getrennt – Server startet neu…")
            } catch (e: Exception) {
                appendRestartLog("Fehler beim Senden: ${e.message}")
                _isRestarting.value = false
                return@launch
            }
            // 10 Sekunden warten damit alle Instanzen Zeit haben hochzufahren
            delay(10_000)
            appendRestartLog("Warte auf Server-Bereitschaft…")
            var elapsed = 0
            while (elapsed < 90_000) {
                delay(2_000)
                elapsed += 2_000
                try {
                    val status = apiService.getAdminStatus()
                    if (status.isSuccessful) {
                        appendRestartLog("✓ Server wieder online! (nach ${(elapsed + 10000) / 1000}s)")
                        _serverStatus.value = com.securechat.app.data.network.ServiceStatus.ONLINE
                        delay(500)
                        loadAdminLogs(40)
                        refreshInstances()
                        break
                    } else {
                        appendRestartLog("… noch nicht bereit (${(elapsed + 3000) / 1000}s)")
                    }
                } catch (_: Exception) {
                    appendRestartLog("… noch nicht erreichbar (${(elapsed + 3000) / 1000}s)")
                }
            }
            if (elapsed >= 90_000) {
                appendRestartLog("⚠ Timeout – Server antwortet nicht. Bitte manuell prüfen.")
            }
            _isRestarting.value = false
        }
    }

    fun clearRestartLog() {
        _restartLog.value = emptyList()
    }

    private fun appendRestartLog(line: String) {
        val ts = java.time.LocalTime.now()
            .format(java.time.format.DateTimeFormatter.ofPattern("HH:mm:ss"))
        _restartLog.value = _restartLog.value + "[$ts] $line"
    }

