                } else {
                    _adminActionMessage.value = "Fehler: ${response.code()}"
                }
            } catch (e: Exception) {
                _adminActionMessage.value = "Fehler: ${e.message}"
            }
        }
    }

    fun deleteSparkComment(sparkId: String, commentId: String) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                Timber.tag("LETHE_SPARK").d("deleteSparkComment: sparkId=$sparkId commentId=$commentId")
                val backup = _sparkComments.value
                _sparkComments.value = backup.filter { it.id != commentId }
                val response = apiService.deleteSparkComment(sparkId, commentId)
                if (!response.isSuccessful) {
                    val errorBody = response.errorBody()?.string()
                    Timber.tag("LETHE_SPARK").e("deleteSparkComment: HTTP ${response.code()} – $errorBody")
                    _sparkComments.value = backup
                }
            } catch (e: Exception) {
                Timber.tag("LETHE_SPARK").e(e, "deleteSparkComment: exception")
                loadSparkComments(sparkId)
            }
        }
    }

