    private val _adminEditUserDetails = MutableStateFlow<com.securechat.app.data.network.AdminUserDetails?>(null)
    val adminEditUserDetails: StateFlow<com.securechat.app.data.network.AdminUserDetails?> = _adminEditUserDetails

    private val _adminEditUserMessage = MutableStateFlow<String?>(null)
