    fun adminCreateUser(
        fakeNumber: String,
        name: String,
        password: String,
        phoneNumber: String?,
        isAdmin: Boolean,
        isModerator: Boolean,
        isCreator: Boolean,
        onDone: (success: Boolean, msg: String) -> Unit = { _, _ -> }
    ) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val body = com.securechat.app.data.network.AdminCreateUserRequest(
                    fakeNumber = fakeNumber,
                    name = name,
                    password = password,
                    phoneNumber = phoneNumber?.takeIf { it.isNotBlank() },
                    isAdmin = isAdmin,
                    isModerator = isModerator,
                    isCreator = isCreator
                )
                val response = apiService.adminCreateUser(body)
                if (response.isSuccessful) {
                    val msg = "User angelegt ✓"
                    _adminCreateUserMessage.value = msg
                    withContext(Dispatchers.Main) { onDone(true, msg) }
                } else {
                    val err = response.errorBody()?.string() ?: response.code().toString()
                    val msg = "Fehler: $err"
                    _adminCreateUserMessage.value = msg
                    withContext(Dispatchers.Main) { onDone(false, msg) }
                }
            } catch (e: Exception) {
                val msg = "Fehler: ${e.message}"
                _adminCreateUserMessage.value = msg
                withContext(Dispatchers.Main) { onDone(false, msg) }
            }
        }
    }

    fun adminLoadUserDetails(userId: String) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val response = apiService.adminGetUserDetails(userId)
                if (response.isSuccessful) {
                    val map = response.body() ?: return@launch
                    _adminEditUserDetails.value = com.securechat.app.data.network.AdminUserDetails(
                        id = map["id"]?.toString() ?: "",
                        fakeNumber = map["fake_number"]?.toString() ?: "",
                        name = map["name"]?.toString() ?: "",
                        phoneNumber = map["phone_number"]?.toString() ?: "",
                        isAdmin = map["is_admin"] == true,
                        isModerator = map["is_moderator"] == true,
                        isCreator = map["is_creator"] == true,
                        isBlocked = map["is_blocked"] == true,
                        ageVerified = map["age_verified"] == true,
                        isPhoneVerified = map["is_phone_verified"] == true,
                        isVerified = map["is_verified"] == true,
                        info = map["info"]?.toString() ?: "",
                        styx = (map["styx"] as? Double)?.toInt() ?: (map["styx"] as? Int) ?: 0,
                        instagram = map["instagram"]?.toString() ?: "",
                        tiktok = map["tiktok"]?.toString() ?: "",
                        youtube = map["youtube"]?.toString() ?: "",
                        showOnlineStatus = map["show_online_status"] != false,
                        showReadReceipts = map["show_read_receipts"] != false,
                        statusVisible = map["status_visible"] != false,
                        profileImageUrl = map["profile_image_url"]?.toString() ?: "",
                        letheId = map["lethe_id"]?.toString() ?: "",
                        createdAt = map["created_at"]?.toString()
                    )
                    _adminEditUserMessage.value = null
                } else {
                    _adminEditUserMessage.value = "Nutzer nicht gefunden: ${response.code()}"
                }
            } catch (e: Exception) {
                _adminEditUserMessage.value = "Fehler: ${e.message}"
            }
        }
    }

