    fun runFailoverStatus() { runFailover("status") }
    fun runFailoverPromote() { runFailover("promote") }
    fun runFailoverRecover() { runFailover("recover") }
    fun clearFailoverLog() { _failoverLog.value = emptyList() }

    private fun runFailover(mode: String) {
        viewModelScope.launch {
            val token = tokenManager.getToken() ?: return@launch
            _failoverRunning.value = true
            _failoverLog.value = emptyList()
            _failoverLog.value = listOf("Führe failover.sh $mode aus…")
            try {
                val resp = when (mode) {
                    "status"  -> apiService.failoverStatus("Bearer $token")
                    "promote" -> apiService.failoverPromote("Bearer $token")
                    "recover" -> apiService.failoverRecover("Bearer $token")
                    else -> null
                }
                val output = resp?.body()?.output ?: "Keine Antwort."
                _failoverLog.value = output.lines().filter { it.isNotBlank() }
            } catch (e: Exception) {
                _failoverLog.value = listOf("Fehler: ${e.message}")
            } finally {
                _failoverRunning.value = false
            }
        }
    }

