    // --- POLLS ---

    /**
     * Erstellt eine neue Poll im Chat mit einem Kontakt.
     * Der Server speichert die Poll und sendet sie als "poll"-Nachricht an den Empfänger.
     */
    fun createPoll(question: String, options: List<String>, receiverId: String, allowMultipleChoice: Boolean = false) {
        viewModelScope.launch {
            if (options.size < 2) {
                _statusMessage.value = "Mindestens 2 Optionen erforderlich."
                return@launch
            }
            _isLoading.value = true
            try {
                val response = apiService.createPoll(PollCreate(question, options, receiverId, allowMultipleChoice))
                if (response.isSuccessful && response.body() != null) {
                    val poll = response.body()!!
                    // Lokal in Room cachen
                    val entity = PollEntity(
                        pollId = poll.id,
                        question = poll.question,
                        optionsJson = com.google.gson.Gson().toJson(poll.options),
                        resultsJson = com.google.gson.Gson().toJson(poll.results),
                        createdBy = poll.createdBy,
                        receiverId = poll.receiverId,
                        userVote = -1,
                        allowMultipleChoice = poll.allowMultipleChoice,
                        userVotesJson = com.google.gson.Gson().toJson(poll.userVotes),
                        createdAt = System.currentTimeMillis()
                    )
                    pollDao.insertPoll(entity)
                    _currentPoll.value = entity
                    _statusMessage.value = "Poll erstellt!"
                } else {
                    _statusMessage.value = "Fehler beim Erstellen der Poll."
                }
            } catch (e: Exception) {
                _statusMessage.value = "Netzwerkfehler: ${e.message}"
                Timber.tag("Poll").e("createPoll failed", e)
            } finally {
                _isLoading.value = false
            }
        }
    }

    /**
     * Lädt eine Poll (zuerst aus lokalem Cache, dann vom Server).
     */
    fun loadPoll(pollId: String) {
        viewModelScope.launch {
            // Sofort aus Cache anzeigen
            _currentPoll.value = pollDao.getPollById(pollId)
            // Dann aktuellen Stand vom Server holen
            try {
                val response = apiService.getPoll(pollId)
                if (response.isSuccessful && response.body() != null) {
                    val poll = response.body()!!
                    val entity = PollEntity(
                        pollId = poll.id,
                        question = poll.question,
                        optionsJson = com.google.gson.Gson().toJson(poll.options),
                        resultsJson = com.google.gson.Gson().toJson(poll.results),
                        createdBy = poll.createdBy,
                        receiverId = poll.receiverId,
                        userVote = poll.userVote ?: -1,
                        allowMultipleChoice = poll.allowMultipleChoice,
                        userVotesJson = com.google.gson.Gson().toJson(poll.userVotes),
                        createdAt = System.currentTimeMillis()
                    )
                    pollDao.insertPoll(entity)
                    _currentPoll.value = entity
                }
            } catch (e: Exception) {
                Timber.tag("Poll").e("loadPoll failed", e)
            }
        }
    }

    /**
     * Gibt eine Stimme für eine Poll-Option ab.
     * Server schickt poll_update via WebSocket an beide Chat-Partner.
     */
    fun voteOnPoll(pollId: String, optionIndex: Int) {
        viewModelScope.launch {
            try {
                val response = apiService.voteOnPoll(pollId, PollVoteRequest(optionIndex))
                if (response.isSuccessful) {
                    pollDao.setUserVote(pollId, optionIndex)
                    _currentPoll.value = pollDao.getPollById(pollId)
                    _statusMessage.value = "Stimme abgegeben!"
                } else if (response.code() == 409) {
                    _statusMessage.value = "Du hast bereits abgestimmt."
                } else {
                    _statusMessage.value = "Fehler beim Abstimmen."
                }
            } catch (e: Exception) {
                _statusMessage.value = "Netzwerkfehler: ${e.message}"
                Timber.tag("Poll").e("voteOnPoll failed", e)
            }
        }
    }

    // --- MEDIEN & BACKUP ---

    fun uploadProfileImage(uri: Uri) {
        viewModelScope.launch {
            _isLoading.value = true
            val me = _currentUser.value ?: return@launch
            try {
                val file = uriToFile(uri) ?: throw Exception("Datei konnte nicht erstellt werden.")
                val requestFile = file.asRequestBody("image/*".toMediaTypeOrNull())
                val body = MultipartBody.Part.createFormData("file", file.name, requestFile)
                val response = apiService.uploadProfileImage(me.userId, body)
                if (response.isSuccessful) {
                    val imageUrl = response.body()?.get("url")?.let {
                        "${toAbsoluteUrl(it)}?t=${System.currentTimeMillis()}"
                    }
                    val updated = _currentUser.value?.copy(profileImageUrl = imageUrl)
                    if (updated != null) {
                        userDao.insertUser(updated)
                        _currentUser.value = updated
                    }
                    _statusMessage.value = "Profilbild hochgeladen!"
                }
            } catch (e: Exception) {
                _statusMessage.value = "Upload fehlgeschlagen."
            } finally {
                _isLoading.value = false
            }
        }
    }

    private suspend fun uriToFile(uri: Uri, mediaType: String = "image"): File? = withContext(Dispatchers.IO) {
        try {
            val ext = when (mediaType) {
                "video" -> "mp4"
                "audio" -> "m4a"
                else -> "jpg"
            }
            val file = File(context.cacheDir, "upload_${java.util.UUID.randomUUID()}.$ext")
            context.contentResolver.openInputStream(uri)?.use { input ->
                FileOutputStream(file).use { output -> input.copyTo(output) }
            }
            file
        } catch (e: Exception) { null }
    }

    /**
     * Liest EXIF-Orientierung, dreht das Bild, skaliert und komprimiert adaptiv
     * basierend auf der gemessenen Upload-Geschwindigkeit. Bei schnellem Netz/WLAN
     * wird Standard-Qualität (82%, 1920px) verwendet, bei langsamem Mobilnetz
     * wird stärker komprimiert.
     */
    private fun fixImageOrientation(file: File): File {
        try {
            val exif = android.media.ExifInterface(file.absolutePath)
            val orientation = exif.getAttributeInt(
                android.media.ExifInterface.TAG_ORIENTATION,
                android.media.ExifInterface.ORIENTATION_NORMAL
            )
            val degrees = when (orientation) {
                android.media.ExifInterface.ORIENTATION_ROTATE_90  -> 90f
                android.media.ExifInterface.ORIENTATION_ROTATE_180 -> 180f
                android.media.ExifInterface.ORIENTATION_ROTATE_270 -> 270f
                else -> 0f
            }
            if (degrees == 0f) return file
            val bitmap = BitmapFactory.decodeFile(file.absolutePath) ?: return file
            val matrix = android.graphics.Matrix().apply { postRotate(degrees) }
            val rotated = Bitmap.createBitmap(bitmap, 0, 0, bitmap.width, bitmap.height, matrix, true)
            bitmap.recycle()
            FileOutputStream(file).use { rotated.compress(Bitmap.CompressFormat.JPEG, 98, it) }
            rotated.recycle()
            exif.setAttribute(android.media.ExifInterface.TAG_ORIENTATION,
                android.media.ExifInterface.ORIENTATION_NORMAL.toString())
            exif.saveAttributes()
        } catch (e: Exception) {
            Timber.tag("LETHE_UPLOAD").e("fixImageOrientation failed: ${e.message}")
        }
        return file
    }

    private fun prepareImageForUpload(file: File, clientId: String, speedMbps: Float = -1f): File {
        return try {
            val maxWidth = SpeedTestHelper.getOptimalMaxWidth(speedMbps)
            val quality = SpeedTestHelper.getOptimalImageQuality(speedMbps)

            // EXIF-Orientierung lesen
            val exif = android.media.ExifInterface(file.absolutePath)
            val orientation = exif.getAttributeInt(
                android.media.ExifInterface.TAG_ORIENTATION,
                android.media.ExifInterface.ORIENTATION_NORMAL
            )
            val degrees = when (orientation) {
                android.media.ExifInterface.ORIENTATION_ROTATE_90  -> 90f
                android.media.ExifInterface.ORIENTATION_ROTATE_180 -> 180f
                android.media.ExifInterface.ORIENTATION_ROTATE_270 -> 270f
                else -> 0f
            }

            // Bildgröße ohne Decode ermitteln, um inSampleSize zu berechnen
            val boundsOpts = BitmapFactory.Options().apply { inJustDecodeBounds = true }
            BitmapFactory.decodeFile(file.absolutePath, boundsOpts)
            val origWidth = boundsOpts.outWidth.takeIf { it > 0 } ?: maxWidth

            // Größte Zweierpotenz wählen, sodass das dekodierte Bild noch >= maxWidth bleibt
            var sample = 1
            while (origWidth / (sample * 2) >= maxWidth) sample *= 2

            // Bild mit Subsampling dekodieren (deutlich weniger RAM + schneller)
            var bitmap = BitmapFactory.decodeFile(
                file.absolutePath,
                BitmapFactory.Options().apply { inSampleSize = sample }
            ) ?: return file

            // Rotieren falls nötig
            if (degrees != 0f) {
                val matrix = android.graphics.Matrix().apply { postRotate(degrees) }
                val rotated = Bitmap.createBitmap(bitmap, 0, 0, bitmap.width, bitmap.height, matrix, true)
                bitmap.recycle()
                bitmap = rotated
            }

            // Fein-Skalierung falls nach Subsampling noch zu breit
            if (bitmap.width > maxWidth) {
                val ratio = maxWidth.toFloat() / bitmap.width
                val h = (bitmap.height * ratio).toInt()
                val scaled = Bitmap.createScaledBitmap(bitmap, maxWidth, h, true)
                bitmap.recycle()
                bitmap = scaled
            }

            val out = File(context.cacheDir, "img_upload_${clientId}.jpg")
            FileOutputStream(out).use { bitmap.compress(Bitmap.CompressFormat.JPEG, quality, it) }
            bitmap.recycle()
            out
        } catch (e: Exception) {
            Timber.tag("LETHE_UPLOAD").e("prepareImageForUpload failed: ${e.message}")
            file
        }
    }

