    // --- DATA EXPORT / IMPORT (Full Backup) ---

    private val _backupProgress = MutableStateFlow(-1f)
    val backupProgress: StateFlow<Float> = _backupProgress.asStateFlow()

    // --- KEY-BACKUP INFO (Zeitpunkt + Typ des letzten Schlüssel-Backups) ---

    private val KEY_BACKUP_INFO_PREF_KEY = "lethe_key_backup_info_json"
    private val _keyBackupInfo = MutableStateFlow<KeyBackupInfo?>(null)
    val keyBackupInfo: StateFlow<KeyBackupInfo?> = _keyBackupInfo.asStateFlow()

    /** Persistiert die Metadaten nach jedem erfolgreichen Backup und aktualisiert den StateFlow. */
    private fun recordKeyBackupInfo(automatic: Boolean) {
        val info = KeyBackupInfo(System.currentTimeMillis(), automatic)
        try {
            deferredBackupPrefs().edit()
                .putString(KEY_BACKUP_INFO_PREF_KEY, com.google.gson.Gson().toJson(info))
                .apply()
        } catch (_: Exception) { /* nicht-kritisch */ }
        _keyBackupInfo.value = info
    }

    /** Lädt die zuletzt gespeicherten Backup-Metadaten in den StateFlow (für die Einstellungen-Anzeige). */
    fun loadKeyBackupInfo() {
        // Lokale Metadaten (mit Datum/Typ) haben Vorrang.
        try {
            val json = deferredBackupPrefs().getString(KEY_BACKUP_INFO_PREF_KEY, null)
            if (json != null) {
                _keyBackupInfo.value = com.google.gson.Gson().fromJson(json, KeyBackupInfo::class.java)
                return
            }
        } catch (_: Exception) { /* nicht-kritisch */ }
        // Kein lokales Backup-Datum vorhanden: prüfen, ob auf dem Server ein Backup liegt.
        // Wenn ja, sofort als "vorhanden" anzeigen – ohne Datum.
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val resp = apiService.getKeyBackup()
                val blob = resp.body()?.encryptedBlob
                if (resp.isSuccessful && !blob.isNullOrBlank()) {
                    _keyBackupInfo.value = KeyBackupInfo(timestamp = 0L, automatic = false, dateKnown = false)
                }
            } catch (_: Exception) { /* nicht-kritisch */ }
        }
    }

    /** Pending Google Drive Account – gesetzt von Activity nach Sign-In */
    var pendingGoogleAccount: android.accounts.Account? = null

    fun exportFullBackup(password: String, outputUri: Uri, onResult: (Boolean, String) -> Unit) {
        viewModelScope.launch(Dispatchers.IO) {
            _backupProgress.value = 0f
            val result = com.securechat.app.data.BackupManager.createBackup(
                context = context,
                password = password,
                outputUri = outputUri,
                userDao = userDao,
                contactDao = contactDao,
                messageDao = messageDao,
                groupDao = groupDao,
                groupSenderKeyDao = groupSenderKeyDao,
                pollDao = pollDao,
                tokenManager = tokenManager,
                userPreferencesRepository = prefsRepository,
                onProgress = { _backupProgress.value = it }
            )
            _backupProgress.value = -1f
            if (result.isSuccess) {
                renewAllContactHandshakesSilent()
            }
            withContext(Dispatchers.Main) {
                if (result.isSuccess) {
                    onResult(true, result.getOrDefault("Backup erfolgreich erstellt"))
                } else {
                    onResult(false, "Backup fehlgeschlagen: ${result.exceptionOrNull()?.message ?: "Unbekannter Fehler"}")
                }
            }
        }
    }

