    fun exportToGoogleDrive(password: String, account: android.accounts.Account, onResult: (Boolean, String) -> Unit) {
        viewModelScope.launch(Dispatchers.IO) {
            _backupProgress.value = 0f
            // 1) Backup lokal erstellen
            val tempFile = java.io.File(context.cacheDir, "lethe_backup_gdrive_${System.currentTimeMillis()}.lethe")
            val tempUri = android.net.Uri.fromFile(tempFile)
            val result = com.securechat.app.data.BackupManager.createBackup(
                context = context,
                password = password,
                outputUri = tempUri,
                userDao = userDao,
                contactDao = contactDao,
                messageDao = messageDao,
                groupDao = groupDao,
                groupSenderKeyDao = groupSenderKeyDao,
                pollDao = pollDao,
                tokenManager = tokenManager,
                userPreferencesRepository = prefsRepository,
                onProgress = { _backupProgress.value = it * 0.7f }
            )
            if (result.isFailure) {
                tempFile.delete()
                _backupProgress.value = -1f
                withContext(Dispatchers.Main) {
                    onResult(false, "Backup-Erstellung fehlgeschlagen: ${result.exceptionOrNull()?.message}")
                }
                return@launch
            }

            // 2) Zu Google Drive hochladen (Upload-Logik im flavor-spezifischen
            // DriveBackupProvider, damit src/main frei von Google-Drive-API-Referenzen bleibt)
            _backupProgress.value = 0.75f
            val uploadResult = driveBackupProvider.uploadBackup(context, account, tempFile) { p ->
                _backupProgress.value = 0.75f + p * 0.25f
            }
            tempFile.delete()
            if (uploadResult.isSuccess) {
                _backupProgress.value = -1f
                renewAllContactHandshakesSilent()
                withContext(Dispatchers.Main) {
                    onResult(true, "Backup auf Google Drive hochgeladen")
                }
            } else {
                _backupProgress.value = -1f
                val e = uploadResult.exceptionOrNull()
                timber.log.Timber.e(e, "Google Drive Upload fehlgeschlagen")
                withContext(Dispatchers.Main) {
                    onResult(false, "Google Drive Upload fehlgeschlagen: ${e?.message}")
                }
            }
        }
    }

