    private suspend fun renewAllContactHandshakesSilent() {
        try {
            val contacts = contactDao.getAllContacts().first()
            contacts.forEach { c ->
                if (c.publicKey.length > 100) {
                    try {
                        val resp = apiService.requestHandshakeRenew(HandshakeRenewRequest(c.userId))
                        if (!resp.isSuccessful) {
                            com.securechat.app.data.crypto.CryptoManager.forceRederiveSharedSecret(c.userId, c.publicKey)
                        }
                    } catch (_: Exception) {
                        com.securechat.app.data.crypto.CryptoManager.forceRederiveSharedSecret(c.userId, c.publicKey)
                    }
                }
            }
            Timber.tag("LETHE_E2EE").i("renewAllContactHandshakesSilent: Handshake-Erneuerung für ${contacts.size} Kontakte abgeschlossen")
        } catch (_: Exception) {}
    }

    // --- E2EE KEY-BACKUP ---

    /**
     * Erstellt einen verschlüsselten Key-Backup-Blob und lädt ihn auf den Server hoch.
     *
     * Für API 31+ (Hardware-Key): Wechselt einmalig auf einen Software-Key, der exportierbar ist.
     * Der neue öffentliche Key wird danach ebenfalls hochgeladen.
     *
     * @param passphrase  Backup-Passwort (PBKDF2+AES-256-GCM, 100.000 Iterationen)
     * @param automatic   true = automatisch ausgelöst (V3), false = manuell über den Button (V2)
     * @param onResult    Callback mit (success, message)
     */
    fun backupKeys(passphrase: String, automatic: Boolean = false, onResult: (Boolean, String) -> Unit) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val (blob, newPubKey) = CryptoManager.encryptKeyForBackup(passphrase)
                    ?: run {
                        withContext(Dispatchers.Main) { onResult(false, "Schlüssel konnten nicht verschlüsselt werden.") }
                        return@launch
                    }

                // Backup hochladen
                val uploadResp = apiService.uploadKeyBackup(KeyBackupUploadRequest(blob))
                if (!uploadResp.isSuccessful) {
                    withContext(Dispatchers.Main) { onResult(false, "Upload fehlgeschlagen (HTTP ${uploadResp.code()}).") }
                    return@launch
                }

                // Falls ein neuer Soft-Key generiert wurde (API 31+): Public Key aktualisieren
                val user = _currentUser.value
                if (user != null && newPubKey != user.publicKey) {
                    try {
                        // notifyContacts: Key wurde rotiert (API 31+ Hardware→Soft-Key). Kontakte müssen
                        // den neuen Public Key übernehmen, sonst bricht ihr v2-Shared-Secret zu uns ab.
                        apiService.updateEcdhKey(EcdhKeyUpdateRequest(newPubKey, notifyContacts = true))
                        // Soft-Key in Room persistieren
                        val softPriv = CryptoManager.exportSoftPrivateKey()
                        val updated = user.copy(publicKey = newPubKey, privateKey = softPriv ?: user.privateKey)
                        userDao.insertUser(updated)
                        _currentUser.value = updated
                    } catch (e: Exception) {
                        Timber.tag("KeyBackup").w("Public Key Upload nach Backup fehlgeschlagen: ${e.message}")
                    }
                }

                recordKeyBackupInfo(automatic)
                withContext(Dispatchers.Main) { onResult(true, "Schlüssel-Backup erfolgreich gespeichert.") }
            } catch (e: Exception) {
                Timber.tag("KeyBackup").e("backupKeys fehlgeschlagen: ${e.message}")
                withContext(Dispatchers.Main) { onResult(false, "Backup-Fehler: ${e.message}") }
            }
        }
    }

    /**
     * Lädt den Key-Backup-Blob vom Server und stellt die Schlüssel wieder her.
     *
     * Nach der Wiederherstellung wird der Shared-Secret-Cache neu aufgebaut
     * und der öffentliche Key ggf. erneut hochgeladen (falls er sich geändert hat).
     *
     * @param passphrase  Das beim Backup gesetzte Passwort
     * @param onResult    Callback mit (success, message)
     */
    fun restoreKeysFromBackup(passphrase: String, onResult: (Boolean, String) -> Unit) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                // Backup vom Server laden
                val resp = apiService.getKeyBackup()
                if (!resp.isSuccessful) {
                    withContext(Dispatchers.Main) { onResult(false, "Backup konnte nicht abgerufen werden (HTTP ${resp.code()}).") }
                    return@launch
                }
                val blob = resp.body()?.encryptedBlob
                if (blob.isNullOrBlank()) {
                    withContext(Dispatchers.Main) { onResult(false, "Kein Backup auf dem Server gefunden.") }
                    return@launch
                }

                // Entschlüsseln & Keys laden
                val restoredPubKey = CryptoManager.decryptAndLoadKeyBackup(passphrase, blob)
                if (restoredPubKey == null) {
                    withContext(Dispatchers.Main) { onResult(false, "Falsches Passwort oder beschädigtes Backup.") }
                    return@launch
                }

                // Soft-Key in Room persistieren
                val user = _currentUser.value
                if (user != null) {
                    val softPriv = CryptoManager.exportSoftPrivateKey()
                    val updated = user.copy(publicKey = restoredPubKey, privateKey = softPriv ?: user.privateKey)
                    userDao.insertUser(updated)
                    _currentUser.value = updated
                }

                // Public Key auf Server aktualisieren (falls nötig)
                try {
                    apiService.updateEcdhKey(EcdhKeyUpdateRequest(restoredPubKey, notifyContacts = true))
                } catch (e: Exception) {
                    Timber.tag("KeyBackup").w("Public Key Re-Upload fehlgeschlagen: ${e.message}")
                }

                // Shared-Secret-Cache für alle Kontakte neu aufbauen
                CryptoManager.clearSecrets()
                try {
                    val contacts = contactDao.getAllContacts().first()
                    contacts.forEach { c ->
                        if (c.publicKey.length > 100) {
                            CryptoManager.deriveSharedSecret(c.userId, c.publicKey)
                        }
                    }
                } catch (e: Exception) {
                    Timber.tag("KeyBackup").w("Secret-Cache Rebuild fehlgeschlagen: ${e.message}")
                }

                withContext(Dispatchers.Main) { onResult(true, "Schlüssel erfolgreich wiederhergestellt.") }
            } catch (e: Exception) {
                Timber.tag("KeyBackup").e("restoreKeysFromBackup fehlgeschlagen: ${e.message}")
                withContext(Dispatchers.Main) { onResult(false, "Wiederherstellungs-Fehler: ${e.message}") }
            }
        }
    }

    /**
     * Schlüssel-Rotation bei Gerätewechsel.
     *
     * Ablauf:
     * 1. Alle gespeicherten Nachrichten mit alten Shared Secrets entschlüsseln (Zugriff sicherstellen).
     * 2. Aktuellen ECDH-Key auf Server hochladen und alle Kontakte per WS benachrichtigen.
     * 3. Shared-Secret-Cache leeren und für alle Kontakte neu aufbauen.
     *
     * Kontakte erhalten ein key_rotated WS-Event und leiten ihrerseits den neuen Shared Secret ab.
     *
     * @param onResult Callback mit (success, message)
     */
    fun rotateEcdhKey(onResult: (Boolean, String) -> Unit) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val user = _currentUser.value
                    ?: run {
                        withContext(Dispatchers.Main) { onResult(false, "Nicht eingeloggt.") }
                        return@launch
                    }

                // Schritt 1: Sicherstellen dass alle lokal gecachten v2:-Blobs noch entschlüsselbar sind.
                // Room speichert i.d.R. Klartext – dieser Schritt deckt etwaige nicht entschlüsselte Blobs ab.
                try {
                    val contacts = contactDao.getAllContacts().first()
                    contacts.forEach { contact ->
                        if (CryptoManager.hasSharedSecret(contact.userId)) {
                            val msgs = messageDao.getRecentMessagesForChat(contact.userId, 50)
                            msgs.forEach { m ->
                                val raw = m.content ?: return@forEach
                                if (raw.startsWith("v2:")) {
                                    CryptoManager.decryptBestEffort(contact.userId, raw)
                                }
                            }
                        }
                    }
                } catch (e: Exception) {
                    Timber.tag("KeyRotation").w("Nachrichten-Verifikation fehlgeschlagen: ${e.message}")
                }

                // Schritt 2: Aktuellen ECDH Public Key ermitteln und mit notify_contacts hochladen
                val currentPubKey = CryptoManager.ensureKeyPair(context, user.privateKey)
                val resp = apiService.updateEcdhKey(
                    EcdhKeyUpdateRequest(ecdhPublicKey = currentPubKey, notifyContacts = true)
                )
                if (!resp.isSuccessful) {
                    withContext(Dispatchers.Main) { onResult(false, "Key-Upload fehlgeschlagen (HTTP ${resp.code()}).") }
                    return@launch
                }

                // Schritt 3: Shared-Secret-Cache neu aufbauen
                CryptoManager.clearSecrets()
                try {
                    val contacts = contactDao.getAllContacts().first()
                    contacts.forEach { c ->
                        if (c.publicKey.length > 100) {
                            CryptoManager.deriveSharedSecret(c.userId, c.publicKey)
                        }
                    }
                } catch (e: Exception) {
                    Timber.tag("KeyRotation").w("Secret-Cache Rebuild fehlgeschlagen: ${e.message}")
                }

                Timber.tag("KeyRotation").i("Schlüssel-Rotation abgeschlossen. Kontakte benachrichtigt.")
                withContext(Dispatchers.Main) { onResult(true, "Schlüssel-Rotation abgeschlossen.") }
            } catch (e: Exception) {
                Timber.tag("KeyRotation").e("rotateEcdhKey fehlgeschlagen: ${e.message}")
                withContext(Dispatchers.Main) { onResult(false, "Fehler bei der Schlüssel-Rotation: ${e.message}") }
            }
        }
    }

    // ─────────────────────────────────────────────────────────────────────────
    // UMK (User Master Key) – Multi-Device Schlüsselmanagement
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * Initialisiert den UMK nach dem Login.
     * 1. Holt encrypted_umk vom Server
     * 2. Entschlüsselt mit Passwort (PBKDF2)
     * 3. Oder generiert neuen UMK falls keiner existiert
     * 4. Holt Partner-UMKs für alle Kontakte und leitet Conversation Keys ab
     */
    fun initUmk(password: String) {
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val resp = apiService.getUmk()
                if (!resp.isSuccessful) {
                    Timber.tag("LETHE_UMK").w("UMK-Abruf fehlgeschlagen: HTTP ${resp.code()}")
                    return@launch
                }
                val umkResp = resp.body() ?: return@launch

                if (umkResp.hasUmk && !umkResp.encryptedUmk.isNullOrBlank()) {
                    // UMK entschlüsseln
                    val success = CryptoManager.decryptUmkWithPassword(password, umkResp.encryptedUmk)
                    if (!success) {
                        Timber.tag("LETHE_UMK").w("UMK-Entschlüsselung fehlgeschlagen (falsches Passwort?)")
                        return@launch
                    }
                } else {
                    // Neuen UMK generieren und hochladen
                    CryptoManager.generateUmk()
                    val blob = CryptoManager.encryptUmkWithPassword(password)
                    if (blob != null) {
                        apiService.uploadUmk(UmkUploadRequest(encryptedUmk = blob))
                    }
                }
                Timber.tag("LETHE_UMK").i("UMK initialisiert.")

                // Partner-UMKs für alle Kontakte laden → Conversation Keys ableiten
                loadPartnerUmks()
            } catch (e: Exception) {
                Timber.tag("LETHE_UMK").e("initUmk fehlgeschlagen: ${e.message}")
            }
        }
    }

    /**
     * Initiiert UMK-Exchange mit allen Kontakten die UMK-fähig sind.
     * Sendet eigenen UMK (ECDH-verschlüsselt) an Partner → Partner antwortet mit seinem UMK.
     */
    private suspend fun loadPartnerUmks() {
        if (!CryptoManager.hasUmk()) return
        try {
            val contacts = contactDao.getAllContacts().first()
            for (contact in contacts) {
                if (CryptoManager.hasConversationKey(contact.userId)) continue
                try {
                    val resp = apiService.getPartnerUmk(contact.userId)
                    if (resp.isSuccessful && resp.body()?.hasUmk == true) {
                        initiateUmkExchange(contact.userId)
                    }
                } catch (_: Exception) {}
            }
        } catch (e: Exception) {
            Timber.tag("LETHE_UMK").w("loadPartnerUmks fehlgeschlagen: ${e.message}")
        }
    }

    /**
     * Stellt beim Öffnen eines 1:1-Chats sicher, dass ein Conversation Key (v3) für den Partner
     * existiert. Fehlt er, wird der UMK-Exchange gezielt für diesen Kontakt erneut angestoßen
     * (nicht-blockierend) – behebt den Fall, dass der Partner beim Login offline war.
     */
    private fun ensureConversationKeyForChat(contactId: String) {
        if (!CryptoManager.hasUmk()) return
        if (CryptoManager.hasConversationKey(contactId)) return
        viewModelScope.launch(Dispatchers.IO) {
            try {
                val resp = apiService.getPartnerUmk(contactId)
                if (resp.isSuccessful && resp.body()?.hasUmk == true) {
                    initiateUmkExchange(contactId)
                }
            } catch (_: Exception) {}
        }
    }

    /**
     * Versucht beim Senden kurzzeitig (max. ~1,2 s) einen Conversation Key (v3) zu beschaffen,
     * falls noch keiner existiert. Stößt den UMK-Exchange an und pollt auf das Ergebnis.
     * Schlägt es fehl (Partner offline / kein UMK), wird ohne Verzögerung auf v2 zurückgefallen.
     */
    private suspend fun tryLazyConversationKey(contactId: String) {
        if (!CryptoManager.hasUmk()) return
        if (CryptoManager.hasConversationKey(contactId)) return
        try {
            val resp = apiService.getPartnerUmk(contactId)
            if (!(resp.isSuccessful && resp.body()?.hasUmk == true)) return
            initiateUmkExchange(contactId)
            kotlinx.coroutines.withTimeoutOrNull(1200L) {
                while (!CryptoManager.hasConversationKey(contactId)) {
                    delay(100L)
                }
            }
        } catch (_: Exception) {}
    }

    // --- KONTAKTANFRAGEN POLLING ---

    /**
     * Ruft ausstehende Kontaktanfragen vom Server ab und zeigt sie im In-App-Dialog an.
     * Wird beim App-Start / Login ausgeführt, damit Anfragen nicht verloren gehen.
     */
    fun loadPendingContactRequests() {
        viewModelScope.launch {
            try {
                val response = apiService.getPendingContacts()
                if (response.isSuccessful) {
                    val pending = response.body() ?: emptyList()
                    if (pending.isNotEmpty()) {
                        // Erste ausstehende Anfrage im Dialog anzeigen
                        val first = pending.first()
                        _incomingContactRequest.value = IncomingRequest(
                            fromFakeNumber = first.fromFakeNumber,
                            fromName = first.fromName,
                            contactEntryId = first.contactEntryId
                        )
                        Timber.tag("Contacts").d("${pending.size} ausstehende Kontaktanfragen geladen.")
                    }
                }
            } catch (e: Exception) {
                Timber.tag("Contacts").e("Pending requests check failed", e)
            }
        }
    }

    /**
     * Plant eine periodische Hintergrundaufgabe (alle 15 Minuten) die auch dann
     * läuft wenn die App geschlossen ist.
     */
    private fun schedulePendingContactsCheck() {
        val wm = WorkManager.getInstance(context)

        // Kontaktanfragen-Check
        val contactRequest = PeriodicWorkRequestBuilder<ContactRequestWorker>(15, TimeUnit.MINUTES)
            .build()
        wm.enqueueUniquePeriodicWork(
            "contact_request_check",
            ExistingPeriodicWorkPolicy.KEEP,
            contactRequest
        )

        // WebSocket-Reconnect als Fallback (alle 15 Minuten)
        val reconnectRequest = PeriodicWorkRequestBuilder<WebSocketReconnectWorker>(15, TimeUnit.MINUTES)
            .build()
        wm.enqueueUniquePeriodicWork(
            "websocket_reconnect",
            ExistingPeriodicWorkPolicy.KEEP,
            reconnectRequest
        )

        // Upload-Geschwindigkeitstest (alle 15 Min – WorkManager-Minimum)
        val speedTestRequest = PeriodicWorkRequestBuilder<SpeedTestWorker>(15, TimeUnit.MINUTES)
            .build()
        wm.enqueueUniquePeriodicWork(
            "upload_speed_test",
            ExistingPeriodicWorkPolicy.KEEP,
            speedTestRequest
        )

        Timber.tag("WorkManager").d("Periodischer Kontaktanfragen-Check, WS-Reconnect und Speed-Test geplant.")
    }

