    // --- LINK PREVIEW ---

    /** Lädt OG-Metadaten (Titel, Beschreibung, Bild) von einer URL.
     * Erkennt YouTube/TikTok/Instagram automatisch für Embed-Unterstützung. */
    suspend fun fetchPublicContentPreview(contentId: String): com.securechat.app.data.network.PublicContentPreview? {
        return try {
            val resp = kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) {
                apiService.getPublicContentPreview(contentId)
            }
            if (resp.isSuccessful) resp.body() else null
        } catch (_: Exception) { null }
    }

    fun fetchLinkPreview(url: String) {
        if (_linkPreviewLoading.value) return
        viewModelScope.launch(Dispatchers.IO) {
            _linkPreviewLoading.value = true
            try {
                // --- Interner Spark/Livestream/Beitrag-Link: lethe://sp?id=, lethe://li?id=, lethe://post?C= ---
                val uri = android.net.Uri.parse(url)
                val isSparkScheme = uri.scheme == "lethe" && uri.host == "sp"
                val isLiveScheme = uri.scheme == "lethe" && uri.host == "li"
                val isLegacyPostScheme = uri.scheme == "lethe" && uri.host == "post"
                if (isSparkScheme || isLiveScheme || isLegacyPostScheme) {
                    val contentId = when {
                        isSparkScheme || isLiveScheme -> uri.getQueryParameter("id")
                        else -> uri.getQueryParameter("C") ?: uri.getQueryParameter("c")
                    }
                    if (!contentId.isNullOrBlank()) {
                        val resp = apiService.getPublicContentPreview(contentId)
                        if (resp.isSuccessful) {
                            val c = resp.body() ?: run { _linkPreviewLoading.value = false; return@launch }
                            val imgUrl = if (isLiveScheme) null else c.previewImageUrl?.let {
                                if (it.startsWith("http")) it else "https://letheapp.de$it"
                            }
                            _linkPreview.value = LinkPreviewData(
                                url = url,
                                title = c.title ?: if (isLiveScheme) "Livestream" else "Spark",
                                description = c.description,
                                imageUrl = imgUrl,
                                thumbnailUrl = imgUrl,
                                siteName = "@${c.creatorUsername ?: c.creatorName ?: "Lethe"}"
                            )
                        }
                    }
                    _linkPreviewLoading.value = false
                    return@launch
                }

                // --- Embed-Erkennung VOR dem OG-Fetch ---
                val youtubeRegex = Regex(
                    """(?:youtu\.be/|youtube\.com/(?:watch\?v=|shorts/|embed/))([a-zA-Z0-9_-]{11})"""
                )
                val youtubeMatch = youtubeRegex.find(url)
                if (youtubeMatch != null) {
                    val videoId = youtubeMatch.groupValues[1]
                    _linkPreview.value = LinkPreviewData(
                        url = url,
                        title = "YouTube Video",
                        siteName = "YouTube",
                        embedType = "youtube",
                        embedUrl = "https://www.youtube.com/embed/$videoId",
                        thumbnailUrl = "https://img.youtube.com/vi/$videoId/hqdefault.jpg",
                        imageUrl = "https://img.youtube.com/vi/$videoId/hqdefault.jpg"
                    )
                    _linkPreviewLoading.value = false
                    return@launch
                }

                val isTikTok = url.contains("tiktok.com/@") && url.contains("/video/") ||
                    url.contains("vm.tiktok.com/")
                val isInstagram = url.contains("instagram.com/reel/") || url.contains("instagram.com/p/")

                val request = Request.Builder()
                    .url(url)
                    .header("User-Agent", "Mozilla/5.0 (Linux; Android 14; Pixel 8) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Mobile Safari/537.36")
                    .header("Accept", "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8")
                    .header("Accept-Language", "de-DE,de;q=0.9,en-US;q=0.8,en;q=0.7")
                    .get()
                    .build()
                val response = linkPreviewHttpClient.newCall(request).execute()
                // Bis zu 512 KB lesen: OG-Tags stehen im <head>, aber Shops wie Amazon
                // liefern das Produktbild erst im <body> (landingImage) → mehr lesen.
                val html = response.use { resp ->
                    resp.body?.source()?.let { src ->
                        val buf = okio.Buffer()
                        var total = 0L
                        while (total < 512_000L) {
                            val read = src.read(buf, 32_768)
                            if (read == -1L) break
                            total += read
                        }
                        buf.readUtf8()
                    }
                } ?: return@launch

                val title = extractOgTag(html, "og:title")
                    ?: extractHtmlTitle(html)
                    ?: url
                val description = extractOgTag(html, "og:description")
                    ?: extractMetaName(html, "description")
                val rawImage = extractOgTag(html, "og:image")
                    ?: extractOgTag(html, "og:image:secure_url")
                    ?: extractOgTag(html, "og:image:url")
                    ?: extractMetaName(html, "twitter:image")
                    ?: extractMetaName(html, "twitter:image:src")
                    ?: extractOgTag(html, "twitter:image")
                    ?: extractLinkRelImage(html)
                    ?: extractAmazonImage(html)
                val imageUrl = when {
                    rawImage == null -> null
                    rawImage.startsWith("http") -> rawImage
                    rawImage.startsWith("//") -> "https:$rawImage"
                    else -> {
                        val uri = java.net.URL(url)
                        "${uri.protocol}://${uri.host}$rawImage"
                    }
                }
                val siteName = extractOgTag(html, "og:site_name")

                _linkPreview.value = LinkPreviewData(
                    url = url,
                    title = title.trim().take(120),
                    description = description?.trim()?.take(200),
                    imageUrl = imageUrl,
                    siteName = siteName,
                    embedType = when {
                        isTikTok -> "tiktok"
                        isInstagram -> "instagram"
                        else -> null
                    },
                    thumbnailUrl = imageUrl
                )
            } catch (_: Throwable) {
                // Keine Vorschau verfügbar – kein Fehler anzeigen
            } finally {
                _linkPreviewLoading.value = false
            }
        }
    }

    fun clearLinkPreview() {
        _linkPreview.value = null
        _linkPreviewLoading.value = false
    }

    private fun extractOgTag(html: String, property: String): String? {
        val p1 = Regex(
            """<meta[^>]+property=["']${Regex.escape(property)}["'][^>]+content=["']([^"']+)["']""",
            RegexOption.IGNORE_CASE
        )
        val p2 = Regex(
            """<meta[^>]+content=["']([^"']+)["'][^>]+property=["']${Regex.escape(property)}["']""",
            RegexOption.IGNORE_CASE
        )
        return p1.find(html)?.groupValues?.getOrNull(1)
            ?: p2.find(html)?.groupValues?.getOrNull(1)
    }

    private fun extractMetaName(html: String, name: String): String? {
        val p1 = Regex(
            """<meta[^>]+name=["']${Regex.escape(name)}["'][^>]+content=["']([^"']+)["']""",
            RegexOption.IGNORE_CASE
        )
        val p2 = Regex(
            """<meta[^>]+content=["']([^"']+)["'][^>]+name=["']${Regex.escape(name)}["']""",
            RegexOption.IGNORE_CASE
        )
        return p1.find(html)?.groupValues?.getOrNull(1)
            ?: p2.find(html)?.groupValues?.getOrNull(1)
    }

    private fun extractHtmlTitle(html: String): String? {
        val p = Regex("""<title[^>]*>([^<]+)</title>""", RegexOption.IGNORE_CASE)
        return p.find(html)?.groupValues?.getOrNull(1)
    }

    /** <link rel="image_src" href="..."> – ältere Bildvorschau-Konvention. */
    private fun extractLinkRelImage(html: String): String? {
        val p1 = Regex(
            """<link[^>]+rel=["']image_src["'][^>]+href=["']([^"']+)["']""",
            RegexOption.IGNORE_CASE
        )
        val p2 = Regex(
            """<link[^>]+href=["']([^"']+)["'][^>]+rel=["']image_src["']""",
            RegexOption.IGNORE_CASE
        )
        return p1.find(html)?.groupValues?.getOrNull(1)
            ?: p2.find(html)?.groupValues?.getOrNull(1)
    }

    /**
     * Amazon liefert oft kein og:image – Produktbild aus dem Bild-Element ziehen.
     * Deckt Desktop- (id="landingImage") UND Mobile-/Kurzlink-Layout (amzn.eu →
     * id="main-image" bzw. beliebiges <img> mit data-a-dynamic-image) ab.
     */
    private fun extractAmazonImage(html: String): String? {
        // 1) Desktop-Layout: <img id="landingImage" ...>
        Regex("""<img[^>]*\bid=["']landingImage["'][^>]*>""", RegexOption.IGNORE_CASE)
            .find(html)?.value?.let { imageFromAmazonImgTag(it)?.let { u -> return u } }
        // 2) Mobile-Layout: <img id="main-image" ...>
        Regex("""<img[^>]*\bid=["']main-image["'][^>]*>""", RegexOption.IGNORE_CASE)
            .find(html)?.value?.let { imageFromAmazonImgTag(it)?.let { u -> return u } }
        // 3) Fallback: erstes <img> mit data-a-dynamic-image (Amazon-Produktbild-Marker)
        Regex("""<img[^>]*\bdata-a-dynamic-image=[^>]*>""", RegexOption.IGNORE_CASE)
            .find(html)?.value?.let { imageFromAmazonImgTag(it)?.let { u -> return u } }
        return null
    }

    /** Extrahiert die beste Bild-URL aus einem einzelnen Amazon-<img>-Tag. */
    private fun imageFromAmazonImgTag(imgTag: String): String? {
        // data-old-hires: höchste Auflösung
        Regex("""data-old-hires=["']([^"']+)["']""", RegexOption.IGNORE_CASE)
            .find(imgTag)?.groupValues?.getOrNull(1)
            ?.takeIf { it.startsWith("http") }?.let { return it }
        // data-a-dynamic-image: JSON-Map URL->[w,h]; Quotes können HTML-escaped sein (&quot;)
        Regex("""data-a-dynamic-image=["']([^"']+)["']""", RegexOption.IGNORE_CASE)
            .find(imgTag)?.groupValues?.getOrNull(1)?.let { raw ->
                val decoded = raw.replace("&quot;", "\"").replace("&#34;", "\"")
                Regex("""https?://[^"'\\\s]+?\.(?:jpg|jpeg|png|webp)""", RegexOption.IGNORE_CASE)
                    .find(decoded)?.value?.let { return it }
            }
        // data-src / src (Platzhalter-Pixel ausschließen)
        Regex("""\bdata-src=["'](https?://[^"']+)["']""", RegexOption.IGNORE_CASE)
            .find(imgTag)?.groupValues?.getOrNull(1)
            ?.takeIf { !it.contains("pixel") }?.let { return it }
        Regex("""\bsrc=["'](https?://[^"']+)["']""", RegexOption.IGNORE_CASE)
            .find(imgTag)?.groupValues?.getOrNull(1)
            ?.takeIf { !it.contains("pixel") }?.let { return it }
        return null
    }

