    /** Prüft ob die gegebene ID eine Gruppe ist (suspend, für Coroutine-Kontext). */
    suspend fun isGroupChat(chatId: String): Boolean = groupDao.getGroupById(chatId) != null

    /**
     * Verarbeitet einen Google-Assistant-Intent ("Hey Google, schreibe eine Lethe an [Name]").
     * [recipient] ist die Nummer/der Name aus dem smsto:-URI.
     * [messageBody] ist der optional diktierte Nachrichtentext.
     *
     * Sucht den passenden Kontakt und navigiert direkt in den Chat (via setPendingDeepLink).
     * Falls kein Kontakt gefunden: öffnet die Kontaktliste.
     */
    fun handleAssistantSendToIntent(recipient: String, messageBody: String?) {
        viewModelScope.launch {
            val allContacts = contactDao.getAllContacts().first()
            val recipientTrimmed = recipient.trim()
            val contact = allContacts.find { c ->
                val displayName = c.username?.takeIf { it.isNotBlank() } ?: c.fakeNumber
                c.fakeNumber.equals(recipientTrimmed, ignoreCase = true) ||
                    c.username?.equals(recipientTrimmed, ignoreCase = true) == true ||
                    displayName.equals(recipientTrimmed, ignoreCase = true)
            }
            if (contact != null) {
                if (!messageBody.isNullOrBlank()) setPendingChatText(messageBody)
                setPendingDeepLink(chatId = contact.userId, navigateTo = null)
            } else {
                // Kein Kontakt gefunden → Kontaktliste öffnen
                setPendingDeepLink(chatId = null, navigateTo = null)
            }
        }
    }

    /** Setzt Text, der beim nächsten Chat-Öffnen vorbefüllt werden soll. */
    fun setPendingChatText(text: String) { _pendingChatText.value = text }
    fun clearPendingChatText() { _pendingChatText.value = null }

    /**
     * Verarbeitet einen abgeschlossenen Google-Play-Kauf mit 2-Stufen-Sicherheit:
     *   1. Server-Verifikation: RSA-Signatur gegen Google-Schlüssel geprüft (POST /coins/verify-purchase)
     *   2. Gutschrift:          Coins werden verbucht (POST /coins/purchase)
     *   → consumeAsync im PlaystoreBillingProvider wird nur bei Rückgabe > 0 ausgelöst.
     *
     * Die lokale RSA-Signaturprüfung + PURCHASED-State-Filterung passiert bereits im
     * BillingProvider, bevor [purchase] (nur noch primitive Felder) hier ankommt.
     *
     * @return Anzahl gutgeschriebener Styx (0 bei jeder Fehlerart)
     */
    suspend fun handleCoinPurchase(purchase: com.securechat.app.billing.CoinPurchaseInfo): Int {
        val productId = purchase.productId

        return try {
            // ── Stufe 1: Server prüft RSA-Signatur ──────────────────────────────
            val verifyResponse = apiService.verifyPurchase(
                com.securechat.app.data.network.VerifyPurchaseRequest(
                    signedData = purchase.signedData,
                    signature  = purchase.signature,
                    productId  = productId
                )
            )
            if (!verifyResponse.isSuccessful) {
                Timber.tag("LETHE_COINS").e("Server-Verifikation fehlgeschlagen (${verifyResponse.code()}) – Kauf abgelehnt")
                return 0
            }
            Timber.tag("LETHE_COINS").d("Server-Verifikation OK")

            // ── Stufe 2: Coins gutschreiben ──────────────────────────────────────
            val grantResponse = apiService.grantCoins(
                com.securechat.app.data.network.CoinPurchaseRequest(
                    purchaseToken = purchase.purchaseToken,
                    productId     = productId,
                    signedData    = purchase.signedData,
                    signature     = purchase.signature
                )
            )
            if (grantResponse.isSuccessful) {
                val body = grantResponse.body() ?: return 0
                val updated = _currentUser.value?.copy(styx = body.newBalance) ?: return 0
                userDao.insertUser(updated)
                _currentUser.value = updated
                Timber.tag("LETHE_COINS").d("+${body.added} Styx – neues Guthaben: ${body.newBalance}")
                body.added
            } else {
                Timber.tag("LETHE_COINS").w("grantCoins Fehler: ${grantResponse.code()}")
                0
            }
        } catch (e: Exception) {
            Timber.tag("LETHE_COINS").e("handleCoinPurchase Exception: ${e.message}")
            0
        }
    }

