    fun verifyAge(imageFile: java.io.File, birthdate: String) {
        viewModelScope.launch {
            try {
                _ageVerificationResult.value = null
                val reqFile = imageFile.readBytes().toRequestBody("image/jpeg".toMediaTypeOrNull())
                val part = MultipartBody.Part.createFormData("file", imageFile.name, reqFile)
                val birthdateBody = birthdate.toRequestBody("text/plain".toMediaTypeOrNull())
                val response = apiService.verifyAge(part, birthdateBody)
                if (response.isSuccessful) {
                    _ageVerificationResult.value = response.body()
                    if (response.body()?.success == true) {
                        // Aktuelles Profil vom Server holen, damit is18Verified korrekt gesetzt wird
                        try {
                            val profileResp = apiService.getMe()
                            if (profileResp.isSuccessful) {
                                val p = profileResp.body()
                                _currentUser.value?.let { u ->
                                    val updated = u.copy(
                                        ageVerified = p?.ageVerified ?: true,
                                        is18Verified = p?.is18Verified ?: false
                                    )
                                    userDao.insertUser(updated)
                                    _currentUser.value = updated
                                }
                            }
                        } catch (_: Exception) {
                            // Fallback: nur ageVerified setzen
                            _currentUser.value?.let { u ->
                                val updated = u.copy(ageVerified = true)
                                userDao.insertUser(updated)
                                _currentUser.value = updated
                            }
                        }
                    }
                } else {
                    _ageVerificationResult.value = AgeVerificationResponse(
                        success = false,
                        message = "Serverfehler (${response.code()})"
                    )
                }
            } catch (e: Exception) {
                Timber.tag("AgeVerify").e("verifyAge fehlgeschlagen: ${e.message}")
                _ageVerificationResult.value = AgeVerificationResponse(
                    success = false,
                    message = "Verbindungsfehler: ${e.message}"
                )
            }
        }
    }

    fun resetAgeVerificationResult() {
        _ageVerificationResult.value = null
    }

