    val listenTogetherChatId: StateFlow<String?> = _listenTogetherChatId.asStateFlow()

    private val _listenTogetherTrack      = MutableStateFlow<ListenTogetherTrack?>(null)
    val listenTogetherTrack: StateFlow<ListenTogetherTrack?> = _listenTogetherTrack.asStateFlow()

    private val _listenTogetherIsPlaying  = MutableStateFlow(false)
    val listenTogetherIsPlaying: StateFlow<Boolean> = _listenTogetherIsPlaying.asStateFlow()

    private val _listenTogetherPosition   = MutableStateFlow(0L)
