    /** Lokal gespeicherte Playlist (ohne aktive Session). */
    private val _savedListenTogetherPlaylist = MutableStateFlow<List<ListenTogetherTrack>>(emptyList())
    val savedListenTogetherPlaylist: StateFlow<List<ListenTogetherTrack>> = _savedListenTogetherPlaylist.asStateFlow()

    private val _savedListenTogetherChatId = MutableStateFlow<String?>(null)
    val savedListenTogetherChatId: StateFlow<String?> = _savedListenTogetherChatId.asStateFlow()

    /** Speichert die Playlist lokal und auf dem Server (persistiert über Neuinstallationen). */
    fun saveListenTogetherPlaylist(chatId: String, playlist: List<ListenTogetherTrack>) {
        _savedListenTogetherChatId.value   = chatId
        _savedListenTogetherPlaylist.value = playlist
        viewModelScope.launch {
            try {
                val request = SavePlaylistRequest(
                    tracks = playlist.map { t ->
                        SavedPlaylistTrack(
                            url      = t.url,
                            title    = t.title,
                            artist   = t.artist,
                            cover    = t.coverUrl,
                            duration = t.durationMs
                        )
                    }
                )
                apiService.saveListenTogetherPlaylist(chatId, request)
            } catch (e: Exception) {
                android.util.Log.e("ListenTogether", "Playlist speichern fehlgeschlagen: ${e.message}")
            }
        }
    }

    /** Lädt die gespeicherte Playlist vom Server und setzt _savedListenTogetherPlaylist. */
    fun loadSavedListenTogetherPlaylist(chatId: String) {
        viewModelScope.launch {
            try {
                val response = apiService.getListenTogetherPlaylist(chatId)
                if (response.isSuccessful) {
                    val tracks = response.body()?.tracks ?: return@launch
                    if (tracks.isNotEmpty()) {
                        _savedListenTogetherChatId.value   = chatId
                        _savedListenTogetherPlaylist.value = tracks.map { t ->
                            ListenTogetherTrack(
                                url       = toAbsoluteUrl(t.url),
                                title     = t.title,
                                artist    = t.artist,
                                coverUrl  = t.cover,
                                durationMs = t.duration
                            )
                        }
                    }
                }
            } catch (e: Exception) {
                android.util.Log.e("ListenTogether", "Playlist laden fehlgeschlagen: ${e.message}")
            }
        }
    }

    /** Startet eine Listen-Together-Session und sendet eine Einladung an den Chat-Partner. */
    fun requestListenTogether(chatId: String, track: ListenTogetherTrack, playlist: List<ListenTogetherTrack> = emptyList()) {
        val resolvedPlaylist = if (playlist.isEmpty()) listOf(track) else playlist
        _listenTogetherWaiting.value   = true
        _listenTogetherActive.value    = false
        _listenTogetherChatId.value    = chatId
        _listenTogetherTrack.value     = track
        _listenTogetherPlaylist.value  = resolvedPlaylist
        _listenTogetherTrackIndex.value = 0
        _listenTogetherIsPlaying.value = false
        _listenTogetherPosition.value  = 0L
        _isListenTogetherHost.value    = true
        _listenTogetherRejected.value  = false
        webSocketManager.sendMessage(
            type       = "request_listen_together",
            receiverId = chatId,
            payload    = mapOf(
                "chat_id"        to chatId,
                "track_url"      to track.url,
                "track_title"    to track.title,
                "track_artist"   to track.artist,
                "track_cover"    to track.coverUrl,
                "track_duration" to track.durationMs
            )
        )
        // Systemnachricht lokal in den Chat einfügen (für den Host sichtbar)
        viewModelScope.launch(Dispatchers.IO) {
            val myName = _currentUser.value?.name ?: _currentUser.value?.fakeNumber ?: "Du"
            messageDao.insertMessage(
                MessageEntity(
                    chatId     = chatId,
                    senderId   = "lethe_system",
                    receiverId = chatId,
                    content    = "🎵 $myName möchte Listen Together starten: ${track.title}",
                    mediaType  = "text",
                    timestamp  = System.currentTimeMillis(),
                    isRead     = true,
                    isSent     = true,
                    deliveryStatus = 3,
                    replyToSenderId = _currentUser.value?.userId
                )
            )
        }
        Timber.tag("LETHE_LISTEN").d("Listen Together angefragt: ${track.title} → $chatId")
    }

    /** Nimmt eine eingehende Listen-Together-Einladung an. */
    fun acceptListenTogether() {
        val invite = _listenTogetherInvite.value ?: return
        _listenTogetherActive.value    = true
        // fromUserId = the host's userId, which matches the guest's ChatScreen chatId
        _listenTogetherChatId.value    = invite.fromUserId
        _listenTogetherTrack.value     = invite.track
        _listenTogetherIsPlaying.value = false
        _listenTogetherPosition.value  = 0L
        _isListenTogetherHost.value    = false
        _listenTogetherInvite.value    = null
        // Bestätigung an Host senden – Track-Info für Server-Session mitschicken
        webSocketManager.sendMessage(
            type       = "accept_listen_together",
            receiverId = invite.fromUserId,
            payload    = mapOf(
                "chat_id"        to invite.fromUserId,
                "track_url"      to invite.track.url,
                "track_title"    to invite.track.title,
                "track_artist"   to invite.track.artist,
                "track_cover"    to (invite.track.coverUrl ?: ""),
                "track_duration" to invite.track.durationMs,
            )
        )
    }

    /** Lehnt eine eingehende Einladung ab oder schließt den Einladungs-Dialog. */
    fun dismissListenTogetherInvite() {
        val invite = _listenTogetherInvite.value
        if (invite != null) {
            webSocketManager.sendMessage(
                type       = "reject_listen_together",
                receiverId = invite.fromUserId,
                payload    = mapOf("chat_id" to invite.fromUserId)
            )
        }
        _listenTogetherInvite.value = null
    }

    /** Beendet die aktive Session und benachrichtigt den Partner. */
    fun leaveListenTogether() {
        val chatId = _listenTogetherChatId.value
        if (chatId != null) {
            webSocketManager.sendMessage(
                type       = "playlist_action",
                receiverId = chatId,
                payload    = mapOf("chat_id" to chatId, "action" to "leave")
            )
        }
        _listenTogetherActive.value        = false
        _listenTogetherWaiting.value       = false
        _listenTogetherChatId.value        = null
        _listenTogetherTrack.value         = null
        _listenTogetherPlaylist.value      = emptyList()
        _listenTogetherTrackIndex.value    = 0
        _isListenTogetherHost.value        = false
        _listenTogetherRejected.value      = false
        _listenTogetherPendingAction.value = null
        _listenTogetherActionRequest.value = null
        _listenTogetherShuffleActive.value = false
        Timber.tag("LETHE_LISTEN").d("Listen Together verlassen")
    }

    /** Sendet den aktuellen Wiedergabe-Status (Host → Gast). */
    fun syncListenTogetherState(isPlaying: Boolean, positionMs: Long) {
        val chatId = _listenTogetherChatId.value ?: return
        _listenTogetherIsPlaying.value = isPlaying
        _listenTogetherPosition.value  = positionMs
        webSocketManager.sendMessage(
            type       = "music_sync_state",
            receiverId = chatId,
            payload    = mapOf(
                "chat_id"     to chatId,
                "is_playing"  to isPlaying,
                "position_ms" to positionMs
            )
        )
    }

    /** Sendet eine Playlist-Aktion (next / prev) an den Partner und wechselt den Track. */
    fun sendPlaylistAction(action: String) {
        val chatId   = _listenTogetherChatId.value ?: return
        val playlist = _listenTogetherPlaylist.value
        if ((action == "next" || action == "prev") && playlist.size > 1) {
            val currentIdx = _listenTogetherTrackIndex.value
            val newIdx = when (action) {
                "next" -> (currentIdx + 1).coerceAtMost(playlist.size - 1)
                else   -> (currentIdx - 1).coerceAtLeast(0)
            }
            if (newIdx != currentIdx) {
                _listenTogetherTrackIndex.value = newIdx
                val newTrack = playlist[newIdx]
                _listenTogetherTrack.value       = newTrack
                _listenTogetherIsPlaying.value   = false
                _listenTogetherPosition.value    = 0L
                webSocketManager.sendMessage(
                    type       = "playlist_action",
                    receiverId = chatId,
                    payload    = mapOf(
                        "chat_id"        to chatId,
                        "action"         to action,
                        "track_url"      to newTrack.url,
                        "track_title"    to newTrack.title,
                        "track_artist"   to newTrack.artist,
                        "track_cover"    to (newTrack.coverUrl ?: ""),
                        "track_duration" to newTrack.durationMs
                    )
                )
            }
        } else {
            webSocketManager.sendMessage(
                type       = "playlist_action",
                receiverId = chatId,
                payload    = mapOf("chat_id" to chatId, "action" to action)
            )
        }
    }

    /**
     * Führt Play/Pause direkt mit Partner-Bestätigung aus.
     * Next/Prev werden sofort ohne Bestätigung ausgeführt.
     */
    fun requestPlayAction(action: String) {
        val chatId = _listenTogetherChatId.value ?: return
        when (action) {
            "next", "prev" -> {
                // Sofort wechseln – kein Confirmation-Flow nötig
                sendPlaylistAction(action)
            }
            else -> {
                _listenTogetherPendingAction.value = action
                webSocketManager.sendMessage(
                    type       = "action_request",
                    receiverId = chatId,
                    payload    = mapOf(
                        "chat_id"     to chatId,
                        "action"      to action,
                        "position_ms" to _listenTogetherPosition.value
                    )
                )
                Timber.tag("LETHE_LISTEN").d("Aktionsanfrage gesendet: $action")
            }
        }
    }

    /** Bestätigt die eingehende Aktionsanfrage des Partners. */
    fun confirmPeerAction() {
        val req    = _listenTogetherActionRequest.value ?: return
        val chatId = _listenTogetherChatId.value ?: return
        _listenTogetherActionRequest.value = null
        webSocketManager.sendMessage(
            type       = "action_confirm",
            receiverId = chatId,
            payload    = mapOf("chat_id" to chatId, "action" to req.action)
        )
    }

    /** Lehnt die eingehende Aktionsanfrage des Partners ab. */
    fun rejectPeerAction() {
        val chatId = _listenTogetherChatId.value ?: return
        _listenTogetherActionRequest.value = null
        webSocketManager.sendMessage(
            type       = "action_reject",
            receiverId = chatId,
            payload    = mapOf("chat_id" to chatId)
        )
    }

    /** Schließt den Ablehnungs-Hinweis. */
    fun dismissListenTogetherRejected() {
        _listenTogetherRejected.value = false
    }

    /** Mischt die Playlist lokal und synchronisiert die neue Reihenfolge mit dem Partner. */
    fun shuffleListenTogetherPlaylist() {
        val chatId = _listenTogetherChatId.value ?: return
        val playlist = _listenTogetherPlaylist.value.toMutableList()
        if (playlist.size < 2) return
        val currentTrack = _listenTogetherTrack.value
        playlist.shuffle()
        // Aktiven Track an den Anfang setzen damit er weiter läuft
        if (currentTrack != null) {
            val idx = playlist.indexOf(currentTrack)
            if (idx > 0) {
                playlist.removeAt(idx)
                playlist.add(0, currentTrack)
            }
        }
        _listenTogetherPlaylist.value = playlist
        _listenTogetherTrackIndex.value = 0
        _listenTogetherShuffleActive.value = true
        // Eindeutige IDs für die Sync-Message: url als Fallback
        val order = playlist.map { it.url }
        webSocketManager.sendMessage(
            type       = "sync_shuffle_order",
            receiverId = chatId,
            payload    = mapOf(
                "chat_id" to chatId,
                "order"   to order,
                "shuffle_active" to true
            )
        )
        Timber.tag("LETHE_LISTEN").d("Playlist geshuffelt und synchronisiert (${playlist.size} Tracks)")
    }

    /**
     * Lädt eine oder mehrere Musikdateien hoch (Listen Together) und startet
     * danach automatisch eine Session mit der ersten Datei als aktiver Track
     * und allen Dateien als Playlist.
     */
    /** Lädt die verfügbaren Tracks für den Listen-Together-Ordner des Chats vom Server. */
    private suspend fun fetchAndApplyListenTogetherTracks(chatId: String) {
        try {
            val response = apiService.getListenTogetherTracks(chatId)
            if (response.isSuccessful) {
                _listenTogetherAvailableTracks.value = withContext(Dispatchers.IO) {
                    response.body()?.tracks?.map {
                        val absUrl = toAbsoluteUrl(it.url)
                        val fallbackTitle = it.filename.substringBeforeLast('.')
                        var title = fallbackTitle
                        var artist = ""
                        try {
                            val retriever = MediaMetadataRetriever()
                            retriever.setDataSource(absUrl, HashMap<String, String>())
                            title = retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_TITLE)
                                ?.takeIf { t -> t.isNotBlank() } ?: fallbackTitle
                            artist = retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_ARTIST) ?: ""
                            retriever.release()
                        } catch (e: Exception) {
                            android.util.Log.w("ListenTogether", "ID3 lesen fehlgeschlagen für $absUrl: ${e.message}")
                        }
                        ListenTogetherTrack(url = absUrl, title = title, artist = artist)
                    } ?: emptyList()
                }
            } else {
                android.util.Log.e("ListenTogether", "Tracks laden fehlgeschlagen: HTTP ${response.code()}")
            }
        } catch (e: Exception) {
            android.util.Log.e("ListenTogether", "Tracks laden Exception: ${e.message}", e)
        }
    }

    fun loadListenTogetherTracks(chatId: String) {
        viewModelScope.launch {
            fetchAndApplyListenTogetherTracks(chatId)
        }
    }

    /** Lädt eine einzelne Audiodatei in den Listen-Together-Ordner des Chats hoch und aktualisiert die Liste. */
    fun uploadListenTogetherTrack(chatId: String, uri: Uri) {
        viewModelScope.launch {
            _listenTogetherUploading.value = true
            _mediaUploadStatus.value = MediaUploadStatus.Uploading(0)
            try {
                val displayName = context.contentResolver.query(
                    uri, arrayOf(android.provider.OpenableColumns.DISPLAY_NAME), null, null, null
                )?.use { c -> if (c.moveToFirst()) c.getString(0) else null }
                    ?: "music_${System.currentTimeMillis()}.mp3"
                val ext = displayName.substringAfterLast('.', "mp3").lowercase()
                val cacheFile = File(context.cacheDir, "lt_setup_${System.currentTimeMillis()}.$ext")
                withContext(Dispatchers.IO) {
                    context.contentResolver.openInputStream(uri)?.use { input ->
                        java.io.FileOutputStream(cacheFile).use { out -> input.copyTo(out) }
                    }
                }
                val rawRequest = cacheFile.asRequestBody("audio/*".toMediaTypeOrNull())
                val body = MultipartBody.Part.createFormData("file", displayName, rawRequest)
                val response = apiService.uploadListenTogetherTrack(chatId, body)
                withContext(Dispatchers.IO) { cacheFile.delete() }
                if (response.isSuccessful) {
                    fetchAndApplyListenTogetherTracks(chatId)
                } else {
                    android.util.Log.e("ListenTogether", "Upload fehlgeschlagen: HTTP ${response.code()} – ${response.errorBody()?.string()}")
                }
            } catch (e: Exception) {
                android.util.Log.e("ListenTogether", "Upload Exception: ${e.message}", e)
            } finally {
                _listenTogetherUploading.value = false
                _mediaUploadStatus.value = MediaUploadStatus.Idle
            }
        }
    }

    fun uploadAndStartListenTogether(chatId: String, uris: List<Uri>) {
        if (uris.isEmpty()) return
        viewModelScope.launch {
            _mediaUploadStatus.value = MediaUploadStatus.Uploading(0)
            val uploadedTracks = mutableListOf<ListenTogetherTrack>()
            try {
                uris.forEachIndexed { index, uri ->
                    val displayName = context.contentResolver.query(
                        uri, arrayOf(android.provider.OpenableColumns.DISPLAY_NAME), null, null, null
                    )?.use { c -> if (c.moveToFirst()) c.getString(0) else null }
                        ?: "music_${System.currentTimeMillis()}.mp3"
                    val ext = displayName.substringAfterLast('.', "mp3").lowercase()
                    val cacheFile = File(context.cacheDir, "lt_${System.currentTimeMillis()}_$index.$ext")
                    withContext(Dispatchers.IO) {
                        context.contentResolver.openInputStream(uri)?.use { input ->
                            java.io.FileOutputStream(cacheFile).use { out -> input.copyTo(out) }
                        }
                    }

                    var title    = displayName.substringBeforeLast('.')
                    var artist   = "Unbekannt"
                    var duration = 0L
                    withContext(Dispatchers.IO) {
                        runCatching {
                            val retriever = MediaMetadataRetriever()
                            retriever.setDataSource(cacheFile.absolutePath)
                            title    = retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_TITLE)    ?: title
                            artist   = retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_ARTIST)   ?: artist
                            duration = retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION)?.toLongOrNull() ?: 0L
                            retriever.release()
                        }
                    }

                    val totalFiles = uris.size
                    val rawRequest = cacheFile.asRequestBody("audio/*".toMediaTypeOrNull())
                    val requestFile = ProgressRequestBody(
                        delegate   = rawRequest,
                        onProgress = { sent, total ->
                            if (total > 0) {
                                val filePct = sent.toFloat() / total
                                val overallPct = ((index + filePct) / totalFiles * 99).toInt().coerceIn(0, 99)
                                _mediaUploadStatus.value = MediaUploadStatus.Uploading(overallPct)
                            }
                        }
                    )
                    val body     = MultipartBody.Part.createFormData("file", cacheFile.name, requestFile)
                    val typeBody = "audio_music".toRequestBody("text/plain".toMediaTypeOrNull())
                    val response = apiService.uploadMedia(typeBody, body)
                    withContext(Dispatchers.IO) { cacheFile.delete() }

                    if (response.isSuccessful) {
                        val mediaUrl = response.body()?.get("url")?.let { toAbsoluteUrl(it) }
                        if (mediaUrl != null) {
                            uploadedTracks += ListenTogetherTrack(
                                url        = mediaUrl,
                                title      = title,
                                artist     = artist,
                                durationMs = duration
                            )
                        }
                    } else {
                        Timber.tag("LETHE_LISTEN").e("Upload fehlgeschlagen (${index + 1}/${uris.size}): ${response.code()}")
                    }
                }

                if (uploadedTracks.isNotEmpty()) {
                    requestListenTogether(
                        chatId   = chatId,
                        track    = uploadedTracks.first(),
                        playlist = uploadedTracks
                    )
                }
            } catch (e: Exception) {
                Timber.tag("LETHE_LISTEN").e(e, "Musik-Upload für Listen Together fehlgeschlagen")
            } finally {
                _mediaUploadStatus.value = MediaUploadStatus.Idle
            }
        }
    }

