    private val _adminSupportTickets = MutableStateFlow<List<com.securechat.app.data.network.AdminSupportTicket>>(emptyList())
    val adminSupportTickets: StateFlow<List<com.securechat.app.data.network.AdminSupportTicket>> = _adminSupportTickets.asStateFlow()

    private val _adminSupportActionMessage = MutableStateFlow<String?>(null)
    val adminSupportActionMessage: StateFlow<String?> = _adminSupportActionMessage.asStateFlow()

    private val _adminSupportLoading = MutableStateFlow(false)
    val adminSupportLoading: StateFlow<Boolean> = _adminSupportLoading.asStateFlow()

    private val _adminSupportLoadError = MutableStateFlow<String?>(null)
    val adminSupportLoadError: StateFlow<String?> = _adminSupportLoadError.asStateFlow()

    fun loadAdminSupportTickets(status: String = "all") {
        viewModelScope.launch {
            _adminSupportLoading.value = true
            _adminSupportLoadError.value = null
            try {
                val token = tokenManager.getToken() ?: run {
                    _adminSupportLoadError.value = "Nicht eingeloggt"
                    _adminSupportLoading.value = false
                    return@launch
                }
                val response = apiService.adminGetSupportTickets("Bearer $token", status)
                if (response.isSuccessful) {
                    _adminSupportTickets.value = response.body() ?: emptyList()
                } else {
                    Timber.tag("MainViewModel").w("loadAdminSupportTickets: HTTP ${response.code()}")
                    _adminSupportLoadError.value = "Fehler ${response.code()}"
                }
            } catch (e: Exception) {
                Timber.tag("MainViewModel").w("loadAdminSupportTickets: ${e.message}")
                _adminSupportLoadError.value = "Netzwerkfehler"
            } finally {
                _adminSupportLoading.value = false
            }
        }
    }

    fun adminReplySupportTicket(ticketId: String, reply: String, newStatus: String = "closed") {
        viewModelScope.launch {
            try {
                val token = tokenManager.getToken() ?: return@launch
                val response = apiService.adminReplySupportTicket(
                    "Bearer $token", ticketId,
                    com.securechat.app.data.network.AdminSupportReplyRequest(reply, newStatus)
                )
                if (response.isSuccessful) {
                    _adminSupportActionMessage.value = "Antwort gesendet"
                    loadAdminSupportTickets()
                } else {
                    _adminSupportActionMessage.value = "Fehler beim Senden"
                }
            } catch (e: Exception) {
                _adminSupportActionMessage.value = "Fehler: ${e.message}"
            }
        }
    }

    fun adminUpdateSupportTicketStatus(ticketId: String, status: String) {
        viewModelScope.launch {
            try {
                val token = tokenManager.getToken() ?: return@launch
                apiService.adminUpdateSupportTicketStatus("Bearer $token", ticketId, mapOf("status" to status))
                loadAdminSupportTickets()
            } catch (e: Exception) {}
        }
    }

