    // LETHE FAMILY – Elternkontrolle
    // =========================================================================

    // ── State ─────────────────────────────────────────────────────────────────

    /**
     * Vollständiger Family-Status des eingeloggten Nutzers.
     * null = noch nicht geladen.
     */
    private val _familyStatus = MutableStateFlow<com.securechat.app.data.network.FamilyStatusResponse?>(null)
    val familyStatus: StateFlow<com.securechat.app.data.network.FamilyStatusResponse?> = _familyStatus.asStateFlow()

    /**
     * Permissions des EIGENEN Accounts (nur befüllt wenn is_child_account == true).
     * Wird beim Login und bei jedem "permissions_updated" WS-Event aktualisiert.
     */
    private val _myChildPermissions = MutableStateFlow<com.securechat.app.data.network.ChildPermissionsResponse?>(null)
    val myChildPermissions: StateFlow<com.securechat.app.data.network.ChildPermissionsResponse?> = _myChildPermissions.asStateFlow()

    /**
     * Berechtigungs-Cache für den Parent-Dashboard: childId → ChildPermissionsResponse.
     * Wird beim Öffnen des Dashboards gefüllt, bei PATCH sofort lokal aktualisiert.
     */
    private val _childPermissionsMap = MutableStateFlow<Map<String, com.securechat.app.data.network.ChildPermissionsResponse>>(emptyMap())
    val childPermissionsMap: StateFlow<Map<String, com.securechat.app.data.network.ChildPermissionsResponse>> = _childPermissionsMap.asStateFlow()

    /** Kontakt-Cache für den Parent-Dashboard: childId → Liste der Kind-Kontakte. */
    private val _childContactsMap = MutableStateFlow<Map<String, List<com.securechat.app.data.network.ChildContactEntry>>>(emptyMap())
    val childContactsMap: StateFlow<Map<String, List<com.securechat.app.data.network.ChildContactEntry>>> = _childContactsMap.asStateFlow()

    /** True wenn gerade ein Family-API-Call läuft. */
    private val _familyLoading = MutableStateFlow(false)
    val familyLoading: StateFlow<Boolean> = _familyLoading.asStateFlow()

    /** Letzter Family-Fehlertext (null = kein Fehler). */
    private val _familyError = MutableStateFlow<String?>(null)
    val familyError: StateFlow<String?> = _familyError.asStateFlow()

    /** Letztes Family-Erfolgsmessage (null = keine). */
    private val _familyMessage = MutableStateFlow<String?>(null)
    val familyMessage: StateFlow<String?> = _familyMessage.asStateFlow()

    // ── Hilfsfunktionen (Permission-Checks) ──────────────────────────────────

    /** Gibt zurück ob der aktuelle Account ein Kind-Account ist. */
    fun isChildAccount(): Boolean = _familyStatus.value?.isChildAccount == true

    /** Gibt zurück ob eine bestimmte Aktion für den Kind-Account erlaubt ist. */
    fun childCan(action: ChildPermission): Boolean {
        val perms = _myChildPermissions.value ?: return true  // kein Kind → alles erlaubt
        return when (action) {
            ChildPermission.VIDEO_CALL  -> perms.canVideoCall
            ChildPermission.AUDIO_CALL  -> perms.canAudioCall
            ChildPermission.SEND_MEDIA  -> perms.canSendMedia
            ChildPermission.VIEW_SPARKS -> perms.canViewSparks
            ChildPermission.USE_NEARBY  -> perms.canUseNearby
            ChildPermission.PLAY_GAMES  -> perms.canPlayGames
        }
    }

    // ── API-Funktionen ────────────────────────────────────────────────────────

    /** Lädt den Family-Status und (falls Kind-Account) die eigenen Permissions. */
    fun loadFamilyStatus() {
        viewModelScope.launch {
            _familyLoading.value = true
            _familyError.value = null
            try {
                val response = apiService.getFamilyStatus()
                if (response.isSuccessful) {
                    val status = response.body() ?: return@launch
                    _familyStatus.value = status
                    // Falls Kind-Account → eigene Permissions laden
                    if (status.isChildAccount) {
                        val parentRelationId = status.parent?.relationId
                        if (parentRelationId != null) {
                            loadMyChildPermissions()
                        }
                    }
                } else {
                    Timber.tag("LETHE_FAMILY").w("loadFamilyStatus HTTP ${response.code()}")
                }
            } catch (e: Exception) {
                Timber.tag("LETHE_FAMILY").e(e, "loadFamilyStatus fehlgeschlagen")
            } finally {
                _familyLoading.value = false
            }
        }
    }

    /**
     * Lädt die eigenen Kind-Permissions vom Server.
     * Wird intern bei loadFamilyStatus() aufgerufen, kann aber auch manuell aufgerufen werden.
     */
    fun loadMyChildPermissions() {
        viewModelScope.launch {
            try {
                val response = apiService.getMyChildPermissions()
                if (response.isSuccessful) {
                    val perms = response.body() ?: return@launch
                    _myChildPermissions.value = perms
                    Timber.tag("LETHE_FAMILY").i(
                        "loadMyChildPermissions: video=${perms.canVideoCall}, " +
                        "audio=${perms.canAudioCall}, media=${perms.canSendMedia}, " +
                        "sparks=${perms.canViewSparks}, nearby=${perms.canUseNearby}, " +
                        "games=${perms.canPlayGames}"
                    )
                } else {
                    Timber.tag("LETHE_FAMILY").w("loadMyChildPermissions HTTP ${response.code()}")
                }
            } catch (e: Exception) {
                Timber.tag("LETHE_FAMILY").e(e, "loadMyChildPermissions fehlgeschlagen")
            }
        }
    }

    /** Parent erstellt eine neue Einladung und gibt den invite_token zurück. */
    fun createFamilyInvite(onSuccess: (String) -> Unit, onError: (String) -> Unit) {
        viewModelScope.launch {
            _familyLoading.value = true
            try {
                val response = apiService.createFamilyInvite()
                if (response.isSuccessful) {
                    val body = response.body()
                    if (body != null) {
                        _familyMessage.value = "Einladung erstellt"
                        loadFamilyStatus()
                        onSuccess(body.inviteToken)
                    } else {
                        onError("Leere Antwort vom Server")
                    }
                } else {
                    val msg = "Fehler ${response.code()}"
                    _familyError.value = msg
                    onError(msg)
                }
            } catch (e: Exception) {
                val msg = "Netzwerkfehler: ${e.message}"
                _familyError.value = msg
                onError(msg)
            } finally {
                _familyLoading.value = false
            }
        }
    }

    /** Kind-Account akzeptiert eine Family-Einladung anhand des invite_tokens. */
    fun acceptFamilyInvite(token: String, onSuccess: () -> Unit, onError: (String) -> Unit) {
        viewModelScope.launch {
            _familyLoading.value = true
            try {
                val response = apiService.acceptFamilyInvite(
                    com.securechat.app.data.network.FamilyAcceptInviteRequest(inviteToken = token)
                )
                if (response.isSuccessful) {
                    _familyMessage.value = "Erfolgreich mit Familie verbunden"
                    loadFamilyStatus()
                    onSuccess()
                } else {
                    val msg = when (response.code()) {
                        400 -> "Ungültiger oder abgelaufener Token"
                        404 -> "Einladung nicht gefunden"
                        409 -> "Du hast bereits einen Parent verbunden"
                        else -> "Fehler ${response.code()}"
                    }
                    _familyError.value = msg
                    onError(msg)
                }
            } catch (e: Exception) {
                val msg = "Netzwerkfehler: ${e.message}"
                _familyError.value = msg
                onError(msg)
            } finally {
                _familyLoading.value = false
            }
        }
    }

    /**
     * Parent lädt die Berechtigungen eines bestimmten Kind-Accounts.
     * Ergebnis wird im _childPermissionsMap gecacht.
     */
    fun loadChildPermissions(childId: String) {
        viewModelScope.launch {
            _familyLoading.value = true
