            } finally {
                _familyLoading.value = false
            }
        }
    }

    /**
     * Parent aktualisiert die Berechtigungen eines Kind-Accounts.
     * Aktualisiert den lokalen Cache sofort (optimistic update).
     */
    fun updateChildPermissions(
        childId: String,
        update: com.securechat.app.data.network.ChildPermissionsUpdateRequest,
        onSuccess: () -> Unit = {},
        onError: (String) -> Unit = {}
    ) {
        viewModelScope.launch {
            _familyLoading.value = true
            try {
                val response = apiService.updateChildPermissions(childId, update)
                if (response.isSuccessful) {
                    val perms = response.body() ?: return@launch
                    // Lokalen Cache sofort aktualisieren
                    _childPermissionsMap.value = _childPermissionsMap.value + (childId to perms)
                    _familyMessage.value = "Berechtigungen gespeichert"
                    onSuccess()
                } else {
                    val msg = "Fehler beim Speichern (${response.code()})"
                    _familyError.value = msg
                    onError(msg)
                }
            } catch (e: Exception) {
                val msg = "Netzwerkfehler: ${e.message}"
                _familyError.value = msg
                onError(msg)
            } finally {
                _familyLoading.value = false
            }
        }
    }

