    /**
     * Parent sperrt oder entsperrt einen Kontakt für das Kind.
     * Aktualisiert contact_blocked_ids in den Berechtigungen.
     */
    fun toggleChildContactBlock(childId: String, contactId: String, block: Boolean) {
        viewModelScope.launch {
            val currentPerms = _childPermissionsMap.value[childId] ?: return@launch
            val currentBlocked = try {
                if (currentPerms.contactBlockedIds != null)
                    com.google.gson.Gson().fromJson(currentPerms.contactBlockedIds, Array<String>::class.java).toMutableList()
                else mutableListOf()
            } catch (e: Exception) { mutableListOf() }

            if (block) { if (!currentBlocked.contains(contactId)) currentBlocked.add(contactId) }
            else currentBlocked.remove(contactId)

            val update = com.securechat.app.data.network.ChildPermissionsUpdateRequest(
                contactBlockedIds = currentBlocked
            )
            try {
                val response = apiService.updateChildPermissions(childId, update)
                if (response.isSuccessful) {
                    val perms = response.body() ?: return@launch
                    _childPermissionsMap.value = _childPermissionsMap.value + (childId to perms)
                    _familyMessage.value = if (block) "Kontakt gesperrt" else "Kontakt freigegeben"
                } else {
                    _familyError.value = "Fehler beim Aktualisieren (${response.code()})"
                }
            } catch (e: Exception) {
                _familyError.value = "Netzwerkfehler: ${e.message}"
            }
        }
    }

    fun clearFamilyError() { _familyError.value = null }
    fun clearFamilyMessage() { _familyMessage.value = null }

