        viewModelScope.launch {
            _creatorApplicationLoading.value = true
            _creatorApplicationError.value = null
            try {
                val response = apiService.submitCreatorApplication(
                    com.securechat.app.data.network.CreatorApplicationRequest(
                        bio = bio,
                        age = age,
                        email = email,
                        references = references?.ifBlank { null },
                        contentTypes = contentTypes
                    )
                )
                if (response.isSuccessful) {
                    _creatorApplicationSuccess.value = true
                    // Styx-Stand aktualisieren
                    try {
                        val me = apiService.getMe()
                        if (me.isSuccessful) {
                            me.body()?.let { profile ->
                                val updated = _currentUser.value?.copy(styx = profile.styx ?: 0) ?: return@let
                                userDao.insertUser(updated)
                                _currentUser.value = updated
                            }
                        }
                    } catch (_: Exception) {}
                } else {
                    val msg = try {
                        org.json.JSONObject(response.errorBody()?.string() ?: "").optString("detail", "Fehler ${response.code()}")
                    } catch (_: Exception) { "Fehler ${response.code()}" }
                    _creatorApplicationError.value = msg
                }
            } catch (e: Exception) {
                _creatorApplicationError.value = "Netzwerkfehler: ${e.message}"
            } finally {
                _creatorApplicationLoading.value = false
            }
        }
    }

    fun clearCreatorApplicationState() {
        _creatorApplicationSuccess.value = false
        _creatorApplicationError.value = null
    }

