    /**
     * Ruft die .onion-Adresse vom Server ab (/network-info) und speichert sie.
     * Wird im TorSettingsScreen über "Vom Server laden" ausgelöst.
     */
    fun fetchOnionAddressFromServer() {
        viewModelScope.launch(kotlinx.coroutines.Dispatchers.IO) {
            try {
                // Immer direkte Verbindung verwenden (kein Tor-Proxy) – dieser Aufruf
                // dient dem Bootstrapping der Tor-Konfiguration und darf nicht selbst
                // durch den (möglicherweise noch nicht gestarteten) Tor-Proxy laufen.
                val conn = java.net.URL("https://letheapp.de/network-info").openConnection()
                    as java.net.HttpURLConnection
                conn.connectTimeout = 15_000
                conn.readTimeout = 15_000
                val body = conn.inputStream.bufferedReader().readText()
                conn.disconnect()
                val json = org.json.JSONObject(body)
                val onion = json.optString("onion_address").takeIf { it.isNotBlank() }
                kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                    if (onion != null) {
                        setOnionAddress(onion)
                        _statusMessage.value = ".onion-Adresse gespeichert: $onion"
                    } else {
                        _statusMessage.value = "Server hat noch keinen Tor Hidden Service konfiguriert."
                    }
                }
            } catch (e: Exception) {
                kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Main) {
                    _statusMessage.value = "Fehler beim Abrufen der .onion-Adresse."
                    Timber.tag("MainViewModel").w("fetchOnionAddress: ${e.message}")
                }
            }
        }
    }

