    /** Speichert die Home-Server-URL und konfiguriert den Fallback sofort. */
    fun setHomeServerUrl(url: String) {
        val trimmed = url.trim()
        fallbackInterceptor.setHomeServerUrl(trimmed.ifBlank { null })
        webSocketManager.setHomeServerUrl(trimmed.ifBlank { null })
        viewModelScope.launch {
            prefsRepository.setHomeServerUrl(trimmed)
        }
    }

    /**
     * Ruft einmal täglich die Backup-URL vom Primary-Server ab (/network-info)
     * und speichert sie als autoBackupUrl. Die manuelle homeServerUrl bleibt davon unberührt.
     */
    private fun refreshBackupUrlIfNeeded(lastFetchMs: Long) {
        val now = System.currentTimeMillis()
        if (now - lastFetchMs < 24L * 60 * 60 * 1000) return  // noch keine 24h vergangen
        viewModelScope.launch(kotlinx.coroutines.Dispatchers.IO) {
            try {
                val info = apiService.getNetworkInfo()
                val backupUrl = info.backupUrl?.trim() ?: return@launch
                prefsRepository.setAutoBackupUrl(backupUrl)
                prefsRepository.setLastBackupUrlFetchMs(System.currentTimeMillis())
                // Sofort anwenden, wenn kein manueller Home-Server eingetragen ist
                val manualUrl = prefsRepository.userPreferencesFlow.first().homeServerUrl.trim()
                if (manualUrl.isBlank()) {
                    fallbackInterceptor.setHomeServerUrl(backupUrl)
                    webSocketManager.setHomeServerUrl(backupUrl)
                }
                android.util.Log.d("MainViewModel", "Auto-Backup-URL aktualisiert: $backupUrl")
            } catch (e: Exception) {
                android.util.Log.w("MainViewModel", "Backup-URL-Abruf fehlgeschlagen: ${e.message}")
            }
        }
    }

