    override fun onCleared() {
        super.onCleared()
        // Ab jetzt übernimmt der lifecycle-unabhängige NotificationHandler-Service die
        // WS-Benachrichtigungen, damit während der ViewModel-Neuerstellung (Reconnect) keine
        // Nachrichten verloren gehen.
        FcmMessageBus.isViewModelActive = false
        context.unregisterReceiver(screenStateReceiver)
        webSocketManager.disconnect()
        p2pMeshManager.stop()
        webRTCDataChannelManager.closeAll()
        // Musik-Player und MediaSession freigeben
        _metadataJob?.cancel()
        _musicProgressJob?.cancel()
        _musicNotificationManager?.setPlayer(null)
        _musicNotificationManager = null
        _musicMediaSession?.release()
        abandonMusicAudioFocus()
        _musicExoPlayer?.release()
        _musicExoPlayer = null
        _musicMediaSession = null
        // AudioRecord freigeben falls Aufnahme noch läuft (verhindert Mikrofon-Lock)
        xiaomiReadJob?.cancel()
        xiaomiAudioRecord?.release()
        xiaomiAudioRecord = null
        Timber.tag("MainViewModel").d("ViewModel zerstört, WebSocket getrennt.")
    }

    /** Lädt ein statisches Kartenvorschaubild für die angegebenen Koordinaten herunter
     *  und speichert es auf dem Server. Gibt die Bild-URL zurück oder null bei Fehler. */
    suspend fun uploadMapPreviewImage(lat: Double, lng: Double): String? {
        return try {
            withContext(Dispatchers.IO) {
                val osmUrl = "https://staticmap.openstreetmap.de/staticmap.php?center=$lat,$lng&zoom=14&size=520x320&markers=$lat,$lng,red-pushpin"
                val connection = java.net.URL(osmUrl).openConnection() as java.net.HttpURLConnection
                connection.connectTimeout = 8000
                connection.readTimeout = 8000
                val bytes = connection.inputStream.use { it.readBytes() }
                connection.disconnect()

                val tmpFile = java.io.File.createTempFile("map_prev_", ".png", context.cacheDir)
                tmpFile.writeBytes(bytes)
                try {
                    val reqFile = tmpFile.asRequestBody("image/png".toMediaTypeOrNull())
                    val part = MultipartBody.Part.createFormData("file", tmpFile.name, reqFile)
                    val resp = apiService.uploadNearbyChatImage(part)
                    if (resp.isSuccessful) resp.body()?.get("url") else null
                } finally {
                    tmpFile.delete()
                }
            }
        } catch (e: Exception) {
            android.util.Log.w("MapPreview", "Upload fehlgeschlagen: ${e.message}")
            null
        }
    }
}
